-- Autoimmune & Infectious Disorders question bank: exactly 900 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Autoimmune & Infectious Disorders/Rheumatoid-Arthritis.html
--   Notes/Autoimmune & Infectious Disorders/Lupus.html
--   Notes/Autoimmune & Infectious Disorders/Clostridium-Difficile.html
--   Notes/Autoimmune & Infectious Disorders/Infections.html
--   Notes/Autoimmune & Infectious Disorders/Myasthenia-Gravis.html
--   Notes/Autoimmune & Infectious Disorders/Autoimmune-Diseases.html
--   Notes/Autoimmune & Infectious Disorders/GBS.html
--   Notes/Autoimmune & Infectious Disorders/Immunodeficiency.html
--   Notes/Infections/Chickenpox-Varicella.html
--   Notes/Infections/Lyme-Disease.html
--   Notes/Infections/Anthrax.html
--   Notes/Infections/Mumps.html
--   Notes/Infections/Rubella.html
--   Notes/Infections/Rubeola-Measles.html
--   Notes/Infections/Hepatitis.html
--   Notes/Infections/Meningitis.html
--   Notes/Infections/HIV.html
--   Notes/Infections/SARS-Covid.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (900) exist after insert.
BEGIN;

CREATE TEMP TABLE _autoinf_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _autoinf_sources (source_key, source_path, category) VALUES
  ('ra', 'Notes/Autoimmune & Infectious Disorders/Rheumatoid-Arthritis.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - rheumatoid arthritis'),
  ('lupus', 'Notes/Autoimmune & Infectious Disorders/Lupus.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - lupus'),
  ('cdiff', 'Notes/Autoimmune & Infectious Disorders/Clostridium-Difficile.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - clostridium difficile'),
  ('infections', 'Notes/Autoimmune & Infectious Disorders/Infections.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - infections'),
  ('mg', 'Notes/Autoimmune & Infectious Disorders/Myasthenia-Gravis.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - myasthenia gravis'),
  ('autoimmune', 'Notes/Autoimmune & Infectious Disorders/Autoimmune-Diseases.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - autoimmune diseases'),
  ('gbs', 'Notes/Autoimmune & Infectious Disorders/GBS.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - gbs'),
  ('immunodef', 'Notes/Autoimmune & Infectious Disorders/Immunodeficiency.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - immunodeficiency'),
  ('chickenpox', 'Notes/Infections/Chickenpox-Varicella.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - chickenpox varicella'),
  ('lyme', 'Notes/Infections/Lyme-Disease.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - lyme disease'),
  ('anthrax', 'Notes/Infections/Anthrax.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - anthrax'),
  ('mumps', 'Notes/Infections/Mumps.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - mumps'),
  ('rubella', 'Notes/Infections/Rubella.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - rubella'),
  ('measles', 'Notes/Infections/Rubeola-Measles.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - rubeola measles'),
  ('hepatitis', 'Notes/Infections/Hepatitis.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - hepatitis'),
  ('meningitis', 'Notes/Infections/Meningitis.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - meningitis'),
  ('hiv', 'Notes/Infections/HIV.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - hiv'),
  ('covid', 'Notes/Infections/SARS-Covid.html', 'Autoimmune & Infectious Disorders NCLEX seed v1 - sars covid');

CREATE TEMP TABLE _autoinf_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _autoinf_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'autoimmune & infectious disorders'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Autoimmune & Infectious Disorders"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'autoimmune & infectious disorders'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _autoinf_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Autoimmune & Infectious Disorders subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Autoimmune & Infectious Disorders points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _autoinf_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Autoimmune-Infectious seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _autoinf_seed_map) <> 18 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 18 note mappings, found %.',
      (SELECT count(*) FROM _autoinf_seed_map);
  END IF;

  INSERT INTO _autoinf_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _autoinf_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('ra', 1, 'The nurse is comparing joint findings in clients with arthritis. Which finding is most consistent with rheumatoid arthritis (RA) rather than osteoarthritis (OA)?', '[{"id": "a", "text": "Absence of fatigue or low-grade fever"}, {"id": "b", "text": "Morning stiffness lasting less than 30 minutes"}, {"id": "c", "text": "Morning stiffness lasting more than 1 hour"}, {"id": "d", "text": "Asymmetric involvement of a single knee"}]'::jsonb, '["c"]', 'Morning stiffness greater than 1 hour is the key feature distinguishing RA from OA. Stiffness under 30 minutes, asymmetric involvement, and no systemic symptoms describe OA.'),
  ('ra', 2, 'The nurse reviews four clients who report joint pain. Which client''s presentation is most consistent with osteoarthritis (OA)?', '[{"id": "a", "text": "Both wrists stiff for 90 minutes each morning, with a low-grade fever"}, {"id": "b", "text": "Swelling of the knuckles on both hands, with fatigue and weight loss"}, {"id": "c", "text": "Symmetric finger swelling with firm lumps over the elbows"}, {"id": "d", "text": "One stiff hip that loosens within 20 minutes, with no fever or fatigue"}]'::jsonb, '["d"]', 'OA causes morning stiffness under 30 minutes, is asymmetric, affects weight-bearing joints, and has no systemic symptoms. Symmetric small-joint involvement, prolonged stiffness, and systemic symptoms point to RA.'),
  ('ra', 3, 'A client is being evaluated for early rheumatoid arthritis. Which joints does the nurse expect to be affected first?', '[{"id": "a", "text": "The weight-bearing hips and knees"}, {"id": "b", "text": "The finger joints (PIP and MCP) and wrists"}, {"id": "c", "text": "A single knee on one side of the body"}, {"id": "d", "text": "The distal interphalangeal (DIP) joints"}]'::jsonb, '["b"]', 'RA affects small joints first, such as the PIP and MCP finger joints and the wrists, before larger joints. Weight-bearing joints are typical of OA, and RA spares the DIP joints.'),
  ('ra', 4, 'A nursing student is describing the joint pattern of rheumatoid arthritis. Which statement by the student requires correction?', '[{"id": "a", "text": "''The wrists are commonly involved early in the disease.''"}, {"id": "b", "text": "''Small joints are usually affected before larger joints.''"}, {"id": "c", "text": "''The DIP joints of the fingers are usually affected first.''"}, {"id": "d", "text": "''Both hands are usually affected to the same degree.''"}]'::jsonb, '["c"]', 'RA spares the DIP joints, unlike OA or psoriatic arthritis. Symmetric involvement and early involvement of small joints such as the wrists are accurate.'),
  ('ra', 5, 'A client with rheumatoid arthritis asks, ''Will moving around make my morning stiffness worse?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "''Stay in bed until the stiffness has completely gone away.''"}, {"id": "b", "text": "''Stiffness usually improves as you move and stay active during the day.''"}, {"id": "c", "text": "''Stiffness usually worsens the more you move during the day.''"}, {"id": "d", "text": "''Avoid using your joints until the afternoon each day.''"}]'::jsonb, '["b"]', 'Morning stiffness in RA improves with movement and activity throughout the day. Staying in bed or avoiding joint use reverses this principle.'),
  ('ra', 6, 'A client newly diagnosed with rheumatoid arthritis asks what causes the permanent joint damage. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Temporary joint swelling resolves without causing lasting damage."}, {"id": "b", "text": "Excess lubricating fluid dissolves the bone at the joint margins."}, {"id": "c", "text": "Inflamed granulation tissue called pannus erodes cartilage and bone."}, {"id": "d", "text": "Wear and tear gradually breaks down weight-bearing joint cartilage."}]'::jsonb, '["c"]', 'In chronic RA, pannus (inflamed granulation tissue) erodes cartilage and bone, causing permanent joint destruction. Degenerative wear and tear of weight-bearing joints describes OA.'),
  ('ra', 7, 'A client with rheumatoid arthritis asks which part of the joint the immune system is attacking. The nurse explains that the immune system primarily attacks which structure?', '[{"id": "a", "text": "The bone marrow inside the long bones"}, {"id": "b", "text": "The cartilage of the weight-bearing joints only"}, {"id": "c", "text": "The skin covering the bony prominences"}, {"id": "d", "text": "The synovial membrane that lines the joint"}]'::jsonb, '["d"]', 'RA is an autoimmune disease in which the immune system attacks the synovial membrane, the joint lining that produces lubricating fluid. Inflammation of this lining (synovitis) causes pain, swelling, and warmth.'),
  ('ra', 8, 'During assessment of a client with long-standing rheumatoid arthritis, the nurse palpates firm lumps under the skin over the elbows. How should the nurse document this finding?', '[{"id": "a", "text": "Boutonnière deformity"}, {"id": "b", "text": "Subcutaneous nodules"}, {"id": "c", "text": "Swan-neck deformity"}, {"id": "d", "text": "Ulnar deviation"}]'::jsonb, '["b"]', 'Subcutaneous nodules are firm lumps under the skin over bony prominences. Ulnar deviation, swan-neck, and boutonnière deformities describe finger positions, not lumps.'),
  ('ra', 9, 'The nurse observes that the fingers of a client with late rheumatoid arthritis drift toward the little-finger side of the hand. Which deformity is this?', '[{"id": "a", "text": "Swan-neck deformity"}, {"id": "b", "text": "Boutonnière deformity"}, {"id": "c", "text": "Ulnar deviation"}, {"id": "d", "text": "Subcutaneous nodule"}]'::jsonb, '["c"]', 'Ulnar deviation is drift of the fingers toward the ulnar (pinky) side. Swan-neck and boutonnière deformities involve flexion and hyperextension of the PIP and DIP joints.'),
  ('ra', 10, 'A client with late-stage rheumatoid arthritis has a finger with PIP joint hyperextension and DIP joint flexion. The nurse documents which deformity?', '[{"id": "a", "text": "Boutonnière deformity"}, {"id": "b", "text": "Subcutaneous nodule"}, {"id": "c", "text": "Ulnar deviation"}, {"id": "d", "text": "Swan-neck deformity"}]'::jsonb, '["d"]', 'Swan-neck deformity is PIP hyperextension with DIP flexion. Boutonnière deformity is the reverse pattern: PIP flexion with DIP hyperextension.'),
  ('ra', 11, 'A client with late-stage rheumatoid arthritis has a finger with PIP joint flexion and DIP joint hyperextension. The nurse documents which deformity?', '[{"id": "a", "text": "Subcutaneous nodule"}, {"id": "b", "text": "Boutonnière deformity"}, {"id": "c", "text": "Swan-neck deformity"}, {"id": "d", "text": "Ulnar deviation"}]'::jsonb, '["b"]', 'Boutonnière deformity is PIP flexion with DIP hyperextension. Swan-neck deformity is the reverse: PIP hyperextension with DIP flexion.'),
  ('ra', 12, 'A client with rheumatoid arthritis is being assessed for systemic involvement. Which finding reflects a systemic (constitutional) manifestation of RA?', '[{"id": "a", "text": "Sparing of the small finger joints"}, {"id": "b", "text": "Stiffness lasting under 30 minutes"}, {"id": "c", "text": "Pain limited to one weight-bearing knee"}, {"id": "d", "text": "Fatigue with a low-grade fever"}]'::jsonb, '["d"]', 'RA causes constitutional symptoms such as fatigue, low-grade fever, weight loss, and anorexia. Brief stiffness, single weight-bearing joint pain, and absent systemic symptoms describe OA.'),
  ('ra', 13, 'A client with rheumatoid arthritis asks how the disease can affect organs outside the joints. Which pairing of organ and RA manifestation is accurate?', '[{"id": "a", "text": "Vessels — pericarditis"}, {"id": "b", "text": "Eyes — pleural effusion"}, {"id": "c", "text": "Lungs — interstitial lung disease"}, {"id": "d", "text": "Heart — scleritis"}]'::jsonb, '["c"]', 'RA can affect the lungs with interstitial lung disease (ILD) and pleural effusion. Scleritis affects the eyes, pericarditis affects the heart, and pleural effusion affects the lungs.'),
  ('ra', 14, 'A client with rheumatoid arthritis has new chest discomfort, and the provider is evaluating for heart involvement. Which cardiac manifestation of RA should the nurse anticipate?', '[{"id": "a", "text": "Scleritis"}, {"id": "b", "text": "Pannus formation"}, {"id": "c", "text": "Pericarditis"}, {"id": "d", "text": "Atlantoaxial subluxation"}]'::jsonb, '["c"]', 'RA involves the heart as pericarditis. Scleritis is an eye manifestation, atlantoaxial subluxation is a cervical spine complication, and pannus forms in the joints.'),
  ('ra', 15, 'A client with symmetric hand swelling has several laboratory tests drawn. Which result most specifically supports a diagnosis of rheumatoid arthritis?', '[{"id": "a", "text": "Positive rheumatoid factor"}, {"id": "b", "text": "Anemia on the CBC"}, {"id": "c", "text": "Elevated ESR"}, {"id": "d", "text": "Positive anti-CCP antibodies"}]'::jsonb, '["d"]', 'Anti-CCP antibodies are the most specific test for RA and are positive early in the disease. Rheumatoid factor can be positive in other conditions, and ESR is a non-specific inflammation marker.'),
  ('ra', 16, 'A client says, ''My rheumatoid factor (RF) came back positive, so I must have rheumatoid arthritis.'' Which response by the nurse is accurate?', '[{"id": "a", "text": "''RF can also be positive in conditions other than RA.''"}, {"id": "b", "text": "''A positive RF confirms RA with complete certainty.''"}, {"id": "c", "text": "''RF is the most specific blood test available for RA.''"}, {"id": "d", "text": "''RF is positive in every person who has RA.''"}]'::jsonb, '["a"]', 'RF is positive in about 80% of clients with RA but is not specific and can be positive in other conditions. Anti-CCP, not RF, is the most specific test.'),
  ('ra', 17, 'A client with rheumatoid arthritis is admitted during a flare. Which laboratory findings should the nurse expect?', '[{"id": "a", "text": "Elevated ESR and elevated CRP"}, {"id": "b", "text": "Decreased white blood cell count"}, {"id": "c", "text": "Decreased ESR and decreased CRP"}, {"id": "d", "text": "Normal ESR with a low CRP"}]'::jsonb, '["a"]', 'ESR and CRP are elevated in RA, and ESR rises during flares; the CBC may show leukocytosis during flares. Decreased inflammatory markers or a low WBC would not be expected from a flare itself.'),
  ('ra', 18, 'A client with symptoms of early rheumatoid arthritis has normal joint x-rays and asks, ''Does this mean I don''t have RA?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "''Normal x-rays mean the disease is cured.''"}, {"id": "b", "text": "''X-rays may look normal early in the disease.''"}, {"id": "c", "text": "''Normal x-rays rule out rheumatoid arthritis.''"}, {"id": "d", "text": "''X-rays always show erosions at diagnosis.''"}]'::jsonb, '["b"]', 'In RA, joint x-rays may appear normal early in the disease. Later x-rays show joint space narrowing, erosions, and osteopenia, so a normal early film does not exclude RA.'),
  ('ra', 19, 'The nurse reviews the joint x-ray report of a client with long-standing rheumatoid arthritis. Which findings does the nurse expect?', '[{"id": "a", "text": "Increased bone density without erosions"}, {"id": "b", "text": "Joint space narrowing and erosions"}, {"id": "c", "text": "Normal joints with no bone changes"}, {"id": "d", "text": "Widened joint spaces and denser bone"}]'::jsonb, '["b"]', 'X-rays in RA show joint space narrowing, erosions, and osteopenia. Increased bone density or widened joint spaces reverse these findings, and normal films are seen only in early disease.'),
  ('ra', 20, 'The CBC of a client with rheumatoid arthritis who is not yet taking DMARDs shows mild anemia. How should the nurse interpret this finding?', '[{"id": "a", "text": "It is caused by methotrexate toxicity."}, {"id": "b", "text": "It confirms the client has osteoarthritis."}, {"id": "c", "text": "It indicates the RA is in remission."}, {"id": "d", "text": "It may reflect anemia of chronic disease."}]'::jsonb, '["d"]', 'RA can cause anemia of chronic disease. Methotrexate-induced bone marrow suppression is a DMARD concern, but this client is not yet taking a DMARD.'),
  ('ra', 21, 'A client with rheumatoid arthritis is prescribed naproxen for joint pain and swelling. Which instruction should the nurse include?', '[{"id": "a", "text": "Take it with food and report signs of GI bleeding."}, {"id": "b", "text": "It will stop the joint destruction caused by RA."}, {"id": "c", "text": "Take it on an empty stomach for faster relief."}, {"id": "d", "text": "Take it in place of the prescribed methotrexate."}]'::jsonb, '["a"]', 'NSAIDs such as naproxen reduce pain and swelling but carry a GI bleeding risk and should be taken with food. They provide symptom relief; DMARDs are what slow disease progression.'),
  ('ra', 22, 'A client with an RA flare asks why prednisone was prescribed for only a short time. Which response by the nurse is accurate?', '[{"id": "a", "text": "''Steroids are the first-line drug for long-term RA control.''"}, {"id": "b", "text": "''Steroids bridge a flare but cause side effects with long-term use.''"}, {"id": "c", "text": "''Steroids are used briefly because they halt joint destruction.''"}, {"id": "d", "text": "''Steroids are stopped early because they rarely work in RA.''"}]'::jsonb, '["b"]', 'Corticosteroids are used for short-term bridging during flares and are avoided long term because of side effects. Methotrexate, not a steroid, is the first-line long-term drug.'),
  ('ra', 23, 'A client with rheumatoid arthritis has been taking a corticosteroid for an extended period. Which finding should the nurse recognize as a complication of this therapy?', '[{"id": "a", "text": "Mouth sores"}, {"id": "b", "text": "Low blood glucose"}, {"id": "c", "text": "Increased bone density"}, {"id": "d", "text": "Elevated blood glucose"}]'::jsonb, '["d"]', 'Steroid complications include hyperglycemia, osteoporosis, and Cushing-like features. Increased bone density reverses the osteoporosis risk, and mouth sores (stomatitis) are a methotrexate effect.'),
  ('ra', 24, 'A client with rheumatoid arthritis reports that the hands are very stiff each morning on waking. Which recommendation by the nurse is most appropriate?', '[{"id": "a", "text": "Stay in bed until the stiffness resolves."}, {"id": "b", "text": "Take a warm shower or bath after waking."}, {"id": "c", "text": "Avoid using the hands until the afternoon."}, {"id": "d", "text": "Apply ice packs to the hands before rising."}]'::jsonb, '["b"]', 'Heat therapy, such as a warm shower or bath on waking, relieves stiffness. Cold packs are used for acute inflammation, not stiffness.'),
  ('ra', 25, 'A client in an RA flare has an acutely swollen, warm knee. Which comfort measure should the nurse apply?', '[{"id": "a", "text": "A warm shower over the swollen knee"}, {"id": "b", "text": "A cold pack to the swollen knee"}, {"id": "c", "text": "A heating pad to the swollen knee"}, {"id": "d", "text": "Vigorous exercise of the swollen knee"}]'::jsonb, '["b"]', 'Cold therapy is used for acute swelling and inflammation. Heat is used for stiffness, not for an acutely inflamed joint.'),
  ('ra', 26, 'The nurse teaches a client with rheumatoid arthritis about heat and cold therapy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "''Heat helps stiffness, and cold helps acute inflammation.''"}, {"id": "b", "text": "''I''ll take a warm shower when I wake up stiff.''"}, {"id": "c", "text": "''I''ll use a cold pack when a joint is acutely swollen.''"}, {"id": "d", "text": "''I''ll put a heating pad on my hot, swollen knee during a flare.''"}]'::jsonb, '["d"]', 'Heat is for stiffness and cold is for acute inflammation, so a hot, swollen joint during a flare needs cold, not heat. The other statements apply the rule correctly.'),
  ('ra', 27, 'A client with rheumatoid arthritis asks how methotrexate differs from ibuprofen. Which response by the nurse is accurate?', '[{"id": "a", "text": "''Methotrexate slows the disease; ibuprofen eases pain and swelling.''"}, {"id": "b", "text": "''Both drugs only relieve pain and do not change the disease.''"}, {"id": "c", "text": "''Both drugs are used short term only during flares.''"}, {"id": "d", "text": "''Ibuprofen slows the disease; methotrexate eases the pain.''"}]'::jsonb, '["a"]', 'Methotrexate is a DMARD, which slows or halts disease progression, whereas NSAIDs such as ibuprofen reduce pain and swelling. Reversing the roles is incorrect.'),
  ('ra', 28, 'A client is newly diagnosed with rheumatoid arthritis. The nurse anticipates which medication as the first-line disease-modifying drug?', '[{"id": "a", "text": "Methotrexate"}, {"id": "b", "text": "Rituximab"}, {"id": "c", "text": "Prednisone"}, {"id": "d", "text": "Tocilizumab"}]'::jsonb, '["a"]', 'Methotrexate is the first-line DMARD for RA. Rituximab and tocilizumab are biologics used if DMARDs fail, and prednisone is a short-term bridge.'),
  ('ra', 29, 'A client taking methotrexate for rheumatoid arthritis calls the clinic. Which reported finding should the nurse recognize as an adverse effect of the drug?', '[{"id": "a", "text": "Improved grip strength in the hands"}, {"id": "b", "text": "Morning stiffness lasting two hours"}, {"id": "c", "text": "Less swelling in the finger joints"}, {"id": "d", "text": "Painful sores in the mouth"}]'::jsonb, '["d"]', 'Stomatitis (mouth sores) is a methotrexate adverse effect. Prolonged morning stiffness is a feature of RA itself, and improved grip and less swelling suggest the drug is working.'),
  ('ra', 30, 'A client with rheumatoid arthritis is starting methotrexate. Which laboratory tests should the nurse plan to monitor?', '[{"id": "a", "text": "Anti-CCP antibodies and RF"}, {"id": "b", "text": "Liver function tests and a CBC"}, {"id": "c", "text": "Blood pressure and annual eye exam"}, {"id": "d", "text": "TB screening as the only test"}]'::jsonb, '["b"]', 'Methotrexate requires monitoring of LFTs and the CBC. Blood pressure monitoring is for leflunomide, annual eye exams are for hydroxychloroquine, and TB screening is required before biologics.'),
  ('ra', 31, 'A client taking methotrexate has a CBC showing decreased white blood cells, red blood cells, and platelets. How should the nurse interpret these results?', '[{"id": "a", "text": "A normal finding requiring no follow-up"}, {"id": "b", "text": "Expected leukocytosis from an RA flare"}, {"id": "c", "text": "Evidence that the drug is working well"}, {"id": "d", "text": "Possible methotrexate-induced bone marrow suppression"}]'::jsonb, '["d"]', 'Methotrexate can cause bone marrow suppression, shown by decreased WBC, RBC, and platelets. Leukocytosis during a flare would be an increased, not decreased, WBC.'),
  ('ra', 32, 'A client asks why folic acid was prescribed along with methotrexate. Which response by the nurse is accurate?', '[{"id": "a", "text": "''It helps reduce the side effects of methotrexate.''"}, {"id": "b", "text": "''It makes the methotrexate safe in pregnancy.''"}, {"id": "c", "text": "''It replaces the need for monthly blood tests.''"}, {"id": "d", "text": "''It treats the morning stiffness directly.''"}]'::jsonb, '["a"]', 'Folic acid is supplemented to reduce methotrexate side effects. It does not remove the need for lab monitoring, and methotrexate must not be used in pregnancy.'),
  ('ra', 33, 'A 28-year-old client with rheumatoid arthritis is starting methotrexate. Which teaching point is the priority?', '[{"id": "a", "text": "Get an eye exam before the first dose."}, {"id": "b", "text": "Take the drug only during painful flares."}, {"id": "c", "text": "Use reliable contraception during treatment."}, {"id": "d", "text": "Stop folic acid once treatment starts."}]'::jsonb, '["c"]', 'Methotrexate is teratogenic, so reliable contraception is required and the drug must not be used in pregnancy. Folic acid is supplemented, not stopped, and annual eye exams apply to hydroxychloroquine.'),
  ('ra', 34, 'The nurse reviews laboratory results for a client taking methotrexate. Which result should the nurse report to the provider?', '[{"id": "a", "text": "ESR lower than at diagnosis"}, {"id": "b", "text": "Hemoglobin unchanged from baseline"}, {"id": "c", "text": "Elevated liver function tests"}, {"id": "d", "text": "CRP lower than last month"}]'::jsonb, '["c"]', 'Hepatotoxicity, shown by elevated LFTs, is a key methotrexate adverse effect that must be reported. Falling ESR and CRP reflect less inflammation.'),
  ('ra', 35, 'A client with rheumatoid arthritis is prescribed hydroxychloroquine. Which monitoring should the nurse include in the teaching?', '[{"id": "a", "text": "Blood pressure checks at every visit"}, {"id": "b", "text": "TB screening before every dose"}, {"id": "c", "text": "An eye examination every year"}, {"id": "d", "text": "Mouth checks for stomatitis daily"}]'::jsonb, '["c"]', 'Hydroxychloroquine requires annual eye exams because of the risk of retinal toxicity. Blood pressure monitoring is for leflunomide, and stomatitis is a methotrexate effect.'),
  ('ra', 36, 'A client with rheumatoid arthritis is prescribed leflunomide. In addition to liver function tests, which assessment should the nurse monitor?', '[{"id": "a", "text": "Annual eye exams"}, {"id": "b", "text": "Oral mucosa for sores"}, {"id": "c", "text": "Blood pressure"}, {"id": "d", "text": "Blood glucose"}]'::jsonb, '["c"]', 'Leflunomide requires monitoring of LFTs and blood pressure because it can cause hepatotoxicity and hypertension. Annual eye exams are for hydroxychloroquine, and mouth sores are a methotrexate effect.'),
  ('ra', 37, 'A client with rheumatoid arthritis is starting sulfasalazine. Which side effect should the nurse teach the client to expect?', '[{"id": "a", "text": "Gastrointestinal upset"}, {"id": "b", "text": "Hypertension"}, {"id": "c", "text": "Retinal toxicity"}, {"id": "d", "text": "Stomatitis"}]'::jsonb, '["a"]', 'Sulfasalazine''s key side effects are GI upset and hepatotoxicity. Retinal toxicity is linked to hydroxychloroquine, hypertension to leflunomide, and stomatitis to methotrexate.'),
  ('ra', 38, 'A client''s rheumatoid arthritis continues to progress despite DMARD therapy. Which treatment step should the nurse anticipate next?', '[{"id": "a", "text": "NSAIDs as the only therapy"}, {"id": "b", "text": "Stopping all medications"}, {"id": "c", "text": "Long-term high-dose steroids"}, {"id": "d", "text": "A biologic such as a TNF inhibitor"}]'::jsonb, '["d"]', 'Biologics are the next step when DMARDs fail. NSAIDs only relieve symptoms, and corticosteroids are avoided long term because of side effects.'),
  ('ra', 39, 'A client with rheumatoid arthritis is scheduled to receive the first dose of adalimumab. Which action should the nurse take before the dose?', '[{"id": "a", "text": "Verify that TB screening has been completed."}, {"id": "b", "text": "Verify that an eye exam was done this year."}, {"id": "c", "text": "Verify that blood pressure is below baseline."}, {"id": "d", "text": "Verify that the client stopped folic acid."}]'::jsonb, '["a"]', 'All biologics cause significant immunosuppression and a high infection risk, so TB screening is required before starting. Annual eye exams relate to hydroxychloroquine.'),
  ('ra', 40, 'The nurse is reviewing the medication list of a client with rheumatoid arthritis. Which medication is a TNF inhibitor?', '[{"id": "a", "text": "Etanercept"}, {"id": "b", "text": "Rituximab"}, {"id": "c", "text": "Leflunomide"}, {"id": "d", "text": "Tocilizumab"}]'::jsonb, '["a"]', 'Etanercept, adalimumab, and infliximab are TNF inhibitors. Tocilizumab is an IL-6 inhibitor, rituximab causes B-cell depletion, and leflunomide is a DMARD.'),
  ('ra', 41, 'A client receiving infliximab for rheumatoid arthritis reports a new fever and persistent cough. Which action should the nurse take?', '[{"id": "a", "text": "Report the findings promptly as a possible infection."}, {"id": "b", "text": "Advise doubling the next dose of infliximab."}, {"id": "c", "text": "Explain that fever is an expected sign of RA."}, {"id": "d", "text": "Advise resting at home without any follow-up."}]'::jsonb, '["a"]', 'Biologics cause significant immunosuppression and can lead to serious infections, including TB and fungal infections, so new fever and cough must be reported. Assuming the fever is from RA could delay care for a serious infection.'),
  ('ra', 42, 'A client whose rheumatoid arthritis is in remission asks about exercise. Which recommendation by the nurse is most appropriate?', '[{"id": "a", "text": "Exercising only during a painful flare"}, {"id": "b", "text": "Avoiding all exercise to protect joints"}, {"id": "c", "text": "Low-impact exercise such as swimming or walking"}, {"id": "d", "text": "Complete bed rest until the next flare"}]'::jsonb, '["c"]', 'Rest is used during flares, balanced with low-impact exercise such as swimming and walking during remission. Bed rest or avoiding exercise in remission is not recommended.'),
  ('ra', 43, 'The nurse teaches a client with rheumatoid arthritis about assistive devices. Which client statement indicates understanding?', '[{"id": "a", "text": "''Grab bars are useful only for people with OA.''"}, {"id": "b", "text": "''Devices are needed only after deformities develop.''"}, {"id": "c", "text": "''A jar opener and button hook will help protect my joints.''"}, {"id": "d", "text": "''I should avoid devices so my hands stay strong.''"}]'::jsonb, '["c"]', 'Assistive devices such as button hooks, jar openers, raised toilet seats, and grab bars preserve joint function in RA. Avoiding them or delaying their use does not protect the joints.'),
  ('ra', 44, 'The nurse observes a client with rheumatoid arthritis carrying out daily tasks. Which action by the client demonstrates correct joint protection?', '[{"id": "a", "text": "Twisting open tight jars with the fingers"}, {"id": "b", "text": "Carrying grocery bags by the fingertips"}, {"id": "c", "text": "Carrying a heavy bag over the forearm"}, {"id": "d", "text": "Gripping a heavy pot with the fingers"}]'::jsonb, '["c"]', 'Joint protection in RA means avoiding activities that stress small joints and using large joints for heavy tasks. Gripping, twisting, or carrying loads with the fingers stresses the small joints.'),
  ('ra', 45, 'The nurse is supervising a UAP caring for a client with rheumatoid arthritis. Which action by the UAP requires correction?', '[{"id": "a", "text": "Telling the client to skip daily range-of-motion exercises"}, {"id": "b", "text": "Placing a raised toilet seat in the client''s bathroom"}, {"id": "c", "text": "Providing a jar opener for the client at mealtime"}, {"id": "d", "text": "Helping the client take a warm shower after waking"}]'::jsonb, '["a"]', 'Daily gentle range-of-motion exercises are part of RA care, so advising the client to skip them needs correction. Warm showers for stiffness and assistive devices are appropriate.'),
  ('ra', 46, 'A client with long-standing rheumatoid arthritis says, ''The pain never stops, and I don''t enjoy anything anymore.'' Which action should the nurse take?', '[{"id": "a", "text": "Document the comment as expected only."}, {"id": "b", "text": "Tell the client to focus on the positives."}, {"id": "c", "text": "Change the subject to the medication plan."}, {"id": "d", "text": "Assess the client for depression and anxiety."}]'::jsonb, '["d"]', 'Chronic pain in RA affects mood and function, so the nurse should assess for depression and anxiety. Dismissing or only documenting the statement misses this need.'),
  ('ra', 47, 'A client with long-standing rheumatoid arthritis reports new neck pain with tingling and weakness in both arms. Which complication should the nurse suspect?', '[{"id": "a", "text": "Atlantoaxial subluxation"}, {"id": "b", "text": "Expected morning stiffness"}, {"id": "c", "text": "Pleural effusion"}, {"id": "d", "text": "Pericarditis"}]'::jsonb, '["a"]', 'RA can cause cervical spine instability (atlantoaxial subluxation), which carries a risk of spinal cord injury. Pericarditis and pleural effusion involve the heart and lungs, not the cervical spine.'),
  ('ra', 48, 'A client with rheumatoid arthritis takes methotrexate and a biologic. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "''I will keep all of my scheduled blood tests.''"}, {"id": "b", "text": "''I can skip my lab appointments if I feel fine.''"}, {"id": "c", "text": "''I will take my folic acid as it is prescribed.''"}, {"id": "d", "text": "''I will report any fever or chills right away.''"}]'::jsonb, '["b"]', 'Medication compliance is critical, and DMARD monitoring schedules must be followed regardless of how the client feels. Reporting fever and taking folic acid are correct.'),
  ('ra', 49, 'The nurse is planning teaching for a client with rheumatoid arthritis who is taking a DMARD. Which topic is a priority because of the drug''s effect on immunity?', '[{"id": "a", "text": "Signs of infection to report"}, {"id": "b", "text": "Reasons to skip lab monitoring"}, {"id": "c", "text": "Ways to stop the drug at home"}, {"id": "d", "text": "Methods to increase joint stress"}]'::jsonb, '["a"]', 'DMARDs and biologics suppress immunity, so the nurse teaches infection signs. Stopping the drug conflicts with the emphasis on medication compliance.'),
  ('ra', 50, 'A client taking hydroxychloroquine for rheumatoid arthritis reports new changes in vision. How should the nurse interpret this report?', '[{"id": "a", "text": "It may signal retinal toxicity and should be reported."}, {"id": "b", "text": "It is a sign of methotrexate-induced stomatitis."}, {"id": "c", "text": "It is a harmless effect that needs no follow-up."}, {"id": "d", "text": "It is an expected sign that the RA is improving."}]'::jsonb, '["a"]', 'Hydroxychloroquine can cause retinal toxicity, which is rare but serious and is the reason for annual eye exams. Stomatitis is a mouth effect of methotrexate.'),
  ('lupus', 1, 'A client with systemic lupus erythematosus (SLE) has redness across both cheeks and the bridge of the nose that spares the nasolabial folds. How should the nurse document this finding?', '[{"id": "a", "text": "Alopecia"}, {"id": "b", "text": "Discoid rash"}, {"id": "c", "text": "Malar (butterfly) rash"}, {"id": "d", "text": "Raynaud phenomenon"}]'::jsonb, '["c"]', 'The butterfly (malar) rash is erythema across both cheeks and the nose bridge that spares the nasolabial folds. A discoid rash consists of coin-shaped lesions.'),
  ('lupus', 2, 'A client with SLE has several round, coin-shaped skin lesions on the arms. Which term should the nurse use to document these lesions?', '[{"id": "a", "text": "Malar rash"}, {"id": "b", "text": "Raynaud phenomenon"}, {"id": "c", "text": "Alopecia"}, {"id": "d", "text": "Discoid rash"}]'::jsonb, '["d"]', 'A discoid rash consists of coin-shaped lesions. The malar (butterfly) rash appears across the cheeks and nose bridge.'),
  ('lupus', 3, 'The nurse teaches a client with SLE about sun protection. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "''I will wear a wide hat and protective clothing outside.''"}, {"id": "b", "text": "''I only need sunscreen on hot, sunny summer days.''"}, {"id": "c", "text": "''Sun exposure can trigger a lupus flare for me.''"}, {"id": "d", "text": "''I will apply sunscreen with SPF 30 or higher daily.''"}]'::jsonb, '["b"]', 'Sun protection with SPF 30 or higher sunscreen, hats, and protective clothing is needed daily because UV light triggers flares. Limiting sunscreen to summer days is incorrect.'),
  ('lupus', 4, 'A client with SLE asks which sunscreen to buy. Which recommendation by the nurse is accurate?', '[{"id": "a", "text": "No sunscreen if a hat is worn"}, {"id": "b", "text": "A sunscreen with SPF 15 or higher"}, {"id": "c", "text": "A sunscreen with SPF 30 or higher"}, {"id": "d", "text": "A sunscreen with SPF 8 or higher"}]'::jsonb, '["c"]', 'Clients with SLE should use SPF 30 or higher at all times because UV light triggers flares. Lower SPF values or relying on a hat alone do not meet this standard.'),
  ('lupus', 5, 'A client with SLE plans to spend a day gardening outdoors. Which advice by the nurse is most appropriate?', '[{"id": "a", "text": "Skip sunscreen since gardening is brief."}, {"id": "b", "text": "Avoid peak sun hours and wear protective clothing."}, {"id": "c", "text": "Garden at midday when sunlight is strongest."}, {"id": "d", "text": "Expose the skin to the sun to build tolerance."}]'::jsonb, '["b"]', 'Sun protection for SLE includes SPF 30 or higher, protective clothing, and avoiding peak sun hours. Increasing sun exposure would raise the risk of a UV-triggered flare.'),
  ('lupus', 6, 'A client with SLE reports that a facial rash and joint aches worsened after a weekend at the beach. The nurse recognizes this response as which feature of lupus?', '[{"id": "a", "text": "Discoid lesion formation"}, {"id": "b", "text": "Drug-induced lupus"}, {"id": "c", "text": "Photosensitivity"}, {"id": "d", "text": "Raynaud phenomenon"}]'::jsonb, '["c"]', 'Photosensitivity is a rash or flare after sun exposure. Drug-induced lupus is triggered by certain medications, not sun exposure.'),
  ('lupus', 7, 'The nurse is teaching a client with SLE about flare triggers. Which client statement indicates understanding?', '[{"id": "a", "text": "''Sun exposure helps protect against flares.''"}, {"id": "b", "text": "''Medications can never cause lupus symptoms.''"}, {"id": "c", "text": "''Pregnancy lowers my chance of a flare.''"}, {"id": "d", "text": "''Stress and infections can trigger a flare.''"}]'::jsonb, '["d"]', 'Triggers of SLE flares include sun exposure, infections, stress, pregnancy, postpartum, menstruation, and certain medications (drug-induced lupus). Each distractor reverses one of these triggers.'),
  ('lupus', 8, 'A client with SLE wants to become pregnant. Which statement by the nurse about timing is accurate?', '[{"id": "a", "text": "''You should conceive during a flare, when the disease is active.''"}, {"id": "b", "text": "''Lupus should be controlled for at least 6 months before conception.''"}, {"id": "c", "text": "''Lupus control before conception does not affect the pregnancy.''"}, {"id": "d", "text": "''Lupus should be controlled for at least 1 month before conception.''"}]'::jsonb, '["b"]', 'Lupus should be controlled for at least 6 months before conception because pregnancy increases flare risk. Shorter control or conceiving during active disease is not recommended.'),
  ('lupus', 9, 'A pregnant client has SLE. Which pregnancy complications should the nurse monitor for?', '[{"id": "a", "text": "A lower risk of lupus flares"}, {"id": "b", "text": "A reduced tendency to form clots"}, {"id": "c", "text": "Miscarriage and preeclampsia"}, {"id": "d", "text": "Complete remission of the disease"}]'::jsonb, '["c"]', 'Pregnancy in SLE increases flare risk and carries risks of miscarriage, preeclampsia, and clots from antiphospholipid syndrome. A lower flare risk or reduced clotting reverses these risks.'),
  ('lupus', 10, 'A client with SLE delivered a baby 2 weeks ago. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "''I need to watch for signs of a flare after delivery.''"}, {"id": "b", "text": "''The postpartum period can trigger a lupus flare.''"}, {"id": "c", "text": "''My lupus will still need monitoring after delivery.''"}, {"id": "d", "text": "''Now that the baby is born, I no longer need close monitoring.''"}]'::jsonb, '["d"]', 'Postpartum is a flare trigger, and close monitoring is needed throughout pregnancy and the postpartum period. Stopping monitoring after delivery is unsafe.'),
  ('lupus', 11, 'The nurse is reviewing health histories at a clinic. Which client has the highest risk profile for developing SLE?', '[{"id": "a", "text": "A 72-year-old woman with no family history"}, {"id": "b", "text": "A 26-year-old woman whose mother has lupus"}, {"id": "c", "text": "A 26-year-old man with no family history"}, {"id": "d", "text": "A 72-year-old man with no family history"}]'::jsonb, '["b"]', 'SLE occurs mainly in women of childbearing age, with a 9:1 female-to-male ratio, and family history is a risk factor. The young woman with an affected mother has both risk factors.'),
  ('lupus', 12, 'A client with SLE asks why lupus can affect so many different organs. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "''Too few antibodies leave the organs unprotected.''"}, {"id": "b", "text": "''Bacteria spread through the blood to each organ.''"}, {"id": "c", "text": "''Wear and tear damages each organ over time.''"}, {"id": "d", "text": "''Immune complexes deposit in tissues and cause inflammation.''"}]'::jsonb, '["d"]', 'In SLE, immune complexes deposit in the kidneys, skin, joints, and blood vessels, causing inflammation and damage. The disease involves antibody production against the body''s own cells, not too few antibodies.'),
  ('lupus', 13, 'The nurse reviews laboratory results for a client with SLE and notes low complement C3 and C4 levels. How should the nurse interpret these results?', '[{"id": "a", "text": "The results confirm the client does not have lupus."}, {"id": "b", "text": "The kidneys are recovering from lupus nephritis."}, {"id": "c", "text": "The disease is active, and complement is being consumed."}, {"id": "d", "text": "The disease is in remission, and inflammation is low."}]'::jsonb, '["c"]', 'Complement C3 and C4 are low during active disease because they are consumed by inflammation. Low levels do not indicate remission.'),
  ('lupus', 14, 'A client says, ''My ANA test was positive, so I definitely have lupus.'' Which response by the nurse is accurate?', '[{"id": "a", "text": "''A positive ANA confirms lupus with certainty.''"}, {"id": "b", "text": "''A positive ANA rules out other diseases.''"}, {"id": "c", "text": "''ANA is a screening test and is not specific to lupus.''"}, {"id": "d", "text": "''ANA is the most specific test for lupus.''"}]'::jsonb, '["c"]', 'ANA is positive in over 95% of clients with SLE but is a screening test that is not specific to lupus. Anti-dsDNA and anti-Sm are the specific, confirmatory tests.'),
  ('lupus', 15, 'A client with a positive ANA is being evaluated for SLE. Which tests does the nurse anticipate to confirm the diagnosis?', '[{"id": "a", "text": "ANA repeated alone"}, {"id": "b", "text": "Complete blood count"}, {"id": "c", "text": "ESR and CRP"}, {"id": "d", "text": "Anti-dsDNA and anti-Sm"}]'::jsonb, '["d"]', 'Anti-dsDNA and anti-Sm are specific to SLE and confirm the diagnosis. ANA is a non-specific screening test, and ESR and CRP are general inflammation markers.'),
  ('lupus', 16, 'A client with SLE has a rising anti-dsDNA level. Which organ involvement should the nurse closely monitor for, based on this result?', '[{"id": "a", "text": "Kidney involvement such as lupus nephritis"}, {"id": "b", "text": "Retinal toxicity in the eyes"}, {"id": "c", "text": "Coin-shaped discoid skin lesions"}, {"id": "d", "text": "Loss of hair from the scalp"}]'::jsonb, '["a"]', 'Anti-dsDNA correlates with disease activity and with lupus nephritis, so rising levels call for close kidney monitoring. Retinal toxicity is related to hydroxychloroquine, not anti-dsDNA.'),
  ('lupus', 17, 'Which laboratory pattern should the nurse recognize as indicating active SLE?', '[{"id": "a", "text": "Elevated anti-dsDNA, low C3/C4, elevated ESR/CRP"}, {"id": "b", "text": "Elevated anti-dsDNA, high C3/C4, low ESR/CRP"}, {"id": "c", "text": "Low anti-dsDNA, high C3/C4, low ESR/CRP"}, {"id": "d", "text": "Low anti-dsDNA, low C3/C4, low ESR/CRP"}]'::jsonb, '["a"]', 'Active disease markers in SLE are increased anti-dsDNA, decreased C3/C4, and increased ESR/CRP. Complement falls, rather than rises, during active disease.'),
  ('lupus', 18, 'A client is being treated for a lupus flare. Which finding best indicates that the flare is responding to treatment?', '[{"id": "a", "text": "New proteinuria is present."}, {"id": "b", "text": "ESR and CRP are decreasing."}, {"id": "c", "text": "Anti-dsDNA is rising."}, {"id": "d", "text": "C3 and C4 are falling."}]'::jsonb, '["b"]', 'ESR and CRP are elevated during flares and active inflammation, so falling values suggest a response to treatment. Rising anti-dsDNA and falling complement indicate active disease.'),
  ('lupus', 19, 'A client with SLE has new ankle edema, elevated blood pressure, and a urinalysis showing protein and blood. Which complication should the nurse suspect?', '[{"id": "a", "text": "Raynaud phenomenon"}, {"id": "b", "text": "Lupus nephritis"}, {"id": "c", "text": "CNS lupus"}, {"id": "d", "text": "Pericarditis"}]'::jsonb, '["b"]', 'Lupus nephritis presents with proteinuria, hematuria, hypertension, and edema. Pericarditis is a cardiac complication and would not explain the urinalysis findings.'),
  ('lupus', 20, 'The nurse is supervising a UAP caring for a client with lupus nephritis. Which action by the UAP requires correction?', '[{"id": "a", "text": "Reporting the client''s blood pressure readings"}, {"id": "b", "text": "Measuring and recording the client''s urine output"}, {"id": "c", "text": "Reporting new swelling in the client''s ankles"}, {"id": "d", "text": "Skipping the daily weight because the client feels well"}]'::jsonb, '["d"]', 'Kidney monitoring in SLE includes daily weights, urine output, edema, and blood pressure. Skipping the daily weight omits a required kidney assessment.'),
  ('lupus', 21, 'The nurse is planning care for a client with SLE. Which complication is the top monitoring priority?', '[{"id": "a", "text": "Lupus nephritis"}, {"id": "b", "text": "Oral ulcers"}, {"id": "c", "text": "Raynaud phenomenon"}, {"id": "d", "text": "Alopecia"}]'::jsonb, '["a"]', 'Lupus nephritis leading to renal failure is the top complication of SLE and the strictest monitoring priority. The other findings are manifestations but not the top priority.'),
  ('lupus', 22, 'A client with SLE reports new chest pain. Which assessment should the nurse perform to detect pericarditis?', '[{"id": "a", "text": "Inspect the face for a malar rash."}, {"id": "b", "text": "Auscultate the heart for a friction rub."}, {"id": "c", "text": "Examine the mouth for oral ulcers."}, {"id": "d", "text": "Check the urine for protein and blood."}]'::jsonb, '["b"]', 'Cardiac monitoring in SLE includes auscultating for a friction rub, which indicates pericarditis. Urine testing monitors for lupus nephritis, not pericarditis.'),
  ('lupus', 23, 'The nurse is reviewing cardiac manifestations of SLE. Which cardiac finding is most common in clients with lupus?', '[{"id": "a", "text": "Libman-Sacks endocarditis"}, {"id": "b", "text": "Myocarditis"}, {"id": "c", "text": "Heart murmur"}, {"id": "d", "text": "Pericarditis"}]'::jsonb, '["d"]', 'Pericarditis is the most common cardiac finding in SLE. Myocarditis, murmurs, and Libman-Sacks endocarditis can occur but are not the most common.'),
  ('lupus', 24, 'A client with SLE asks how lupus affects different body systems. Which pairing of body system and manifestation is accurate?', '[{"id": "a", "text": "Brain — proteinuria and hematuria"}, {"id": "b", "text": "Lungs — pleuritis and pleural effusion"}, {"id": "c", "text": "Blood — butterfly rash and alopecia"}, {"id": "d", "text": "Kidneys — seizures and psychosis"}]'::jsonb, '["b"]', 'SLE affects the lungs with pleuritis and pleural effusion. Seizures and psychosis are neurologic, proteinuria and hematuria are renal, and the butterfly rash and alopecia are skin findings.'),
  ('lupus', 25, 'A client with SLE who was alert earlier now has a seizure and sudden confusion. Which action should the nurse take?', '[{"id": "a", "text": "Attribute the changes to lupus fatigue."}, {"id": "b", "text": "Report the neurologic changes immediately."}, {"id": "c", "text": "Recheck the client at the next shift."}, {"id": "d", "text": "Encourage the client to sleep it off."}]'::jsonb, '["b"]', 'CNS lupus causes seizures, psychosis, and cognitive changes, and sudden neurologic changes must be reported immediately. Attributing them to fatigue delays care.'),
  ('lupus', 26, 'The nurse reviews the CBC of a client with SLE. Which findings are consistent with lupus blood involvement?', '[{"id": "a", "text": "Elevated platelets with normal WBCs"}, {"id": "b", "text": "Polycythemia, leukocytosis, thrombocytosis"}, {"id": "c", "text": "Normal counts in every lupus client"}, {"id": "d", "text": "Anemia, leukopenia, and thrombocytopenia"}]'::jsonb, '["d"]', 'SLE can cause anemia, leukopenia, and thrombocytopenia. Elevated counts reverse the direction of these changes.'),
  ('lupus', 27, 'A client with SLE has antiphospholipid syndrome (APS). The nurse monitors this client for which complication?', '[{"id": "a", "text": "Blood clots such as DVT, PE, or stroke"}, {"id": "b", "text": "Bleeding from a reduced clotting tendency"}, {"id": "c", "text": "Coin-shaped discoid skin lesions"}, {"id": "d", "text": "Retinal toxicity affecting the vision"}]'::jsonb, '["a"]', 'APS causes hypercoagulability with clots in arteries and veins, leading to DVT, PE, or stroke. It increases, rather than reduces, clotting.'),
  ('lupus', 28, 'A client with SLE has had several miscarriages. Which laboratory test does the nurse anticipate to evaluate the cause?', '[{"id": "a", "text": "Antiphospholipid antibodies"}, {"id": "b", "text": "Complement C3 and C4"}, {"id": "c", "text": "Anti-Sm antibodies"}, {"id": "d", "text": "ESR and CRP"}]'::jsonb, '["a"]', 'Antiphospholipid syndrome is associated with recurrent miscarriages, and antiphospholipid antibodies identify this clotting risk. Anti-Sm confirms SLE, and complement levels reflect disease activity.'),
  ('lupus', 29, 'A client with SLE reports fatigue, a low-grade fever, achy joints, a new rash, and ankle swelling. How should the nurse interpret these findings?', '[{"id": "a", "text": "Expected hydroxychloroquine effects"}, {"id": "b", "text": "Signs of disease remission"}, {"id": "c", "text": "Normal findings after sun protection"}, {"id": "d", "text": "Signs of a lupus flare"}]'::jsonb, '["d"]', 'The FLARE mnemonic lists fatigue, low-grade fever, achy joints, rashes, and edema as signs of a flare. These findings indicate active disease, not remission.'),
  ('lupus', 30, 'The nurse teaches a client with SLE to recognize flare signs. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "''Achy joints can mean a flare is starting.''"}, {"id": "b", "text": "''Swelling in my ankles is not a sign of a flare.''"}, {"id": "c", "text": "''A low-grade fever can signal a flare.''"}, {"id": "d", "text": "''A new rash can be a sign of a flare.''"}]'::jsonb, '["b"]', 'Edema is one of the FLARE signs, along with fatigue, low-grade fever, achy joints, and rashes. Dismissing ankle swelling is incorrect.'),
  ('lupus', 31, 'The nurse teaches a client with SLE ways to prevent flares. Which client statement indicates understanding?', '[{"id": "a", "text": "''Sleep has no effect, so staying up late is not a problem.''"}, {"id": "b", "text": "''I''ll avoid all exercise to protect my joints from damage.''"}, {"id": "c", "text": "''Stress has no effect on how often my lupus flares.''"}, {"id": "d", "text": "''I''ll exercise regularly and find ways to lower my stress.''"}]'::jsonb, '["d"]', 'The LESS strategy for preventing flares includes lowering stress, exercising regularly, getting sufficient sleep, and sun protection. Avoiding exercise and ignoring stress or sleep contradict this strategy.'),
  ('lupus', 32, 'A client with SLE who takes prednisone says, ''I feel better, so I''m going to stop my prednisone today.'' Which response by the nurse is appropriate?', '[{"id": "a", "text": "''Steroids should not be stopped abruptly; they are tapered.''"}, {"id": "b", "text": "''Stop it now and restart it only if you have a flare.''"}, {"id": "c", "text": "''You can stop it today since your symptoms are gone.''"}, {"id": "d", "text": "''Cut the dose in half today and stop it tomorrow.''"}]'::jsonb, '["a"]', 'Corticosteroids should not be stopped abruptly and must be tapered slowly. Stopping today or over two days is an abrupt discontinuation.'),
  ('lupus', 33, 'A client with SLE is receiving prednisone. Which laboratory value should the nurse monitor for a common adverse effect of this drug?', '[{"id": "a", "text": "Antiphospholipid antibodies"}, {"id": "b", "text": "Annual eye exam results"}, {"id": "c", "text": "Blood glucose"}, {"id": "d", "text": "Anti-Sm antibody level"}]'::jsonb, '["c"]', 'Corticosteroids can cause infection risk, hyperglycemia, and osteoporosis, so blood glucose is monitored. Annual eye exams are required for hydroxychloroquine.'),
  ('lupus', 34, 'A client is admitted with a severe lupus flare. Which medication does the nurse anticipate for rapid control of the inflammation?', '[{"id": "a", "text": "Hydroxychloroquine"}, {"id": "b", "text": "Naproxen"}, {"id": "c", "text": "Prednisone"}, {"id": "d", "text": "Belimumab"}]'::jsonb, '["c"]', 'Corticosteroids such as prednisone provide rapid control of severe inflammation and flares. Hydroxychloroquine takes months to work, and NSAIDs are used for mild inflammation.'),
  ('lupus', 35, 'A client with lupus nephritis has been taking over-the-counter ibuprofen for joint pain. Which concern should the nurse discuss with the provider?', '[{"id": "a", "text": "NSAIDs can cause retinal toxicity."}, {"id": "b", "text": "NSAIDs can cause suicidal ideation."}, {"id": "c", "text": "NSAIDs can impair kidney function."}, {"id": "d", "text": "NSAIDs can lower blood glucose."}]'::jsonb, '["c"]', 'NSAID side effects include GI bleeding and kidney impairment, which is a concern for a client with lupus nephritis. Retinal toxicity is linked to hydroxychloroquine, and suicidal ideation to belimumab.'),
  ('lupus', 36, 'The nurse teaches a client with SLE who takes naproxen for joint pain. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "''I take my naproxen with a meal or snack.''"}, {"id": "b", "text": "''Naproxen is used for my mild joint pain.''"}, {"id": "c", "text": "''I take my naproxen on an empty stomach.''"}, {"id": "d", "text": "''I will report any signs of GI bleeding.''"}]'::jsonb, '["c"]', 'NSAIDs are used for mild inflammation and joint pain and should be taken with food because of GI bleeding risk. Taking them on an empty stomach needs correction.'),
  ('lupus', 37, 'A client with SLE is starting hydroxychloroquine. Which teaching point should the nurse include?', '[{"id": "a", "text": "Schedule an eye examination every year."}, {"id": "b", "text": "Check blood pressure before each dose."}, {"id": "c", "text": "Schedule a TB test before each dose."}, {"id": "d", "text": "Expect full effect within a few days."}]'::jsonb, '["a"]', 'Hydroxychloroquine requires annual eye exams because of retinal toxicity, and it takes months to work. Expecting results in days is incorrect.'),
  ('lupus', 38, 'A client with SLE has taken hydroxychloroquine for 3 weeks and says, ''It isn''t working, so I''m going to stop it.'' Which response by the nurse is accurate?', '[{"id": "a", "text": "''It works within days, so stopping is reasonable.''"}, {"id": "b", "text": "''If it hasn''t worked by now, it never will.''"}, {"id": "c", "text": "''Double the dose to make it work faster.''"}, {"id": "d", "text": "''It can take months before you notice its effects.''"}]'::jsonb, '["d"]', 'Hydroxychloroquine takes months to show effects, so lack of benefit at 3 weeks is expected. Stopping it or doubling the dose is inappropriate.'),
  ('lupus', 39, 'A client with SLE who smokes a pack of cigarettes daily is prescribed hydroxychloroquine. Which information should the nurse include in the teaching?', '[{"id": "a", "text": "Smoking decreases the drug''s effectiveness."}, {"id": "b", "text": "Smoking increases the drug''s effectiveness."}, {"id": "c", "text": "Smoking has no effect on this medication."}, {"id": "d", "text": "Smoking removes the need for eye exams."}]'::jsonb, '["a"]', 'Smoking decreases the effectiveness of hydroxychloroquine. Annual eye exams are still required regardless of smoking.'),
  ('lupus', 40, 'A client with SLE who has no current symptoms asks why hydroxychloroquine must be taken every day. Which response by the nurse is accurate?', '[{"id": "a", "text": "''It is taken long term to help prevent flares.''"}, {"id": "b", "text": "''It quickly controls severe inflammation.''"}, {"id": "c", "text": "''It is used to replace your sunscreen.''"}, {"id": "d", "text": "''It is only needed during an active flare.''"}]'::jsonb, '["a"]', 'Hydroxychloroquine is used for long-term flare prevention and is the mainstay of therapy. Rapid control of severe inflammation is the role of corticosteroids.'),
  ('lupus', 41, 'The nurse teaches a client with SLE who takes mycophenolate. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "''I can get the nasal spray flu vaccine this year.''"}, {"id": "b", "text": "''I will report a fever or new cough right away.''"}, {"id": "c", "text": "''I will wash my hands often to prevent infection.''"}, {"id": "d", "text": "''I will tell providers I take an immunosuppressant.''"}]'::jsonb, '["a"]', 'Immunosuppressants such as mycophenolate increase infection risk, and live vaccines, including the nasal flu vaccine, must be avoided. Hand hygiene and reporting fever or cough are correct.'),
  ('lupus', 42, 'A client with SLE is taking azathioprine. The nurse reviews new orders. Which order should the nurse question?', '[{"id": "a", "text": "Obtain a CBC and urinalysis today."}, {"id": "b", "text": "Monitor the blood pressure each shift."}, {"id": "c", "text": "Administer the MMR vaccine today."}, {"id": "d", "text": "Obtain a daily weight each morning."}]'::jsonb, '["c"]', 'Live vaccines such as MMR, varicella, and nasal flu should not be given to clients on immunosuppressants such as azathioprine. Daily weights, blood pressure, CBC, and urinalysis are appropriate monitoring.'),
  ('lupus', 43, 'A client with SLE receiving immunosuppressive therapy reports a fever, a new cough, and redness around a healing cut. Which action should the nurse take?', '[{"id": "a", "text": "Recheck the findings in one month."}, {"id": "b", "text": "Advise doubling the immunosuppressant dose."}, {"id": "c", "text": "Report the findings as a possible infection."}, {"id": "d", "text": "Teach that these are normal lupus symptoms."}]'::jsonb, '["c"]', 'Immunosuppressive therapy increases the risk of opportunistic infections, so fever, cough, and wound changes must be monitored and reported. Assuming these are normal lupus symptoms delays care.'),
  ('lupus', 44, 'A client with lupus nephritis is started on mycophenolate and asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "''It protects the eyes from retinal toxicity.''"}, {"id": "b", "text": "''It is a pain reliever for mild joint aches.''"}, {"id": "c", "text": "''It treats severe disease and reduces steroid needs.''"}, {"id": "d", "text": "''It is a sunscreen taken by mouth for UV protection.''"}]'::jsonb, '["c"]', 'Azathioprine and mycophenolate are immunosuppressants used for severe disease, as steroid-sparing agents, and for lupus nephritis. Mild joint pain is treated with NSAIDs.'),
  ('lupus', 45, 'A client with SLE receiving belimumab says, ''I''ve been feeling hopeless and wonder what the point is.'' Which action should the nurse take?', '[{"id": "a", "text": "Assess for suicidal ideation and report it."}, {"id": "b", "text": "Document the comment as a normal effect."}, {"id": "c", "text": "Suggest the client double the next dose."}, {"id": "d", "text": "Reassure the client it is a passing mood."}]'::jsonb, '["a"]', 'Clients receiving belimumab must be monitored for depression and suicidal ideation. Dismissing hopelessness as a passing mood misses this serious adverse effect.'),
  ('lupus', 46, 'A client with SLE reports memory problems and says, ''I feel down most days and can''t cope with this illness.'' Which nursing action is most appropriate?', '[{"id": "a", "text": "Tell the client mood is unrelated to lupus."}, {"id": "b", "text": "Explain that lupus does not affect the brain."}, {"id": "c", "text": "Defer the concern until the next annual visit."}, {"id": "d", "text": "Assess for depression, anxiety, and coping."}]'::jsonb, '["d"]', 'SLE can cause memory loss and mood disorders such as depression, and nursing care includes assessing depression, anxiety, and coping with chronic illness. Lupus does affect the brain.'),
  ('lupus', 47, 'A client whose SLE has been quiet for several months says, ''I think my lupus is cured.'' Which response by the nurse is accurate?', '[{"id": "a", "text": "''Lupus is chronic, with flares and remissions.''"}, {"id": "b", "text": "''Yes, lupus usually resolves after one flare.''"}, {"id": "c", "text": "''Once in remission, flares no longer occur.''"}, {"id": "d", "text": "''Lupus is short-term and does not come back.''"}]'::jsonb, '["a"]', 'SLE is a chronic disease with a long-lasting, relapsing-remitting course of flares and remissions. A period without symptoms is a remission, not a cure.'),
  ('lupus', 48, 'A client with SLE in remission has mild joint pain. Which intervention is most appropriate for joint care?', '[{"id": "a", "text": "Applying the joints to direct sunlight"}, {"id": "b", "text": "Range-of-motion exercises and a PT referral"}, {"id": "c", "text": "Avoiding all movement of the joints"}, {"id": "d", "text": "Strict bed rest until the pain is gone"}]'::jsonb, '["b"]', 'Joint care in SLE includes pain management, PT referral, and range-of-motion exercise during remissions. Immobility contradicts this, and sun exposure triggers flares.'),
  ('lupus', 49, 'A client newly diagnosed with SLE has painful, swollen joints and asks, ''Is this part of my lupus?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "''Yes, lupus can cause arthritis-like joint pain and swelling.''"}, {"id": "b", "text": "''No, lupus affects only the skin, so this is something else.''"}, {"id": "c", "text": "''No, lupus affects only the kidneys and not the joints.''"}, {"id": "d", "text": "''No, joint swelling never occurs in a person with lupus.''"}]'::jsonb, '["a"]', 'SLE is systemic and affects multiple organ systems, including the joints, with arthritis-like pain and swollen joints. Lupus is not limited to the skin or kidneys.'),
  ('lupus', 50, 'A client asks how lupus develops. Which sequence of events correctly describes the pathophysiology of SLE?', '[{"id": "a", "text": "Defective apoptosis, ANA formation, immune complex deposition, complement activation"}, {"id": "b", "text": "Complement activation, immune complex deposition, ANA formation, defective apoptosis"}, {"id": "c", "text": "ANA formation, complement activation, defective apoptosis, immune complex deposition"}, {"id": "d", "text": "Immune complex deposition, defective apoptosis, complement activation, ANA formation"}]'::jsonb, '["a"]', 'In SLE, defective apoptosis leaves cells uncleared, ANA forms, immune complexes deposit in tissues, and complement is activated and consumed, causing inflammation. Starting with complement activation reverses the process.'),
  ('cdiff', 1, 'A client with mild C. diff is prescribed metronidazole because other agents are unavailable. Which statement about this medication is accurate?', '[{"id": "a", "text": "It is a less effective alternative used for mild disease"}, {"id": "b", "text": "It is the most effective first-line drug for C. diff"}, {"id": "c", "text": "It is a monoclonal antibody that prevents recurrence"}, {"id": "d", "text": "It restores the gut microbiome using donor stool"}]'::jsonb, '["a"]', 'Metronidazole is an alternative when other drugs are unavailable; it is less effective and used for mild disease. Oral vancomycin and fidaxomicin are first-line.'),
  ('cdiff', 2, 'The nurse observes environmental services staff cleaning the room of a client with C. diff. Which action requires correction?', '[{"id": "a", "text": "Applying a bleach solution to the bed rails"}, {"id": "b", "text": "Wearing a gown and gloves while cleaning"}, {"id": "c", "text": "Cleaning the commode thoroughly before reuse"}, {"id": "d", "text": "Wiping all surfaces with an alcohol cleaner"}]'::jsonb, '["d"]', 'Bleach is used for environmental decontamination in C. diff because alcohol does not kill spores. Bleach cleaning, gown and gloves, and cleaning the commode are correct.'),
  ('cdiff', 3, 'A client with C. diff develops toxic megacolon. Which description of this complication is accurate?', '[{"id": "a", "text": "Mild colon irritation that resolves on its own"}, {"id": "b", "text": "Narrowing of the colon that causes constipation"}, {"id": "c", "text": "Massive colon dilation that is a surgical emergency"}, {"id": "d", "text": "Small ulcers limited to the rectal lining"}]'::jsonb, '["c"]', 'Toxic megacolon is a massive, life-threatening dilation of the colon and a surgical emergency. It is not mild or self-limiting.'),
  ('cdiff', 4, 'The nurse has finished providing care to a client with C. diff and has removed gloves. Which hand hygiene action is correct?', '[{"id": "a", "text": "Rub hands with an alcohol-based sanitizer"}, {"id": "b", "text": "Apply alcohol gel and then put on new gloves"}, {"id": "c", "text": "Wipe hands with the bleach surface cleaner"}, {"id": "d", "text": "Wash hands with soap and water"}]'::jsonb, '["d"]', 'Alcohol-based hand sanitizers do not kill C. diff spores, so soap and water must be used. Bleach solution is for environmental cleaning.'),
  ('cdiff', 5, 'The nurse is caring for a client with confirmed C. diff. Which stool characteristic does the nurse expect?', '[{"id": "a", "text": "Odorless, formed stools"}, {"id": "b", "text": "Small, hard pellet stools"}, {"id": "c", "text": "Foul-smelling, loose stools"}, {"id": "d", "text": "Infrequent, dry stools"}]'::jsonb, '["c"]', 'C. diff causes loose stools with a distinctive foul odor. Formed, hard, or infrequent stools do not fit the presentation.'),
  ('cdiff', 6, 'A client with C. diff develops spread of the infection throughout the body. The nurse recognizes this as which complication?', '[{"id": "a", "text": "Sepsis or septic shock"}, {"id": "b", "text": "Pseudomembranous colitis"}, {"id": "c", "text": "Recurrent C. diff"}, {"id": "d", "text": "Toxic megacolon"}]'::jsonb, '["a"]', 'Sepsis and septic shock result from systemic spread of the infection. Pseudomembranous colitis and toxic megacolon are complications confined to the colon.'),
  ('cdiff', 7, 'The nurse reviews laboratory results for a client with C. diff. Which result is expected?', '[{"id": "a", "text": "A decreased white blood cell count"}, {"id": "b", "text": "A normal white blood cell count"}, {"id": "c", "text": "An increased serum albumin level"}, {"id": "d", "text": "An elevated white blood cell count"}]'::jsonb, '["d"]', 'Leukocytosis (elevated WBC) is expected and can be very high. Albumin is decreased, not increased, in severe disease.'),
  ('cdiff', 8, 'The provider orders a test to detect C. diff toxin A and toxin B. Which specimen should the nurse plan to collect?', '[{"id": "a", "text": "A stool specimen"}, {"id": "b", "text": "A blood culture"}, {"id": "c", "text": "A urine specimen"}, {"id": "d", "text": "A sputum specimen"}]'::jsonb, '["a"]', 'The stool toxin assay detects toxin A and/or B and is the most common diagnostic test. Blood, urine, and sputum specimens do not detect C. diff toxins.'),
  ('cdiff', 9, 'The nurse reviews the prescriptions for a client with C. diff. Which prescription should the nurse question?', '[{"id": "a", "text": "Loperamide as needed for diarrhea"}, {"id": "b", "text": "Oral vancomycin as first-line therapy"}, {"id": "c", "text": "Fidaxomicin by mouth as first-line therapy"}, {"id": "d", "text": "Oral metronidazole for mild disease"}]'::jsonb, '["a"]', 'Antidiarrheals such as loperamide are contraindicated in C. diff because of the risk of toxic megacolon. The other medications are listed treatments.'),
  ('cdiff', 10, 'The nurse is providing discharge teaching to a client recovering from C. diff. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wash my hands with soap and water.\""}, {"id": "b", "text": "\"I can take Imodium if the diarrhea keeps going.\""}, {"id": "c", "text": "\"I will take my vancomycin by mouth as directed.\""}, {"id": "d", "text": "\"I will clean the bathroom using a bleach solution.\""}]'::jsonb, '["b"]', 'Antidiarrheals such as Imodium are contraindicated because of the risk of toxic megacolon. Soap and water, oral vancomycin, and bleach cleaning are correct.'),
  ('cdiff', 11, 'A client being treated for a second episode of C. diff says, "Now that I''ve had it twice, I''m probably immune." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, each episode lowers your risk of another.\""}, {"id": "b", "text": "\"Your risk is now the same as anyone else''s.\""}, {"id": "c", "text": "\"The risk of recurrence increases with each episode.\""}, {"id": "d", "text": "\"Your risk disappears after the second episode.\""}]'::jsonb, '["c"]', 'The recurrence rate increases with each episode, and a previous C. diff infection is itself a risk factor. Prior infection does not lower risk.'),
  ('cdiff', 12, 'The family of a client with C. diff asks when the gown-and-glove requirement will end. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"As soon as the first antibiotic dose is given.\""}, {"id": "b", "text": "\"Once the fever has gone away for one day.\""}, {"id": "c", "text": "\"When diarrhea has resolved for over 48 hours.\""}, {"id": "d", "text": "\"After 24 hours of antibiotic therapy.\""}]'::jsonb, '["c"]', 'Contact precautions continue until diarrhea resolves, more than 48 hours after the last loose stool. Starting antibiotics does not end precautions.'),
  ('cdiff', 13, 'A client with C. diff is admitted to the medical unit. Which action should the nurse take?', '[{"id": "a", "text": "Wear gloves only when handling stool"}, {"id": "b", "text": "Wear a surgical mask instead of a gown"}, {"id": "c", "text": "Put on a gown and gloves on room entry"}, {"id": "d", "text": "Place the client in a shared room"}]'::jsonb, '["c"]', 'C. diff requires contact precautions: a private room with gown and gloves on entry. Gloves only for stool or a shared room do not meet contact precautions.'),
  ('cdiff', 14, 'A nurse educator is explaining to new staff why C. diff prevention is a priority on the unit. Which statement by the educator is accurate?', '[{"id": "a", "text": "\"It is the top cause of healthcare-associated infectious diarrhea.\""}, {"id": "b", "text": "\"It is spread mainly through particles that linger in the air.\""}, {"id": "c", "text": "\"It rarely occurs in clients who are hospitalized.\""}, {"id": "d", "text": "\"It affects only clients who are younger than 65.\""}]'::jsonb, '["a"]', 'C. diff is the #1 cause of healthcare-associated infectious diarrhea in the U.S. Recent hospitalization increases risk, and older adults are the most vulnerable.'),
  ('cdiff', 15, 'A client receiving clindamycin for a skin infection reports 4 watery stools in the past 24 hours. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "C. diff infection should be suspected"}, {"id": "b", "text": "The diarrhea is expected and needs no follow-up"}, {"id": "c", "text": "The client needs an antidiarrheal right away"}, {"id": "d", "text": "The diarrhea shows the antibiotic is working"}]'::jsonb, '["a"]', 'Any client with diarrhea after antibiotic use, especially clindamycin, should be suspected of C. diff until proven otherwise. Antidiarrheals are contraindicated in C. diff.'),
  ('cdiff', 16, 'A client with C. diff has been receiving oral vancomycin for several days. Which finding indicates the treatment is effective?', '[{"id": "a", "text": "Stools remain watery and foul-smelling"}, {"id": "b", "text": "Abdominal distension is increasing"}, {"id": "c", "text": "Diarrhea has stopped and cramps resolved"}, {"id": "d", "text": "Rebound tenderness has newly developed"}]'::jsonb, '["c"]', 'Resolution of the key symptoms of profuse watery diarrhea and abdominal cramps indicates improvement. Increasing distension or new rebound tenderness signals severe disease.'),
  ('cdiff', 17, 'The provider orders a test that detects the GDH antigen and toxin in a client with suspected C. diff. The nurse recognizes this as which test?', '[{"id": "a", "text": "A chest x-ray"}, {"id": "b", "text": "A blood culture"}, {"id": "c", "text": "A urinalysis"}, {"id": "d", "text": "An enzyme immunoassay (EIA)"}]'::jsonb, '["d"]', 'The enzyme immunoassay (EIA) detects the GDH antigen plus toxin. Chest x-ray, blood culture, and urinalysis are not listed C. diff tests.'),
  ('cdiff', 18, 'A client who recently completed a course of cephalosporins is being assessed for C. diff. Which group of findings is consistent with this infection?', '[{"id": "a", "text": "Low-grade fever, abdominal cramping, and anorexia"}, {"id": "b", "text": "Hard stools, abdominal fullness, and weight gain"}, {"id": "c", "text": "Productive cough, chest pain, and dyspnea"}, {"id": "d", "text": "Joint pain, skin rash, and dry eyes"}]'::jsonb, '["a"]', 'C. diff presents with low-grade fever, diffuse abdominal cramping, nausea, and anorexia. Hard stools are the opposite of the expected diarrhea.'),
  ('cdiff', 19, 'The nurse is teaching a client about oral vancomycin for C. diff. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will get this medicine through my IV line.\""}, {"id": "b", "text": "\"I will take it by mouth so it reaches my colon.\""}, {"id": "c", "text": "\"I will stop it once my diarrhea slows down.\""}, {"id": "d", "text": "\"I will take loperamide with each dose of it.\""}]'::jsonb, '["b"]', 'Vancomycin must be given orally to reach the colon and is taken for 10–14 days. IV vancomycin is ineffective, and antidiarrheals are contraindicated.'),
  ('cdiff', 20, 'The nurse receives report on four clients with C. diff. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with foul-smelling, loose stools"}, {"id": "b", "text": "A client with nausea and decreased appetite"}, {"id": "c", "text": "A client with a low-grade fever this morning"}, {"id": "d", "text": "A client with abdominal distension and rebound tenderness"}]'::jsonb, '["d"]', 'Abdominal distension with rebound tenderness indicates severe disease such as toxic megacolon, a life-threatening surgical emergency. The other findings are expected C. diff symptoms.'),
  ('cdiff', 21, 'The nurse is reviewing the treatment plan for a client newly diagnosed with C. diff. Which medications are first-line options?', '[{"id": "a", "text": "Intravenous vancomycin or loperamide"}, {"id": "b", "text": "Metronidazole or loperamide"}, {"id": "c", "text": "Intravenous vancomycin or bezlotoxumab"}, {"id": "d", "text": "Oral vancomycin or fidaxomicin"}]'::jsonb, '["d"]', 'First-line treatment is oral vancomycin or fidaxomicin, not IV vancomycin. Loperamide is contraindicated in C. diff.'),
  ('cdiff', 22, 'A client with C. diff is concerned about the infection coming back. Which medication is preferred for recurrence prevention as a first-line treatment?', '[{"id": "a", "text": "Intravenous vancomycin"}, {"id": "b", "text": "Loperamide"}, {"id": "c", "text": "Fidaxomicin"}, {"id": "d", "text": "Metronidazole"}]'::jsonb, '["c"]', 'Fidaxomicin is first-line and preferred for recurrence prevention. Metronidazole is a less effective alternative, and IV vancomycin does not reach the colon.'),
  ('cdiff', 23, 'A client is admitted with new-onset profuse, watery diarrhea. Which history finding most supports suspecting C. diff?', '[{"id": "a", "text": "No medications taken in the past year"}, {"id": "b", "text": "A recent hospital stay with antibiotic therapy"}, {"id": "c", "text": "Age of 30 years with no chronic illness"}, {"id": "d", "text": "No prior hospital stays or infections"}]'::jsonb, '["b"]', 'Recent hospitalization and recent antibiotic use are risk factors for C. diff. The other histories contain no listed risk factors.'),
  ('cdiff', 24, 'A nursing student is preparing a care plan for a client with C. diff. Which description of the organism is accurate?', '[{"id": "a", "text": "A gram-negative virus that spreads by droplets"}, {"id": "b", "text": "An aerobic fungus that lives in the lungs"}, {"id": "c", "text": "A parasite that is acquired from undercooked meat"}, {"id": "d", "text": "A gram-positive bacterium that forms spores"}]'::jsonb, '["d"]', 'C. diff is a gram-positive, spore-forming, anaerobic bacterium. It is not a virus, fungus, or parasite.'),
  ('cdiff', 25, 'The nurse is supervising care on a unit where one client has C. diff. Which action requires correction?', '[{"id": "a", "text": "Putting on a gown and gloves before entering the room"}, {"id": "b", "text": "Washing hands with soap and water after leaving the room"}, {"id": "c", "text": "Cleaning the client''s room surfaces with a bleach solution"}, {"id": "d", "text": "Letting another client use the commode without cleaning it"}]'::jsonb, '["d"]', 'Shared commodes or bathrooms must not be used without thorough cleaning between uses. The other actions are correct C. diff infection control measures.'),
  ('cdiff', 26, 'The nurse reviews the laboratory results of a client with C. diff. Which combination indicates severe disease?', '[{"id": "a", "text": "Low WBC and high albumin"}, {"id": "b", "text": "Normal creatinine and normal albumin"}, {"id": "c", "text": "Low albumin and elevated creatinine"}, {"id": "d", "text": "Low creatinine and high albumin"}]'::jsonb, '["c"]', 'Severe C. diff is associated with elevated WBC, hypoalbuminemia, and elevated creatinine. High albumin and low WBC are the reverse of expected findings.'),
  ('cdiff', 27, 'The daughter of a client with C. diff asks why she cannot use the hand sanitizer by the door. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Alcohol gel dries out the skin too much.\""}, {"id": "b", "text": "\"Alcohol gel does not kill C. diff spores.\""}, {"id": "c", "text": "\"Alcohol gel spreads bacteria into the air.\""}, {"id": "d", "text": "\"Alcohol gel is meant for staff use only.\""}]'::jsonb, '["b"]', 'Alcohol gel does not kill C. diff spores, so soap and water is required. Skin dryness is not the reason it is avoided.'),
  ('cdiff', 28, 'The nurse is reviewing the histories of four clients. Which client is at greatest risk for C. diff infection?', '[{"id": "a", "text": "A 30-year-old outpatient taking acetaminophen as needed"}, {"id": "b", "text": "A 72-year-old nursing home resident who recently took ciprofloxacin"}, {"id": "c", "text": "A 40-year-old taking a daily multivitamin with no recent illness"}, {"id": "d", "text": "A 25-year-old being treated at home for a sprained ankle"}]'::jsonb, '["b"]', 'Recent fluoroquinolone (ciprofloxacin) use, age over 65, and a long-term care stay are all risk factors for C. diff. The other clients have none of the listed risk factors.'),
  ('cdiff', 29, 'A colonoscopy report for a client with C. diff describes toxin-induced colon inflammation with white and yellow membrane plaques. The nurse recognizes this as which complication?', '[{"id": "a", "text": "Pseudomembranous colitis"}, {"id": "b", "text": "Toxic megacolon"}, {"id": "c", "text": "Bowel perforation"}, {"id": "d", "text": "Septic shock"}]'::jsonb, '["a"]', 'Pseudomembranous colitis is toxin-induced colon inflammation with white/yellow membrane plaques. Toxic megacolon is massive dilation of the colon.'),
  ('cdiff', 30, 'A client with C. diff undergoes a sigmoidoscopy. Which finding confirms pseudomembranous colitis?', '[{"id": "a", "text": "Smooth, pink mucosa without lesions"}, {"id": "b", "text": "Yellow-white plaques on the colon wall"}, {"id": "c", "text": "A narrowed colon with no inflammation"}, {"id": "d", "text": "Normal mucosa with a single polyp"}]'::jsonb, '["b"]', 'Pseudomembranes, seen as yellow-white plaques on the colon wall, confirm pseudomembranous colitis. A normal-appearing mucosa would not confirm the diagnosis.'),
  ('cdiff', 31, 'The nurse is planning care for a client on contact precautions for C. diff. Which action reflects correct use of equipment?', '[{"id": "a", "text": "Keeping a dedicated blood pressure cuff in the room"}, {"id": "b", "text": "Using the unit''s shared stethoscope after wiping it"}, {"id": "c", "text": "Bringing the hallway thermometer in for each check"}, {"id": "d", "text": "Sharing the client''s commode with the roommate"}]'::jsonb, '["a"]', 'Dedicated patient equipment such as the thermometer, blood pressure cuff, and stethoscope is required. Shared equipment and shared commodes spread spores.'),
  ('cdiff', 32, 'A client with severe C. diff colitis is at risk for bowel perforation. The nurse monitors for which progression if perforation occurs?', '[{"id": "a", "text": "Constipation followed by bowel obstruction"}, {"id": "b", "text": "Dehydration followed by kidney stones"}, {"id": "c", "text": "Bleeding followed by anemia only"}, {"id": "d", "text": "Peritonitis followed by sepsis"}]'::jsonb, '["d"]', 'Bowel perforation is a rupture of the colonic wall that leads to peritonitis and then sepsis. The other progressions are not described for perforation.'),
  ('cdiff', 33, 'A client with C. diff has a white blood cell count of 32,000/mm³. How should the nurse interpret this result?', '[{"id": "a", "text": "Leukocytosis, which can be very high in C. diff"}, {"id": "b", "text": "A sign that the infection has fully resolved"}, {"id": "c", "text": "A low count showing the client cannot fight infection"}, {"id": "d", "text": "A normal value that requires no further attention"}]'::jsonb, '["a"]', 'Leukocytosis is expected in C. diff and is sometimes very high, above 30,000. It does not indicate resolution of the infection.'),
  ('cdiff', 34, 'A client is being treated for a third episode of C. diff. Which therapy does the nurse anticipate for this recurrent infection?', '[{"id": "a", "text": "Loperamide after each stool"}, {"id": "b", "text": "Intravenous vancomycin"}, {"id": "c", "text": "Fecal microbiota transplant"}, {"id": "d", "text": "A proton pump inhibitor"}]'::jsonb, '["c"]', 'Fecal microbiota transplant is used for recurrent C. diff and restores a healthy gut microbiome. PPIs are a risk factor, and loperamide is contraindicated.'),
  ('cdiff', 35, 'A client with C. diff asks the nurse for loperamide to control the diarrhea. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"I will bring you a dose right away.\""}, {"id": "b", "text": "\"Take one after each loose stool you have.\""}, {"id": "c", "text": "\"It will help your antibiotic work better.\""}, {"id": "d", "text": "\"It could trap toxins inside your colon.\""}]'::jsonb, '["d"]', 'Antidiarrheals slow bowel motility and trap toxins in the colon, causing toxic megacolon. They are contraindicated in C. diff.'),
  ('cdiff', 36, 'A client diagnosed with C. diff asks why an antibiotic led to this infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The antibiotic directly damaged your colon lining.\""}, {"id": "b", "text": "\"The antibiotic disrupted your normal gut flora.\""}, {"id": "c", "text": "\"The antibiotic was contaminated with bacteria.\""}, {"id": "d", "text": "\"The antibiotic caused an allergy in your bowel.\""}]'::jsonb, '["b"]', 'C. diff thrives when the normal gut flora is disrupted by antibiotics. The antibiotic itself does not directly damage the colon; the bacterium''s toxins cause the inflammation.'),
  ('cdiff', 37, 'The nurse is reconciling the home medications of a client admitted with new-onset diarrhea. Which home medication is a risk factor for C. diff?', '[{"id": "a", "text": "An acetaminophen tablet as needed"}, {"id": "b", "text": "A topical skin moisturizer"}, {"id": "c", "text": "A proton pump inhibitor"}, {"id": "d", "text": "A daily multivitamin"}]'::jsonb, '["c"]', 'Use of proton pump inhibitors (PPIs) is a listed risk factor for C. diff. The other medications are not identified as risk factors.'),
  ('cdiff', 38, 'The nurse is caring for a client with C. diff. Which new finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Nausea after most meals today"}, {"id": "b", "text": "Abdominal distension with rebound tenderness"}, {"id": "c", "text": "Foul-smelling, loose stools"}, {"id": "d", "text": "Mild, diffuse abdominal cramping"}]'::jsonb, '["b"]', 'Rebound tenderness and abdominal distension signal severe disease such as toxic megacolon. Nausea, foul-smelling stool, and cramping are expected findings.'),
  ('cdiff', 39, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client with C. diff. Which action by the UAP requires correction?', '[{"id": "a", "text": "Using alcohol gel on the hands after leaving the room"}, {"id": "b", "text": "Washing the hands with soap and water after care"}, {"id": "c", "text": "Putting on a gown and gloves before entering the room"}, {"id": "d", "text": "Using the dedicated thermometer kept in the room"}]'::jsonb, '["a"]', 'Alcohol-based hand sanitizers do not kill C. diff spores, so the UAP must wash with soap and water. Gown and gloves on entry and dedicated equipment are correct.'),
  ('cdiff', 40, 'The nurse on an oncology unit is reviewing client risk for C. diff. Which client is at highest risk?', '[{"id": "a", "text": "A 28-year-old with an ankle fracture who takes no medications"}, {"id": "b", "text": "A client with cancer who is immunocompromised and on antibiotics"}, {"id": "c", "text": "A 40-year-old admitted for elective surgery with no antibiotics"}, {"id": "d", "text": "A 35-year-old being observed overnight for a migraine headache"}]'::jsonb, '["b"]', 'Immunocompromised clients, including those with cancer, and clients on antibiotics are at increased risk for C. diff. The other clients have no listed risk factors.'),
  ('cdiff', 41, 'A client with C. diff had the last loose stool 24 hours ago. Which action regarding isolation should the nurse take?', '[{"id": "a", "text": "Discontinue contact precautions now"}, {"id": "b", "text": "Continue contact precautions"}, {"id": "c", "text": "Change to standard precautions only"}, {"id": "d", "text": "Change to droplet precautions"}]'::jsonb, '["b"]', 'Contact precautions continue until diarrhea resolves, more than 48 hours after the last loose stool. Only 24 hours have passed, so precautions must continue.'),
  ('cdiff', 42, 'A client with C. diff asks why fidaxomicin was chosen. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It slows your bowel so the diarrhea stops.\""}, {"id": "b", "text": "\"It is given IV so it reaches your bloodstream.\""}, {"id": "c", "text": "\"It replaces your gut bacteria with donor stool.\""}, {"id": "d", "text": "\"It targets C. diff with less harm to normal flora.\""}]'::jsonb, '["d"]', 'Fidaxomicin targets C. diff with less disruption to normal gut flora. Slowing the bowel describes an antidiarrheal, which is contraindicated.'),
  ('cdiff', 43, 'A client with C. diff asks how the bacteria make the bowel so inflamed. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The bacteria spread through your blood first.\""}, {"id": "b", "text": "\"The bacteria block the flow of bile to your gut.\""}, {"id": "c", "text": "\"The bacteria release toxins that inflame the colon.\""}, {"id": "d", "text": "\"The bacteria cause your colon to stop moving.\""}]'::jsonb, '["c"]', 'C. diff produces toxins A and B that cause inflammation of the colon. Bloodstream spread is not how colitis develops.'),
  ('cdiff', 44, 'A client with C. diff is being discharged from a private room. Which product should be used for environmental cleaning of the room?', '[{"id": "a", "text": "An alcohol-based surface wipe"}, {"id": "b", "text": "Plain warm tap water"}, {"id": "c", "text": "A bleach (sodium hypochlorite) solution"}, {"id": "d", "text": "Antibacterial hand soap"}]'::jsonb, '["c"]', 'Bleach (sodium hypochlorite) solution is used for environmental cleaning because it kills spores. Alcohol does not kill C. diff spores.'),
  ('cdiff', 45, 'The nurse is teaching a community group about C. diff risk factors. Which statement by a participant indicates a need for further teaching?', '[{"id": "a", "text": "\"Mostly young children are at risk for C. diff.\""}, {"id": "b", "text": "\"Recent antibiotic use raises my risk of C. diff.\""}, {"id": "c", "text": "\"A long-term care stay raises the risk of C. diff.\""}, {"id": "d", "text": "\"Having had C. diff before raises my risk again.\""}]'::jsonb, '["a"]', 'Older adults over 65 are the most vulnerable to C. diff, so focusing on young children is incorrect. Recent antibiotics, long-term care stays, and prior infection are true risk factors.'),
  ('cdiff', 46, 'The nurse is collecting a history from a client admitted with profuse watery diarrhea. Which finding is a risk factor for C. diff?', '[{"id": "a", "text": "Age of 45 years"}, {"id": "b", "text": "No hospital stays in several years"}, {"id": "c", "text": "A daily walking routine"}, {"id": "d", "text": "A previous C. diff infection"}]'::jsonb, '["d"]', 'A previous C. diff infection is a listed risk factor. Age is a risk factor only when over 65, and the absence of recent hospitalization lowers rather than raises risk.'),
  ('cdiff', 47, 'A client completing treatment for a first episode of C. diff asks about the chance of the infection returning. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Once treated, it does not return.\""}, {"id": "b", "text": "\"About 25 to 30 percent of people have it return.\""}, {"id": "c", "text": "\"Nearly everyone has it return within a year.\""}, {"id": "d", "text": "\"It returns only if vancomycin was given IV.\""}]'::jsonb, '["b"]', 'C. diff has a 25–30% recurrence rate, and the rate increases with each episode. It is not guaranteed to stay away after treatment.'),
  ('cdiff', 48, 'A client at high risk for recurrent C. diff is scheduled to receive bezlotoxumab. The nurse explains that the purpose of this drug is to:', '[{"id": "a", "text": "Slow bowel motility to stop diarrhea"}, {"id": "b", "text": "Prevent recurrence of the infection"}, {"id": "c", "text": "Replace normal flora with donor stool"}, {"id": "d", "text": "Disinfect the client''s room surfaces"}]'::jsonb, '["b"]', 'Bezlotoxumab is a monoclonal antibody that prevents recurrence in high-risk clients. Replacing flora with donor stool describes fecal microbiota transplant.'),
  ('cdiff', 49, 'The nurse is assessing a client with suspected C. diff. Which finding is the hallmark of this infection?', '[{"id": "a", "text": "Hard, infrequent stools with straining"}, {"id": "b", "text": "Profuse, watery diarrhea of 3 or more stools in 24 hours"}, {"id": "c", "text": "Vomiting of bright red blood after meals"}, {"id": "d", "text": "A single formed stool every other day"}]'::jsonb, '["b"]', 'Profuse, watery diarrhea with at least 3 loose stools in 24 hours is the hallmark of C. diff. Hard, infrequent stools are the opposite of the expected presentation.'),
  ('cdiff', 50, 'A client with confirmed C. diff has a new prescription for vancomycin to be given intravenously. Which action should the nurse take?', '[{"id": "a", "text": "Clarify the route, because vancomycin for C. diff must be oral"}, {"id": "b", "text": "Administer the vancomycin intravenously as prescribed"}, {"id": "c", "text": "Give the vancomycin together with a dose of loperamide"}, {"id": "d", "text": "Hold the vancomycin until the diarrhea has stopped"}]'::jsonb, '["a"]', 'IV vancomycin does not reach the colon and is ineffective for C. diff; it must be given orally. Loperamide is contraindicated.'),
  ('infections', 1, 'A nursing student is removing a mask after leaving a droplet isolation room. Which technique indicates correct understanding?', '[{"id": "a", "text": "Pulling the mask off by grasping the front"}, {"id": "b", "text": "Handling the mask only by its ties or straps"}, {"id": "c", "text": "Removing the mask before taking off the gloves"}, {"id": "d", "text": "Removing the mask before taking off the goggles"}]'::jsonb, '["b"]', 'The front of the mask is contaminated, so it is handled only by the ties or straps and removed last. Removing it before gloves or goggles reverses the doffing order.'),
  ('infections', 2, 'A client with bacterial meningitis caused by Neisseria meningitidis started IV antibiotics 6 hours ago. Which action should the nurse take?', '[{"id": "a", "text": "Discontinue isolation now that antibiotics have started"}, {"id": "b", "text": "Move the client to an airborne infection isolation room"}, {"id": "c", "text": "Use contact precautions with gown and gloves only"}, {"id": "d", "text": "Maintain droplet precautions in a private room"}]'::jsonb, '["d"]', 'N. meningitidis requires droplet precautions in a private room until 24 hours after antibiotics are started; only 6 hours have passed. It is not an airborne disease.'),
  ('infections', 3, 'A client with hepatitis A is incontinent of stool. Which precautions should the nurse add to standard precautions?', '[{"id": "a", "text": "Contact precautions"}, {"id": "b", "text": "Droplet precautions"}, {"id": "c", "text": "Airborne precautions"}, {"id": "d", "text": "No added precautions"}]'::jsonb, '["a"]', 'Hepatitis A requires contact precautions when the client is incontinent. Droplet and airborne precautions are for respiratory transmission.'),
  ('infections', 4, 'Which client requires standard precautions only?', '[{"id": "a", "text": "A client with pertussis"}, {"id": "b", "text": "A client with RSV"}, {"id": "c", "text": "A client with cytomegalovirus (CMV)"}, {"id": "d", "text": "A client with chickenpox"}]'::jsonb, '["c"]', 'CMV is managed with standard precautions only. Pertussis is droplet, RSV is contact, and chickenpox is airborne plus contact.'),
  ('infections', 5, 'A client is admitted with cutaneous anthrax. Which plan of care is appropriate for infection control?', '[{"id": "a", "text": "Standard precautions with no isolation room"}, {"id": "b", "text": "Airborne precautions in a negative-pressure room"}, {"id": "c", "text": "Droplet precautions with a surgical mask"}, {"id": "d", "text": "Contact precautions with a gown and gloves"}]'::jsonb, '["a"]', 'Anthrax, cutaneous or inhalation, requires standard precautions and no isolation. It is not managed with airborne, droplet, or contact precautions.'),
  ('infections', 6, 'A nursing student asks which clients require standard precautions. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Every client, every time, regardless of diagnosis.\""}, {"id": "b", "text": "\"Only clients with a known bloodborne infection.\""}, {"id": "c", "text": "\"Only clients who are not on another isolation type.\""}, {"id": "d", "text": "\"Only clients with open wounds or drainage.\""}]'::jsonb, '["a"]', 'Standard precautions are used for all clients at all times regardless of diagnosis. Limiting them to known bloodborne infections is a common misconception.'),
  ('infections', 7, 'The nurse is preparing a room for a child admitted with epiglottitis caused by Haemophilus influenzae. Which supplies should be placed at the room entrance?', '[{"id": "a", "text": "Fit-tested N95 respirators"}, {"id": "b", "text": "Gowns and gloves only"}, {"id": "c", "text": "Surgical masks"}, {"id": "d", "text": "No special supplies"}]'::jsonb, '["c"]', 'Epiglottitis caused by H. influenzae requires droplet precautions, so surgical masks are needed. N95 respirators are for airborne diseases.'),
  ('infections', 8, 'The nurse is preparing to enter the room of a client with suspected tuberculosis. Which item of personal protective equipment is essential?', '[{"id": "a", "text": "A surgical mask and a pair of gloves"}, {"id": "b", "text": "A gown and gloves without a mask"}, {"id": "c", "text": "A fit-tested N95 respirator"}, {"id": "d", "text": "A face shield worn without a mask"}]'::jsonb, '["c"]', 'Airborne precautions for TB require a fit-tested N95 respirator plus an AIIR. A surgical mask is used for droplet precautions and does not meet airborne requirements.'),
  ('infections', 9, 'A client with newly diagnosed pulmonary tuberculosis (TB) is being admitted. Which room assignment is most appropriate?', '[{"id": "a", "text": "A semi-private room shared with a client who has influenza"}, {"id": "b", "text": "A negative-pressure airborne infection isolation room"}, {"id": "c", "text": "A private room with the door left open for observation"}, {"id": "d", "text": "Any standard room, because standard precautions are sufficient"}]'::jsonb, '["b"]', 'TB is the classic airborne disease and requires an airborne infection isolation room (AIIR) with negative pressure. An open door or standard room would allow airborne particles to escape.'),
  ('infections', 10, 'The nurse is about to put on a gown, mask, goggles, and gloves to enter an isolation room. Which action should the nurse take first?', '[{"id": "a", "text": "Put on the gloves"}, {"id": "b", "text": "Put on the goggles"}, {"id": "c", "text": "Perform hand hygiene"}, {"id": "d", "text": "Put on the mask"}]'::jsonb, '["c"]', 'Hand hygiene is performed before donning PPE; the gown is then put on first and gloves last. Putting on gloves first is out of order.'),
  ('infections', 11, 'A client with vancomycin-resistant Enterococcus (VRE) is on contact precautions. Which nursing action is appropriate?', '[{"id": "a", "text": "Using the unit''s shared stethoscope after wiping it"}, {"id": "b", "text": "Wearing a surgical mask within 3 feet of the client"}, {"id": "c", "text": "Keeping dedicated equipment in the client''s room"}, {"id": "d", "text": "Wearing gloves only when touching body fluids"}]'::jsonb, '["c"]', 'Contact precautions include a gown and gloves on room entry and dedicated equipment. Shared equipment can carry organisms between clients.'),
  ('infections', 12, 'A newly hired nurse asks what negative pressure means in an airborne infection isolation room. Which response by the preceptor is correct?', '[{"id": "a", "text": "\"Air flows out of the room into the hallway.\""}, {"id": "b", "text": "\"Air is recirculated in the room without filtering.\""}, {"id": "c", "text": "\"Air pressure allows the door to stay open safely.\""}, {"id": "d", "text": "\"Air flows inward to keep particles from escaping.\""}]'::jsonb, '["d"]', 'Negative pressure means air flows inward into the room, preventing airborne particles from escaping. Air flowing out into the hallway would spread particles.'),
  ('infections', 13, 'The nurse needs a gown, mask, goggles, and gloves to enter an isolation room. In which order should the nurse put on this equipment?', '[{"id": "a", "text": "Gloves, gown, goggles, mask"}, {"id": "b", "text": "Mask, gloves, gown, goggles"}, {"id": "c", "text": "Gown, mask, goggles, gloves"}, {"id": "d", "text": "Goggles, gown, gloves, mask"}]'::jsonb, '["c"]', 'Donning order is gown, mask or N95, goggles or face shield, and gloves last. Putting gloves on first reverses the order, because gloves go on last.'),
  ('infections', 14, 'A client with chronic hepatitis B is admitted to the medical unit. Which room requirement applies to this client?', '[{"id": "a", "text": "A negative-pressure isolation room"}, {"id": "b", "text": "A private room with the door closed"}, {"id": "c", "text": "No special room requirement"}, {"id": "d", "text": "A room with 6–12 air exchanges per hour"}]'::jsonb, '["c"]', 'Hepatitis B requires standard precautions, which have no special room requirement. Negative pressure and air exchanges are airborne isolation room features.'),
  ('infections', 15, 'The infection control nurse is inspecting an airborne infection isolation room. Which finding about the room''s exhaust air is appropriate?', '[{"id": "a", "text": "Air is vented outdoors or through a HEPA filter"}, {"id": "b", "text": "Air is recirculated to adjacent rooms unfiltered"}, {"id": "c", "text": "Air is released into the hallway when the door opens"}, {"id": "d", "text": "Air is held in the room without any exchanges"}]'::jsonb, '["a"]', 'AIIR air is vented directly outdoors or passed through a HEPA filter before recirculation. Unfiltered recirculation or release into the hallway would spread airborne particles.'),
  ('infections', 16, 'An immunocompromised client is diagnosed with aspergillosis. Which precautions should the nurse implement?', '[{"id": "a", "text": "Airborne precautions in an isolation room"}, {"id": "b", "text": "Droplet precautions with a surgical mask"}, {"id": "c", "text": "Contact precautions with a gown and gloves"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["d"]', 'Aspergillosis in an immunocompromised client is listed under standard precautions only. No transmission-based isolation is required.'),
  ('infections', 17, 'A client with MRSA is on contact precautions. Which statement about standard precautions for this client is accurate?', '[{"id": "a", "text": "They are replaced by contact precautions"}, {"id": "b", "text": "They remain the foundation beneath contact precautions"}, {"id": "c", "text": "They are needed only if the client also has HIV"}, {"id": "d", "text": "They stop once a gown and gloves are worn"}]'::jsonb, '["b"]', 'Standard precautions are the foundation on which all other precautions are added, so they continue alongside contact precautions. They are not replaced by transmission-based precautions.'),
  ('infections', 18, 'A client receiving chemotherapy who is immunocompromised develops disseminated herpes zoster. Which precautions should the nurse implement?', '[{"id": "a", "text": "Contact precautions with a gown and gloves only"}, {"id": "b", "text": "Airborne precautions with an N95 and an AIIR"}, {"id": "c", "text": "Droplet precautions with a surgical mask"}, {"id": "d", "text": "Standard precautions with no added equipment"}]'::jsonb, '["b"]', 'Disseminated herpes zoster in an immunocompromised client is listed under airborne precautions requiring an N95 and AIIR. Contact precautions alone would not address airborne spread.'),
  ('infections', 19, 'Which client requires the nurse to wear a surgical mask when working within 3 feet of the client?', '[{"id": "a", "text": "A client with diphtheria"}, {"id": "b", "text": "A client with HIV"}, {"id": "c", "text": "A client with scabies"}, {"id": "d", "text": "A client with hepatitis B"}]'::jsonb, '["a"]', 'Diphtheria is listed under droplet precautions, which require a surgical mask within 3 feet. HIV and hepatitis B are standard precautions, and scabies is contact.'),
  ('infections', 20, 'A 6-year-old child with mumps is admitted. Which precautions should the nurse implement?', '[{"id": "a", "text": "Airborne precautions with an N95 respirator"}, {"id": "b", "text": "Contact precautions with a gown and gloves"}, {"id": "c", "text": "Standard precautions with no added equipment"}, {"id": "d", "text": "Droplet precautions with a surgical mask"}]'::jsonb, '["d"]', 'Mumps is a droplet disease requiring a surgical mask within 3 feet. N95 respirators are used for airborne diseases.'),
  ('infections', 21, 'A client on airborne precautions for tuberculosis must be transported to radiology. Which action should the nurse take?', '[{"id": "a", "text": "Have the client wear a gown and gloves for transport"}, {"id": "b", "text": "Cancel the test until the client is discharged home"}, {"id": "c", "text": "Have the transport staff wear a gown and gloves only"}, {"id": "d", "text": "Place a surgical mask on the client for transport"}]'::jsonb, '["d"]', 'When a client on airborne precautions leaves the AIIR, the client wears a surgical mask. Gown and gloves alone do not contain airborne particles.'),
  ('infections', 22, 'A child with varicella (chickenpox) is admitted. Which personal protective equipment should the nurse wear when entering the room?', '[{"id": "a", "text": "An N95 respirator, gown, and gloves"}, {"id": "b", "text": "A surgical mask, gown, and gloves"}, {"id": "c", "text": "A gown and gloves without a mask"}, {"id": "d", "text": "An N95 respirator without a gown"}]'::jsonb, '["a"]', 'Chickenpox requires airborne and contact precautions, so the nurse wears an N95 plus a gown and gloves. A surgical mask does not meet airborne requirements.'),
  ('infections', 23, 'A client with HIV is admitted for management of a medication adverse effect and has no other infections. Which precautions should the nurse use?', '[{"id": "a", "text": "Standard precautions only"}, {"id": "b", "text": "Contact precautions"}, {"id": "c", "text": "Droplet precautions"}, {"id": "d", "text": "Airborne precautions"}]'::jsonb, '["a"]', 'HIV is managed with standard precautions only, using gloves and eye protection if splashing is possible. No transmission-based isolation is required.'),
  ('infections', 24, 'A client with an MRSA wound infection is admitted. Which room assignment is preferred?', '[{"id": "a", "text": "A negative-pressure isolation room"}, {"id": "b", "text": "A room shared with a postoperative client"}, {"id": "c", "text": "A private room with dedicated equipment"}, {"id": "d", "text": "A room shared with a client with influenza"}]'::jsonb, '["c"]', 'For contact precautions, a private room with dedicated equipment is preferred. Negative pressure is required only for airborne diseases.'),
  ('infections', 25, 'A 2-month-old infant with pertussis (whooping cough) is admitted. Which precautions should the nurse implement?', '[{"id": "a", "text": "Airborne precautions in an isolation room"}, {"id": "b", "text": "Contact precautions with gown and gloves"}, {"id": "c", "text": "Droplet precautions with a surgical mask"}, {"id": "d", "text": "Standard precautions without other equipment"}]'::jsonb, '["c"]', 'Pertussis is listed under droplet precautions, which require a surgical mask within 3 feet. Airborne precautions are reserved for diseases such as TB and chickenpox.'),
  ('infections', 26, 'Which sequence for removing personal protective equipment reflects correct technique?', '[{"id": "a", "text": "Gown, gloves, mask, goggles"}, {"id": "b", "text": "Mask, goggles, gown, gloves"}, {"id": "c", "text": "Gloves, goggles, gown, mask"}, {"id": "d", "text": "Goggles, gloves, mask, gown"}]'::jsonb, '["c"]', 'Doffing order is gloves, goggles or face shield, gown, and then the mask last. Removing the mask first reverses the order and risks self-contamination.'),
  ('infections', 27, 'A family member asks how long droplet isolation will continue for a client with Neisseria meningitidis meningitis. The nurse explains that the private room requirement continues until which point?', '[{"id": "a", "text": "24 hours after antibiotics are started"}, {"id": "b", "text": "The client''s fever first breaks"}, {"id": "c", "text": "The first antibiotic dose is given"}, {"id": "d", "text": "The client''s headache resolves"}]'::jsonb, '["a"]', 'For N. meningitidis, a private room on droplet precautions is required until 24 hours after antibiotics are started. The first dose alone is not sufficient.'),
  ('infections', 28, 'A client is admitted with influenza A. Which precautions should the nurse implement?', '[{"id": "a", "text": "Droplet precautions with a surgical mask within 3 feet"}, {"id": "b", "text": "Airborne precautions with a fit-tested N95 respirator"}, {"id": "c", "text": "Contact precautions with a gown and gloves only"}, {"id": "d", "text": "Standard precautions with no additional equipment"}]'::jsonb, '["a"]', 'Influenza is spread by droplets, so the nurse wears a surgical mask when within 3 feet. An N95 is reserved for airborne diseases such as TB.'),
  ('infections', 29, 'The nurse is removing personal protective equipment after caring for a client on airborne precautions. Which item should be removed last?', '[{"id": "a", "text": "Gloves"}, {"id": "b", "text": "Gown"}, {"id": "c", "text": "Face shield"}, {"id": "d", "text": "N95 respirator"}]'::jsonb, '["d"]', 'The mask or N95 is removed last because its front is contaminated. Gloves are removed first as the most contaminated item.'),
  ('infections', 30, 'The spouse of a client hospitalized with tuberculosis asks what to wear before visiting. Which response by the nurse is correct?', '[{"id": "a", "text": "\"You need nothing if you stay 3 feet away.\""}, {"id": "b", "text": "\"A surgical mask is enough for a short visit.\""}, {"id": "c", "text": "\"You need to put on an N95 before going in.\""}, {"id": "d", "text": "\"Gloves are all you need unless you touch him.\""}]'::jsonb, '["c"]', 'Visitors to a client in airborne isolation must wear an N95 before entering, and visits are limited. A surgical mask does not protect against airborne particles.'),
  ('infections', 31, 'The nurse is verifying that a room is ready for a client with suspected tuberculosis. Which finding indicates the room meets airborne isolation requirements?', '[{"id": "a", "text": "The room provides 6–12 air exchanges per hour"}, {"id": "b", "text": "The room provides 1 air exchange every few hours"}, {"id": "c", "text": "The room air recirculates unfiltered to the hall"}, {"id": "d", "text": "The room door is propped open for visibility"}]'::jsonb, '["a"]', 'An AIIR provides 6–12 air exchanges per hour with the door closed. Unfiltered recirculation or an open door would allow particles to escape.'),
  ('infections', 32, 'The nurse will empty a drainage container from a client with hepatitis C, and splashing is likely. Which personal protective equipment is appropriate?', '[{"id": "a", "text": "Gloves alone"}, {"id": "b", "text": "Gloves with a mask and goggles"}, {"id": "c", "text": "An N95 respirator and gown"}, {"id": "d", "text": "A surgical mask alone"}]'::jsonb, '["b"]', 'Under standard precautions, gloves are worn when touching body fluids and a mask and goggles are added when there is a splash risk. An N95 is used for airborne diseases, not hepatitis C.'),
  ('infections', 33, 'A client with COVID-19 requires care. Which personal protective equipment should the nurse wear?', '[{"id": "a", "text": "A surgical mask, gown, and gloves"}, {"id": "b", "text": "An N95, gown, gloves, and eye protection"}, {"id": "c", "text": "An N95 respirator and gloves only"}, {"id": "d", "text": "A gown, gloves, and eye protection only"}]'::jsonb, '["b"]', 'SARS/COVID-19 requires airborne plus contact precautions: N95, gown, gloves, and eye protection in an AIIR. A surgical mask does not provide airborne protection.'),
  ('infections', 34, 'A nursing student asks why a client on droplet precautions does not need a negative-pressure room. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Droplets are 5 µm or smaller and linger in the air.\""}, {"id": "b", "text": "\"Droplets are larger than 5 µm and travel less than 3 feet.\""}, {"id": "c", "text": "\"Droplets spread only by direct skin-to-skin contact.\""}, {"id": "d", "text": "\"Droplets are spread only through blood exposure.\""}]'::jsonb, '["b"]', 'Respiratory droplets are larger than 5 µm and travel less than 3 feet, so a surgical mask within 3 feet is sufficient. Particles 5 µm or smaller that linger in air describe airborne transmission.'),
  ('infections', 35, 'The nurse is leaving the room of a client with C. diff after removing PPE. Which hand hygiene method is required?', '[{"id": "a", "text": "Alcohol-based hand gel"}, {"id": "b", "text": "Glove removal without hand hygiene"}, {"id": "c", "text": "Alcohol gel followed by a dry towel"}, {"id": "d", "text": "Soap and water handwashing"}]'::jsonb, '["d"]', 'C. diff requires soap and water only; alcohol gel is not used. Hand hygiene is still required after doffing, so glove removal alone is incorrect.'),
  ('infections', 36, 'A client with suspected monkeypox is admitted. Which combination of precautions should the nurse implement?', '[{"id": "a", "text": "Droplet precautions only"}, {"id": "b", "text": "Contact precautions only"}, {"id": "c", "text": "Airborne and contact precautions"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["c"]', 'Monkeypox requires both airborne and contact precautions. Contact or droplet precautions alone are insufficient.'),
  ('infections', 37, 'A client is admitted with diarrhea caused by Salmonella. Which precautions should the nurse implement?', '[{"id": "a", "text": "Droplet precautions with a surgical mask"}, {"id": "b", "text": "Airborne precautions with an N95 respirator"}, {"id": "c", "text": "Standard precautions with no added equipment"}, {"id": "d", "text": "Contact precautions with a gown and gloves"}]'::jsonb, '["d"]', 'Salmonella is listed with rotavirus and E. coli O157:H7 under contact precautions, requiring a gown and gloves. It is not a droplet or airborne disease.'),
  ('infections', 38, 'Which characteristic of airborne particles explains why a client with tuberculosis needs an N95 respirator and an isolation room?', '[{"id": "a", "text": "They are larger than 5 µm and fall within 3 feet"}, {"id": "b", "text": "They spread only by touching contaminated surfaces"}, {"id": "c", "text": "They are 5 µm or smaller and linger in the air"}, {"id": "d", "text": "They are transmitted only through blood exposure"}]'::jsonb, '["c"]', 'Airborne particles are 5 µm or smaller, travel more than 3 feet, and linger in air, requiring an N95 and AIIR. Particles larger than 5 µm that travel less than 3 feet are droplets.'),
  ('infections', 39, 'A client in a long-term care facility is diagnosed with scabies. Which precautions should the nurse use?', '[{"id": "a", "text": "A surgical mask within 3 feet"}, {"id": "b", "text": "A gown and gloves on entering"}, {"id": "c", "text": "An N95 respirator in an AIIR"}, {"id": "d", "text": "Gloves only for blood exposure"}]'::jsonb, '["b"]', 'Scabies and lice require contact precautions with a gown and gloves on room entry. Masks and AIIRs are used for droplet and airborne diseases.'),
  ('infections', 40, 'The nurse is about to perform an assessment within 3 feet of a client with rubella (German measles). Which equipment should the nurse wear?', '[{"id": "a", "text": "A surgical mask"}, {"id": "b", "text": "An N95 respirator"}, {"id": "c", "text": "A gown only"}, {"id": "d", "text": "No added equipment"}]'::jsonb, '["a"]', 'Rubella requires droplet precautions, so a surgical mask is worn within 3 feet. An N95 is not required for droplet diseases.'),
  ('infections', 41, 'The nurse is observing care of an infant with rotavirus diarrhea on contact precautions. Which action requires correction?', '[{"id": "a", "text": "Putting on a gown and gloves before entering"}, {"id": "b", "text": "Wearing only gloves while changing diapers"}, {"id": "c", "text": "Keeping a dedicated thermometer in the room"}, {"id": "d", "text": "Placing the infant in a private room"}]'::jsonb, '["b"]', 'Rotavirus requires contact precautions, meaning a gown and gloves on room entry, not gloves alone. Dedicated equipment and a private room are appropriate.'),
  ('infections', 42, 'The charge nurse is reviewing four new admissions. Which client requires placement in an airborne infection isolation room?', '[{"id": "a", "text": "A client with pertussis"}, {"id": "b", "text": "A client with an MRSA wound"}, {"id": "c", "text": "A client with hepatitis C"}, {"id": "d", "text": "A client with chickenpox"}]'::jsonb, '["d"]', 'Chickenpox (varicella) requires airborne plus contact precautions in an AIIR. Pertussis is droplet, MRSA is contact, and hepatitis C is standard.'),
  ('infections', 43, 'Which client should the nurse place on contact precautions?', '[{"id": "a", "text": "A client with mumps"}, {"id": "b", "text": "A client with a multidrug-resistant wound infection"}, {"id": "c", "text": "A client with pulmonary tuberculosis"}, {"id": "d", "text": "A client with cytomegalovirus (CMV)"}]'::jsonb, '["b"]', 'Wound infections with multidrug-resistant organisms require contact precautions. Mumps is droplet, TB is airborne, and CMV is standard.'),
  ('infections', 44, 'A 10-month-old infant is admitted with respiratory syncytial virus (RSV). Which personal protective equipment should the nurse put on before entering the room?', '[{"id": "a", "text": "A surgical mask only"}, {"id": "b", "text": "An N95 respirator and gloves"}, {"id": "c", "text": "Gloves only when touching secretions"}, {"id": "d", "text": "A gown and gloves on room entry"}]'::jsonb, '["d"]', 'RSV requires contact precautions, which means a gown and gloves on entering the room. Gloves only when touching secretions does not meet contact precaution requirements.'),
  ('infections', 45, 'A client is diagnosed with group A streptococcal pharyngitis. Which precautions should the nurse implement?', '[{"id": "a", "text": "Airborne precautions with an N95 respirator"}, {"id": "b", "text": "Contact precautions with a gown and gloves"}, {"id": "c", "text": "Droplet precautions with a surgical mask"}, {"id": "d", "text": "Standard precautions with no added equipment"}]'::jsonb, '["c"]', 'Streptococcal pharyngitis (group A strep) is a droplet disease requiring a surgical mask within 3 feet. It does not require an N95 or AIIR.'),
  ('infections', 46, 'The nurse is caring for a client with MRSA on contact precautions. Which action by the nurse requires correction?', '[{"id": "a", "text": "Putting on a gown and gloves before entering the room"}, {"id": "b", "text": "Entering without a gown because no client contact is planned"}, {"id": "c", "text": "Using a dedicated stethoscope kept in the client''s room"}, {"id": "d", "text": "Removing the gloves first when leaving the room"}]'::jsonb, '["b"]', 'Contact precautions require a gown and gloves upon entering the room, not only when touching the client. Dedicated equipment and removing gloves first are correct actions.'),
  ('infections', 47, 'The nurse is reviewing client assignments. Which client requires droplet precautions?', '[{"id": "a", "text": "A client with tuberculosis"}, {"id": "b", "text": "A client with C. diff"}, {"id": "c", "text": "A client with hepatitis B"}, {"id": "d", "text": "A client with mycoplasma pneumonia"}]'::jsonb, '["d"]', 'Mycoplasma pneumonia is listed under droplet precautions. TB is airborne, C. diff is contact, and hepatitis B is standard.'),
  ('infections', 48, 'The charge nurse is assigning rooms to four clients with respiratory infections. Which client requires an airborne infection isolation room?', '[{"id": "a", "text": "A client with influenza B"}, {"id": "b", "text": "A client with avian influenza (H5N1)"}, {"id": "c", "text": "A client with mycoplasma pneumonia"}, {"id": "d", "text": "A client with streptococcal pharyngitis"}]'::jsonb, '["b"]', 'Avian influenza (H5N1) is listed under airborne precautions requiring an N95 and AIIR. Seasonal influenza, mycoplasma pneumonia, and strep pharyngitis are droplet diseases.'),
  ('infections', 49, 'The nurse is leaving the room of a client on contact precautions and is wearing a gown, gloves, goggles, and a mask. Which item should the nurse remove first?', '[{"id": "a", "text": "Gloves"}, {"id": "b", "text": "Gown"}, {"id": "c", "text": "Mask"}, {"id": "d", "text": "Goggles"}]'::jsonb, '["a"]', 'Gloves are the most contaminated item and are removed first during doffing. The mask is removed last.'),
  ('infections', 50, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client in an airborne infection isolation room. Which action by the UAP requires correction?', '[{"id": "a", "text": "Closing the door after entering the room"}, {"id": "b", "text": "Leaving the door open to hear the client call"}, {"id": "c", "text": "Putting on an N95 respirator before entering"}, {"id": "d", "text": "Reminding the family that visitors are limited"}]'::jsonb, '["b"]', 'The door of an AIIR must remain closed at all times. Wearing an N95 and limiting visitors are correct actions.'),
  ('mg', 1, 'A client reports intermittent double vision over the past month. Which additional finding would the nurse expect if the client has early myasthenia gravis?', '[{"id": "a", "text": "Numbness that begins in the toes"}, {"id": "b", "text": "Weakness that is worst upon waking"}, {"id": "c", "text": "Drooping eyelids that may be uneven"}, {"id": "d", "text": "Constricted pupils and drooling"}]'::jsonb, '["c"]', 'Ocular symptoms such as ptosis, which is often asymmetric, and diplopia are often the first signs of myasthenia gravis. Weakness in MG worsens throughout the day rather than on waking, and constricted pupils with drooling are cholinergic crisis findings.'),
  ('mg', 2, 'The nurse is teaching a newly diagnosed client about myasthenia gravis. Which explanation of the cause of muscle weakness is accurate?', '[{"id": "a", "text": "Antibodies attack acetylcholine receptors at the muscle"}, {"id": "b", "text": "Antibodies attack the nerve cells inside the spinal cord"}, {"id": "c", "text": "The motor nerves release excess acetylcholine"}, {"id": "d", "text": "The muscles break down from repeated overuse"}]'::jsonb, '["a"]', 'In myasthenia gravis, antibodies attack acetylcholine receptors at the neuromuscular junction, leaving fewer working receptors and impaired muscle contraction. The motor nerve terminal still releases acetylcholine; the problem is at the receptor.'),
  ('mg', 3, 'A client with myasthenia gravis states, "In the morning I can read and eat without trouble, but by evening my eyelids droop and chewing tires me out." How should the nurse interpret this statement?', '[{"id": "a", "text": "It suggests a cholinergic crisis from excess medication"}, {"id": "b", "text": "It reflects the typical pattern of weakness in this disease"}, {"id": "c", "text": "It indicates that the client needs more daytime activity"}, {"id": "d", "text": "It shows that the disease is mainly affecting sensation"}]'::jsonb, '["b"]', 'Weakness in myasthenia gravis worsens with activity and repetition and is worse as the day goes on, improving with rest. Cholinergic crisis is caused by overmedication and presents with SLUDGE symptoms, not a predictable evening decline.'),
  ('mg', 4, 'The nurse is planning daily care with a client who has myasthenia gravis. Which schedule is most appropriate?', '[{"id": "a", "text": "Group all care activities into the late evening"}, {"id": "b", "text": "Add strenuous exercise to build muscle endurance"}, {"id": "c", "text": "Plan a hot bath before each therapy session"}, {"id": "d", "text": "Plan bathing and important tasks for the morning"}]'::jsonb, '["d"]', 'Important activities should be scheduled when the client is strongest, which is in the morning, with rest built in. Physical overexertion and heat are triggers that worsen weakness.'),
  ('mg', 5, 'A client with myasthenia gravis asks which factors can make the weakness worse. Which factor should the nurse include?', '[{"id": "a", "text": "Rest periods between daily activities"}, {"id": "b", "text": "Taking pyridostigmine on schedule"}, {"id": "c", "text": "Exposure to heat, such as hot showers"}, {"id": "d", "text": "Eating soft foods at mealtimes"}]'::jsonb, '["c"]', 'Weakness in myasthenia gravis worsens with activity, repetition, heat, stress, infections, and missing medication. Rest and pyridostigmine improve strength.'),
  ('mg', 6, 'The nurse reviews crisis prevention with a client who has myasthenia gravis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will rest when I notice my weakness getting worse.\""}, {"id": "b", "text": "\"I will stay out of hot tubs and very hot weather.\""}, {"id": "c", "text": "\"I will call my provider if I develop an infection.\""}, {"id": "d", "text": "\"I will push through my workouts even when my muscles tire.\""}]'::jsonb, '["d"]', 'Physical overexertion, along with heat, infection, and stress, can trigger a myasthenic crisis, so pushing through fatigue is unsafe. Resting, avoiding heat, and reporting infections are all correct.'),
  ('mg', 7, 'The nurse is preparing a client for a Tensilon (edrophonium) test. Which medication must the nurse have immediately available at the bedside?', '[{"id": "a", "text": "Prednisone"}, {"id": "b", "text": "Magnesium"}, {"id": "c", "text": "Azathioprine"}, {"id": "d", "text": "Atropine"}]'::jsonb, '["d"]', 'Atropine must be at the bedside during the Tensilon test because edrophonium carries a risk of bradycardia and cholinergic effects. Magnesium is a drug that worsens myasthenia gravis.'),
  ('mg', 8, 'A client with suspected myasthenia gravis receives IV edrophonium. Within seconds, the client opens both eyes fully and grip strength improves dramatically. How should the nurse interpret this response?', '[{"id": "a", "text": "The client is developing a cholinergic crisis"}, {"id": "b", "text": "The result rules out myasthenia gravis"}, {"id": "c", "text": "The result supports myasthenia gravis"}, {"id": "d", "text": "The client is showing a toxic drug reaction"}]'::jsonb, '["c"]', 'A temporary dramatic improvement in strength after edrophonium indicates myasthenia gravis. Worsening, not improvement, after edrophonium would point to a cholinergic crisis.'),
  ('mg', 9, 'A nursing student asks why muscle strength improves during a Tensilon test in a client with myasthenia gravis. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Edrophonium briefly raises acetylcholine levels"}, {"id": "b", "text": "Edrophonium removes antibodies from the blood"}, {"id": "c", "text": "Edrophonium permanently repairs the receptors"}, {"id": "d", "text": "Edrophonium blocks the action of acetylcholine"}]'::jsonb, '["a"]', 'Edrophonium is a short-acting cholinesterase inhibitor that temporarily increases acetylcholine, so strength improves within seconds in MG. Removing antibodies from the blood describes plasmapheresis.'),
  ('mg', 10, 'Shortly after receiving edrophonium during a Tensilon test, a client''s heart rate drops sharply and the client becomes lightheaded. Which action should the nurse take first?', '[{"id": "a", "text": "Administer the next scheduled dose of pyridostigmine"}, {"id": "b", "text": "Repeat the edrophonium dose to confirm the result"}, {"id": "c", "text": "Document the response as an expected finding"}, {"id": "d", "text": "Prepare to administer the atropine at the bedside"}]'::jsonb, '["d"]', 'Atropine is the antidote for bradycardia and cholinergic effects and must be ready during the test. Giving more pyridostigmine or edrophonium would add more cholinesterase inhibition.'),
  ('mg', 11, 'The nurse reviews diagnostic results for a client being evaluated for generalized myasthenia gravis. Which result is the most specific diagnostic marker for the disease?', '[{"id": "a", "text": "Enlarged thymus gland seen on chest imaging"}, {"id": "b", "text": "Improved strength after a dose of atropine"}, {"id": "c", "text": "Positive anti-acetylcholine receptor antibodies"}, {"id": "d", "text": "Increasing amplitude with repeated nerve stimulation"}]'::jsonb, '["c"]', 'Anti-AChR antibodies are the most specific diagnostic marker for MG. Chest imaging is done to check for thymoma, and repetitive stimulation in MG shows a decreasing, not increasing, amplitude.'),
  ('mg', 12, 'A client with suspected myasthenia gravis undergoes EMG with repetitive nerve stimulation. Which result would the nurse expect?', '[{"id": "a", "text": "Amplitude that increases with repeated stimulation"}, {"id": "b", "text": "Amplitude that decreases with repeated stimulation"}, {"id": "c", "text": "Amplitude that remains the same with stimulation"}, {"id": "d", "text": "No muscle response to the first stimulation"}]'::jsonb, '["b"]', 'EMG with repetitive stimulation in MG shows a decremental response in which amplitude decreases, confirming neuromuscular junction dysfunction.'),
  ('mg', 13, 'A client newly diagnosed with myasthenia gravis asks why a CT scan of the chest has been ordered. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It checks for a tumor of the thymus gland.\""}, {"id": "b", "text": "\"It measures the strength of your diaphragm.\""}, {"id": "c", "text": "\"It looks for antibodies in your lung tissue.\""}, {"id": "d", "text": "\"It checks your heart for a slow rhythm.\""}]'::jsonb, '["a"]', 'CT or MRI of the chest is used to check for thymoma, a thymus gland tumor, which is present in a portion of MG patients. Breathing muscle strength is monitored clinically, not by chest CT.'),
  ('mg', 14, 'A chest CT for a client with myasthenia gravis shows a thymoma. Which treatment should the nurse anticipate the provider will recommend?', '[{"id": "a", "text": "Stopping all pyridostigmine doses"}, {"id": "b", "text": "Surgical removal of the thymus"}, {"id": "c", "text": "Lifelong weekly plasmapheresis"}, {"id": "d", "text": "Routine magnesium supplementation"}]'::jsonb, '["b"]', 'Thymectomy is recommended especially when a thymoma is present and improves symptoms in many patients. Plasmapheresis has only a short-term effect, and magnesium worsens MG.'),
  ('mg', 15, 'A client with myasthenia gravis scheduled for thymectomy asks how the surgery could help. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It increases the acetylcholine your nerves release.\""}, {"id": "b", "text": "\"It filters the existing antibodies from your blood.\""}, {"id": "c", "text": "\"It replaces the need to monitor your breathing.\""}, {"id": "d", "text": "\"It may reduce the production of the antibodies.\""}]'::jsonb, '["d"]', 'Thymectomy, surgical removal of the thymus, may reduce antibody production. Removing antibodies already in the blood describes plasmapheresis.'),
  ('mg', 16, 'A client with myasthenia gravis asks how pyridostigmine (Mestinon) works. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It suppresses the immune system''s antibody production"}, {"id": "b", "text": "It removes the harmful antibodies from the bloodstream"}, {"id": "c", "text": "It increases acetylcholine at the neuromuscular junction"}, {"id": "d", "text": "It blocks acetylcholine to calm overactive muscles"}]'::jsonb, '["c"]', 'Pyridostigmine is a cholinesterase inhibitor that increases acetylcholine at the neuromuscular junction and improves muscle strength. Reducing the autoimmune response describes corticosteroids and immunosuppressants.'),
  ('mg', 17, 'A client with myasthenia gravis has difficulty chewing and swallowing at dinner. When should the nurse schedule the client''s pyridostigmine in relation to meals?', '[{"id": "a", "text": "Immediately after each meal"}, {"id": "b", "text": "With the evening meal only"}, {"id": "c", "text": "Two hours after each meal"}, {"id": "d", "text": "30 to 45 minutes before meals"}]'::jsonb, '["d"]', 'Pyridostigmine is given 30 to 45 minutes before meals to aid swallowing. Giving it after meals misses the period when chewing and swallowing strength is needed.'),
  ('mg', 18, 'The nurse is administering 0800 medications to a client with myasthenia gravis. Which medication is most important to give exactly at the scheduled time?', '[{"id": "a", "text": "Pyridostigmine"}, {"id": "b", "text": "Prednisone"}, {"id": "c", "text": "Azathioprine"}, {"id": "d", "text": "A daily stool softener"}]'::jsonb, '["a"]', 'Pyridostigmine must be given exactly on time because a missed dose can lead to myasthenic crisis.'),
  ('mg', 19, 'The charge nurse observes a new nurse caring for a client with myasthenia gravis. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Positioning the client fully upright for the breakfast meal"}, {"id": "b", "text": "Keeping suction equipment set up at the bedside"}, {"id": "c", "text": "Clustering care to allow rest periods during the day"}, {"id": "d", "text": "Holding pyridostigmine until the breakfast tray is finished"}]'::jsonb, '["d"]', 'Pyridostigmine should never be delayed and should be scheduled before meals so swallowing is supported. Upright positioning, bedside suction, and rest periods are all correct.'),
  ('mg', 20, 'A client with myasthenia gravis tells the nurse, "I skipped my morning pyridostigmine because I felt strong." Which complication should the nurse monitor for?', '[{"id": "a", "text": "Cholinergic crisis with heavy salivation"}, {"id": "b", "text": "Myasthenic crisis with breathing difficulty"}, {"id": "c", "text": "Slow heart rate from excess acetylcholine"}, {"id": "d", "text": "Diarrhea and cramping from the medication"}]'::jsonb, '["b"]', 'Missing a dose of pyridostigmine can lead to myasthenic crisis, which includes respiratory failure. Salivation, bradycardia, and diarrhea are SLUDGE findings of cholinergic crisis caused by too much medication.'),
  ('mg', 21, 'A client with myasthenia gravis started on prednisone reports that weakness seems slightly worse during the first few days. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"You should stop taking the prednisone right away today.\""}, {"id": "b", "text": "\"Steroids can temporarily worsen symptoms when first started.\""}, {"id": "c", "text": "\"This means you are having a cholinergic crisis now.\""}, {"id": "d", "text": "\"This shows prednisone does not work for your disease.\""}]'::jsonb, '["b"]', 'Corticosteroids may temporarily worsen MG symptoms at the start of therapy. Cholinergic crisis is caused by too much pyridostigmine and presents with SLUDGE symptoms.'),
  ('mg', 22, 'A client with myasthenia gravis is started on azathioprine. Which laboratory tests should the nurse expect to be monitored?', '[{"id": "a", "text": "Complete blood count and liver function tests"}, {"id": "b", "text": "Serum sodium and potassium levels"}, {"id": "c", "text": "Thyroid hormone levels"}, {"id": "d", "text": "Coagulation studies and platelet function"}]'::jsonb, '["a"]', 'Azathioprine requires monitoring of the CBC and LFTs and carries an infection risk.'),
  ('mg', 23, 'A client with myasthenia gravis takes prednisone and azathioprine. Which instruction is most important for the nurse to include in discharge teaching?', '[{"id": "a", "text": "Report fever or other signs of infection promptly"}, {"id": "b", "text": "Increase daily exercise to build muscle stamina"}, {"id": "c", "text": "Take a double dose if a medication is missed"}, {"id": "d", "text": "Limit fluid intake to reduce muscle swelling"}]'::jsonb, '["a"]', 'Both corticosteroids and azathioprine carry an infection risk, and infection can trigger crisis, so new infections should be reported to the provider. Doses should never be skipped, and overexertion is a trigger.'),
  ('mg', 24, 'A client with myasthenia gravis who takes prednisone asks why azathioprine has been added. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It gives rapid rescue relief during a sudden crisis.\""}, {"id": "b", "text": "\"It raises the acetylcholine levels at your muscles.\""}, {"id": "c", "text": "\"It gives long-term immune control and spares steroids.\""}, {"id": "d", "text": "\"It shrinks the thymus gland so surgery is avoided.\""}]'::jsonb, '["c"]', 'Azathioprine is a steroid-sparing immunosuppressant used for long-term immune modulation. Rapid, short-term relief in crisis is the role of IVIG or plasmapheresis.'),
  ('mg', 25, 'A client with myasthenia gravis is scheduled for plasmapheresis. Which statement by the client shows correct understanding of the procedure?', '[{"id": "a", "text": "\"It adds donor antibodies to block mine.\""}, {"id": "b", "text": "\"It removes the antibodies from my blood.\""}, {"id": "c", "text": "\"It increases acetylcholine in my muscles.\""}, {"id": "d", "text": "\"It permanently stops antibody production.\""}]'::jsonb, '["b"]', 'Plasmapheresis removes antibodies from the blood, whereas IVIG blocks antibodies. Neither raises acetylcholine, and their effect is short-term.'),
  ('mg', 26, 'The family of a client in a severe myasthenia gravis exacerbation asks whether IVIG will be needed every day for life. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is used for severe flares and works short-term.\""}, {"id": "b", "text": "\"It is a daily maintenance drug taken for life.\""}, {"id": "c", "text": "\"It replaces the need for pyridostigmine doses.\""}, {"id": "d", "text": "\"It is given mainly to prevent a thymoma.\""}]'::jsonb, '["a"]', 'IVIG and plasmapheresis are used for crisis or severe exacerbation and have a short-term effect. Pyridostigmine remains the drug of choice and must still be given on time.'),
  ('mg', 27, 'A client with myasthenia gravis who was admitted with pneumonia develops severe weakness and increasing difficulty swallowing and speaking. Which condition should the nurse suspect?', '[{"id": "a", "text": "Myasthenic crisis triggered by the infection"}, {"id": "b", "text": "Cholinergic crisis caused by overmedication"}, {"id": "c", "text": "Expected side effects of the pyridostigmine"}, {"id": "d", "text": "Temporary weakness from starting a steroid"}]'::jsonb, '["a"]', 'Myasthenic crisis is caused by undermedication or an illness or infection trigger and presents with severe weakness, respiratory failure, and difficulty swallowing and speaking. Cholinergic crisis is caused by overmedication and includes SLUDGE symptoms.'),
  ('mg', 28, 'A client with myasthenia gravis took extra pyridostigmine doses over the past day. The client now has increased weakness, excessive salivation, tearing, and diarrhea. Which condition should the nurse suspect?', '[{"id": "a", "text": "Myasthenic crisis"}, {"id": "b", "text": "Thymoma growth"}, {"id": "c", "text": "Steroid reaction"}, {"id": "d", "text": "Cholinergic crisis"}]'::jsonb, '["d"]', 'Cholinergic crisis results from overmedication with pyridostigmine and causes weakness plus SLUDGE symptoms such as salivation, lacrimation, and diarrhea. Myasthenic crisis results from undermedication or infection.'),
  ('mg', 29, 'A client with myasthenia gravis is suspected of having a cholinergic crisis. Which set of findings would the nurse expect?', '[{"id": "a", "text": "Bradycardia, sweating, and constricted pupils"}, {"id": "b", "text": "Tachycardia, dry skin, and dilated pupils"}, {"id": "c", "text": "Urinary retention, dry mouth, and constipation"}, {"id": "d", "text": "Improved strength with reduced salivation"}]'::jsonb, '["a"]', 'Cholinergic crisis produces weakness plus SLUDGE symptoms, including bradycardia, sweating, and miosis, along with salivation, urination, and diarrhea.'),
  ('mg', 30, 'A client with myasthenia gravis is diagnosed with cholinergic crisis. Which prescription should the nurse anticipate?', '[{"id": "a", "text": "Give an extra dose of pyridostigmine"}, {"id": "b", "text": "Give edrophonium every few hours"}, {"id": "c", "text": "Stop pyridostigmine and give atropine"}, {"id": "d", "text": "Start magnesium and a sedative"}]'::jsonb, '["c"]', 'Cholinergic crisis is treated by stopping pyridostigmine and giving atropine. More cholinesterase inhibitor would add to the excess acetylcholine, and magnesium and sedatives worsen MG.'),
  ('mg', 31, 'A client with myasthenia gravis in crisis receives edrophonium, and the weakness becomes worse. How should the nurse interpret this result?', '[{"id": "a", "text": "Cholinergic crisis, with too much acetylcholine"}, {"id": "b", "text": "Myasthenic crisis, with too little acetylcholine"}, {"id": "c", "text": "A positive test confirming a new MG diagnosis"}, {"id": "d", "text": "A normal response requiring no change in care"}]'::jsonb, '["a"]', 'Symptoms that worsen after edrophonium indicate cholinergic crisis because there is already too much acetylcholine. Improvement after edrophonium would indicate myasthenic crisis.'),
  ('mg', 32, 'A client with myasthenia gravis in crisis receives edrophonium, and muscle strength improves. How should the nurse interpret this result?', '[{"id": "a", "text": "Cholinergic crisis, with excess acetylcholine present"}, {"id": "b", "text": "Myasthenic crisis, with a need for more acetylcholine"}, {"id": "c", "text": "An adverse reaction requiring immediate atropine"}, {"id": "d", "text": "A sign that the thymoma has grown larger"}]'::jsonb, '["b"]', 'Improvement after edrophonium indicates myasthenic crisis, meaning the client needs more acetylcholine. Worsening after edrophonium would indicate cholinergic crisis.'),
  ('mg', 33, 'A client with myasthenia gravis is admitted with severe weakness. Which finding best helps the nurse distinguish a cholinergic crisis from a myasthenic crisis?', '[{"id": "a", "text": "Severe generalized muscle weakness"}, {"id": "b", "text": "A known diagnosis of myasthenia"}, {"id": "c", "text": "Salivation, tearing, and diarrhea"}, {"id": "d", "text": "Daily use of pyridostigmine at home"}]'::jsonb, '["c"]', 'Both crises cause severe weakness, but cholinergic crisis adds SLUDGE symptoms such as salivation, lacrimation, and diarrhea.'),
  ('mg', 34, 'The nurse is caring for several clients with myasthenia gravis. Which finding should be reported to the provider immediately?', '[{"id": "a", "text": "Mild eyelid drooping late in the evening"}, {"id": "b", "text": "Increasing difficulty breathing and swallowing"}, {"id": "c", "text": "Fatigue after a long walk in the hallway"}, {"id": "d", "text": "Double vision that improves after resting"}]'::jsonb, '["b"]', 'Weakness of the diaphragm and intercostal muscles can progress to respiratory failure, which signals myasthenic crisis. Evening ptosis and fatigue that improves with rest fit the usual MG pattern.'),
  ('mg', 35, 'A client is admitted in myasthenic crisis. Which action is the nurse''s first priority?', '[{"id": "a", "text": "Administer the scheduled prednisone dose"}, {"id": "b", "text": "Assess the airway and respiratory effort"}, {"id": "c", "text": "Teach the client about thymectomy surgery"}, {"id": "d", "text": "Arrange a physical therapy consultation"}]'::jsonb, '["b"]', 'Airway comes first in myasthenia gravis care, with monitoring for respiratory fatigue. Airway management is always the top priority in an MG emergency.'),
  ('mg', 36, 'The nurse is preparing a room for a client admitted with a myasthenia gravis exacerbation. Which equipment is the priority to have at the bedside?', '[{"id": "a", "text": "A heating pad for muscle comfort"}, {"id": "b", "text": "A bed alarm and wrist restraints"}, {"id": "c", "text": "A standing scale for daily weights"}, {"id": "d", "text": "Suction and emergency airway equipment"}]'::jsonb, '["d"]', 'Suction and emergency equipment should be kept at the bedside because airway management is always the first priority. Heat is a trigger that worsens MG weakness.'),
  ('mg', 37, 'The nurse is assisting a client with myasthenia gravis who has dysphagia with lunch. Which position is most appropriate during the meal?', '[{"id": "a", "text": "Lying flat with head turned"}, {"id": "b", "text": "Side-lying with bed flat"}, {"id": "c", "text": "Sitting fully upright"}, {"id": "d", "text": "Reclined with legs raised"}]'::jsonb, '["c"]', 'Aspiration precautions for MG include upright positioning for all meals.'),
  ('mg', 38, 'A client with myasthenia gravis reports that chewing becomes tiring during meals. Which meal choice is most appropriate?', '[{"id": "a", "text": "Grilled steak and raw carrots"}, {"id": "b", "text": "Crusty bread and mixed nuts"}, {"id": "c", "text": "Scrambled eggs and applesauce"}, {"id": "d", "text": "Beef jerky and fresh apples"}]'::jsonb, '["c"]', 'Chewing fatigue is a bulbar symptom of MG, and aspiration precautions include soft foods if needed. Tough, crunchy foods increase chewing demand.'),
  ('mg', 39, 'The nurse is assessing a client with myasthenia gravis. Which finding indicates bulbar muscle involvement?', '[{"id": "a", "text": "Drooping eyelids and double vision"}, {"id": "b", "text": "Weakness of the shoulders and hips"}, {"id": "c", "text": "Slurred speech and trouble swallowing"}, {"id": "d", "text": "Pinpoint pupils and heavy sweating"}]'::jsonb, '["c"]', 'Bulbar symptoms include dysphagia, dysarthria (slurred speech), and chewing fatigue. Ptosis and diplopia are ocular symptoms, and proximal weakness is a limb finding.'),
  ('mg', 40, 'The nurse assesses limb strength in a client with generalized myasthenia gravis. Which pattern would the nurse expect?', '[{"id": "a", "text": "Weakness starting in the toes and moving up"}, {"id": "b", "text": "Weakness limited to one side of the body"}, {"id": "c", "text": "Strength that improves with repeated effort"}, {"id": "d", "text": "Weakness of proximal muscles such as the hips"}]'::jsonb, '["d"]', 'Limb involvement in MG includes proximal limb weakness and weak neck muscles. Weakness in MG worsens, rather than improves, with repetition.'),
  ('mg', 41, 'A client with myasthenia gravis is admitted with hypertension. Which prescription should the nurse clarify with the provider?', '[{"id": "a", "text": "Pyridostigmine 30 minutes before meals"}, {"id": "b", "text": "Soft diet with upright positioning"}, {"id": "c", "text": "A beta-blocker for blood pressure"}, {"id": "d", "text": "Azathioprine with CBC monitoring"}]'::jsonb, '["c"]', 'Beta-blockers, along with aminoglycosides and sedatives, worsen myasthenia gravis and should be avoided. The other prescriptions are consistent with MG care.'),
  ('mg', 42, 'The nurse reviews home medications with a client who has myasthenia gravis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I wear my medical alert bracelet every day.\""}, {"id": "b", "text": "\"I take magnesium supplements for leg cramps.\""}, {"id": "c", "text": "\"I take my Mestinon before I sit down to eat.\""}, {"id": "d", "text": "\"I tell my doctor about any new medicines.\""}]'::jsonb, '["b"]', 'Magnesium is among the medications that worsen MG, along with beta-blockers, aminoglycosides, sedatives, and quinidine. The other statements reflect correct teaching.'),
  ('mg', 43, 'A client with myasthenia gravis develops a serious bacterial infection. Which type of antibiotic should prompt the nurse to contact the provider before administration?', '[{"id": "a", "text": "Any antibiotic given orally"}, {"id": "b", "text": "An antibiotic given with food"}, {"id": "c", "text": "Any antibiotic for a urinary infection"}, {"id": "d", "text": "An aminoglycoside antibiotic"}]'::jsonb, '["d"]', 'Aminoglycosides are among the drugs that worsen MG and should be avoided.'),
  ('mg', 44, 'The nurse is completing discharge teaching for a client with myasthenia gravis. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will wear my medical alert bracelet at all times.\""}, {"id": "b", "text": "\"I only need my medical alert bracelet when I travel.\""}, {"id": "c", "text": "\"I can skip a dose of Mestinon on days I feel strong.\""}, {"id": "d", "text": "\"I will wait to see if crisis symptoms pass on their own.\""}]'::jsonb, '["a"]', 'Clients with MG should wear a medical alert bracelet at all times. Doses should never be skipped, and early crisis signs require immediate emergency care.'),
  ('mg', 45, 'A client with myasthenia gravis asks what to do if breathing or swallowing becomes harder at home. Which instruction should the nurse give?', '[{"id": "a", "text": "Take a nap and reassess later"}, {"id": "b", "text": "Seek emergency care immediately"}, {"id": "c", "text": "Take a double dose of Mestinon"}, {"id": "d", "text": "Mention it at the next visit"}]'::jsonb, '["b"]', 'Clients should know the early signs of crisis and seek emergency care immediately. Doubling doses risks overmedication and cholinergic crisis.'),
  ('mg', 46, 'A client with myasthenia gravis calls the clinic reporting a new fever and productive cough. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "Instruct the client to be evaluated by the provider"}, {"id": "b", "text": "Tell the client to hold pyridostigmine until afebrile"}, {"id": "c", "text": "Recommend more exercise to keep the lungs clear"}, {"id": "d", "text": "Reassure the client that infection will not affect MG"}]'::jsonb, '["a"]', 'Infections can trigger crisis, so new infections should be reported to the provider. Pyridostigmine doses should never be skipped or delayed.'),
  ('mg', 47, 'A client with myasthenia gravis asks how a myasthenic crisis differs from a cholinergic crisis. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Myasthenic is from too much medicine; cholinergic is from too little.\""}, {"id": "b", "text": "\"Myasthenic is from too little medicine; cholinergic is from too much.\""}, {"id": "c", "text": "\"Both are caused by taking too little of your pyridostigmine.\""}, {"id": "d", "text": "\"Both are caused by an infection rather than by medication.\""}]'::jsonb, '["b"]', 'Myasthenic crisis is caused by undermedication or an illness or infection trigger, while cholinergic crisis is caused by overmedication with pyridostigmine.'),
  ('mg', 48, 'A client with generalized myasthenia gravis symptoms asks whether everyone with the disease tests positive for anti-acetylcholine receptor antibodies. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Every person with MG has a positive antibody test.\""}, {"id": "b", "text": "\"About 85% of people with generalized MG test positive.\""}, {"id": "c", "text": "\"Only about 15% of people with MG test positive.\""}, {"id": "d", "text": "\"The test is positive only in people with a thymoma.\""}]'::jsonb, '["b"]', 'Anti-AChR antibodies are positive in about 85% of generalized MG, so most but not all clients test positive. The 15–20% figure in MG refers to thymoma, not antibody positivity.'),
  ('mg', 49, 'A family member asks why the nurse frequently monitors the breathing of a client with myasthenia gravis. Which explanation is accurate?', '[{"id": "a", "text": "The antibodies directly damage the lung tissue"}, {"id": "b", "text": "Pyridostigmine slows the brain''s breathing center"}, {"id": "c", "text": "Ptosis limits how deeply the client can breathe"}, {"id": "d", "text": "Weakness can affect the diaphragm and chest muscles"}]'::jsonb, '["d"]', 'MG can weaken the diaphragm and intercostal muscles, leading to respiratory failure and myasthenic crisis.'),
  ('mg', 50, 'A client with myasthenia gravis asks why prednisone has been prescribed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It reduces the autoimmune response.\""}, {"id": "b", "text": "\"It increases acetylcholine release.\""}, {"id": "c", "text": "\"It filters antibodies from the blood.\""}, {"id": "d", "text": "\"It treats a cholinergic crisis fast.\""}]'::jsonb, '["a"]', 'Corticosteroids such as prednisone reduce the autoimmune response in MG. Filtering antibodies from the blood is plasmapheresis, and cholinergic crisis is treated with atropine.'),
  ('autoimmune', 1, 'Which laboratory findings should the nurse expect for a client with Hashimoto''s thyroiditis?', '[{"id": "a", "text": "Low TSH with elevated T3/T4"}, {"id": "b", "text": "Low C-peptide with GAD antibodies"}, {"id": "c", "text": "Elevated TSH with anti-TPO antibodies"}, {"id": "d", "text": "Positive anti-dsDNA and anti-Sm"}]'::jsonb, '["c"]', 'Hashimoto''s thyroiditis shows an increased TSH, decreased T3/T4, and anti-TPO antibodies. Low TSH with elevated T3/T4 is the Graves'' pattern.'),
  ('autoimmune', 2, 'A client newly diagnosed with multiple sclerosis (MS) asks what is causing the double vision and tingling. The nurse''s explanation should be based on which process?', '[{"id": "a", "text": "The immune system attacks the myelin of CNS nerves"}, {"id": "b", "text": "Antibodies block acetylcholine receptors at muscles"}, {"id": "c", "text": "Immune complexes deposit in multiple organs"}, {"id": "d", "text": "The immune system attacks the synovial joints"}]'::jsonb, '["a"]', 'In MS the immune system attacks the myelin sheath of CNS nerves, causing nerve damage with diplopia, nystagmus, and paresthesia. Antibodies against ACh receptors describe myasthenia gravis.'),
  ('autoimmune', 3, 'A client reports fatigue, constipation, weight gain, and always feeling cold. The client''s heart rate is slow. Which condition do these findings suggest?', '[{"id": "a", "text": "Graves'' disease"}, {"id": "b", "text": "Hashimoto''s thyroiditis"}, {"id": "c", "text": "Celiac disease"}, {"id": "d", "text": "Type 1 diabetes mellitus"}]'::jsonb, '["b"]', 'Cold intolerance, weight gain, and bradycardia with constipation point to Hashimoto''s thyroiditis. Graves'' disease causes heat intolerance, weight loss, and tachycardia.'),
  ('autoimmune', 4, 'A client with Graves'' disease suddenly develops a high fever, a rapid heart rate, and hypertension. How should the nurse interpret these findings?', '[{"id": "a", "text": "Expected effects of beta-blocker therapy"}, {"id": "b", "text": "Early signs of myxedema coma"}, {"id": "c", "text": "A normal response to methimazole"}, {"id": "d", "text": "Thyroid storm requiring immediate action"}]'::jsonb, '["d"]', 'High fever with tachycardia and hypertension in Graves'' disease signals thyroid storm, a life-threatening excess of hormone requiring immediate intervention. Myxedema coma is the worst complication of Hashimoto''s, not Graves''.'),
  ('autoimmune', 5, 'A client asks the nurse what it means to have an autoimmune disease. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your immune system has been absent since birth.\""}, {"id": "b", "text": "\"An infection is directly attacking your organs.\""}, {"id": "c", "text": "\"Your immune system attacks your own healthy cells.\""}, {"id": "d", "text": "\"Your body is unable to make any antibodies.\""}]'::jsonb, '["c"]', 'In autoimmune disease the immune system mistakenly attacks the body''s own healthy cells, a loss of self-tolerance. It is not a direct infection of the organs.'),
  ('autoimmune', 6, 'A client is newly diagnosed with systemic lupus erythematosus. Which medication should the nurse anticipate in the treatment plan?', '[{"id": "a", "text": "Levothyroxine"}, {"id": "b", "text": "Pyridostigmine"}, {"id": "c", "text": "Methimazole"}, {"id": "d", "text": "Hydroxychloroquine"}]'::jsonb, '["d"]', 'SLE is treated with hydroxychloroquine, corticosteroids, NSAIDs, and immunosuppressants. Pyridostigmine treats myasthenia gravis, and methimazole treats Graves'' disease.'),
  ('autoimmune', 7, 'A client with celiac disease is found to be anemic and continues to lose weight. Which explanation for these findings is most accurate?', '[{"id": "a", "text": "Thyroid hormone production is too low"}, {"id": "b", "text": "Beta cells are no longer making insulin"}, {"id": "c", "text": "Immune complexes are damaging the kidneys"}, {"id": "d", "text": "Nutrients are not being absorbed well"}]'::jsonb, '["d"]', 'Celiac disease damages the small intestine villi, causing malabsorption with anemia and weight loss. Low thyroid hormone describes Hashimoto''s, which causes weight gain.'),
  ('autoimmune', 8, 'The nurse reviews the treatment plan for a client newly diagnosed with myasthenia gravis. Which medication should the nurse expect to see?', '[{"id": "a", "text": "Methimazole"}, {"id": "b", "text": "Levothyroxine"}, {"id": "c", "text": "Pyridostigmine"}, {"id": "d", "text": "Hydroxychloroquine"}]'::jsonb, '["c"]', 'Myasthenia gravis is treated with pyridostigmine, corticosteroids, and plasmapheresis/IVIG. Methimazole is a Graves'' disease medication, and hydroxychloroquine is used for SLE.'),
  ('autoimmune', 9, 'A client reports drooping eyelids and double vision that are worse at the end of the day and improve after a nap. Which condition should the nurse suspect?', '[{"id": "a", "text": "Multiple sclerosis"}, {"id": "b", "text": "Myasthenia gravis"}, {"id": "c", "text": "Graves'' disease"}, {"id": "d", "text": "Systemic lupus erythematosus"}]'::jsonb, '["b"]', 'Ptosis and diplopia with weakness that worsens with activity and improves with rest are the key clues for myasthenia gravis. MS can cause diplopia, but improvement with rest is the MG differentiator.'),
  ('autoimmune', 10, 'The nurse teaches a client with SLE about preventing disease flares. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will try to reduce stress in my daily life.\""}, {"id": "b", "text": "\"I will wash my hands often to avoid infections.\""}, {"id": "c", "text": "\"I will take my medications exactly as prescribed.\""}, {"id": "d", "text": "\"I will spend my afternoons sunbathing to relax.\""}]'::jsonb, '["d"]', 'Clients with autoimmune disease should avoid triggers such as stress, infections, and sun, and SLE involves photosensitivity. Reducing stress, hand hygiene, and medication compliance are all correct priorities.'),
  ('autoimmune', 11, 'A client taking prednisone for lupus wants protection against influenza this season. Which recommendation by the nurse is appropriate?', '[{"id": "a", "text": "Receive the nasal spray influenza vaccine"}, {"id": "b", "text": "Receive both nasal and injected vaccines"}, {"id": "c", "text": "Receive the injected influenza vaccine"}, {"id": "d", "text": "Avoid influenza vaccination this year"}]'::jsonb, '["c"]', 'Inactivated vaccines, including the injected flu shot, are safe and recommended for immunosuppressed clients. The nasal flu vaccine (FluMist) is live attenuated and must not be given to clients on steroids.'),
  ('autoimmune', 12, 'A client reports a recent 10-lb weight loss, hand tremor, heat intolerance, and eyes that appear to bulge. Which condition is most consistent with these findings?', '[{"id": "a", "text": "Hashimoto''s thyroiditis"}, {"id": "b", "text": "Graves'' disease"}, {"id": "c", "text": "Myasthenia gravis"}, {"id": "d", "text": "Systemic lupus erythematosus"}]'::jsonb, '["b"]', 'Bulging eyes with weight loss and tremor point to Graves'' disease, which also causes heat intolerance. Hashimoto''s thyroiditis causes cold intolerance and weight gain.'),
  ('autoimmune', 13, 'Which statement by a client newly diagnosed with celiac disease indicates a need for further teaching?', '[{"id": "a", "text": "\"My medication will let me eat bread now and then.\""}, {"id": "b", "text": "\"I need to avoid gluten completely, not just reduce it.\""}, {"id": "c", "text": "\"My treatment depends on following my diet strictly.\""}, {"id": "d", "text": "\"Gluten is what triggers the damage in my intestine.\""}]'::jsonb, '["a"]', 'Celiac disease is treated with a strict gluten-free diet and no medication. Believing a medication will allow occasional gluten shows a misunderstanding.'),
  ('autoimmune', 14, 'A client with type 1 diabetes is admitted with a high blood glucose level and acidosis. Which interventions should the nurse anticipate?', '[{"id": "a", "text": "Oral levothyroxine and a high-fiber diet"}, {"id": "b", "text": "IV fluids and a continuous insulin drip"}, {"id": "c", "text": "Pyridostigmine and suction at the bedside"}, {"id": "d", "text": "Plasmapheresis and IVIG infusions"}]'::jsonb, '["b"]', 'High glucose with acidosis indicates DKA, which is managed with IV fluids, an insulin drip, and monitoring of glucose and ketones. Pyridostigmine and plasmapheresis/IVIG are myasthenia gravis treatments.'),
  ('autoimmune', 15, 'A client is being evaluated for relapsing-remitting multiple sclerosis. Which diagnostic finding should the nurse expect?', '[{"id": "a", "text": "Positive anti-AChR antibodies"}, {"id": "b", "text": "Elevated TSH with low T4"}, {"id": "c", "text": "Positive RF and anti-CCP"}, {"id": "d", "text": "Plaques visible on an MRI"}]'::jsonb, '["d"]', 'The key marker for MS is MRI plaques with a relapsing-remitting course. Anti-AChR antibodies are the marker for myasthenia gravis.'),
  ('autoimmune', 16, 'A school nurse assesses a child suspected of having new-onset type 1 diabetes mellitus. Which findings support this suspicion?', '[{"id": "a", "text": "Weight gain, constipation, and cold intolerance"}, {"id": "b", "text": "Ptosis, diplopia, and difficulty swallowing"}, {"id": "c", "text": "Polyuria, polydipsia, and weight loss"}, {"id": "d", "text": "Bloating, steatorrhea, and anemia"}]'::jsonb, '["c"]', 'Type 1 diabetes presents with polyuria, polydipsia, polyphagia, and weight loss. Weight gain with constipation and cold intolerance suggests Hashimoto''s thyroiditis.'),
  ('autoimmune', 17, 'A client is admitted with an acute relapse of multiple sclerosis. Which medication should the nurse anticipate being prescribed?', '[{"id": "a", "text": "Levothyroxine"}, {"id": "b", "text": "Pyridostigmine"}, {"id": "c", "text": "Methimazole"}, {"id": "d", "text": "Corticosteroids"}]'::jsonb, '["d"]', 'Corticosteroids are used for acute MS episodes, along with immunomodulators and physical therapy. Pyridostigmine treats myasthenia gravis, and levothyroxine treats Hashimoto''s thyroiditis.'),
  ('autoimmune', 18, 'The nurse is caring for two clients with autoimmune thyroid disease. Which finding would be expected in the client with Graves'' disease but not in the client with Hashimoto''s thyroiditis?', '[{"id": "a", "text": "Tachycardia and heat intolerance"}, {"id": "b", "text": "Bradycardia and cold intolerance"}, {"id": "c", "text": "Weight gain and constipation"}, {"id": "d", "text": "Dry skin and hair thinning"}]'::jsonb, '["a"]', 'Graves'' disease causes tachycardia and heat intolerance from excess thyroid hormone. Bradycardia, cold intolerance, weight gain, constipation, dry skin, and hair thinning are features of Hashimoto''s thyroiditis.'),
  ('autoimmune', 19, 'A client with long-standing rheumatoid arthritis is being positioned for a procedure. Which complication should the nurse keep in mind to maintain the client''s safety?', '[{"id": "a", "text": "Myasthenic crisis"}, {"id": "b", "text": "Lupus nephritis"}, {"id": "c", "text": "Thyroid storm"}, {"id": "d", "text": "Cervical spine instability"}]'::jsonb, '["d"]', 'RA can cause joint deformities and cervical spine instability, so the nurse assesses mobility and ensures safety during procedures. Myasthenic crisis is a complication of myasthenia gravis.'),
  ('autoimmune', 20, 'A client is admitted with suspected systemic lupus erythematosus (SLE). Which assessment finding should the nurse expect?', '[{"id": "a", "text": "Bulging eyes with heat intolerance"}, {"id": "b", "text": "Ascending paralysis with loss of reflexes"}, {"id": "c", "text": "Malar rash that worsens with sun exposure"}, {"id": "d", "text": "Tight skin with Raynaud phenomenon"}]'::jsonb, '["c"]', 'A butterfly (malar) rash with photosensitivity is a hallmark of SLE. Bulging eyes with heat intolerance point to Graves'' disease, and tight skin with Raynaud points to scleroderma.'),
  ('autoimmune', 21, 'A client develops ascending paralysis and loss of reflexes two weeks after a respiratory infection. Which cerebrospinal fluid finding supports the suspected diagnosis?', '[{"id": "a", "text": "Normal protein with an elevated WBC count"}, {"id": "b", "text": "Elevated protein with a normal WBC count"}, {"id": "c", "text": "Low protein with a low WBC count"}, {"id": "d", "text": "Elevated protein with an elevated WBC count"}]'::jsonb, '["b"]', 'Ascending paralysis with loss of reflexes after an infection suggests GBS, which shows increased CSF protein with a normal WBC count. An elevated WBC count does not fit this pattern.'),
  ('autoimmune', 22, 'A client with Graves'' disease is being discharged. Which medication should the nurse expect to include in discharge teaching?', '[{"id": "a", "text": "Methimazole"}, {"id": "b", "text": "Levothyroxine"}, {"id": "c", "text": "Pyridostigmine"}, {"id": "d", "text": "Hydroxychloroquine"}]'::jsonb, '["a"]', 'Graves'' disease is treated with methimazole/PTU, beta-blockers, and radioactive iodine. Levothyroxine is the lifelong treatment for Hashimoto''s thyroiditis, which causes low thyroid hormone.'),
  ('autoimmune', 23, 'A 45-year-old client reports painful, swollen joints in both hands and morning stiffness that lasts about 90 minutes each day. Which condition do these findings most strongly suggest?', '[{"id": "a", "text": "Rheumatoid arthritis"}, {"id": "b", "text": "Systemic lupus erythematosus"}, {"id": "c", "text": "Myasthenia gravis"}, {"id": "d", "text": "Multiple sclerosis"}]'::jsonb, '["a"]', 'Symmetric joint pain and swelling with morning stiffness lasting more than 1 hour is the classic clue for rheumatoid arthritis. Myasthenia gravis causes weakness that worsens with activity and improves with rest, not prolonged joint stiffness.'),
  ('autoimmune', 24, 'A client with rheumatoid arthritis has taken methotrexate for several months. Which laboratory tests are most important for the nurse to monitor for drug toxicity?', '[{"id": "a", "text": "TSH and free T4 levels"}, {"id": "b", "text": "C-peptide and GAD antibodies"}, {"id": "c", "text": "Blood counts and liver function"}, {"id": "d", "text": "CSF protein and WBC count"}]'::jsonb, '["c"]', 'Methotrexate is a DMARD, and DMARD toxicity affects the bone marrow and liver, so blood counts and liver function are monitored. TSH and T4 are thyroid tests unrelated to methotrexate toxicity.'),
  ('autoimmune', 25, 'A client receiving methotrexate for rheumatoid arthritis asks about recommended vaccines. Which vaccine should the nurse identify as contraindicated?', '[{"id": "a", "text": "Injected influenza vaccine"}, {"id": "b", "text": "MMR vaccine"}, {"id": "c", "text": "Pneumococcal vaccine"}, {"id": "d", "text": "Tdap vaccine"}]'::jsonb, '["b"]', 'Clients on DMARDs such as methotrexate are immunosuppressed and must not receive live attenuated vaccines such as MMR. The injected flu shot, pneumococcal, and Tdap vaccines are inactivated and recommended.'),
  ('autoimmune', 26, 'A client with an autoimmune disease is starting an immunosuppressant medication. Which teaching point has the highest priority for reducing the risk of infection?', '[{"id": "a", "text": "Perform hand hygiene frequently"}, {"id": "b", "text": "Request the nasal flu vaccine"}, {"id": "c", "text": "Stop the medication if tired"}, {"id": "d", "text": "Increase activity to build immunity"}]'::jsonb, '["a"]', 'Immunosuppressants increase infection risk, so hand hygiene is a key teaching point. The nasal flu vaccine is live and is not given to immunosuppressed clients.'),
  ('autoimmune', 27, 'When assessing a client with rheumatoid arthritis, which additional finding should the nurse expect?', '[{"id": "a", "text": "Subcutaneous nodules and fatigue"}, {"id": "b", "text": "Butterfly rash across the cheeks"}, {"id": "c", "text": "Exophthalmos and a goiter"}, {"id": "d", "text": "Fruity breath and polyuria"}]'::jsonb, '["a"]', 'Along with symmetric joint pain, RA can cause subcutaneous nodules, fatigue, and fever. A butterfly rash is a feature of SLE.'),
  ('autoimmune', 28, 'Which laboratory findings support an autoimmune cause of a client''s newly diagnosed diabetes?', '[{"id": "a", "text": "Elevated TSH with anti-TPO antibodies"}, {"id": "b", "text": "Positive RF and anti-CCP antibodies"}, {"id": "c", "text": "Positive ANA and anti-dsDNA"}, {"id": "d", "text": "Low C-peptide with GAD antibodies"}]'::jsonb, '["d"]', 'The key markers for type 1 diabetes are a decreased C-peptide and GAD antibodies. RF and anti-CCP are markers for rheumatoid arthritis.'),
  ('autoimmune', 29, 'A teen newly diagnosed with type 1 diabetes mellitus asks why insulin injections are needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Your immune system destroyed the cells that make insulin.\""}, {"id": "b", "text": "\"Your thyroid gland is not making enough hormone.\""}, {"id": "c", "text": "\"Your intestines cannot absorb sugar from food.\""}, {"id": "d", "text": "\"Your nerves have lost the coating that protects them.\""}]'::jsonb, '["a"]', 'In type 1 diabetes the immune system destroys pancreatic beta cells, causing insulin deficiency. Loss of nerve coating describes MS, and thyroid destruction describes Hashimoto''s.'),
  ('autoimmune', 30, 'Which laboratory pattern should the nurse expect for a client with Graves'' disease?', '[{"id": "a", "text": "Elevated TSH with low T3/T4"}, {"id": "b", "text": "Low C-peptide with GAD antibodies"}, {"id": "c", "text": "Low TSH with elevated T3/T4"}, {"id": "d", "text": "Elevated CSF protein with normal WBC"}]'::jsonb, '["c"]', 'Graves'' disease shows a decreased TSH with increased T3/T4. Elevated TSH with low T3/T4 is the pattern for Hashimoto''s thyroiditis.'),
  ('autoimmune', 31, 'A client asks what caused their autoimmune disease. Which response by the nurse best reflects current understanding?', '[{"id": "a", "text": "\"A mix of genetics, infections, and environmental triggers.\""}, {"id": "b", "text": "\"A single gene that was inherited from one parent.\""}, {"id": "c", "text": "\"Only a viral infection that you had in the past.\""}, {"id": "d", "text": "\"Mainly a poor diet and a lack of regular exercise.\""}]'::jsonb, '["a"]', 'Autoimmune diseases have multifactorial causes, including genetics, infections, and environmental triggers. Attributing the disease to a single cause such as one gene or one infection is inaccurate.'),
  ('autoimmune', 32, 'Which assessment findings should the nurse expect in a client with untreated celiac disease?', '[{"id": "a", "text": "Morning stiffness and subcutaneous nodules"}, {"id": "b", "text": "Diarrhea, bloating, and steatorrhea"}, {"id": "c", "text": "Exophthalmos and heat intolerance"}, {"id": "d", "text": "Ptosis and weakness after activity"}]'::jsonb, '["b"]', 'Celiac disease damages small intestine villi, causing diarrhea, bloating, and steatorrhea. Morning stiffness with subcutaneous nodules suggests rheumatoid arthritis.'),
  ('autoimmune', 33, 'A client with SLE is hospitalized for a flare. To detect the disease''s most serious complication, which data should the nurse monitor most closely?', '[{"id": "a", "text": "TSH and T3/T4 levels"}, {"id": "b", "text": "BUN, creatinine, and urine output"}, {"id": "c", "text": "Blood glucose and serum ketones"}, {"id": "d", "text": "Cerebrospinal fluid protein level"}]'::jsonb, '["b"]', 'The worst complication of SLE is lupus nephritis leading to renal failure, so the nurse monitors BUN/creatinine, urine output, and BP. Glucose and ketones are monitored for DKA in type 1 diabetes.'),
  ('autoimmune', 34, 'A client with MS reports urinary urgency and has had repeated bladder infections. Which intervention should the nurse include in the plan of care?', '[{"id": "a", "text": "Administer pyridostigmine before meals"}, {"id": "b", "text": "Prepare for radioactive iodine therapy"}, {"id": "c", "text": "Implement a bladder training program"}, {"id": "d", "text": "Begin a strict gluten-free diet"}]'::jsonb, '["c"]', 'Bladder dysfunction and bladder infection are MS complications managed with bladder training, fall prevention, and dysphagia precautions. Pyridostigmine is a myasthenia gravis treatment, and radioactive iodine is used for Graves'' disease.'),
  ('autoimmune', 35, 'A client with myasthenia gravis reports increasing weakness, difficulty swallowing, and shortness of breath. What is the nurse''s priority action?', '[{"id": "a", "text": "Monitor respiratory status with suction at the bedside"}, {"id": "b", "text": "Encourage ambulation to rebuild muscle strength"}, {"id": "c", "text": "Teach energy conservation techniques for home"}, {"id": "d", "text": "Assess range of motion in all affected joints"}]'::jsonb, '["a"]', 'These findings suggest myasthenic crisis, which can progress to respiratory failure, so the priority is monitoring respiratory status and airway with suction ready. Ambulation would worsen weakness, which increases with activity.'),
  ('autoimmune', 36, 'The nurse teaches a client with Hashimoto''s thyroiditis about levothyroxine. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will take this medication every day.\""}, {"id": "b", "text": "\"I know my thyroid hormone level is low.\""}, {"id": "c", "text": "\"I will keep taking it even when I feel well.\""}, {"id": "d", "text": "\"I can stop it once my energy level returns.\""}]'::jsonb, '["d"]', 'Levothyroxine for Hashimoto''s thyroiditis is lifelong because the immune system destroys the thyroid gland. Stopping it when energy improves reflects a misunderstanding.'),
  ('autoimmune', 37, 'Which pattern of joint involvement should the nurse expect when assessing a client with rheumatoid arthritis?', '[{"id": "a", "text": "One large joint affected on a single side"}, {"id": "b", "text": "Asymmetric large joints, worse at night"}, {"id": "c", "text": "Symmetric small joints, worse in the morning"}, {"id": "d", "text": "Joints stiff only briefly after waking"}]'::jsonb, '["c"]', 'RA affects symmetric small joints and is worse in the morning, with stiffness lasting more than 1 hour. Brief stiffness or one-sided involvement does not fit the RA pattern.'),
  ('autoimmune', 38, 'A client with advanced MS coughs and chokes while drinking water at lunch. Which nursing action is most directly indicated by this finding?', '[{"id": "a", "text": "Begin a bladder training program"}, {"id": "b", "text": "Initiate dysphagia precautions"}, {"id": "c", "text": "Implement fall prevention measures"}, {"id": "d", "text": "Schedule physical therapy sessions"}]'::jsonb, '["b"]', 'Aspiration is a life-threatening MS complication, and coughing while drinking calls for dysphagia precautions. Bladder training and fall prevention address other MS complications, not the risk of aspiration.'),
  ('autoimmune', 39, 'A client presents with tight skin on the hands and face, Raynaud phenomenon, and GERD. Which condition should the nurse suspect?', '[{"id": "a", "text": "Systemic lupus erythematosus"}, {"id": "b", "text": "Rheumatoid arthritis"}, {"id": "c", "text": "Scleroderma"}, {"id": "d", "text": "Graves'' disease"}]'::jsonb, '["c"]', 'Tight skin with Raynaud phenomenon and GERD is the clue for scleroderma (CREST). SLE is identified by a butterfly rash with photosensitivity.'),
  ('autoimmune', 40, 'A client newly diagnosed with an autoimmune disease asks whether the condition will go away. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It usually resolves completely within weeks.\""}, {"id": "b", "text": "\"It goes away once the infection is treated.\""}, {"id": "c", "text": "\"It is cured with a short course of steroids.\""}, {"id": "d", "text": "\"It is usually chronic and can worsen over time.\""}]'::jsonb, '["d"]', 'Autoimmune diseases are usually chronic and progressive, and chronic inflammation can cause permanent organ damage. They are managed with immunosuppressants and anti-inflammatory medications, not cured by a short steroid course.'),
  ('autoimmune', 41, 'A client with a malar rash and signs of nephritis has laboratory testing. Which results are most consistent with systemic lupus erythematosus?', '[{"id": "a", "text": "Positive RF and anti-CCP"}, {"id": "b", "text": "Low C-peptide and GAD antibodies"}, {"id": "c", "text": "Positive ANA and anti-dsDNA"}, {"id": "d", "text": "Elevated TSH and anti-TPO"}]'::jsonb, '["c"]', 'SLE markers are ANA, anti-dsDNA, and anti-Sm. RF and anti-CCP point to rheumatoid arthritis instead.'),
  ('autoimmune', 42, 'The nurse teaches the family of a client with myasthenia gravis about complications. Which finding should the family report immediately?', '[{"id": "a", "text": "Mild eyelid drooping in the evening"}, {"id": "b", "text": "Increasing difficulty breathing"}, {"id": "c", "text": "Fatigue that improves after a nap"}, {"id": "d", "text": "Double vision after reading"}]'::jsonb, '["b"]', 'Myasthenic crisis leads to respiratory failure, so increasing difficulty breathing must be reported immediately. Evening ptosis and fatigue that improves with rest are expected MG features.'),
  ('autoimmune', 43, 'A client is being evaluated for myasthenia gravis. Which diagnostic result would support this diagnosis?', '[{"id": "a", "text": "Positive anti-CCP antibodies"}, {"id": "b", "text": "Positive GAD antibodies"}, {"id": "c", "text": "Positive anti-TPO antibodies"}, {"id": "d", "text": "Positive anti-AChR antibodies"}]'::jsonb, '["d"]', 'In myasthenia gravis, antibodies attack ACh receptors at the neuromuscular junction, so anti-AChR antibodies are the key marker. Anti-CCP supports RA, GAD supports type 1 diabetes, and anti-TPO supports Hashimoto''s.'),
  ('autoimmune', 44, 'The nurse is planning morning care for a client with myasthenia gravis. Which approach is most appropriate?', '[{"id": "a", "text": "Plan rest periods between care activities"}, {"id": "b", "text": "Complete all care in one continuous session"}, {"id": "c", "text": "Encourage extra activity to build endurance"}, {"id": "d", "text": "Schedule therapy for late in the evening"}]'::jsonb, '["a"]', 'Fatigue is managed with rest periods between activities and energy conservation, and MG weakness worsens with activity. Grouping all care into one long session would increase weakness.'),
  ('autoimmune', 45, 'A client with a long-standing autoimmune disease says, "I hate how my body looks now, and I just feel down all the time." Which nursing priority does this statement most directly reflect?', '[{"id": "a", "text": "Medication safety"}, {"id": "b", "text": "Psychosocial support"}, {"id": "c", "text": "Fatigue management"}, {"id": "d", "text": "Infection prevention"}]'::jsonb, '["b"]', 'Chronic illness is associated with depression, anxiety, and body image concerns, which call for psychosocial support. Fatigue management addresses rest and energy conservation rather than mood and body image.'),
  ('autoimmune', 46, 'The nurse reviews the record of a client with systemic lupus erythematosus. Which group of findings reflects organ involvement from this disease?', '[{"id": "a", "text": "Nephritis, pericarditis, and pleuritis"}, {"id": "b", "text": "Exophthalmos, goiter, and tremor"}, {"id": "c", "text": "Ptosis, diplopia, and dysphagia"}, {"id": "d", "text": "Steatorrhea, bloating, and anemia"}]'::jsonb, '["a"]', 'SLE attacks multiple organs via immune complexes, causing nephritis, pericarditis, and pleuritis. Ptosis, diplopia, and dysphagia are features of myasthenia gravis.'),
  ('autoimmune', 47, 'A client with celiac disease asks why eating gluten causes symptoms. The nurse explains that the immune reaction to gluten damages which structure?', '[{"id": "a", "text": "Pancreatic beta cells"}, {"id": "b", "text": "Small intestine villi"}, {"id": "c", "text": "Synovial joint linings"}, {"id": "d", "text": "Myelin sheath of nerves"}]'::jsonb, '["b"]', 'In celiac disease the immune system reacts to gluten and damages the small intestine villi. Destruction of pancreatic beta cells describes type 1 diabetes.'),
  ('autoimmune', 48, 'A client with symmetric joint swelling is being evaluated. Which laboratory results would support a diagnosis of rheumatoid arthritis?', '[{"id": "a", "text": "Positive ANA and anti-Sm"}, {"id": "b", "text": "Positive RF and anti-CCP"}, {"id": "c", "text": "Positive anti-AChR antibodies"}, {"id": "d", "text": "Positive anti-TPO antibodies"}]'::jsonb, '["b"]', 'The key markers for rheumatoid arthritis are RF and anti-CCP. ANA and anti-Sm are markers for SLE.'),
  ('autoimmune', 49, 'A nurse is supervising a nursing student caring for a client who receives a biologic for rheumatoid arthritis. Which action by the student requires correction?', '[{"id": "a", "text": "Teaching the client to perform hand hygiene"}, {"id": "b", "text": "Planning rest periods between activities"}, {"id": "c", "text": "Offering a pneumococcal vaccine as ordered"}, {"id": "d", "text": "Preparing a varicella vaccine for the client"}]'::jsonb, '["d"]', 'Clients on biologics are immunosuppressed and must not receive live attenuated vaccines such as varicella. Pneumococcal vaccine is inactivated and recommended for immunosuppressed clients.'),
  ('autoimmune', 50, 'A client with rheumatoid arthritis asks about the role of prednisone in treatment. Which statement by the client shows correct understanding?', '[{"id": "a", "text": "\"Steroids are used short-term along with my DMARD.\""}, {"id": "b", "text": "\"Steroids will permanently replace my methotrexate.\""}, {"id": "c", "text": "\"Steroids are the only medication I will need.\""}, {"id": "d", "text": "\"Steroids are given lifelong at high doses.\""}]'::jsonb, '["a"]', 'RA treatment includes DMARDs such as methotrexate, NSAIDs, biologics, and steroids used short-term. Steroids do not replace DMARDs or get used lifelong.'),
  ('gbs', 1, 'A client newly diagnosed with Guillain-Barré syndrome (GBS) asks what is happening to the nerves. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The immune system attacks the myelin of the brain and cord"}, {"id": "b", "text": "A virus directly destroys the muscle fibers in the legs"}, {"id": "c", "text": "The immune system attacks the myelin of peripheral nerves"}, {"id": "d", "text": "A blood clot blocks the nerves that supply the legs"}]'::jsonb, '["c"]', 'GBS is an acute autoimmune disorder in which the immune system attacks the myelin sheath of peripheral nerves. Attack on the central nervous system describes multiple sclerosis.'),
  ('gbs', 2, 'A client with Guillain-Barré syndrome asks how the condition differs from multiple sclerosis. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"GBS affects the CNS; MS affects peripheral nerves.\""}, {"id": "b", "text": "\"Both conditions attack only the spinal cord nerves.\""}, {"id": "c", "text": "\"GBS affects peripheral nerves; MS affects the CNS.\""}, {"id": "d", "text": "\"Both conditions attack only the peripheral nerves.\""}]'::jsonb, '["c"]', 'GBS is an attack on the peripheral nervous system, while multiple sclerosis is an attack on the central nervous system.'),
  ('gbs', 3, 'A client is admitted with bilateral leg weakness and suspected Guillain-Barré syndrome. Which finding in the client''s history is most significant?', '[{"id": "a", "text": "Seasonal allergies every spring"}, {"id": "b", "text": "A sprained ankle ten years ago"}, {"id": "c", "text": "A diarrheal illness three weeks ago"}, {"id": "d", "text": "A family history of high cholesterol"}]'::jsonb, '["c"]', 'Campylobacter jejuni GI infection is the number one preceding infection, and GBS usually follows an infection 2 to 4 weeks earlier.'),
  ('gbs', 4, 'The nurse is taking a history from a client with suspected Guillain-Barré syndrome. Within which time frame should the nurse ask about recent infections?', '[{"id": "a", "text": "The previous 1 to 2 days"}, {"id": "b", "text": "The previous 6 to 12 months"}, {"id": "c", "text": "The previous several years"}, {"id": "d", "text": "The previous 2 to 4 weeks"}]'::jsonb, '["d"]', 'GBS usually follows an infection 2 to 4 weeks earlier.'),
  ('gbs', 5, 'The nurse is reviewing the history of a client with suspected Guillain-Barré syndrome. Which history item is a recognized trigger of the condition?', '[{"id": "a", "text": "Daily multivitamin use"}, {"id": "b", "text": "Recent dental cleaning"}, {"id": "c", "text": "Long-term contact lens use"}, {"id": "d", "text": "Zika virus infection"}]'::jsonb, '["d"]', 'Besides infections such as Campylobacter jejuni, other triggers include recent vaccination, surgery or trauma, and Zika virus infection.'),
  ('gbs', 6, 'A nursing student asks why an intestinal infection can lead to Guillain-Barré syndrome. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The bacteria travel to and directly infect the spinal cord"}, {"id": "b", "text": "Dehydration from diarrhea damages the peripheral nerves"}, {"id": "c", "text": "The infection lowers acetylcholine at the muscle junction"}, {"id": "d", "text": "Antibodies to the infection cross-react with nerve myelin"}]'::jsonb, '["d"]', 'An infection triggers antibody formation, and those antibodies cross-react with the myelin sheath of peripheral nerves through molecular mimicry, causing demyelination.'),
  ('gbs', 7, 'A client reports tingling and weakness in both feet that began two days ago. Which description of symptom onset is consistent with Guillain-Barré syndrome?', '[{"id": "a", "text": "Weakness began in both feet and is moving upward"}, {"id": "b", "text": "Weakness began in the face and is moving downward"}, {"id": "c", "text": "Weakness affects one arm and one leg on one side"}, {"id": "d", "text": "Weakness appears only after periods of exercise"}]'::jsonb, '["a"]', 'GBS begins with bilateral leg weakness that starts distally in the feet and toes with tingling and numbness, then ascends.'),
  ('gbs', 8, 'The nurse is assessing deep tendon reflexes in a client with Guillain-Barré syndrome. Which finding would the nurse expect?', '[{"id": "a", "text": "Absent reflexes"}, {"id": "b", "text": "Brisk reflexes"}, {"id": "c", "text": "Normal reflexes"}, {"id": "d", "text": "Reflexes only in the legs"}]'::jsonb, '["a"]', 'Absent reflexes (areflexia) are a key diagnostic feature of GBS.'),
  ('gbs', 9, 'The nurse is teaching the family of a client with Guillain-Barré syndrome about the expected progression of weakness. Which sequence is accurate?', '[{"id": "a", "text": "Breathing muscles, then arms, then trunk, then feet and legs"}, {"id": "b", "text": "Arms, then feet and legs, then breathing muscles, then trunk"}, {"id": "c", "text": "Feet and legs, then trunk, then arms, then breathing muscles"}, {"id": "d", "text": "Trunk, then breathing muscles, then feet and legs, then arms"}]'::jsonb, '["c"]', 'GBS has an ascending pattern that starts in the legs and moves upward through the thighs and trunk to the arms, with diaphragm involvement causing respiratory failure.'),
  ('gbs', 10, 'A client with Guillain-Barré syndrome states, "Nothing can be done for this burning pain in my legs." Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Managing your pain is part of your treatment plan.\""}, {"id": "b", "text": "\"Pain means the disease is now in your spinal cord.\""}, {"id": "c", "text": "\"Pain is not a symptom of this condition at all.\""}, {"id": "d", "text": "\"Steroids will be ordered to take the pain away.\""}]'::jsonb, '["a"]', 'Pain is a sensory symptom of GBS, and pain management is part of supportive care. Steroids are not effective in GBS.'),
  ('gbs', 11, 'The nurse is assessing a client with Guillain-Barré syndrome. Which finding indicates autonomic dysfunction?', '[{"id": "a", "text": "Absent deep tendon reflexes in the legs"}, {"id": "b", "text": "Tingling and numbness in the feet"}, {"id": "c", "text": "Fluctuating blood pressure and heart rate"}, {"id": "d", "text": "Weakness in the thighs and trunk"}]'::jsonb, '["c"]', 'Autonomic dysfunction in GBS includes HR and BP instability, urinary retention, and diaphoresis. Areflexia is a motor finding, and tingling is a sensory finding.'),
  ('gbs', 12, 'A client with Guillain-Barré syndrome has not voided in many hours, and the bladder is distended. Which action should the nurse anticipate?', '[{"id": "a", "text": "Restricting all oral fluid intake"}, {"id": "b", "text": "Catheterization for urinary retention"}, {"id": "c", "text": "Starting a high-dose corticosteroid"}, {"id": "d", "text": "Waiting until the next shift to recheck"}]'::jsonb, '["b"]', 'Urinary retention is an autonomic finding in GBS, and urinary output is monitored because catheterization may be needed. Steroids are not effective in GBS.'),
  ('gbs', 13, 'A client with Guillain-Barré syndrome is admitted to the unit. Which prescription should the nurse anticipate to address autonomic dysfunction?', '[{"id": "a", "text": "Daily vital signs only"}, {"id": "b", "text": "Continuous cardiac monitoring"}, {"id": "c", "text": "Weekly heart rhythm strip"}, {"id": "d", "text": "Heart rate check at discharge"}]'::jsonb, '["b"]', 'Continuous cardiac monitoring is needed because clients with GBS can develop sudden bradycardia or tachycardia.'),
  ('gbs', 14, 'The nurse observes assistive personnel (AP) caring for a client with Guillain-Barré syndrome. Which action by the AP requires correction?', '[{"id": "a", "text": "Repositioning the client every 2 hours"}, {"id": "b", "text": "Checking blood pressure only once per shift"}, {"id": "c", "text": "Applying the ordered compression stockings"}, {"id": "d", "text": "Reporting new sweating to the nurse"}]'::jsonb, '["b"]', 'Frequent BP checks are required in GBS because BP swings can be severe and sudden. Turning every 2 hours, compression stockings, and reporting diaphoresis are appropriate.'),
  ('gbs', 15, 'A client with mild leg weakness and suspected Guillain-Barré syndrome reports back pain that began before the weakness. How should the nurse interpret this report?', '[{"id": "a", "text": "Back pain rules out a diagnosis of GBS"}, {"id": "b", "text": "Back pain is often an early symptom of GBS"}, {"id": "c", "text": "Back pain shows a separate spine injury"}, {"id": "d", "text": "Back pain appears only in late recovery"}]'::jsonb, '["b"]', 'Pain, often back pain early in the course, is a sensory manifestation of GBS.'),
  ('gbs', 16, 'The nurse is comparing motor and sensory findings in a client with Guillain-Barré syndrome. Which finding would the nurse expect?', '[{"id": "a", "text": "Motor weakness more severe than sensory changes"}, {"id": "b", "text": "Sensory loss more severe than motor weakness"}, {"id": "c", "text": "Sensory loss with fully normal motor strength"}, {"id": "d", "text": "Motor and sensory findings limited to one arm"}]'::jsonb, '["a"]', 'In GBS, sensory changes such as tingling and numbness are usually less severe than the motor weakness.'),
  ('gbs', 17, 'The spouse of a client with Guillain-Barré syndrome asks how quickly the weakness will progress. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It usually progresses over several years.\""}, {"id": "b", "text": "\"It usually peaks within a few minutes.\""}, {"id": "c", "text": "\"It usually stops progressing within hours.\""}, {"id": "d", "text": "\"It usually progresses over days to weeks.\""}]'::jsonb, '["d"]', 'Weakness in GBS progresses over days to weeks.'),
  ('gbs', 18, 'A client with progressive leg weakness has a lumbar puncture. Results show an elevated cerebrospinal fluid protein with a normal white blood cell count. How should the nurse interpret these results?', '[{"id": "a", "text": "They indicate a bacterial infection of the spinal fluid"}, {"id": "b", "text": "They are a classic finding of Guillain-Barré syndrome"}, {"id": "c", "text": "They rule out GBS because the white cells are normal"}, {"id": "d", "text": "They suggest the sample was contaminated with blood"}]'::jsonb, '["b"]', 'High CSF protein with normal white cells, called albuminocytologic dissociation, is the classic GBS finding.'),
  ('gbs', 19, 'A client with suspected Guillain-Barré syndrome is scheduled for a lumbar puncture. Which cerebrospinal fluid result would the nurse expect?', '[{"id": "a", "text": "Increased WBC count with normal protein"}, {"id": "b", "text": "Increased protein with increased WBC count"}, {"id": "c", "text": "Increased protein with a normal WBC count"}, {"id": "d", "text": "Normal protein with a normal WBC count"}]'::jsonb, '["c"]', 'The expected LP finding in GBS is increased CSF protein with a normal WBC count, known as albuminocytologic dissociation.'),
  ('gbs', 20, 'A client with suspected Guillain-Barré syndrome undergoes nerve conduction studies. Which result would the nurse expect?', '[{"id": "a", "text": "Shortened latency and increased amplitude"}, {"id": "b", "text": "Normal latency and normal amplitude"}, {"id": "c", "text": "Shortened latency and reduced amplitude"}, {"id": "d", "text": "Prolonged latency and reduced amplitude"}]'::jsonb, '["d"]', 'Nerve conduction studies in GBS show prolonged latency and reduced amplitude due to demyelination.'),
  ('gbs', 21, 'The nurse is trending serial pulmonary function tests for a client with Guillain-Barré syndrome. Which finding should prompt the nurse to prepare for intubation?', '[{"id": "a", "text": "Falling vital capacity with shallow breathing"}, {"id": "b", "text": "Stable vital capacity with steady breathing"}, {"id": "c", "text": "New tingling in both of the client''s feet"}, {"id": "d", "text": "Mild back pain rated as tolerable"}]'::jsonb, '["a"]', 'The nurse should prepare for intubation if vital capacity falls or breathing becomes shallow, because respiratory failure is the leading life-threatening complication.'),
  ('gbs', 22, 'A client is admitted with newly diagnosed Guillain-Barré syndrome. Which assessment is the nurse''s highest priority?', '[{"id": "a", "text": "Strength and reflexes in the lower legs"}, {"id": "b", "text": "Pain level and response to analgesia"}, {"id": "c", "text": "Skin condition over the bony prominences"}, {"id": "d", "text": "Respiratory rate, depth, and oxygen saturation"}]'::jsonb, '["d"]', 'Airway and breathing are the number one priority in GBS, with monitoring of respiratory rate, depth, SpO2, ABGs, and vital capacity.'),
  ('gbs', 23, 'The nurse receives report on four clients with Guillain-Barré syndrome. Which client should the nurse assess first?', '[{"id": "a", "text": "The client with tingling in both feet since this morning"}, {"id": "b", "text": "The client with back pain rated 4 on a 10-point scale"}, {"id": "c", "text": "The client asking when physical therapy will begin"}, {"id": "d", "text": "The client with shallow breathing and accessory muscle use"}]'::jsonb, '["d"]', 'Shallow breathing and accessory muscle use are signs of respiratory failure, the number one life-threatening complication of GBS.'),
  ('gbs', 24, 'A nursing student asks which complication poses the greatest threat to life in a client with Guillain-Barré syndrome. Which response by the nurse is accurate?', '[{"id": "a", "text": "Foot drop"}, {"id": "b", "text": "Pressure injury"}, {"id": "c", "text": "Muscle contracture"}, {"id": "d", "text": "Respiratory failure"}]'::jsonb, '["d"]', 'Respiratory failure is the number one life-threatening complication of GBS. Foot drop, pressure injuries, and contractures are prevented with mobility care but are not the top threat.'),
  ('gbs', 25, 'A client with Guillain-Barré syndrome asks for a glass of water. Which action should the nurse take first?', '[{"id": "a", "text": "Assess the client''s ability to swallow"}, {"id": "b", "text": "Provide the water through a straw"}, {"id": "c", "text": "Raise the head of the bed and leave"}, {"id": "d", "text": "Ask the AP to help the client drink"}]'::jsonb, '["a"]', 'Swallowing ability must be assessed before all oral intake because aspiration risk is high in GBS.'),
  ('gbs', 26, 'The nurse observes a client with Guillain-Barré syndrome during lunch. Which finding suggests the client is at risk for aspiration?', '[{"id": "a", "text": "Coughing while eating and drooling"}, {"id": "b", "text": "Eating slowly while sitting upright"}, {"id": "c", "text": "Asking for a second serving of soup"}, {"id": "d", "text": "Reporting mild tingling in the hands"}]'::jsonb, '["a"]', 'Weak swallowing muscles in GBS lead to coughing when eating, drooling, and silent aspiration.'),
  ('gbs', 27, 'A client with Guillain-Barré syndrome has weak swallowing muscles. Which position should the nurse use to reduce aspiration risk?', '[{"id": "a", "text": "Flat supine"}, {"id": "b", "text": "Prone"}, {"id": "c", "text": "Trendelenburg"}, {"id": "d", "text": "Semi-upright"}]'::jsonb, '["d"]', 'Aspiration prevention in GBS includes a semi-upright position along with swallowing assessment.'),
  ('gbs', 28, 'A client with Guillain-Barré syndrome coughs and chokes with most meals despite positioning. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "A regular diet with larger, faster bites"}, {"id": "b", "text": "A swallow study and possible nasogastric tube"}, {"id": "c", "text": "A high-dose corticosteroid to restore swallowing"}, {"id": "d", "text": "Thin liquids only until symptoms resolve"}]'::jsonb, '["b"]', 'Actions for aspiration risk in GBS include swallowing assessment, semi-upright positioning, a swallow study, and an NGT if needed. Steroids are not effective in GBS.'),
  ('gbs', 29, 'A client is diagnosed with Guillain-Barré syndrome. Which first-line treatment should the nurse anticipate?', '[{"id": "a", "text": "High-dose IV corticosteroids"}, {"id": "b", "text": "Oral pyridostigmine"}, {"id": "c", "text": "Long-term oral antibiotics"}, {"id": "d", "text": "IV immunoglobulin (IVIG)"}]'::jsonb, '["d"]', 'IVIG blocks damaging antibodies and is first-line treatment for GBS. Steroids are not effective in GBS.'),
  ('gbs', 30, 'A client with Guillain-Barré syndrome is scheduled for plasmapheresis. Which statement by the client indicates understanding of the procedure?', '[{"id": "a", "text": "\"It removes harmful antibodies from my blood.\""}, {"id": "b", "text": "\"It adds donor antibodies that block mine.\""}, {"id": "c", "text": "\"It rebuilds the myelin on my nerves.\""}, {"id": "d", "text": "\"It replaces my need for breathing checks.\""}]'::jsonb, '["a"]', 'Plasmapheresis removes harmful antibodies from the blood, whereas IVIG blocks damaging antibodies.'),
  ('gbs', 31, 'The family of a client with Guillain-Barré syndrome asks whether IVIG or plasmapheresis is more effective. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Plasmapheresis works far better than IVIG.\""}, {"id": "b", "text": "\"IVIG works only after plasmapheresis fails.\""}, {"id": "c", "text": "\"Both work equally well; IVIG is easier to give.\""}, {"id": "d", "text": "\"Neither works as well as steroid therapy.\""}]'::jsonb, '["c"]', 'IVIG and plasmapheresis are equally effective, and IVIG is often preferred because it is easier to administer. Steroids are not effective in GBS.'),
  ('gbs', 32, 'The nurse reviews admission prescriptions for a client with Guillain-Barré syndrome. Which prescription should the nurse question?', '[{"id": "a", "text": "IV immunoglobulin infusion"}, {"id": "b", "text": "Subcutaneous heparin"}, {"id": "c", "text": "High-dose IV corticosteroid"}, {"id": "d", "text": "Passive range-of-motion exercises"}]'::jsonb, '["c"]', 'Corticosteroids are not effective in GBS; IVIG and plasmapheresis are the treatments. Heparin for DVT prevention and passive ROM are appropriate.'),
  ('gbs', 33, 'The nurse is teaching the family of a client with Guillain-Barré syndrome about treatment. Which statement by a family member indicates a need for further teaching?', '[{"id": "a", "text": "\"IVIG helps block the antibodies causing damage.\""}, {"id": "b", "text": "\"Plasmapheresis filters antibodies out of his blood.\""}, {"id": "c", "text": "\"Steroids will be the main drug used to treat him.\""}, {"id": "d", "text": "\"His breathing will be checked very closely.\""}]'::jsonb, '["c"]', 'Steroids should not be given for GBS because they are not effective. IVIG blocks antibodies and plasmapheresis removes them, and respiratory monitoring is the top priority.'),
  ('gbs', 34, 'A client with Guillain-Barré syndrome asks why subcutaneous heparin has been prescribed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It helps block the antibodies attacking nerves.\""}, {"id": "b", "text": "\"It helps prevent clots while you are immobile.\""}, {"id": "c", "text": "\"It helps restore the reflexes in your legs.\""}, {"id": "d", "text": "\"It helps stabilize your heart rate and blood pressure.\""}]'::jsonb, '["b"]', 'Anticoagulants such as heparin are used for DVT prevention in immobile GBS clients. Blocking antibodies is the role of IVIG.'),
  ('gbs', 35, 'The nurse observes assistive personnel (AP) caring for an immobile client with Guillain-Barré syndrome. Which action by the AP requires correction?', '[{"id": "a", "text": "Turning the client on a 2-hour repositioning schedule"}, {"id": "b", "text": "Reporting a sudden change in heart rate to the nurse"}, {"id": "c", "text": "Leaving compression stockings off while the client rests"}, {"id": "d", "text": "Placing the client semi-upright for the lunch meal"}]'::jsonb, '["c"]', 'DVT prophylaxis in GBS includes anticoagulants plus compression stockings because immobility leads to clot formation. Turning every 2 hours and semi-upright positioning for meals are correct.'),
  ('gbs', 36, 'The nurse is planning repositioning for an immobile client with Guillain-Barré syndrome. How often should the client be turned?', '[{"id": "a", "text": "Every 2 hours"}, {"id": "b", "text": "Every 4 hours"}, {"id": "c", "text": "Every 8 hours"}, {"id": "d", "text": "Once a day"}]'::jsonb, '["a"]', 'Clients with GBS should be turned every 2 hours to prevent pressure ulcers and hypostatic pneumonia.'),
  ('gbs', 37, 'A family member asks why the nurse performs passive range-of-motion exercises for a client with Guillain-Barré syndrome. Which response is accurate?', '[{"id": "a", "text": "\"They help prevent contractures and muscle atrophy.\""}, {"id": "b", "text": "\"They help speed the removal of harmful antibodies.\""}, {"id": "c", "text": "\"They help restore reflexes within a day or two.\""}, {"id": "d", "text": "\"They help prevent changes in blood pressure.\""}]'::jsonb, '["a"]', 'Passive ROM exercises are done to prevent contractures and muscle atrophy in GBS.'),
  ('gbs', 38, 'A client with Guillain-Barré syndrome has profound weakness of both lower legs. Which intervention should the nurse include to prevent foot drop?', '[{"id": "a", "text": "Keeping the feet unsupported in bed"}, {"id": "b", "text": "Applying splints or orthotics as ordered"}, {"id": "c", "text": "Waiting for strength to return on its own"}, {"id": "d", "text": "Limiting range of motion of the ankles"}]'::jsonb, '["b"]', 'Foot drop prevention in GBS includes splints or orthotics as ordered, along with passive ROM to prevent contractures.'),
  ('gbs', 39, 'A client with Guillain-Barré syndrome has developed facial nerve involvement with facial weakness. Which intervention should the nurse add to the plan of care?', '[{"id": "a", "text": "Lubricating eye drops and eye patches"}, {"id": "b", "text": "Warm compresses applied to the cheeks"}, {"id": "c", "text": "Limiting all oral care to once daily"}, {"id": "d", "text": "Restricting fluids to reduce drooling"}]'::jsonb, '["a"]', 'If the facial nerve is involved, eye care includes lubricating drops and eye patches.'),
  ('gbs', 40, 'A client with Guillain-Barré syndrome has just been intubated and placed on mechanical ventilation. Which nursing intervention is a priority for psychosocial care?', '[{"id": "a", "text": "Establishing a non-verbal communication system"}, {"id": "b", "text": "Limiting conversation to protect the airway"}, {"id": "c", "text": "Asking the family to speak for the client"}, {"id": "d", "text": "Postponing all teaching until extubation"}]'::jsonb, '["a"]', 'A non-verbal communication system should be established if the client is intubated or facial muscles are weak, because the client is cognitively intact.'),
  ('gbs', 41, 'A nursing student caring for an intubated client with Guillain-Barré syndrome makes several statements. Which statement requires correction by the nurse?', '[{"id": "a", "text": "\"I will explain each procedure before I begin it.\""}, {"id": "b", "text": "\"I will use the letter board to let him answer me.\""}, {"id": "c", "text": "\"He can''t follow us, so we can talk freely at his bedside.\""}, {"id": "d", "text": "\"I know that he may feel very frightened right now.\""}]'::jsonb, '["c"]', 'The client with GBS is cognitively intact but unable to move, which causes severe psychological distress, so care should include explanations and communication.'),
  ('gbs', 42, 'The spouse of a client with Guillain-Barré syndrome asks, "Will my husband ever get better?" Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Most people recover completely within a few days.\""}, {"id": "b", "text": "\"Most people recover significantly, but recovery is slow.\""}, {"id": "c", "text": "\"Most people stay permanently paralyzed after this.\""}, {"id": "d", "text": "\"Recovery depends on how soon steroids are started.\""}]'::jsonb, '["b"]', 'Most clients with GBS recover significantly, but recovery is slow and takes months. Steroids are not effective in GBS.'),
  ('gbs', 43, 'A client with Guillain-Barré syndrome is being transferred to rehabilitation. Which statement by the client indicates understanding of the recovery pattern?', '[{"id": "a", "text": "\"I expect to need months of therapy to regain strength.\""}, {"id": "b", "text": "\"I expect to be walking normally by the end of the week.\""}, {"id": "c", "text": "\"I expect my weakness to stay the same for the rest of my life.\""}, {"id": "d", "text": "\"I expect to stop therapy once my first IVIG dose is done.\""}]'::jsonb, '["a"]', 'Recovery from GBS is slow and takes months, and physical therapy supports rehabilitation and recovery, though most clients recover significantly.'),
  ('gbs', 44, 'A client with Guillain-Barré syndrome asks whether the flu vaccine caused the illness. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Vaccines are the most common GBS trigger.\""}, {"id": "b", "text": "\"Vaccines have never been linked to GBS.\""}, {"id": "c", "text": "\"Only childhood vaccines can trigger GBS.\""}, {"id": "d", "text": "\"Vaccination is a rare trigger for GBS.\""}]'::jsonb, '["d"]', 'Recent vaccination, such as the flu vaccine, is a rare trigger. Campylobacter jejuni GI infection is the most common preceding infection.'),
  ('gbs', 45, 'The nurse is reviewing the history of a client with suspected Guillain-Barré syndrome. Besides a GI illness, which recent infection is also associated with GBS?', '[{"id": "a", "text": "A seasonal pollen allergy"}, {"id": "b", "text": "A minor paper cut infection"}, {"id": "c", "text": "A fungal toenail condition"}, {"id": "d", "text": "Epstein-Barr virus infection"}]'::jsonb, '["d"]', 'In addition to Campylobacter jejuni, respiratory infections, CMV, and EBV are preceding infections associated with GBS.'),
  ('gbs', 46, 'The nurse is planning care for a client with Guillain-Barré syndrome who is on bed rest. Which factor places the client at risk for both deep vein thrombosis and pressure ulcers?', '[{"id": "a", "text": "IVIG therapy"}, {"id": "b", "text": "Immobility"}, {"id": "c", "text": "Recent GI infection"}, {"id": "d", "text": "Elevated CSF protein"}]'::jsonb, '["b"]', 'In GBS, immobility leads to clot formation and skin breakdown, managed with anticoagulants, compression, and repositioning every 2 hours.'),
  ('gbs', 47, 'An anxious, intubated client with Guillain-Barré syndrome uses a letter board to ask, "Am I going to be like this forever?" Which nursing approach is most appropriate?', '[{"id": "a", "text": "Avoid the question to prevent added distress"}, {"id": "b", "text": "Give honest, reassuring information about recovery"}, {"id": "c", "text": "Tell the client that recovery is not expected"}, {"id": "d", "text": "Promise the client a full recovery by next week"}]'::jsonb, '["b"]', 'Communication with the client should be honest and reassuring about expected recovery; most clients recover significantly with treatment.'),
  ('gbs', 48, 'A nursing student asks why the nurse repositions a client with Guillain-Barré syndrome so frequently. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It speeds the return of the deep tendon reflexes"}, {"id": "b", "text": "It prevents pressure ulcers and hypostatic pneumonia"}, {"id": "c", "text": "It removes the antibodies that damage the nerves"}, {"id": "d", "text": "It prevents the paralysis from moving upward"}]'::jsonb, '["b"]', 'Turning every 2 hours prevents pressure ulcers and hypostatic pneumonia in the immobile client.'),
  ('gbs', 49, 'A client with Guillain-Barré syndrome is breathing at a normal rate. Which additional respiratory finding indicates the client''s breathing is becoming compromised?', '[{"id": "a", "text": "Deep, even breaths with a strong cough"}, {"id": "b", "text": "Clear speech in full, long sentences"}, {"id": "c", "text": "Shallow breaths with decreased tidal volume"}, {"id": "d", "text": "Oxygen saturation unchanged from admission"}]'::jsonb, '["c"]', 'Respiratory compromise in GBS includes shallow breathing with decreased tidal volume, inability to cough effectively, and decreasing SpO2.'),
  ('gbs', 50, 'The nurse is assessing a client with Guillain-Barré syndrome whose leg weakness has been progressing. Which finding indicates that the paralysis has reached the upper body?', '[{"id": "a", "text": "New tingling and numbness in the toes"}, {"id": "b", "text": "New hand weakness and trouble swallowing"}, {"id": "c", "text": "New weakness in the feet and ankles"}, {"id": "d", "text": "New absence of reflexes at the ankles"}]'::jsonb, '["b"]', 'As GBS ascends, it reaches the upper body, affecting the arms and hands and causing dysphagia, before involving the respiratory muscles.'),
  ('immunodef', 1, 'A client starting chemotherapy asks why the treatment increases the risk of infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It causes the thymus gland to stop forming.\""}, {"id": "b", "text": "\"It kills fast-growing immune cells.\""}, {"id": "c", "text": "\"It destroys only the CD4+ T cells.\""}, {"id": "d", "text": "\"It removes antibodies from the blood.\""}]'::jsonb, '["b"]', 'Chemotherapy and radiation kill fast-growing immune cells, causing secondary immunodeficiency. Selective destruction of CD4+ T cells describes HIV.'),
  ('immunodef', 2, 'The nurse teaches a client with common variable immunodeficiency (CVID) about IVIG therapy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep all of my scheduled infusions.\""}, {"id": "b", "text": "\"I can stop IVIG once my infections stop.\""}, {"id": "c", "text": "\"IVIG gives me antibodies my body lacks.\""}, {"id": "d", "text": "\"I will need these infusions for life.\""}]'::jsonb, '["b"]', 'CVID is treated with lifelong IVIG infusions, and schedule adherence is a nursing priority. Stopping IVIG when infections stop shows a misunderstanding.'),
  ('immunodef', 3, 'Which intervention is most important for preventing infection in a client with immunodeficiency?', '[{"id": "a", "text": "Wearing a mask at all times at home"}, {"id": "b", "text": "Performing frequent hand hygiene"}, {"id": "c", "text": "Avoiding all types of vaccines"}, {"id": "d", "text": "Eating mostly raw fruits and vegetables"}]'::jsonb, '["b"]', 'Hand hygiene is the number one infection prevention tool. Inactivated vaccines are recommended rather than avoided, and masks are advised for public or crowded places.'),
  ('immunodef', 4, 'A client receiving chemotherapy develops a fever and a new cough. Which action should the nurse take?', '[{"id": "a", "text": "Recheck the temperature in 8 hours"}, {"id": "b", "text": "Encourage fluids and reassess tomorrow"}, {"id": "c", "text": "Give a live vaccine to boost immunity"}, {"id": "d", "text": "Report the findings to the provider now"}]'::jsonb, '["d"]', 'Signs of infection such as fever and cough in an immunocompromised client must be reported immediately. Delaying reassessment risks a life-threatening infection.'),
  ('immunodef', 5, 'The parent of a boy with Bruton''s X-linked agammaglobulinemia asks why his bacterial infections did not begin until about 6 months of age. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"His thymus finished developing at that age.\""}, {"id": "b", "text": "\"His T cells were not produced until then.\""}, {"id": "c", "text": "\"His routine vaccines triggered the infections.\""}, {"id": "d", "text": "\"The antibodies from his mother had worn off.\""}]'::jsonb, '["d"]', 'In Bruton''s, recurrent bacterial infections start around 6 months, after maternal antibodies are gone. The defect is absent B cells and antibodies, not T cells or the thymus.'),
  ('immunodef', 6, 'The parents of an infant with SCID ask what is wrong with their baby''s immune system. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Only the B cells are missing.\""}, {"id": "b", "text": "\"Only the T cells are missing.\""}, {"id": "c", "text": "\"The thymus is enlarged and overactive.\""}, {"id": "d", "text": "\"Both B cells and T cells are absent.\""}]'::jsonb, '["d"]', 'In SCID both lymphocyte lines are absent, with no B or T cells, giving zero immune defense. Absent B cells alone describes Bruton''s agammaglobulinemia.'),
  ('immunodef', 7, 'An infant with SCID is due for routine immunizations. Which vaccine should the nurse identify as contraindicated?', '[{"id": "a", "text": "Rotavirus vaccine"}, {"id": "b", "text": "Hepatitis B vaccine"}, {"id": "c", "text": "Pneumococcal vaccine"}, {"id": "d", "text": "Injected influenza vaccine"}]'::jsonb, '["a"]', 'Rotavirus is a live attenuated vaccine and is contraindicated in immunocompromised clients. Hepatitis B, pneumococcal, and injected flu vaccines are inactivated and safe.'),
  ('immunodef', 8, 'Which statement by a client being discharged on ongoing chemotherapy indicates understanding of follow-up care?', '[{"id": "a", "text": "\"I will have my blood counts checked regularly.\""}, {"id": "b", "text": "\"I will skip my lab work if I am feeling fine.\""}, {"id": "c", "text": "\"I will get the MMR vaccine at my next visit.\""}, {"id": "d", "text": "\"I will check my labs only if I get a fever.\""}]'::jsonb, '["a"]', 'Immunocompromised clients should have their CBC and labs monitored regularly. The MMR vaccine is live and contraindicated.'),
  ('immunodef', 9, 'A charge nurse observes assistive personnel (AP) caring for a client with severe neutropenia. Which action by the AP requires correction?', '[{"id": "a", "text": "Performing hand hygiene before entering"}, {"id": "b", "text": "Providing care while having a cough and fever"}, {"id": "c", "text": "Washing the fruit on the meal tray before serving"}, {"id": "d", "text": "Keeping the protective isolation sign posted"}]'::jsonb, '["b"]', 'Immunocompromised clients must avoid sick contacts, so an AP with a cough and fever should not provide care. Hand hygiene and protective isolation for severe neutropenia are correct.'),
  ('immunodef', 10, 'An infant with SCID is admitted to the pediatric unit while awaiting treatment. Which room assignment is most appropriate?', '[{"id": "a", "text": "A private room with protective isolation"}, {"id": "b", "text": "A shared room with a child who has a cold"}, {"id": "c", "text": "A bed in the shared playroom area"}, {"id": "d", "text": "A room with a child recovering from pneumonia"}]'::jsonb, '["a"]', 'SCID is the most severe primary immunodeficiency, and the infant must be in protective isolation. Rooming with a child who has a cold violates the rule to avoid sick contacts.'),
  ('immunodef', 11, 'A nurse is caring for a client on long-term prednisone therapy. Which action by the nurse requires correction?', '[{"id": "a", "text": "Administering the injected influenza vaccine"}, {"id": "b", "text": "Administering the nasal spray influenza vaccine"}, {"id": "c", "text": "Teaching the client to avoid sick contacts"}, {"id": "d", "text": "Reviewing the client''s CBC results"}]'::jsonb, '["b"]', 'Prednisone causes immunosuppression, and the nasal flu vaccine is a live vaccine that must be avoided. The injected flu shot is inactivated and safe.'),
  ('immunodef', 12, 'A client with leukemia develops severe neutropenia. Which precaution should the nurse implement?', '[{"id": "a", "text": "Standard precautions in a shared room"}, {"id": "b", "text": "No special precautions are required"}, {"id": "c", "text": "Protective isolation as indicated"}, {"id": "d", "text": "Visits from all family members, including ill ones"}]'::jsonb, '["c"]', 'Protective isolation is indicated for severe neutropenia and SCID. Allowing ill visitors violates the rule to avoid sick contacts.'),
  ('immunodef', 13, 'A client with Bruton''s agammaglobulinemia is scheduled for an IVIG infusion and asks what it does. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It cures the disease by replacing B cells.\""}, {"id": "b", "text": "\"It is a live vaccine that builds immunity.\""}, {"id": "c", "text": "\"It provides passive antibody immunity.\""}, {"id": "d", "text": "\"It prevents CD4 decline from the virus.\""}]'::jsonb, '["c"]', 'IVIG provides passive antibody immunity for clients who cannot make their own antibodies. Preventing CD4 decline is the purpose of antiretroviral therapy for HIV.'),
  ('immunodef', 14, 'A client has taken high-dose prednisone for several months and now has recurrent infections. How should the nurse explain the cause?', '[{"id": "a", "text": "A genetic defect present since birth"}, {"id": "b", "text": "A virus that destroys CD4+ T cells"}, {"id": "c", "text": "Treatment-caused immunosuppression"}, {"id": "d", "text": "Loss of the mother''s antibodies"}]'::jsonb, '["c"]', 'Steroids such as prednisone are a major cause of iatrogenic (treatment-caused) immunosuppression. A genetic defect from birth describes primary immunodeficiency.'),
  ('immunodef', 15, 'Which condition in a client with AIDS does the nurse identify as an opportunistic infection?', '[{"id": "a", "text": "Frequent colds"}, {"id": "b", "text": "Ear infection"}, {"id": "c", "text": "Toxoplasmosis"}, {"id": "d", "text": "Sinus infection"}]'::jsonb, '["c"]', 'Toxoplasmosis is listed among the opportunistic infections, along with PCP, CMV retinitis, oral candidiasis, TB, and cryptococcal meningitis. Colds, ear infections, and sinus infections are listed as mild manifestations.'),
  ('immunodef', 16, 'A client with immunodeficiency asks which health problems they are now at increased risk for. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Infections, cancers, and autoimmune diseases.\""}, {"id": "b", "text": "\"Infections, but not cancers or autoimmunity.\""}, {"id": "c", "text": "\"Cancers, but not infections or autoimmunity.\""}, {"id": "d", "text": "\"Only infections caused by live vaccines.\""}]'::jsonb, '["a"]', 'Immunodeficiency increases the risk of infections, cancers, and even autoimmune diseases. Limiting the risk to infections alone is incomplete.'),
  ('immunodef', 17, 'An infant with a congenital heart defect and frequent infections has a low CD4+ T-cell count. HIV testing is negative. Which condition should the nurse suspect?', '[{"id": "a", "text": "Bruton''s agammaglobulinemia"}, {"id": "b", "text": "Common variable immunodeficiency"}, {"id": "c", "text": "Cryptococcal meningitis"}, {"id": "d", "text": "DiGeorge syndrome"}]'::jsonb, '["d"]', 'Low CD4+ T cells occur in HIV/AIDS and DiGeorge syndrome, and DiGeorge also features heart defects. Bruton''s and CVID are antibody deficiencies.'),
  ('immunodef', 18, 'A nursing student asks what makes an infection opportunistic. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It occurs only in infants born with SCID"}, {"id": "b", "text": "It is caused only by live vaccine strains"}, {"id": "c", "text": "It harms mainly those with weakened immunity"}, {"id": "d", "text": "It is a mild illness like a common cold"}]'::jsonb, '["c"]', 'Opportunistic infections don''t normally harm healthy people but become life-threatening in immunodeficient clients. Frequent colds are listed as mild manifestations, not opportunistic infections.'),
  ('immunodef', 19, 'A client with recurrent infections has a CBC with differential that shows a decreased WBC count. How should the nurse interpret this finding?', '[{"id": "a", "text": "It confirms an HIV diagnosis"}, {"id": "b", "text": "It suggests immunodeficiency"}, {"id": "c", "text": "It is expected after vaccination"}, {"id": "d", "text": "It rules out an infection"}]'::jsonb, '["b"]', 'A decreased WBC count on CBC suggests immunodeficiency, and the lymphocyte count should be assessed. HIV infection is confirmed by HIV testing, not a low WBC count.'),
  ('immunodef', 20, 'Which statement by a client receiving chemotherapy indicates a need for further teaching about infection prevention?', '[{"id": "a", "text": "\"I will wash fruits and vegetables thoroughly.\""}, {"id": "b", "text": "\"I will wear a mask when I go to crowded stores.\""}, {"id": "c", "text": "\"I will cook my eggs until they are fully done.\""}, {"id": "d", "text": "\"I will spend my weekends planting in my garden.\""}]'::jsonb, '["d"]', 'Immunocompromised clients should avoid gardening because soil contains Aspergillus, which causes fungal infection. Washing produce, wearing masks in crowds, and fully cooking eggs are correct.'),
  ('immunodef', 21, 'A client with AIDS lives with a pet cat. Which instruction regarding the cat should the nurse give?', '[{"id": "a", "text": "\"Have another person change the cat litter.\""}, {"id": "b", "text": "\"Change the cat litter yourself every day.\""}, {"id": "c", "text": "\"Change the litter only on days you feel well.\""}, {"id": "d", "text": "\"Change the litter right after gardening.\""}]'::jsonb, '["a"]', 'Immunocompromised clients should not handle cat litter because of the risk of Toxoplasma gondii. Changing it only when feeling well still exposes the client to toxoplasmosis.'),
  ('immunodef', 22, 'A client is diagnosed with common variable immunodeficiency (CVID). Which finding should the nurse anticipate?', '[{"id": "a", "text": "Hypocalcemia and a cleft palate"}, {"id": "b", "text": "Absent B and T cells since birth"}, {"id": "c", "text": "Kaposi''s sarcoma lesions"}, {"id": "d", "text": "Frequent respiratory infections"}]'::jsonb, '["d"]', 'CVID causes low immunoglobulins with frequent respiratory infections and possible autoimmune disease. Hypocalcemia and cleft palate are features of DiGeorge syndrome, and absent B and T cells describe SCID.'),
  ('immunodef', 23, 'A client recently diagnosed with HIV says, "I can''t tell anyone. People will judge me." Which nursing priority does this statement most directly reflect?', '[{"id": "a", "text": "Medication adherence"}, {"id": "b", "text": "Infection prevention"}, {"id": "c", "text": "Adequate nutrition"}, {"id": "d", "text": "Psychosocial support"}]'::jsonb, '["d"]', 'Psychosocial support addresses chronic illness, stigma (especially with HIV), and depression risk. The statement reflects fear of stigma, not adherence or nutrition.'),
  ('immunodef', 24, 'The nurse is caring for a client with advanced HIV. Which malignancy should the nurse recognize as a severe manifestation of immunodeficiency in this client?', '[{"id": "a", "text": "Cryptococcal meningitis"}, {"id": "b", "text": "Oral candidiasis"}, {"id": "c", "text": "Toxoplasmosis"}, {"id": "d", "text": "Kaposi''s sarcoma"}]'::jsonb, '["d"]', 'Kaposi''s sarcoma is the cancer listed as a severe manifestation in HIV. Cryptococcal meningitis, oral candidiasis, and toxoplasmosis are opportunistic infections, not malignancies.'),
  ('immunodef', 25, 'A client with AIDS has a CD4+ count of 120 cells/μL. Which medication should the nurse anticipate to prevent Pneumocystis jirovecii pneumonia (PCP)?', '[{"id": "a", "text": "TMP-SMX prophylaxis"}, {"id": "b", "text": "Prednisone therapy"}, {"id": "c", "text": "IVIG infusions"}, {"id": "d", "text": "Varicella vaccine"}]'::jsonb, '["a"]', 'Antibiotic prophylaxis such as TMP-SMX prevents PCP before it happens. Prednisone suppresses the immune response, and the varicella vaccine is live and contraindicated.'),
  ('immunodef', 26, 'A client with HIV has a CD4+ T-cell count of 150 cells/μL. How should the nurse interpret this result?', '[{"id": "a", "text": "It meets the criteria for an AIDS diagnosis"}, {"id": "b", "text": "It confirms a primary immunodeficiency"}, {"id": "c", "text": "It is within the expected normal range"}, {"id": "d", "text": "It indicates the client has DiGeorge syndrome"}]'::jsonb, '["a"]', 'For HIV staging, a CD4+ count below 200 cells/μL establishes an AIDS diagnosis. HIV is a secondary, not primary, immunodeficiency.'),
  ('immunodef', 27, 'A client receiving chemotherapy plans to attend a crowded holiday event. Which instruction by the nurse is most appropriate?', '[{"id": "a", "text": "\"Skip hand hygiene to protect your skin.\""}, {"id": "b", "text": "\"Get the nasal flu vaccine beforehand.\""}, {"id": "c", "text": "\"Choose the deli meats from the buffet.\""}, {"id": "d", "text": "\"Wear a mask while you are in the crowd.\""}]'::jsonb, '["d"]', 'Immunocompromised clients should use masks in public and crowded places. The nasal flu vaccine is live and contraindicated, and deli meats should be avoided.'),
  ('immunodef', 28, 'The parents of a child with DiGeorge syndrome ask why the child has frequent infections. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The bone marrow makes no B cells.\""}, {"id": "b", "text": "\"Antibodies from the mother never passed.\""}, {"id": "c", "text": "\"A missing or small thymus means no T cells.\""}, {"id": "d", "text": "\"A virus is destroying the CD4+ T cells.\""}]'::jsonb, '["c"]', 'DiGeorge syndrome is thymic hypoplasia; a missing or small thymus results in no T cells. Absent B cells describes Bruton''s, and viral destruction of CD4+ T cells describes HIV.'),
  ('immunodef', 29, 'A client newly diagnosed with HIV asks how the virus weakens the immune system. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It destroys the B cells that make antibodies.\""}, {"id": "b", "text": "\"It causes the thymus gland to disappear.\""}, {"id": "c", "text": "\"It kills all of the fast-growing immune cells.\""}, {"id": "d", "text": "\"It destroys a type of cell called CD4+ T cells.\""}]'::jsonb, '["d"]', 'HIV causes secondary immunodeficiency by destroying CD4+ T cells. Killing fast-growing immune cells describes the effect of chemotherapy and radiation.'),
  ('immunodef', 30, 'The nurse assesses a client with HIV who had minor surgery last week. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Redness at an incision that is not healing"}, {"id": "b", "text": "Questions about the medication schedule"}, {"id": "c", "text": "A request for a high-protein snack"}, {"id": "d", "text": "Interest in joining a support group"}]'::jsonb, '["a"]', 'Redness and wounds that are not healing are signs of infection that must be reported immediately in an immunocompromised client. Requests for protein or psychosocial support are appropriate and not urgent.'),
  ('immunodef', 31, 'The nurse is reviewing assignments on a mixed unit. Which client does the nurse recognize as having a primary immunodeficiency?', '[{"id": "a", "text": "An adult receiving long-term prednisone"}, {"id": "b", "text": "A child with DiGeorge syndrome"}, {"id": "c", "text": "An adult with HIV infection"}, {"id": "d", "text": "A client receiving chemotherapy"}]'::jsonb, '["b"]', 'DiGeorge syndrome is a primary (genetic) immunodeficiency along with SCID and Bruton''s. HIV/AIDS, chemotherapy, and steroids are examples of secondary immunodeficiency.'),
  ('immunodef', 32, 'Which assessment finding should the nurse expect in an infant with SCID?', '[{"id": "a", "text": "Steady weight gain with rare infections"}, {"id": "b", "text": "Failure to thrive with severe infections"}, {"id": "c", "text": "Infections that first begin in adolescence"}, {"id": "d", "text": "Occasional mild colds that resolve quickly"}]'::jsonb, '["b"]', 'SCID causes frequent severe infections such as pneumonia and ear infections, failure to thrive, and is life-threatening in infancy. Mild, quickly resolving colds do not fit this severe picture.'),
  ('immunodef', 33, 'When planning care for a client with a CD4+ count below 200 cells/μL, the nurse recognizes which as the biggest threat to the client?', '[{"id": "a", "text": "Hypocalcemia"}, {"id": "b", "text": "Opportunistic infections"}, {"id": "c", "text": "Failure to thrive"}, {"id": "d", "text": "Loss of maternal antibodies"}]'::jsonb, '["b"]', 'A CD4+ count below 200 cells/μL indicates AIDS, and opportunistic infections are the biggest threat. Hypocalcemia is a feature of DiGeorge syndrome.'),
  ('immunodef', 34, 'A client is admitted to the burn unit after extensive burns. The nurse recognizes that the client is at risk for which type of immunodeficiency?', '[{"id": "a", "text": "Primary, inherited from the parents"}, {"id": "b", "text": "Primary, from a missing thymus"}, {"id": "c", "text": "Secondary, acquired from the injury"}, {"id": "d", "text": "Congenital, present since birth"}]'::jsonb, '["c"]', 'Burns, major surgery, and trauma are listed causes of secondary (acquired) immunodeficiency. Primary immunodeficiency is genetic and present from birth.'),
  ('immunodef', 35, 'Which treatment plan should the nurse anticipate for a child with DiGeorge syndrome?', '[{"id": "a", "text": "Bone marrow transplant alone"}, {"id": "b", "text": "Thymus transplant and treating each defect"}, {"id": "c", "text": "Lifelong antiretroviral therapy"}, {"id": "d", "text": "Live vaccines to stimulate T cells"}]'::jsonb, '["b"]', 'DiGeorge syndrome is treated with thymus transplant and treatment of each defect. Bone marrow transplant is the cure for SCID, and live vaccines are contraindicated in immunocompromised clients.'),
  ('immunodef', 36, 'An infant is diagnosed with severe combined immunodeficiency (SCID). How should the nurse classify this client''s immunodeficiency?', '[{"id": "a", "text": "Primary, because it is genetic and present from birth"}, {"id": "b", "text": "Secondary, because it is acquired from a disease"}, {"id": "c", "text": "Secondary, because it is caused by a treatment"}, {"id": "d", "text": "Primary, because it develops later in life"}]'::jsonb, '["a"]', 'Primary immunodeficiency is genetic or congenital, meaning the client is born with weak or absent immune components, and SCID is a primary example. Secondary immunodeficiency is acquired later in life from disease, medications, or other causes.'),
  ('immunodef', 37, 'The nurse is planning dietary teaching for a client with secondary immunodeficiency. Which dietary emphasis best supports immune function?', '[{"id": "a", "text": "Adequate protein and vitamins"}, {"id": "b", "text": "Raw foods to preserve nutrients"}, {"id": "c", "text": "Deli meats for convenient protein"}, {"id": "d", "text": "Raw shellfish for added minerals"}]'::jsonb, '["a"]', 'Adequate nutrition with protein and vitamins boosts immune function. Raw foods, deli meats, and raw shellfish should be avoided by immunocompromised clients.'),
  ('immunodef', 38, 'The nurse is reviewing four clients'' histories. Which client has a secondary immunodeficiency caused by a disease that attacks immune cells?', '[{"id": "a", "text": "An infant with SCID"}, {"id": "b", "text": "A child with Bruton''s agammaglobulinemia"}, {"id": "c", "text": "An adult with lymphoma"}, {"id": "d", "text": "A child with DiGeorge syndrome"}]'::jsonb, '["c"]', 'Cancers such as leukemia and lymphoma attack immune cells and are a top cause of secondary immunodeficiency. SCID, Bruton''s, and DiGeorge are primary (genetic) immunodeficiencies.'),
  ('immunodef', 39, 'A newborn is diagnosed with DiGeorge syndrome. Which laboratory value is most important for the nurse to monitor?', '[{"id": "a", "text": "Serum calcium"}, {"id": "b", "text": "Serum glucose"}, {"id": "c", "text": "Serum sodium"}, {"id": "d", "text": "Serum potassium"}]'::jsonb, '["a"]', 'DiGeorge syndrome features heart defects, cleft palate, hypocalcemia, and frequent infections, so calcium must be monitored. The other electrolytes are not identified as DiGeorge features.'),
  ('immunodef', 40, 'A child with recurrent bacterial infections has very low IgG, IgA, and IgM levels. How should the nurse interpret these results?', '[{"id": "a", "text": "They indicate an antibody deficiency"}, {"id": "b", "text": "They confirm a T-cell-only defect"}, {"id": "c", "text": "They indicate progression to AIDS"}, {"id": "d", "text": "They are expected after vaccination"}]'::jsonb, '["a"]', 'Low immunoglobulin levels indicate an antibody deficiency (agammaglobulinemia). Progression to AIDS is identified by a CD4+ count below 200 cells/μL, not by immunoglobulin levels.'),
  ('immunodef', 41, 'Which finding in a client with HIV is classified as a severe, life-threatening manifestation of immunodeficiency?', '[{"id": "a", "text": "Frequent colds"}, {"id": "b", "text": "Recurrent pneumonia"}, {"id": "c", "text": "Sinus infections"}, {"id": "d", "text": "Mild fatigue"}]'::jsonb, '["b"]', 'Recurrent pneumonia is listed among the severe, life-threatening manifestations. Frequent colds, sinus infections, and fatigue are mild to moderate manifestations.'),
  ('immunodef', 42, 'Which meal selection by a client with immunodeficiency indicates understanding of food safety teaching?', '[{"id": "a", "text": "Soft-boiled eggs with runny yolks"}, {"id": "b", "text": "Raw oysters with a side salad"}, {"id": "c", "text": "Fully cooked chicken and washed fruit"}, {"id": "d", "text": "A deli turkey sandwich with chips"}]'::jsonb, '["c"]', 'Meat and eggs must be fully cooked and produce washed thoroughly. Runny eggs, raw shellfish, and deli meats should be avoided.'),
  ('immunodef', 43, 'The nurse is assessing a client with suspected immunodeficiency. Which findings would the nurse classify as mild to moderate manifestations?', '[{"id": "a", "text": "Frequent sinus infections and slow-healing wounds"}, {"id": "b", "text": "Cryptococcal meningitis and CMV retinitis"}, {"id": "c", "text": "Recurrent pneumonia and chronic diarrhea"}, {"id": "d", "text": "Kaposi''s sarcoma and oral thrush"}]'::jsonb, '["a"]', 'Mild to moderate manifestations include frequent colds, sinus and ear infections, slow-healing wounds, fatigue, and weight loss. Recurrent pneumonia, chronic diarrhea, thrush, and opportunistic infections are severe manifestations.'),
  ('immunodef', 44, 'A client with poorly controlled diabetes has had several infections this year. The nurse explains the increased infection risk is related to which factor?', '[{"id": "a", "text": "Absence of both B and T cells"}, {"id": "b", "text": "Destruction of CD4+ T cells"}, {"id": "c", "text": "A missing or small thymus"}, {"id": "d", "text": "Hyperglycemia impairing WBC function"}]'::jsonb, '["d"]', 'Diabetes causes secondary immunodeficiency because hyperglycemia impairs WBC function. Absent B and T cells describe SCID, a primary disorder.'),
  ('immunodef', 45, 'A client asks why antiretroviral therapy (ART) is prescribed after an HIV diagnosis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It cures HIV within several months.\""}, {"id": "b", "text": "\"It provides passive antibody immunity.\""}, {"id": "c", "text": "\"It replaces the missing B and T cells.\""}, {"id": "d", "text": "\"It prevents CD4 decline and is lifelong.\""}]'::jsonb, '["d"]', 'ART is used for HIV/AIDS to prevent CD4 decline and must be taken lifelong. Passive antibody immunity is provided by IVIG, not ART.'),
  ('immunodef', 46, 'A client receiving chemotherapy asks which vaccines are safe to receive. Which vaccine should the nurse recommend?', '[{"id": "a", "text": "MMR vaccine"}, {"id": "b", "text": "Varicella vaccine"}, {"id": "c", "text": "Pneumococcal vaccine"}, {"id": "d", "text": "Yellow fever vaccine"}]'::jsonb, '["c"]', 'Inactivated vaccines such as pneumococcal are safe and recommended for immunocompromised clients. MMR, varicella, and yellow fever are live attenuated vaccines and are contraindicated.'),
  ('immunodef', 47, 'A 58-year-old client receiving chemotherapy for cancer has developed frequent infections. The nurse identifies this immunodeficiency as which type?', '[{"id": "a", "text": "Primary, because it is inherited"}, {"id": "b", "text": "Primary, because it began at birth"}, {"id": "c", "text": "Secondary, because it is acquired"}, {"id": "d", "text": "Congenital, from an absent thymus"}]'::jsonb, '["c"]', 'Secondary immunodeficiency is acquired later in life from disease, medications, or other causes, and chemotherapy is a listed example. Primary immunodeficiency is genetic and present from birth.'),
  ('immunodef', 48, 'The parents of an infant with SCID ask which treatment can cure the condition. Which treatment should the nurse identify?', '[{"id": "a", "text": "Lifelong IVIG infusions"}, {"id": "b", "text": "Antiretroviral therapy"}, {"id": "c", "text": "Bone marrow transplant"}, {"id": "d", "text": "Thymus transplant"}]'::jsonb, '["c"]', 'Bone marrow transplant is curative for SCID. IVIG is given with it to provide passive immunity but does not cure the disease, and thymus transplant is a treatment for DiGeorge syndrome.'),
  ('immunodef', 49, 'Which statement by a client with HIV indicates a need for further teaching about antiretroviral therapy (ART)?', '[{"id": "a", "text": "\"I will take my ART every day for the rest of my life.\""}, {"id": "b", "text": "\"I can skip doses on the days when I feel well.\""}, {"id": "c", "text": "\"I will set a phone reminder so I do not miss doses.\""}, {"id": "d", "text": "\"I will keep my ART refills from running out.\""}]'::jsonb, '["b"]', 'Medication adherence is a priority, and ART for HIV must not be missed. ART is taken lifelong, so the plans to take it daily and use reminders are correct.'),
  ('immunodef', 50, 'For which client should the nurse anticipate IVIG to provide passive immunity?', '[{"id": "a", "text": "A client with HIV who is starting ART"}, {"id": "b", "text": "An adult on prednisone for asthma"}, {"id": "c", "text": "A child with Bruton''s agammaglobulinemia"}, {"id": "d", "text": "An infant with hypocalcemia from DiGeorge"}]'::jsonb, '["c"]', 'IVIG provides passive immunity in antibody deficiencies such as Bruton''s and CVID. DiGeorge syndrome is treated with thymus transplant and treatment of each defect.'),
  ('chickenpox', 1, 'A nurse assesses a 4-year-old child who has a new itchy rash on the trunk. Which finding most strongly supports a diagnosis of varicella?', '[{"id": "a", "text": "Macules, vesicles, and crusted lesions present at the same time"}, {"id": "b", "text": "Every lesion at the identical stage of development"}, {"id": "c", "text": "Lesions that first appeared on the hands and feet"}, {"id": "d", "text": "Flat lesions that never progress to vesicles"}]'::jsonb, '["a"]', 'Lesions in all stages at the same time are pathognomonic for chickenpox. A rash with every lesion at one identical stage does not fit this hallmark pattern.'),
  ('chickenpox', 2, 'A child with suspected chickenpox is being admitted to the pediatric unit. Which room assignment is most appropriate?', '[{"id": "a", "text": "A semi-private room shared with another febrile child"}, {"id": "b", "text": "A private room with the door open and standard precautions"}, {"id": "c", "text": "A negative-pressure private room"}, {"id": "d", "text": "A room near the nurses'' station with droplet precautions only"}]'::jsonb, '["c"]', 'Varicella requires airborne plus contact precautions in a negative-pressure private room. Droplet precautions alone are not enough because the virus is airborne.'),
  ('chickenpox', 3, 'The charge nurse observes a newly hired nurse caring for a hospitalized child with active chickenpox lesions. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Keeps the child in a negative-pressure room"}, {"id": "b", "text": "Plans isolation until every lesion has crusted"}, {"id": "c", "text": "Puts on a surgical mask before entering the room"}, {"id": "d", "text": "Uses contact precautions when touching the lesions"}]'::jsonb, '["c"]', 'Healthcare workers must wear an N95 mask because varicella requires airborne precautions, not just droplet protection. The negative-pressure room, contact precautions, and isolation until crusting are all correct.'),
  ('chickenpox', 4, 'The parent of a 6-year-old child with chickenpox asks when the child may return to school. Which response by the nurse is correct?', '[{"id": "a", "text": "\"After the fever has been gone for 24 hours.\""}, {"id": "b", "text": "\"After one full day of antihistamine therapy.\""}, {"id": "c", "text": "\"When the first new blisters stop appearing.\""}, {"id": "d", "text": "\"When all of the lesions have crusted over.\""}]'::jsonb, '["d"]', 'The child is contagious until all lesions crust over, so isolation continues until every lesion is crusted. Resolution of fever does not end the contagious period.'),
  ('chickenpox', 5, 'A 7-year-old child developed a chickenpox rash this morning. The parent asks how long ago the child could have spread the virus to a younger sibling. Which response is accurate?', '[{"id": "a", "text": "\"Starting about 1 to 2 days before the rash appeared.\""}, {"id": "b", "text": "\"Only after the blisters began to form today.\""}, {"id": "c", "text": "\"Only after the lesions begin to crust over.\""}, {"id": "d", "text": "\"Starting about 3 weeks before the rash appeared.\""}]'::jsonb, '["a"]', 'Chickenpox is contagious 1 to 2 days before the rash and until all lesions crust over. A child is not contagious only after vesicles appear; spread can begin before the rash.'),
  ('chickenpox', 6, 'A parent reports that a classmate of their 5-year-old child was diagnosed with chickenpox today. The parent asks when symptoms might appear if the child was infected. Which response is correct?', '[{"id": "a", "text": "\"Usually within 24 to 48 hours of the exposure.\""}, {"id": "b", "text": "\"Usually about 2 weeks, but anywhere from 10 to 21 days.\""}, {"id": "c", "text": "\"Usually 4 to 6 weeks after the exposure.\""}, {"id": "d", "text": "\"Usually within 3 to 5 days of the exposure.\""}]'::jsonb, '["b"]', 'The incubation period for varicella is 10 to 21 days, typically 14 to 16 days. Symptoms within 1 to 5 days would be far shorter than this incubation period.'),
  ('chickenpox', 7, 'A nurse is teaching a parent about the early phase of varicella. Which symptoms should the nurse describe as typically occurring before the rash appears?', '[{"id": "a", "text": "Intense itching and crusted skin lesions"}, {"id": "b", "text": "Seizures and altered mental status"}, {"id": "c", "text": "Fever, fatigue, headache, and loss of appetite"}, {"id": "d", "text": "Vesicles spreading from the trunk to the limbs"}]'::jsonb, '["c"]', 'The prodrome before the rash includes fever, fatigue, headache, and loss of appetite. Itching and crusted lesions belong to the rash itself, and seizures suggest the complication of encephalitis.'),
  ('chickenpox', 8, 'A nursing student asks about the progression of a single chickenpox lesion. Which sequence should the nurse describe?', '[{"id": "a", "text": "Vesicle, macule, papule, crust, pustule"}, {"id": "b", "text": "Papule, macule, pustule, vesicle, crust"}, {"id": "c", "text": "Pustule, vesicle, papule, macule, crust"}, {"id": "d", "text": "Macule, papule, vesicle, pustule, crust"}]'::jsonb, '["d"]', 'Chickenpox lesions progress from macules to papules to vesicles to pustules and finally to crusting. The other sequences place the stages in the wrong order.'),
  ('chickenpox', 9, 'A healthy 6-year-old child with chickenpox has a fever. Which medication should the nurse anticipate being recommended to reduce the fever?', '[{"id": "a", "text": "Acetaminophen"}, {"id": "b", "text": "Aspirin"}, {"id": "c", "text": "Acyclovir"}, {"id": "d", "text": "Calamine lotion"}]'::jsonb, '["a"]', 'Antipyretics are used for routine cases, but aspirin is avoided because of Reye''s syndrome risk, making acetaminophen the choice. Acyclovir is an antiviral reserved for high-risk clients, not a fever reducer for a healthy child.'),
  ('chickenpox', 10, 'A nurse provides home-care teaching to the parent of a child with chickenpox. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will use oatmeal baths to soothe the itching.\""}, {"id": "b", "text": "\"I will give my child aspirin when the fever goes up.\""}, {"id": "c", "text": "\"I will put calamine lotion on the itchy spots.\""}, {"id": "d", "text": "\"I will keep my child home until every spot has crusted.\""}]'::jsonb, '["b"]', 'Aspirin must never be given to children with a viral illness because of Reye''s syndrome risk. Oatmeal baths, calamine lotion, and isolation until all lesions crust are appropriate.'),
  ('chickenpox', 11, 'A healthy 4-year-old child with chickenpox is scratching constantly. Which comfort measures should the nurse recommend to the parent?', '[{"id": "a", "text": "Aspirin given every 6 hours for skin inflammation"}, {"id": "b", "text": "Oral acyclovir given to stop the itching"}, {"id": "c", "text": "Oatmeal baths and calamine lotion on the lesions"}, {"id": "d", "text": "Withholding antihistamines until crusting"}]'::jsonb, '["c"]', 'Oatmeal baths and calamine lotion are routine comfort measures for healthy children, and antihistamines are used for itching. Aspirin is avoided because of Reye''s syndrome, and antivirals are reserved for high-risk clients.'),
  ('chickenpox', 12, 'A nurse reviews four clients who have varicella. For which client should the nurse anticipate a prescription for an antiviral medication?', '[{"id": "a", "text": "A healthy 5-year-old child with a mild rash"}, {"id": "b", "text": "A healthy 7-year-old child with intense itching"}, {"id": "c", "text": "A healthy 3-year-old child with a low fever"}, {"id": "d", "text": "A pregnant client with a new vesicular rash"}]'::jsonb, '["d"]', 'Antivirals are given to high-risk clients, which include pregnant women. Healthy children receive routine symptom care such as antihistamines and antipyretics.'),
  ('chickenpox', 13, 'A 16-year-old adolescent is diagnosed with chickenpox. Which prescription should the nurse anticipate?', '[{"id": "a", "text": "Acyclovir"}, {"id": "b", "text": "Aspirin"}, {"id": "c", "text": "Varicella vaccine"}, {"id": "d", "text": "No medication of any kind"}]'::jsonb, '["a"]', 'Adolescents and adults are high-risk and receive an antiviral such as acyclovir or valacyclovir. Aspirin is avoided because of Reye''s syndrome risk.'),
  ('chickenpox', 14, 'A nurse is planning care for clients with varicella. For which client would antiviral therapy NOT routinely be indicated?', '[{"id": "a", "text": "A neonate with new vesicular lesions"}, {"id": "b", "text": "A healthy 6-year-old child with an itchy rash"}, {"id": "c", "text": "An adult receiving immunosuppressive therapy"}, {"id": "d", "text": "A pregnant client in the second trimester"}]'::jsonb, '["b"]', 'Antivirals are given only to high-risk patients: immunocompromised clients, adolescents and adults, pregnant women, and neonates. A healthy child receives routine symptom management instead.'),
  ('chickenpox', 15, 'The parent of a 12-month-old infant asks when the child should receive the varicella vaccine. Which response by the nurse is correct?', '[{"id": "a", "text": "\"A single dose is given at birth.\""}, {"id": "b", "text": "\"The first dose is at 2 months, with a booster at 12 months.\""}, {"id": "c", "text": "\"The first dose is at 12 to 15 months, and the second at 4 to 6 years.\""}, {"id": "d", "text": "\"One dose is given at 10 years of age.\""}]'::jsonb, '["c"]', 'The varicella vaccine is given in 2 doses, the first at 12 to 15 months and the second at 4 to 6 years. A single dose at birth or at age 10 does not match this schedule.'),
  ('chickenpox', 16, 'A client who is 10 weeks pregnant has never had chickenpox and asks to receive the varicella vaccine today. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"It is safest to give it during the first trimester.\""}, {"id": "b", "text": "\"You can receive it today along with your prenatal labs.\""}, {"id": "c", "text": "\"It is an inactivated vaccine, so it is safe in pregnancy.\""}, {"id": "d", "text": "\"It is a live vaccine, so it is not given during pregnancy.\""}]'::jsonb, '["d"]', 'The varicella vaccine is live attenuated and is contraindicated in pregnancy. It is not an inactivated vaccine.'),
  ('chickenpox', 17, 'A nurse in a clinic reviews clients scheduled to receive the varicella vaccine. Which client should NOT receive the vaccine?', '[{"id": "a", "text": "A child with severe immunosuppression"}, {"id": "b", "text": "A healthy 12-month-old infant"}, {"id": "c", "text": "A healthy 4-year-old due for a second dose"}, {"id": "d", "text": "A healthy 14-month-old with no prior doses"}]'::jsonb, '["a"]', 'The live varicella vaccine is contraindicated in pregnancy and severe immunosuppression. Healthy children at 12 to 15 months and 4 to 6 years are scheduled to receive it.'),
  ('chickenpox', 18, 'A nurse teaches a parent about the varicella vaccine. Which statement by the parent indicates understanding?', '[{"id": "a", "text": "\"One dose will protect my child for life.\""}, {"id": "b", "text": "\"My child needs two doses of this live vaccine.\""}, {"id": "c", "text": "\"This vaccine is made from a killed virus.\""}, {"id": "d", "text": "\"The second dose is due at 12 months of age.\""}]'::jsonb, '["b"]', 'The varicella vaccine is a live attenuated vaccine given as 2 doses. The second dose is due at 4 to 6 years, not at 12 months.'),
  ('chickenpox', 19, 'A nurse is teaching the parent of a child with chickenpox how to reduce the risk of secondary bacterial infection of the lesions. Which instruction is appropriate?', '[{"id": "a", "text": "\"Apply crushed aspirin directly to the lesions.\""}, {"id": "b", "text": "\"Avoid bathing until all of the lesions are gone.\""}, {"id": "c", "text": "\"Keep your child''s skin clean.\""}, {"id": "d", "text": "\"Give acyclovir to prevent skin infection.\""}]'::jsonb, '["c"]', 'Keeping the skin clean and monitoring for cellulitis addresses the complication of secondary bacterial infection. Aspirin is avoided in children with viral illness, and acyclovir is an antiviral for high-risk clients.'),
  ('chickenpox', 20, 'A nurse caring for a child with chickenpox monitors the lesions for signs of cellulitis. This assessment is aimed at detecting which complication?', '[{"id": "a", "text": "Herpes zoster (shingles)"}, {"id": "b", "text": "Pneumonia"}, {"id": "c", "text": "Reye''s syndrome"}, {"id": "d", "text": "Secondary bacterial infection"}]'::jsonb, '["d"]', 'Monitoring for cellulitis and keeping the skin clean is the nursing focus for secondary bacterial infection. Pneumonia is monitored through respiratory status.'),
  ('chickenpox', 21, 'A 30-year-old client is hospitalized with varicella. Which assessment is the priority for the nurse to monitor closely in this client?', '[{"id": "a", "text": "Respiratory status"}, {"id": "b", "text": "Number of new lesions"}, {"id": "c", "text": "Appetite at meals"}, {"id": "d", "text": "Intensity of itching"}]'::jsonb, '["a"]', 'Pneumonia is a complication of varicella, so respiratory status is monitored, especially in adults. Lesion count and itching are not the priority concern in an adult.'),
  ('chickenpox', 22, 'An adult client with varicella reports a new cough and increasing shortness of breath. The nurse should suspect which complication?', '[{"id": "a", "text": "Reye''s syndrome"}, {"id": "b", "text": "Pneumonia"}, {"id": "c", "text": "Herpes zoster"}, {"id": "d", "text": "Secondary skin infection"}]'::jsonb, '["b"]', 'Pneumonia is a varicella complication that requires monitoring of respiratory status, especially in adults. Secondary bacterial infection involves the skin and is monitored for cellulitis.'),
  ('chickenpox', 23, 'A 5-year-old child with chickenpox becomes confused and then has a seizure. The nurse recognizes these findings as signs of which complication?', '[{"id": "a", "text": "Pneumonia"}, {"id": "b", "text": "Secondary bacterial infection"}, {"id": "c", "text": "Encephalitis"}, {"id": "d", "text": "Herpes zoster"}]'::jsonb, '["c"]', 'Encephalitis presents with altered mental status and seizures. Pneumonia is recognized through changes in respiratory status.'),
  ('chickenpox', 24, 'A nurse teaches the parent of a child with chickenpox what to watch for at home. Which finding should the parent be taught to report to the provider?', '[{"id": "a", "text": "Lesions in several stages at the same time"}, {"id": "b", "text": "Itching that improves with calamine lotion"}, {"id": "c", "text": "Crusts forming over the older vesicles"}, {"id": "d", "text": "Signs of cellulitis around scratched lesions"}]'::jsonb, '["d"]', 'Cellulitis signals a secondary bacterial infection, a complication requiring follow-up. Lesions in multiple stages and crusting are expected features of chickenpox.'),
  ('chickenpox', 25, 'A 70-year-old client who had chickenpox as a child is diagnosed with shingles. The client asks how this happened. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The chickenpox virus stayed dormant and has reactivated.\""}, {"id": "b", "text": "\"You caught a new, unrelated virus from someone else.\""}, {"id": "c", "text": "\"Bacteria infected the old chickenpox scars.\""}, {"id": "d", "text": "\"It is a reaction to antihistamines you took as a child.\""}]'::jsonb, '["a"]', 'Herpes zoster (shingles) is a reactivation of dormant VZV later in life. It is not a new unrelated virus or a bacterial infection.'),
  ('chickenpox', 26, 'The parent of a child recovering from chickenpox asks whether the illness can cause any problem many years from now. The nurse should explain that the child could later develop which condition?', '[{"id": "a", "text": "Reye''s syndrome"}, {"id": "b", "text": "Herpes zoster (shingles)"}, {"id": "c", "text": "Encephalitis"}, {"id": "d", "text": "Secondary skin infection"}]'::jsonb, '["b"]', 'Herpes zoster is a reactivation of dormant VZV later in life. Encephalitis and secondary infection are complications of the acute illness rather than later reactivation.'),
  ('chickenpox', 27, 'The parent of a child with chickenpox asks whether the illness is caused by bacteria. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, it is a bacterial infection of the skin.\""}, {"id": "b", "text": "\"No, it is caused by a fungus on the skin.\""}, {"id": "c", "text": "\"No, it is caused by the varicella-zoster virus.\""}, {"id": "d", "text": "\"No, it is an allergic reaction of the skin.\""}]'::jsonb, '["c"]', 'Chickenpox is a highly contagious viral infection caused by the varicella-zoster virus (VZV). It is not bacterial, fungal, or allergic.'),
  ('chickenpox', 28, 'The parent of a child with chickenpox asks how the child''s younger sibling could catch the illness. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Only by touching the dry scabs.\""}, {"id": "b", "text": "\"Only by sharing food or drinks.\""}, {"id": "c", "text": "\"Only through contact with blood.\""}, {"id": "d", "text": "\"Through the air and by touching blister fluid.\""}]'::jsonb, '["d"]', 'Varicella spreads by the airborne route and by direct contact with vesicle fluid. Limiting spread to scabs, food, or blood is incorrect.'),
  ('chickenpox', 29, 'A nurse is assessing a child on the first day of a chickenpox rash. Which pattern of spread should the nurse expect?', '[{"id": "a", "text": "From the trunk to the face and extremities"}, {"id": "b", "text": "From the hands and feet to the trunk"}, {"id": "c", "text": "From the lower legs upward to the chest"}, {"id": "d", "text": "Confined to the inside of the mouth"}]'::jsonb, '["a"]', 'The chickenpox rash spreads from the trunk to the face and then the extremities. A rash starting on the hands and feet reverses this pattern.'),
  ('chickenpox', 30, 'A nurse is preparing to care for a client with active chickenpox. Which type of transmission-based precautions should the nurse implement?', '[{"id": "a", "text": "Droplet precautions only"}, {"id": "b", "text": "Airborne and contact precautions"}, {"id": "c", "text": "Contact precautions only"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["b"]', 'Varicella requires airborne plus contact precautions. Droplet precautions alone are inadequate because the virus is airborne.'),
  ('chickenpox', 31, 'A child with a fever and an itchy rash of vesicles, pustules, and crusts arrives in a crowded emergency department waiting room. Which action should the nurse take first?', '[{"id": "a", "text": "Give aspirin to bring the fever down"}, {"id": "b", "text": "Ask the parent to wait in the lobby"}, {"id": "c", "text": "Move the child to a negative-pressure isolation room"}, {"id": "d", "text": "Complete a full history before moving the child"}]'::jsonb, '["c"]', 'Lesions in all stages suggest chickenpox, which requires airborne precautions and isolation, so placing the child in a negative-pressure room protects others first. Aspirin is contraindicated because of Reye''s syndrome risk.'),
  ('chickenpox', 32, 'On day 5 of illness, a child with chickenpox has mostly crusted lesions but a few vesicles remain on the legs. The parent asks if isolation can end. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes, because the fever has already gone away.\""}, {"id": "b", "text": "\"Yes, because most of the lesions have crusted.\""}, {"id": "c", "text": "\"Yes, because it has been 5 days since the rash began.\""}, {"id": "d", "text": "\"No, isolation continues until every lesion is crusted.\""}]'::jsonb, '["d"]', 'Isolation continues until ALL lesions are crusted, so remaining vesicles mean the child is still contagious. Having most lesions crusted is not sufficient.'),
  ('chickenpox', 33, 'A nurse is assessing the rash of a child with chickenpox. Which characteristic of the lesions should the nurse expect?', '[{"id": "a", "text": "The lesions are intensely itchy"}, {"id": "b", "text": "The lesions are painless and not itchy"}, {"id": "c", "text": "The lesions appear only on the palms"}, {"id": "d", "text": "The lesions never progress past macules"}]'::jsonb, '["a"]', 'The chickenpox rash is intensely itchy and progresses from macules through vesicles to crusting. Lesions that never progress past macules do not fit this course.'),
  ('chickenpox', 34, 'A healthy 5-year-old child with chickenpox is unable to sleep because of itching. Which type of medication should the nurse anticipate for this symptom?', '[{"id": "a", "text": "An aspirin product"}, {"id": "b", "text": "An antihistamine"}, {"id": "c", "text": "An antiviral"}, {"id": "d", "text": "A live vaccine"}]'::jsonb, '["b"]', 'Antihistamines are used for itching in routine cases. Antivirals are reserved for high-risk clients, and aspirin is avoided because of Reye''s syndrome risk.'),
  ('chickenpox', 35, 'The parent of a child with chickenpox asks why aspirin should not be used. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Aspirin makes the rash spread to the face.\""}, {"id": "b", "text": "\"Aspirin prevents the vaccine from working.\""}, {"id": "c", "text": "\"Aspirin in a viral illness can cause Reye''s syndrome.\""}, {"id": "d", "text": "\"Aspirin keeps the lesions from crusting over.\""}]'::jsonb, '["c"]', 'Aspirin is avoided in children with viral illness because of the risk of Reye''s syndrome. The other explanations are not reasons given for avoiding aspirin.'),
  ('chickenpox', 36, 'The parent of a 3-year-old child with chickenpox brings several over-the-counter products from home. Which product should the nurse instruct the parent NOT to use?', '[{"id": "a", "text": "Calamine lotion"}, {"id": "b", "text": "An oatmeal bath product"}, {"id": "c", "text": "Acetaminophen"}, {"id": "d", "text": "An aspirin-containing pain reliever"}]'::jsonb, '["d"]', 'Aspirin should never be given to children with a viral illness because of Reye''s syndrome risk. Calamine, oatmeal baths, and acetaminophen are acceptable for routine care.'),
  ('chickenpox', 37, 'A 10-day-old neonate develops vesicular lesions after exposure to varicella. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Antiviral therapy such as acyclovir"}, {"id": "b", "text": "Oatmeal baths as the only therapy"}, {"id": "c", "text": "Aspirin given every 6 hours for fever"}, {"id": "d", "text": "Immediate varicella vaccination"}]'::jsonb, '["a"]', 'Neonates are high-risk and receive antivirals such as acyclovir or valacyclovir. Aspirin is avoided because of Reye''s syndrome risk.'),
  ('chickenpox', 38, 'A child was exposed to chickenpox 5 days ago and has no symptoms. The parent states, "Since there is no rash yet, my child must not have caught it." Which response by the nurse is best?', '[{"id": "a", "text": "\"You are right; your child is no longer at risk.\""}, {"id": "b", "text": "\"Symptoms can appear up to 21 days after exposure.\""}, {"id": "c", "text": "\"Symptoms always appear within 48 hours or not at all.\""}, {"id": "d", "text": "\"A rash would not appear until at least 6 weeks later.\""}]'::jsonb, '["b"]', 'The incubation period is 10 to 21 days, so a child without symptoms at day 5 may still develop chickenpox. A 48-hour window is far shorter than the incubation period.'),
  ('chickenpox', 39, 'A child exposed to chickenpox 2 weeks ago now has fever, fatigue, headache, and loss of appetite but no rash. How should the nurse interpret these findings?', '[{"id": "a", "text": "They indicate the complication of encephalitis"}, {"id": "b", "text": "They show the child was not infected"}, {"id": "c", "text": "They may be the prodrome that occurs before the rash"}, {"id": "d", "text": "They are early signs of herpes zoster"}]'::jsonb, '["c"]', 'Fever, fatigue, headache, and loss of appetite form the prodrome before the rash, and 2 weeks falls within the incubation period. Encephalitis presents with altered mental status and seizures.'),
  ('chickenpox', 40, 'A nurse assesses a child with chickenpox and notes several clear, fluid-filled vesicles. Which lesion stage should the nurse expect these vesicles to progress to next?', '[{"id": "a", "text": "Macules"}, {"id": "b", "text": "Papules"}, {"id": "c", "text": "Crusts"}, {"id": "d", "text": "Pustules"}]'::jsonb, '["d"]', 'Lesions progress from macules to papules to vesicles to pustules and then crusting, so vesicles become pustules next. Crusting is the final stage after pustules.'),
  ('chickenpox', 41, 'A nurse is precepting a student on a pediatric unit. Which statement by the student about the chickenpox rash indicates correct understanding?', '[{"id": "a", "text": "\"Lesions in different stages of healing at once are typical.\""}, {"id": "b", "text": "\"All of the lesions erupt and crust at the very same time.\""}, {"id": "c", "text": "\"The rash characteristically starts on the hands and feet.\""}, {"id": "d", "text": "\"The rash is usually painless and does not itch.\""}]'::jsonb, '["a"]', 'Lesions in all stages of healing simultaneously is the hallmark of chickenpox. The rash is intensely itchy and spreads from the trunk outward.'),
  ('chickenpox', 42, 'A healthy 13-month-old child who has never received a varicella vaccine is seen for a well-child visit. Which action should the nurse anticipate?', '[{"id": "a", "text": "Waiting until age 4 to give the first dose"}, {"id": "b", "text": "Giving the first dose of varicella vaccine"}, {"id": "c", "text": "Giving acyclovir to prevent chickenpox"}, {"id": "d", "text": "Waiting until age 10 to give a single dose"}]'::jsonb, '["b"]', 'The first varicella vaccine dose is given at 12 to 15 months, and the second at 4 to 6 years. Age 4 is when the second dose, not the first, is scheduled.'),
  ('chickenpox', 43, 'A 4-year-old child who is severely immunosuppressed from chemotherapy is listed as due for the second varicella vaccine dose. Which action should the nurse take?', '[{"id": "a", "text": "Give the vaccine as scheduled today"}, {"id": "b", "text": "Give a double dose for better protection"}, {"id": "c", "text": "Hold the vaccine and notify the provider"}, {"id": "d", "text": "Give the vaccine and then isolate the child"}]'::jsonb, '["c"]', 'The varicella vaccine is live attenuated and is contraindicated in severe immunosuppression, so the nurse should hold it and notify the provider. Giving it as scheduled ignores this contraindication.'),
  ('chickenpox', 44, 'A nurse is caring for a 6-year-old child and a 35-year-old adult who both have varicella. For which complication should the nurse especially monitor the adult?', '[{"id": "a", "text": "Reye''s syndrome"}, {"id": "b", "text": "Herpes zoster"}, {"id": "c", "text": "Secondary skin infection"}, {"id": "d", "text": "Pneumonia"}]'::jsonb, '["d"]', 'Pneumonia requires monitoring of respiratory status, especially in adults. Reye''s syndrome is linked to aspirin use in children with viral illness.'),
  ('chickenpox', 45, 'An unlicensed assistive personnel (UAP) is helping care for a child with draining chickenpox vesicles. Which action by the UAP requires correction?', '[{"id": "a", "text": "Handles linens wet with vesicle fluid with bare hands"}, {"id": "b", "text": "Puts on an N95 mask before entering the room"}, {"id": "c", "text": "Keeps the child inside the negative-pressure room"}, {"id": "d", "text": "Wears gloves when bathing the child''s skin lesions"}]'::jsonb, '["a"]', 'Varicella spreads by direct contact with vesicle fluid and requires contact as well as airborne precautions, so handling soiled linens barehanded is unsafe. Wearing an N95 and keeping the child in a negative-pressure room are correct.'),
  ('chickenpox', 46, 'A nurse teaches a parent why their child with chickenpox needs a special isolation room. Which statement by the parent indicates understanding?', '[{"id": "a", "text": "\"It only spreads if someone touches the scabs.\""}, {"id": "b", "text": "\"The virus can spread through the air, not only by touch.\""}, {"id": "c", "text": "\"It only spreads after all lesions have crusted.\""}, {"id": "d", "text": "\"It only spreads by sharing cups and utensils.\""}]'::jsonb, '["b"]', 'Varicella is airborne, so it requires airborne precautions rather than only droplet or contact measures. Spread does not depend solely on touching lesions.'),
  ('chickenpox', 47, 'A 4-year-old child with chickenpox is being cared for on the pediatric unit. Which finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "New lesions appearing beside crusted ones"}, {"id": "b", "text": "Itching that disturbs the child''s nap"}, {"id": "c", "text": "Decreased appetite at lunch"}, {"id": "d", "text": "New onset of confusion and seizure activity"}]'::jsonb, '["d"]', 'Altered mental status and seizures indicate encephalitis, a serious complication that needs immediate follow-up. New lesions beside crusted ones and itching are expected features of chickenpox.'),
  ('chickenpox', 48, 'A nurse has four clients with varicella. Which client should the nurse assess first?', '[{"id": "a", "text": "A child whose lesions are all crusted"}, {"id": "b", "text": "A child requesting calamine for itching"}, {"id": "c", "text": "An adult reporting increasing difficulty breathing"}, {"id": "d", "text": "An adolescent asking for an oatmeal bath"}]'::jsonb, '["c"]', 'Pneumonia is a complication requiring respiratory monitoring, especially in adults, so breathing difficulty is the priority. Itching and comfort requests are routine needs.'),
  ('chickenpox', 49, 'A nurse reviews the chart of a child admitted with a diagnosis of chickenpox. Which documented finding is inconsistent with this diagnosis and should be clarified?', '[{"id": "a", "text": "Lesions noted on the trunk, face, and extremities"}, {"id": "b", "text": "Fever and fatigue before the rash appeared"}, {"id": "c", "text": "Intensely itchy vesicles and crusts noted together"}, {"id": "d", "text": "All lesions at exactly the same stage of development"}]'::jsonb, '["d"]', 'Chickenpox is characterized by lesions in all stages at the same time, so uniform lesions do not fit. Trunk-to-extremity spread, a fever and fatigue prodrome, and itchy lesions are all expected.'),
  ('chickenpox', 50, 'A nurse is reviewing varicella-zoster virus (VZV) with a group of nursing students. Which student statement requires correction?', '[{"id": "a", "text": "\"Varicella vaccine is a live attenuated vaccine.\""}, {"id": "b", "text": "\"After chickenpox resolves, the virus is gone from the body.\""}, {"id": "c", "text": "\"Lesions in many stages at once are typical of chickenpox.\""}, {"id": "d", "text": "\"Airborne and contact precautions are both required.\""}]'::jsonb, '["b"]', 'VZV remains dormant and can reactivate later in life as herpes zoster (shingles). The other statements correctly describe the vaccine, rash, and precautions.'),
  ('lyme', 1, 'A client who went hiking yesterday finds a tick on the leg and estimates it was attached for about 24 hours. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A tick attached less than 36 hours is unlikely to transmit Lyme disease.\""}, {"id": "b", "text": "\"Any tick bite transmits Lyme disease within the first few minutes.\""}, {"id": "c", "text": "\"You will need IV ceftriaxone today to prevent Lyme disease.\""}, {"id": "d", "text": "\"A Western blot should be drawn today to confirm the infection.\""}]'::jsonb, '["a"]', 'A tick attached for less than 36 hours is likely not to transmit disease, because the tick must be attached 36–48 hours or more. IV ceftriaxone is reserved for late, neurological, or cardiac Lyme disease, not for a recent bite.'),
  ('lyme', 2, 'The nurse is teaching a client how to remove an attached tick. Which instruction is correct?', '[{"id": "a", "text": "\"Pinch the tick''s body with your fingers and squeeze it off.\""}, {"id": "b", "text": "\"Grasp the tick close to the skin with tweezers and pull straight out.\""}, {"id": "c", "text": "\"Leave the tick in place until it falls off on its own.\""}, {"id": "d", "text": "\"Cover the tick with repellent and wait for it to back out.\""}]'::jsonb, '["b"]', 'A tick is removed with tweezers by grasping it close to the skin and pulling straight out. Leaving the tick attached is unsafe because early removal prevents infection.'),
  ('lyme', 3, 'The nurse teaches a client who hikes often about preventing Lyme disease. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wear long sleeves and pants when hiking in tick areas.\""}, {"id": "b", "text": "\"I will check my whole body for ticks after being outdoors.\""}, {"id": "c", "text": "\"I will wait until the next morning to shower after a hike.\""}, {"id": "d", "text": "\"I will use a DEET or permethrin repellent before hiking.\""}]'::jsonb, '["c"]', 'The client should shower within 2 hours of outdoor activity, so waiting until the next morning needs correction. Long sleeves and pants, full-body tick checks, and DEET or permethrin are all correct prevention measures.'),
  ('lyme', 4, 'Ten days after a camping trip, a client has an expanding red rash with a bull''s-eye appearance on the thigh, along with fatigue and muscle aches. The nurse recognizes these findings as which stage of Lyme disease?', '[{"id": "a", "text": "Stage 3, late disease"}, {"id": "b", "text": "Stage 2, early disseminated disease"}, {"id": "c", "text": "Post-treatment Lyme disease syndrome"}, {"id": "d", "text": "Stage 1, early localized disease"}]'::jsonb, '["d"]', 'Stage 1 (early localized) occurs days 3–30 after the bite and presents with erythema migrans and flu-like symptoms. Stage 2 occurs weeks to months later with facial palsy, heart block, or neurological symptoms.'),
  ('lyme', 5, 'The spouse of a client newly diagnosed with Lyme disease asks whether the spouse could catch the infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Lyme disease is not spread from person to person.\""}, {"id": "b", "text": "\"It spreads by close contact, so sleep in separate rooms.\""}, {"id": "c", "text": "\"It can spread through shared towels and dishes.\""}, {"id": "d", "text": "\"It spreads to others only while the rash is present.\""}]'::jsonb, '["a"]', 'Lyme disease is transmitted by the bite of an infected black-legged tick and is not spread person-to-person. No contact with the client, the rash, or shared items transmits the disease.'),
  ('lyme', 6, 'A client diagnosed with Lyme disease asks the nurse what causes the illness. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It is caused by a virus carried by mosquitoes.\""}, {"id": "b", "text": "\"It is caused by a bacterium spread by an infected tick.\""}, {"id": "c", "text": "\"It is caused by a parasite in contaminated water.\""}, {"id": "d", "text": "\"It is caused by a fungus entering through skin breaks.\""}]'::jsonb, '["b"]', 'Lyme disease is a bacterial tick-borne infection caused by Borrelia burgdorferi. It is not viral, parasitic, or fungal, and it is transmitted by ticks rather than mosquitoes.'),
  ('lyme', 7, 'A client living near a wooded area asks how Lyme disease is transmitted. The nurse explains that transmission occurs through which route?', '[{"id": "a", "text": "A mosquito bite at dusk"}, {"id": "b", "text": "A flea bite from a household pet"}, {"id": "c", "text": "The bite of an infected black-legged (deer) tick"}, {"id": "d", "text": "Contact with an infected person''s skin rash"}]'::jsonb, '["c"]', 'Lyme disease is transmitted by the bite of an infected black-legged (deer) tick. It is not spread person-to-person, so contact with another person''s rash does not transmit it.'),
  ('lyme', 8, 'Several weeks after an untreated bull''s-eye rash, a client reports new drooping on one side of the face. The nurse recognizes this finding as consistent with which stage of Lyme disease?', '[{"id": "a", "text": "Stage 1, early localized disease"}, {"id": "b", "text": "Stage 3, late disease"}, {"id": "c", "text": "Post-treatment Lyme disease syndrome"}, {"id": "d", "text": "Stage 2, early disseminated disease"}]'::jsonb, '["d"]', 'Stage 2 (early disseminated) occurs weeks to months after the bite and includes facial palsy (Bell''s palsy), heart block, and neurological symptoms. Stage 1 presents with erythema migrans and flu-like symptoms, not facial palsy.'),
  ('lyme', 9, 'A client who had untreated Lyme disease two years ago reports chronic swelling of both knees, numbness in the feet, and memory problems. The nurse recognizes these findings as which stage of Lyme disease?', '[{"id": "a", "text": "Stage 3, late disease"}, {"id": "b", "text": "Stage 1, early localized disease"}, {"id": "c", "text": "Stage 2, early disseminated disease"}, {"id": "d", "text": "Post-treatment Lyme disease syndrome"}]'::jsonb, '["a"]', 'Stage 3 (late) Lyme disease occurs months to years after the bite and causes chronic arthritis (especially knees), memory loss, and neuropathy. Post-treatment Lyme disease syndrome occurs after treatment, and this client was never treated.'),
  ('lyme', 10, 'A client with Lyme disease reports dizziness, and the electrocardiogram shows heart block. The nurse anticipates preparing the client for which intervention?', '[{"id": "a", "text": "Oral amoxicillin at home for 10 days"}, {"id": "b", "text": "Placement of a temporary pacemaker"}, {"id": "c", "text": "Western blot before any treatment"}, {"id": "d", "text": "Topical permethrin to the bite site"}]'::jsonb, '["b"]', 'Lyme carditis causes heart block and may require a temporary pacemaker. Cardiac involvement is treated with IV ceftriaxone, not oral amoxicillin, which is an early-stage option.'),
  ('lyme', 11, 'A client with a bull''s-eye rash who removed a tick after a hike last week asks whether a blood test is needed before Lyme disease can be diagnosed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Diagnosis requires a positive Western blot first.\""}, {"id": "b", "text": "\"Diagnosis requires a positive ELISA result first.\""}, {"id": "c", "text": "\"The rash plus tick exposure allows a clinical diagnosis.\""}, {"id": "d", "text": "\"Diagnosis must wait until antibodies have formed.\""}]'::jsonb, '["c"]', 'Lyme disease can be diagnosed clinically from erythema migrans plus a history of tick exposure. Waiting for antibody results is not required and early antibody tests can be falsely negative.'),
  ('lyme', 12, 'A client being evaluated for Lyme disease has a positive ELISA result. Which test does the nurse anticipate next?', '[{"id": "a", "text": "A second ELISA in several months"}, {"id": "b", "text": "No further testing is needed"}, {"id": "c", "text": "A full-body tick check"}, {"id": "d", "text": "A Western blot to confirm"}]'::jsonb, '["d"]', 'ELISA is the first test, and a positive result is confirmed with a Western blot. A positive ELISA alone does not complete the diagnostic workup.'),
  ('lyme', 13, 'A client who has had a bull''s-eye rash for 5 days after a tick bite is told that an antibody test is negative. The client asks, "So I don''t have Lyme disease?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Antibodies take weeks to develop, so early tests can be falsely negative.\""}, {"id": "b", "text": "\"A negative test rules out Lyme disease, so treatment is not needed.\""}, {"id": "c", "text": "\"A negative test means the tick was attached less than 36 hours.\""}, {"id": "d", "text": "\"A negative test means the infection has already reached stage 3.\""}]'::jsonb, '["a"]', 'Early antibody tests can be false negative because antibodies take weeks to develop. A negative result early in illness does not rule out Lyme disease, especially when erythema migrans is present.'),
  ('lyme', 14, 'A client with recent tick exposure, fever, and muscle aches says, "I can''t have Lyme disease because I never had a bull''s-eye rash." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"That''s right; Lyme disease always causes a bull''s-eye rash.\""}, {"id": "b", "text": "\"The rash is classic, but Lyme can occur without it.\""}, {"id": "c", "text": "\"The rash appears only in the late stage of Lyme disease.\""}, {"id": "d", "text": "\"The rash appears only after antibiotics are started.\""}]'::jsonb, '["b"]', 'The bull''s-eye rash is the classic sign of early Lyme disease, but it is not always present and the client can still have Lyme. The rash is a Stage 1 finding, not a late-stage finding.'),
  ('lyme', 15, 'An adult client is diagnosed with early localized Lyme disease. Which medication does the nurse anticipate as first-line treatment?', '[{"id": "a", "text": "IV ceftriaxone"}, {"id": "b", "text": "Acetaminophen alone"}, {"id": "c", "text": "Oral doxycycline"}, {"id": "d", "text": "Topical permethrin"}]'::jsonb, '["c"]', 'Doxycycline is the first-line antibiotic for early (Stage 1) Lyme disease. IV ceftriaxone is used for late, neurological, or cardiac disease, and permethrin is a repellent used for prevention.'),
  ('lyme', 16, 'A client starting an oral antibiotic for early localized Lyme disease asks how long treatment usually lasts. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A single dose is usually enough.\""}, {"id": "b", "text": "\"Treatment usually lasts 60 days.\""}, {"id": "c", "text": "\"Treatment usually lasts six months.\""}, {"id": "d", "text": "\"Treatment usually lasts 10 to 21 days.\""}]'::jsonb, '["d"]', 'Early (Stage 1) Lyme disease is treated with doxycycline, amoxicillin, or cefuroxime for 10–21 days. Courses of 60 days or six months are not the stated duration for early disease.'),
  ('lyme', 17, 'A client is admitted with Lyme carditis. Which antibiotic does the nurse anticipate the provider will prescribe?', '[{"id": "a", "text": "IV ceftriaxone"}, {"id": "b", "text": "Oral amoxicillin"}, {"id": "c", "text": "Oral cefuroxime"}, {"id": "d", "text": "Topical permethrin"}]'::jsonb, '["a"]', 'Late, neurological, or cardiac Lyme disease (Stage 2–3) is treated with IV ceftriaxone. Oral amoxicillin and cefuroxime are options for early Stage 1 disease.'),
  ('lyme', 18, 'A client with late Lyme disease is started on IV ceftriaxone and asks how long the infusions will continue. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Usually for about 3 days.\""}, {"id": "b", "text": "\"Usually for 2 to 4 weeks.\""}, {"id": "c", "text": "\"Usually for 60 days.\""}, {"id": "d", "text": "\"Usually for the rest of your life.\""}]'::jsonb, '["b"]', 'IV ceftriaxone for late, neurological, or cardiac Lyme disease is given for 2–4 weeks. Sixty days is not the stated duration for this treatment.'),
  ('lyme', 19, 'The provider decides not to prescribe doxycycline for a client with early localized Lyme disease. Which oral antibiotic does the nurse anticipate as an alternative?', '[{"id": "a", "text": "Oral prednisone"}, {"id": "b", "text": "Topical permethrin"}, {"id": "c", "text": "Oral amoxicillin"}, {"id": "d", "text": "IV ceftriaxone"}]'::jsonb, '["c"]', 'Amoxicillin or cefuroxime are the oral alternatives to doxycycline for early Lyme disease. IV ceftriaxone is not oral and is reserved for late, neurological, or cardiac disease.'),
  ('lyme', 20, 'A client completed a full antibiotic course for Lyme disease several months ago but still reports fatigue and joint pain. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Reinfection from household contact"}, {"id": "b", "text": "Stage 1 early localized disease"}, {"id": "c", "text": "Lyme carditis"}, {"id": "d", "text": "Post-treatment Lyme disease syndrome"}]'::jsonb, '["d"]', 'Post-Treatment Lyme Disease Syndrome (PTLDS) is fatigue and joint pain that persist even after treatment. Reinfection from household contact is not possible because Lyme is not spread person-to-person.'),
  ('lyme', 21, 'A client plans a weekend hike through a tick-infested area. Which instruction should the nurse include?', '[{"id": "a", "text": "\"Apply a DEET or permethrin repellent.\""}, {"id": "b", "text": "\"Take a dose of doxycycline before hiking.\""}, {"id": "c", "text": "\"Wear shorts so ticks are easier to see.\""}, {"id": "d", "text": "\"Check for ticks once at the end of the week.\""}]'::jsonb, '["a"]', 'DEET or permethrin repellent is a recommended prevention measure. Long sleeves and pants, not shorts, are recommended, and a full-body tick check should be done after every outdoor exposure.'),
  ('lyme', 22, 'A parent asks the nurse how a child should dress for a camping trip in an area known for ticks. Which recommendation is best?', '[{"id": "a", "text": "Shorts and a tank top to stay cool"}, {"id": "b", "text": "Long sleeves and long pants"}, {"id": "c", "text": "Sandals and a short-sleeved shirt"}, {"id": "d", "text": "A swimsuit under loose shorts"}]'::jsonb, '["b"]', 'Long sleeves and pants are recommended in tick-infested areas to prevent tick bites. Clothing that leaves skin exposed increases the chance of a tick attaching.'),
  ('lyme', 23, 'A client returns home after hiking in a wooded area. Which action is most important for the client to take to find ticks before they can transmit infection?', '[{"id": "a", "text": "Check only the legs for ticks"}, {"id": "b", "text": "Wait for a rash before looking"}, {"id": "c", "text": "Perform a full-body tick check"}, {"id": "d", "text": "Inspect the skin once a week"}]'::jsonb, '["c"]', 'A full-body tick check should be done after being outdoors so ticks are found and removed early. Waiting for a rash or checking weekly delays removal, and early removal prevents infection.'),
  ('lyme', 24, 'The nurse observes an unlicensed assistive personnel (UAP) removing a tick from a client''s scalp. Which action by the UAP requires correction?', '[{"id": "a", "text": "Using fine-tipped tweezers"}, {"id": "b", "text": "Grasping the tick close to the skin"}, {"id": "c", "text": "Pulling the tick straight out"}, {"id": "d", "text": "Squeezing the tick''s body and twisting"}]'::jsonb, '["d"]', 'The correct technique is to grasp the tick close to the skin with tweezers and pull straight out. Squeezing the body and twisting does not follow this technique and requires correction.'),
  ('lyme', 25, 'The nurse is returning phone calls from clients being treated for early localized Lyme disease. Which client report requires prompt follow-up because it suggests progression of the disease?', '[{"id": "a", "text": "\"One side of my face has started drooping.\""}, {"id": "b", "text": "\"My bull''s-eye rash is starting to fade.\""}, {"id": "c", "text": "\"My mild muscle aches are getting better.\""}, {"id": "d", "text": "\"I have taken my antibiotic every day.\""}]'::jsonb, '["a"]', 'Facial palsy is a sign of Stage 2 (early disseminated) Lyme disease and indicates progression. A fading rash and improving aches suggest the early infection is responding.'),
  ('lyme', 26, 'A client with Lyme disease reports that the mouth droops on one side and one eye will not fully close. The nurse recognizes this as which complication?', '[{"id": "a", "text": "Lyme carditis"}, {"id": "b", "text": "Bell''s palsy"}, {"id": "c", "text": "Lyme arthritis"}, {"id": "d", "text": "Post-treatment Lyme disease syndrome"}]'::jsonb, '["b"]', 'Bell''s palsy is a complication of Lyme disease that causes facial nerve drooping. Lyme carditis involves heart block, and Lyme arthritis involves chronic joint swelling.'),
  ('lyme', 27, 'The nurse is assessing a client with Lyme arthritis. Which joints does the nurse expect to be most commonly affected?', '[{"id": "a", "text": "The fingers"}, {"id": "b", "text": "The wrists"}, {"id": "c", "text": "The knees"}, {"id": "d", "text": "The spine"}]'::jsonb, '["c"]', 'Lyme arthritis causes chronic joint swelling, especially in the knees. The other joints are not identified as the typical site.'),
  ('lyme', 28, 'The nurse is assessing a client with late (stage 3) Lyme disease. Which finding does the nurse expect?', '[{"id": "a", "text": "A new bull''s-eye rash"}, {"id": "b", "text": "Flu-like symptoms after a recent bite"}, {"id": "c", "text": "A fading rash at the bite site"}, {"id": "d", "text": "Peripheral neuropathy"}]'::jsonb, '["d"]', 'Stage 3 (late) Lyme disease causes chronic arthritis, memory loss, and neuropathy. A bull''s-eye rash with flu-like symptoms is a Stage 1 (early localized) finding.'),
  ('lyme', 29, 'A client removed a tick yesterday and asks when a bull''s-eye rash would most likely appear if Lyme disease develops. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Usually within 3 to 30 days.\""}, {"id": "b", "text": "\"Usually within the first hour.\""}, {"id": "c", "text": "\"Usually months to years later.\""}, {"id": "d", "text": "\"Only after antibiotics are started.\""}]'::jsonb, '["a"]', 'Stage 1 (early localized) Lyme disease, with erythema migrans, occurs days 3–30 after the bite. Months to years later is the timing of Stage 3 (late) disease.'),
  ('lyme', 30, 'A client with Lyme disease develops facial palsy and other new neurological symptoms. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Oral amoxicillin for 10 days"}, {"id": "b", "text": "IV ceftriaxone"}, {"id": "c", "text": "Topical permethrin"}, {"id": "d", "text": "No antibiotic until a Western blot results"}]'::jsonb, '["b"]', 'Neurological Lyme disease (Stage 2–3) is treated with IV ceftriaxone. Oral amoxicillin is an option for early Stage 1 disease, not neurological involvement.'),
  ('lyme', 31, 'A client with Lyme carditis is being prepared for pacemaker insertion and asks, "Will I need this pacemaker forever?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, Lyme carditis always needs a permanent pacemaker.\""}, {"id": "b", "text": "\"The pacemaker is used to treat the facial palsy.\""}, {"id": "c", "text": "\"Lyme carditis may need only a temporary pacemaker.\""}, {"id": "d", "text": "\"The pacemaker replaces the need for antibiotics.\""}]'::jsonb, '["c"]', 'Cardiac involvement in Lyme disease may need a temporary pacemaker for heart block. The pacemaker does not replace antibiotic treatment, which for cardiac disease is IV ceftriaxone.'),
  ('lyme', 32, 'The nurse teaches a client about testing for Lyme disease. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"The ELISA is usually the first blood test.\""}, {"id": "b", "text": "\"A positive ELISA is confirmed with a Western blot.\""}, {"id": "c", "text": "\"An early antibody test can be falsely negative.\""}, {"id": "d", "text": "\"One positive ELISA is all that is needed to confirm.\""}]'::jsonb, '["d"]', 'A positive ELISA must be confirmed with a Western blot, so a single ELISA does not confirm the diagnosis. The other statements are accurate.'),
  ('lyme', 33, 'The nurse teaches a group of campers about ticks and Lyme disease. Which camper statement indicates understanding?', '[{"id": "a", "text": "\"Removing a tick early lowers my chance of getting Lyme.\""}, {"id": "b", "text": "\"A tick must be attached for weeks before it spreads Lyme.\""}, {"id": "c", "text": "\"Lyme spreads only if the same tick bites me twice.\""}, {"id": "d", "text": "\"How long the tick stays attached does not matter.\""}]'::jsonb, '["a"]', 'Early tick removal (within 36 hours) prevents infection because transmission requires attachment for 36–48 hours or more. Attachment time matters, but transmission does not require weeks.'),
  ('lyme', 34, 'During a full-body check after hiking, a client finds a tick attached behind the knee and calls the clinic. Which instruction should the nurse give first?', '[{"id": "a", "text": "\"Wait to see whether a rash develops before removing it.\""}, {"id": "b", "text": "\"Remove the tick now with tweezers, pulling straight out.\""}, {"id": "c", "text": "\"Go to the emergency department for IV ceftriaxone.\""}, {"id": "d", "text": "\"Have an ELISA drawn before the tick is removed.\""}]'::jsonb, '["b"]', 'Early tick removal (within 36 hours) prevents infection, so the tick should be removed promptly with tweezers and pulled straight out. Waiting for a rash allows longer attachment and increases the risk of transmission.'),
  ('lyme', 35, 'A client with a bull''s-eye rash that appeared one week after a tick bite is diagnosed with early localized Lyme disease. Which additional finding does the nurse expect?', '[{"id": "a", "text": "Heart block on the electrocardiogram"}, {"id": "b", "text": "Chronic swelling of the knees"}, {"id": "c", "text": "Flu-like symptoms"}, {"id": "d", "text": "Memory loss"}]'::jsonb, '["c"]', 'Stage 1 (early localized) Lyme disease presents with erythema migrans and flu-like symptoms. Heart block is a Stage 2 finding, while chronic knee arthritis and memory loss are Stage 3 findings.'),
  ('lyme', 36, 'A client reports fever and muscle aches that began after a hiking trip 2 weeks ago, when a tick was found attached for several days. No rash is present. Which conclusion by the nurse is appropriate?', '[{"id": "a", "text": "Lyme disease is ruled out because no rash is present"}, {"id": "b", "text": "The client has post-treatment Lyme disease syndrome"}, {"id": "c", "text": "The findings indicate stage 3 late Lyme disease"}, {"id": "d", "text": "Lyme disease is still possible without the rash"}]'::jsonb, '["d"]', 'The bull''s-eye rash is classic for early Lyme disease but is not always present, so the client can still have Lyme. Post-treatment Lyme disease syndrome occurs only after treatment.'),
  ('lyme', 37, 'The nurse is reviewing the histories of four clients at a rural clinic. Which client is at greatest risk for developing Lyme disease?', '[{"id": "a", "text": "A client who found a deer tick attached for about 3 days"}, {"id": "b", "text": "A client who removed a tick 12 hours after it attached"}, {"id": "c", "text": "A client who shares a bedroom with a person who has Lyme"}, {"id": "d", "text": "A client who was bitten by mosquitoes while camping"}]'::jsonb, '["a"]', 'A tick must be attached 36–48 hours or more to transmit Lyme disease, so a tick attached about 3 days poses the greatest risk. Lyme is not spread person-to-person, and a tick removed at 12 hours is unlikely to transmit disease.'),
  ('lyme', 38, 'A client has a bull''s-eye rash 4 days after a tick bite. The provider prescribes doxycycline without waiting for antibody results, and the client asks why. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Antibody tests are used only for stage 3 disease.\""}, {"id": "b", "text": "\"Antibodies take weeks to form, so early tests may miss it.\""}, {"id": "c", "text": "\"Antibody tests are not available for Lyme disease.\""}, {"id": "d", "text": "\"Treatment must start before the tick is removed.\""}]'::jsonb, '["b"]', 'Early antibody tests can be false negative because antibodies take weeks to develop, and erythema migrans with tick exposure allows a clinical diagnosis. Antibody testing (ELISA and Western blot) is available for Lyme disease.'),
  ('lyme', 39, 'An unlicensed assistive personnel (UAP) asks whether visitors of a hospitalized client with Lyme carditis need special precautions to avoid catching the disease. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Visitors must wear N95 masks in the room.\""}, {"id": "b", "text": "\"Visitors should avoid touching the client''s skin.\""}, {"id": "c", "text": "\"Visitors cannot catch Lyme from the client.\""}, {"id": "d", "text": "\"Visitors must stay 6 feet from the client.\""}]'::jsonb, '["c"]', 'Lyme disease is transmitted by the bite of an infected tick and is not spread person-to-person. Masks, distance, and avoiding skin contact do not apply to preventing Lyme transmission.'),
  ('lyme', 40, 'Which client finding best supports a clinical diagnosis of Lyme disease without waiting for laboratory results?', '[{"id": "a", "text": "A positive ELISA with no symptoms"}, {"id": "b", "text": "Chronic fatigue with no tick exposure"}, {"id": "c", "text": "Facial drooping after a viral illness"}, {"id": "d", "text": "A bull''s-eye rash after a tick bite while hiking"}]'::jsonb, '["d"]', 'A clinical diagnosis is based on erythema migrans plus a history of tick exposure. A positive ELISA alone is not a clinical diagnosis and must be confirmed with a Western blot.'),
  ('lyme', 41, 'A client asks the nurse why a Western blot has been ordered. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It confirms a positive ELISA result.\""}, {"id": "b", "text": "\"It is the first screening test for Lyme.\""}, {"id": "c", "text": "\"It checks your heart for heart block.\""}, {"id": "d", "text": "\"It prevents Lyme after a tick bite.\""}]'::jsonb, '["a"]', 'ELISA is the first test, and if it is positive, the result is confirmed with a Western blot. The Western blot is not the initial screening test.'),
  ('lyme', 42, 'A client with untreated Lyme disease asks when the late-stage problems, such as chronic arthritis, would develop. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Within 3 days of the tick bite.\""}, {"id": "b", "text": "\"Months to years after the bite.\""}, {"id": "c", "text": "\"Days 3 to 30 after the bite.\""}, {"id": "d", "text": "\"Within hours of the tick bite.\""}]'::jsonb, '["b"]', 'Stage 3 (late) Lyme disease develops months to years after the bite. Days 3–30 is the timing of Stage 1 (early localized) disease.'),
  ('lyme', 43, 'A client who gardens near a wooded area asks how soon to shower after working outdoors to help prevent Lyme disease. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Within 24 hours of being outdoors.\""}, {"id": "b", "text": "\"The next morning is soon enough.\""}, {"id": "c", "text": "\"Within 2 hours of being outdoors.\""}, {"id": "d", "text": "\"Only if you notice a rash later.\""}]'::jsonb, '["c"]', 'Showering within 2 hours of outdoor activity is a recommended prevention measure. Waiting 24 hours or until a rash appears delays this protection.'),
  ('lyme', 44, 'The nurse at an outpatient clinic receives four messages. Which client should the nurse call back first?', '[{"id": "a", "text": "A client who removed a tick 6 hours after it attached"}, {"id": "b", "text": "A client on day 3 of doxycycline whose rash is fading"}, {"id": "c", "text": "A client asking how to apply permethrin repellent"}, {"id": "d", "text": "A client with Lyme carditis reporting new dizziness"}]'::jsonb, '["d"]', 'Lyme carditis causes heart block and may need a temporary pacemaker, so new dizziness requires priority follow-up. A tick removed at 6 hours is unlikely to transmit disease, and a fading rash on treatment is expected.'),
  ('lyme', 45, 'The nurse evaluates a client''s understanding of Lyme disease prevention before a hunting trip. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I''ll wear long sleeves and pants and use DEET.\""}, {"id": "b", "text": "\"I''ll wear shorts so I can spot ticks easily.\""}, {"id": "c", "text": "\"I''ll check for ticks only if my skin itches.\""}, {"id": "d", "text": "\"I''ll shower the day after I get back home.\""}]'::jsonb, '["a"]', 'Long sleeves and pants plus DEET or permethrin repellent are recommended prevention measures. Showering should occur within 2 hours, and a full-body tick check should be done after every outdoor exposure.'),
  ('lyme', 46, 'A client taking doxycycline for early localized Lyme disease is receiving discharge teaching. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will take the full course that was prescribed.\""}, {"id": "b", "text": "\"I can stop the doxycycline once my rash fades.\""}, {"id": "c", "text": "\"My course may last anywhere from 10 to 21 days.\""}, {"id": "d", "text": "\"Doxycycline is the first-line drug for early Lyme.\""}]'::jsonb, '["b"]', 'Early Lyme disease is treated for 10–21 days, so stopping when the rash fades needs correction. Doxycycline is the first-line drug for early disease.'),
  ('lyme', 47, 'The nurse teaches a community group about how Lyme disease is transmitted. Which participant statement indicates understanding?', '[{"id": "a", "text": "\"A tick transmits Lyme as soon as it bites.\""}, {"id": "b", "text": "\"I can catch Lyme from an infected relative.\""}, {"id": "c", "text": "\"A tick usually must be attached 36 to 48 hours.\""}, {"id": "d", "text": "\"Only ticks attached over a month are a risk.\""}]'::jsonb, '["c"]', 'A tick must be attached 36–48 hours or more to transmit disease. Lyme disease is not spread person-to-person.'),
  ('lyme', 48, 'A client asks why an antibiotic is prescribed for an illness that came from a tick bite. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The tick''s saliva causes an allergic reaction.\""}, {"id": "b", "text": "\"Lyme is a viral illness that antibiotics shorten.\""}, {"id": "c", "text": "\"The antibiotic repels ticks from your skin.\""}, {"id": "d", "text": "\"Lyme is caused by the bacterium Borrelia burgdorferi.\""}]'::jsonb, '["d"]', 'Lyme disease is a bacterial tick-borne infection caused by Borrelia burgdorferi, so it is treated with antibiotics. It is not a viral illness.'),
  ('lyme', 49, 'While assessing a client who recently hiked in a wooded area, the nurse notes a red rash with a bull''s-eye pattern near the waistline. The nurse recognizes this finding as which of the following?', '[{"id": "a", "text": "Erythema migrans of Lyme disease"}, {"id": "b", "text": "Bell''s palsy of Lyme disease"}, {"id": "c", "text": "Lyme carditis"}, {"id": "d", "text": "Post-treatment Lyme disease syndrome"}]'::jsonb, '["a"]', 'A bull''s-eye rash is erythema migrans, the classic sign of Lyme disease. Bell''s palsy is facial nerve drooping, and Lyme carditis is heart block.'),
  ('lyme', 50, 'The nurse is teaching a client about the progression of untreated Lyme disease. Which sequence of findings correctly reflects the stages from earliest to latest?', '[{"id": "a", "text": "Facial palsy, bull''s-eye rash, chronic knee arthritis"}, {"id": "b", "text": "Bull''s-eye rash, facial palsy, chronic knee arthritis"}, {"id": "c", "text": "Chronic knee arthritis, facial palsy, bull''s-eye rash"}, {"id": "d", "text": "Bull''s-eye rash, chronic knee arthritis, facial palsy"}]'::jsonb, '["b"]', 'Stage 1 (days 3–30) causes erythema migrans, Stage 2 (weeks–months) causes facial palsy, and Stage 3 (months–years) causes chronic arthritis of the knees. Facial palsy therefore comes after the rash and before chronic arthritis.'),
  ('anthrax', 1, 'A client reports a sore that developed on the forearm a few days after cutting it while handling an unfamiliar powder. The nurse notes a black, painless ulcer with surrounding swelling. The nurse recognizes this as which type of anthrax?', '[{"id": "a", "text": "Cutaneous anthrax"}, {"id": "b", "text": "Inhalation anthrax"}, {"id": "c", "text": "Gastrointestinal anthrax"}, {"id": "d", "text": "Anthrax meningitis"}]'::jsonb, '["a"]', 'A black painless ulcer (eschar) with swelling that follows a skin cut or break is cutaneous anthrax. Inhalation anthrax presents with flu-like symptoms that rapidly worsen, not a skin ulcer.'),
  ('anthrax', 2, 'A client is admitted with cutaneous anthrax. Which type of precautions should the nurse implement?', '[{"id": "a", "text": "Airborne precautions in a negative-pressure room"}, {"id": "b", "text": "Standard precautions without isolation"}, {"id": "c", "text": "Droplet precautions with a surgical mask"}, {"id": "d", "text": "Strict isolation with limited visitors"}]'::jsonb, '["b"]', 'Anthrax is not spread person-to-person, so no isolation is needed beyond standard precautions. Airborne or droplet isolation is not required.'),
  ('anthrax', 3, 'A mail sorter came to the clinic two days ago with fever, fatigue, and body aches. The client now returns with severe shortness of breath and rapid clinical decline. The nurse suspects which condition?', '[{"id": "a", "text": "Cutaneous anthrax"}, {"id": "b", "text": "Gastrointestinal anthrax"}, {"id": "c", "text": "Inhalation anthrax"}, {"id": "d", "text": "A self-limited viral illness"}]'::jsonb, '["c"]', 'Flu-like symptoms that worsen rapidly are the hallmark of inhalation anthrax, which is a bioterrorism concern. Cutaneous anthrax presents with a black painless eschar rather than rapid systemic decline.'),
  ('anthrax', 4, 'A client with suspected inhalation anthrax has a chest x-ray. Which finding does the nurse expect the report to show?', '[{"id": "a", "text": "A black eschar over the chest wall"}, {"id": "b", "text": "A normal chest x-ray"}, {"id": "c", "text": "A single small nodule in one lung"}, {"id": "d", "text": "A widened mediastinum"}]'::jsonb, '["d"]', 'Chest x-ray or CT in inhalation anthrax shows a widened mediastinum. An eschar is a skin finding of cutaneous anthrax, not an imaging finding.'),
  ('anthrax', 5, 'A client with suspected inhalation anthrax has blood cultures drawn in the emergency department. The results will not be available for 48 hours. Which action should the nurse take first?', '[{"id": "a", "text": "Administer the prescribed antibiotic now"}, {"id": "b", "text": "Hold the antibiotic until cultures result"}, {"id": "c", "text": "Place the client in airborne isolation"}, {"id": "d", "text": "Wait for the chest CT before treating"}]'::jsonb, '["a"]', 'Antibiotics are started immediately for anthrax without waiting for confirmation. Airborne isolation is not needed because anthrax is not spread person-to-person.'),
  ('anthrax', 6, 'A laboratory worker is started on post-exposure prophylaxis after an anthrax exposure. The worker asks how long the antibiotic must be taken. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"For 10 days.\""}, {"id": "b", "text": "\"For 60 days.\""}, {"id": "c", "text": "\"For 6 months.\""}, {"id": "d", "text": "\"Until symptoms appear.\""}]'::jsonb, '["b"]', 'Anthrax post-exposure prophylaxis includes 60 days of oral ciprofloxacin or doxycycline. Shorter courses do not match the PEP regimen.'),
  ('anthrax', 7, 'A client receiving post-exposure prophylaxis for anthrax asks how many doses of anthrax vaccine are included. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A single dose.\""}, {"id": "b", "text": "\"Two doses.\""}, {"id": "c", "text": "\"Three doses.\""}, {"id": "d", "text": "\"Five doses.\""}]'::jsonb, '["c"]', 'Anthrax post-exposure prophylaxis includes 3 doses of anthrax vaccine along with 60 days of oral antibiotics.'),
  ('anthrax', 8, 'The nurse teaches a client who is starting post-exposure prophylaxis after an anthrax exposure. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will take the antibiotic by mouth.\""}, {"id": "b", "text": "\"I will receive three doses of the vaccine.\""}, {"id": "c", "text": "\"My antibiotic may be ciprofloxacin or doxycycline.\""}, {"id": "d", "text": "\"I can stop the pills after two weeks if I feel fine.\""}]'::jsonb, '["d"]', 'Post-exposure prophylaxis requires 60 days of oral ciprofloxacin or doxycycline, so stopping after two weeks needs correction. The other statements reflect the PEP regimen.'),
  ('anthrax', 9, 'A client reports nausea, vomiting, fever, and severe abdominal pain several days after eating meat from an animal that later was found to be infected with anthrax. The nurse suspects which type of anthrax?', '[{"id": "a", "text": "Gastrointestinal anthrax"}, {"id": "b", "text": "Cutaneous anthrax"}, {"id": "c", "text": "Inhalation anthrax"}, {"id": "d", "text": "Anthrax meningitis"}]'::jsonb, '["a"]', 'Gastrointestinal anthrax follows eating infected meat and causes nausea, vomiting, fever, and severe abdominal pain. Cutaneous anthrax enters through skin cuts and causes a black painless eschar.'),
  ('anthrax', 10, 'A nursing student asks which form of anthrax is seen most often. Which response by the nurse is accurate?', '[{"id": "a", "text": "Inhalation anthrax"}, {"id": "b", "text": "Cutaneous anthrax"}, {"id": "c", "text": "Gastrointestinal anthrax"}, {"id": "d", "text": "All forms occur equally"}]'::jsonb, '["b"]', 'Cutaneous anthrax is the most common and least deadly form. Inhalation anthrax is the deadliest form.'),
  ('anthrax', 11, 'During an emergency preparedness class, the nurse is asked which form of anthrax carries the highest risk of death. Which response is accurate?', '[{"id": "a", "text": "Cutaneous anthrax"}, {"id": "b", "text": "Gastrointestinal anthrax"}, {"id": "c", "text": "Inhalation anthrax"}, {"id": "d", "text": "All forms are equally deadly"}]'::jsonb, '["c"]', 'Inhalation anthrax is the deadliest form, progressing rapidly to sepsis or meningitis. Cutaneous anthrax is the most common and least deadly form.'),
  ('anthrax', 12, 'A client is diagnosed with anthrax. Which medication does the nurse anticipate the provider will prescribe?', '[{"id": "a", "text": "An antiviral agent"}, {"id": "b", "text": "A corticosteroid alone"}, {"id": "c", "text": "An antifungal agent"}, {"id": "d", "text": "Ciprofloxacin"}]'::jsonb, '["d"]', 'Anthrax is a bacterial infection treated with ciprofloxacin (a fluoroquinolone) or doxycycline. Antiviral or antifungal agents do not treat a bacterial infection.'),
  ('anthrax', 13, 'A client with confirmed inhalation anthrax is receiving IV ciprofloxacin. Which additional therapy does the nurse anticipate may be added?', '[{"id": "a", "text": "Antitoxin"}, {"id": "b", "text": "An antifungal agent"}, {"id": "c", "text": "Topical wound ointment"}, {"id": "d", "text": "An antiviral agent"}]'::jsonb, '["a"]', 'Antitoxin may be added for inhalation anthrax along with antibiotics. A topical wound treatment would not address the systemic inhalation form.'),
  ('anthrax', 14, 'The occupational health nurse is reviewing which employees should be offered the anthrax vaccine before any exposure occurs. Which employee is the best candidate?', '[{"id": "a", "text": "An office clerk who works from home"}, {"id": "b", "text": "A laboratory worker who handles anthrax samples"}, {"id": "c", "text": "A school teacher with seasonal allergies"}, {"id": "d", "text": "A retail cashier with a recent cut"}]'::jsonb, '["b"]', 'The anthrax vaccine is available for high-risk groups such as military personnel and laboratory workers. The other employees are not identified as high risk.'),
  ('anthrax', 15, 'A client has a black, painless skin lesion, and the provider suspects cutaneous anthrax. Which specimen does the nurse anticipate collecting from the lesion?', '[{"id": "a", "text": "A sputum sample"}, {"id": "b", "text": "A stool sample"}, {"id": "c", "text": "A wound swab"}, {"id": "d", "text": "A throat swab"}]'::jsonb, '["c"]', 'A wound swab is used to diagnose cutaneous anthrax. Chest imaging is used for the inhalation form, and a sputum or stool sample is not the listed test for the skin form.'),
  ('anthrax', 16, 'The charge nurse is observing a new nurse caring for a client with cutaneous anthrax. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Wearing gloves to change the wound dressing"}, {"id": "b", "text": "Performing hand hygiene after client care"}, {"id": "c", "text": "Giving the prescribed antibiotic promptly"}, {"id": "d", "text": "Placing the client in airborne isolation"}]'::jsonb, '["d"]', 'Anthrax is not contagious person-to-person, so no isolation is required. Gloves and hand hygiene for wound care are the correct standard precautions.'),
  ('anthrax', 17, 'The family of a client hospitalized with inhalation anthrax asks whether they can visit without becoming infected. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Anthrax does not spread from person to person.\""}, {"id": "b", "text": "\"You must wear an N95 respirator in the room.\""}, {"id": "c", "text": "\"Visits must wait until antibiotics are finished.\""}, {"id": "d", "text": "\"Only one adult may visit, behind a closed door.\""}]'::jsonb, '["a"]', 'Anthrax is not spread person-to-person, so no isolation is needed beyond standard precautions. Respirators and visitor restrictions are not required.'),
  ('anthrax', 18, 'Over several hours, the emergency department receives multiple clients from the same office building, each with flu-like symptoms that are worsening rapidly. Which concern should the nurse report immediately?', '[{"id": "a", "text": "A seasonal outbreak of cutaneous anthrax"}, {"id": "b", "text": "Possible inhalation anthrax from bioterrorism"}, {"id": "c", "text": "Gastrointestinal anthrax from a shared lunch"}, {"id": "d", "text": "Person-to-person spread of anthrax at work"}]'::jsonb, '["b"]', 'Flu-like symptoms with rapid deterioration indicate inhalation anthrax, which is a bioterrorism concern. Anthrax is not spread person-to-person.'),
  ('anthrax', 19, 'A client asks the nurse what causes anthrax. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A virus spread through coughing.\""}, {"id": "b", "text": "\"A parasite found in unclean water.\""}, {"id": "c", "text": "\"Spores of the bacterium Bacillus anthracis.\""}, {"id": "d", "text": "\"A fungus that grows in damp buildings.\""}]'::jsonb, '["c"]', 'Anthrax is a serious bacterial infection caused by Bacillus anthracis spores. It is not a viral, parasitic, or fungal infection.'),
  ('anthrax', 20, 'A client is diagnosed with inhalation anthrax. The nurse understands that this form of anthrax was acquired through which route?', '[{"id": "a", "text": "Eating infected meat"}, {"id": "b", "text": "A cut or break in the skin"}, {"id": "c", "text": "Close contact with an infected person"}, {"id": "d", "text": "Breathing in spores"}]'::jsonb, '["d"]', 'Inhalation anthrax results from breathing in spores. Eating infected meat causes gastrointestinal anthrax, and anthrax is not spread person-to-person.'),
  ('anthrax', 21, 'A client asks how a person develops cutaneous anthrax. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Spores enter through cuts or breaks in the skin.\""}, {"id": "b", "text": "\"Spores are breathed in from contaminated air.\""}, {"id": "c", "text": "\"Bacteria are swallowed in infected meat.\""}, {"id": "d", "text": "\"Bacteria pass from an infected person''s touch.\""}]'::jsonb, '["a"]', 'Cutaneous anthrax develops when spores enter through skin cuts or breaks. Breathing in spores causes inhalation anthrax, and swallowing infected meat causes gastrointestinal anthrax.'),
  ('anthrax', 22, 'A client is diagnosed with gastrointestinal anthrax. The nurse understands that this form of anthrax was most likely acquired through which route?', '[{"id": "a", "text": "Breathing in spores"}, {"id": "b", "text": "Eating infected meat"}, {"id": "c", "text": "A cut on the hand"}, {"id": "d", "text": "Contact with an ill coworker"}]'::jsonb, '["b"]', 'Gastrointestinal anthrax is acquired by eating infected meat. Breathing in spores causes inhalation anthrax, and a skin cut leads to cutaneous anthrax.'),
  ('anthrax', 23, 'The nurse is changing the dressing on a draining lesion of a client with cutaneous anthrax. Which infection control measures are appropriate?', '[{"id": "a", "text": "An N95 respirator and negative-pressure room"}, {"id": "b", "text": "A surgical mask and droplet precautions"}, {"id": "c", "text": "Gloves and hand hygiene"}, {"id": "d", "text": "A full gown and face shield in isolation"}]'::jsonb, '["c"]', 'Standard precautions for wound care, including gloves and hand hygiene, are used because anthrax is not contagious person-to-person. Respirators and negative-pressure rooms are not required.'),
  ('anthrax', 24, 'A client arrives at the emergency department with flu-like symptoms, and anthrax is being considered. Which assessment data is most critical for the nurse to obtain?', '[{"id": "a", "text": "Family history of lung disease"}, {"id": "b", "text": "Recent travel vaccination record"}, {"id": "c", "text": "Current over-the-counter medications"}, {"id": "d", "text": "History of possible exposure"}]'::jsonb, '["d"]', 'Exposure history is critical in diagnosing anthrax. Family history and medication history do not identify contact with anthrax spores.'),
  ('anthrax', 25, 'A client with suspected systemic anthrax is admitted. Which laboratory test does the nurse anticipate collecting to help confirm the diagnosis?', '[{"id": "a", "text": "Blood cultures"}, {"id": "b", "text": "A urinalysis"}, {"id": "c", "text": "A lipid panel"}, {"id": "d", "text": "A hemoglobin A1C"}]'::jsonb, '["a"]', 'Blood cultures are used in diagnosing anthrax, along with chest imaging for the inhalation form and a wound swab for the cutaneous form. The other tests are not used to diagnose anthrax.'),
  ('anthrax', 26, 'The nurse is assessing a client with a skin lesion caused by cutaneous anthrax. Which description of the lesion does the nurse expect?', '[{"id": "a", "text": "A red, painful blister with clear fluid"}, {"id": "b", "text": "A black, painless ulcer with swelling"}, {"id": "c", "text": "A raised, itchy bull''s-eye rash"}, {"id": "d", "text": "A white, painful patch that bleeds"}]'::jsonb, '["b"]', 'Cutaneous anthrax causes a black painless ulcer (eschar) with swelling. A painful lesion does not match the classic painless eschar.'),
  ('anthrax', 27, 'A client is receiving treatment for inhalation anthrax. The nurse monitors closely for which complications that develop with rapid progression of this form?', '[{"id": "a", "text": "Black eschar and local swelling"}, {"id": "b", "text": "Vomiting and severe abdominal pain"}, {"id": "c", "text": "Sepsis and meningitis"}, {"id": "d", "text": "Chronic arthritis of the knees"}]'::jsonb, '["c"]', 'Inhalation anthrax starts with flu-like symptoms and rapidly progresses to sepsis or meningitis. A black eschar with swelling is the cutaneous form, and vomiting with abdominal pain is the gastrointestinal form.'),
  ('anthrax', 28, 'A client is admitted in serious condition with inhalation anthrax, and ciprofloxacin is prescribed. Which route of administration does the nurse anticipate?', '[{"id": "a", "text": "Topical application to the skin"}, {"id": "b", "text": "Inhaled by nebulizer"}, {"id": "c", "text": "Intramuscular injection only"}, {"id": "d", "text": "Intravenous infusion"}]'::jsonb, '["d"]', 'Ciprofloxacin or doxycycline is given orally, or IV for serious forms of anthrax. Inhalation anthrax is the deadliest form, so IV therapy is anticipated.'),
  ('anthrax', 29, 'An asymptomatic employee was exposed to anthrax spores at work and is prescribed post-exposure prophylaxis. Which antibiotic regimen does the nurse anticipate?', '[{"id": "a", "text": "Oral ciprofloxacin or doxycycline"}, {"id": "b", "text": "IV ceftriaxone for 2 weeks"}, {"id": "c", "text": "An oral antiviral for 5 days"}, {"id": "d", "text": "A single dose of antitoxin"}]'::jsonb, '["a"]', 'Post-exposure prophylaxis consists of 60 days of oral ciprofloxacin or doxycycline plus 3 doses of anthrax vaccine. Antitoxin may be added for inhalation anthrax, not used alone as prophylaxis.'),
  ('anthrax', 30, 'The nurse is teaching a group of new graduates about the types of anthrax. Which statement by a graduate is accurate?', '[{"id": "a", "text": "\"Inhalation anthrax is the least deadly form.\""}, {"id": "b", "text": "\"Cutaneous anthrax is the least deadly form.\""}, {"id": "c", "text": "\"Gastrointestinal anthrax is the most common form.\""}, {"id": "d", "text": "\"Cutaneous anthrax is the deadliest form.\""}]'::jsonb, '["b"]', 'Cutaneous anthrax is the most common and least deadly form, while inhalation anthrax is the deadliest. Gastrointestinal anthrax is moderate to severe but is not the most common.'),
  ('anthrax', 31, 'The nurse manager reviews the care of a client admitted with suspected anthrax. Which action by the staff nurse requires correction?', '[{"id": "a", "text": "Collecting blood cultures as prescribed"}, {"id": "b", "text": "Asking about possible exposure history"}, {"id": "c", "text": "Holding the antibiotic until results return"}, {"id": "d", "text": "Using standard precautions for care"}]'::jsonb, '["c"]', 'Antibiotics should be started immediately for anthrax without waiting for confirmation. Blood cultures, exposure history, and standard precautions are appropriate.'),
  ('anthrax', 32, 'A client being treated for cutaneous anthrax is preparing for discharge home. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wash my hands after touching my dressing.\""}, {"id": "b", "text": "\"I will take my antibiotic as prescribed.\""}, {"id": "c", "text": "\"My family will use gloves when helping with my wound.\""}, {"id": "d", "text": "\"My children must stay away so they don''t catch it from me.\""}]'::jsonb, '["d"]', 'Anthrax is not spread person-to-person, so family members do not need to be kept away. Gloves and hand hygiene for wound care are appropriate standard precautions.'),
  ('anthrax', 33, 'A client exposed to anthrax spores by inhalation has not yet deteriorated. Which early findings does the nurse expect?', '[{"id": "a", "text": "Flu-like symptoms"}, {"id": "b", "text": "A black painless eschar"}, {"id": "c", "text": "Severe abdominal pain with vomiting"}, {"id": "d", "text": "No symptoms for several years"}]'::jsonb, '["a"]', 'Inhalation anthrax begins with flu-like symptoms before rapid progression to sepsis or meningitis. A black painless eschar is the cutaneous form.'),
  ('anthrax', 34, 'A client with cutaneous anthrax is to be treated with an oral antibiotic other than ciprofloxacin. Which medication does the nurse anticipate?', '[{"id": "a", "text": "An antiviral agent"}, {"id": "b", "text": "Doxycycline"}, {"id": "c", "text": "An antifungal agent"}, {"id": "d", "text": "Antitoxin alone"}]'::jsonb, '["b"]', 'Anthrax is treated with ciprofloxacin or doxycycline. Antitoxin may be added for inhalation anthrax and is not an oral antibiotic.'),
  ('anthrax', 35, 'After a suspected anthrax release, the emergency department nurse receives four clients. Which client should the nurse see first?', '[{"id": "a", "text": "A client with a black, painless eschar on the hand"}, {"id": "b", "text": "A client who needs post-exposure prophylaxis teaching"}, {"id": "c", "text": "A client with flu-like symptoms and worsening dyspnea"}, {"id": "d", "text": "A client asking whether family members can visit"}]'::jsonb, '["c"]', 'Flu-like symptoms that rapidly worsen indicate inhalation anthrax, the deadliest form, which progresses to sepsis or meningitis. A painless eschar indicates cutaneous anthrax, the least deadly form.'),
  ('anthrax', 36, 'The nurse is reviewing types of anthrax with a client who works in a high-risk laboratory. Which client statement indicates correct understanding?', '[{"id": "a", "text": "\"A painful red blister means inhalation anthrax.\""}, {"id": "b", "text": "\"Flu that improves on its own means skin anthrax.\""}, {"id": "c", "text": "\"Abdominal pain after a cut means skin anthrax.\""}, {"id": "d", "text": "\"A black painless ulcer means skin anthrax.\""}]'::jsonb, '["d"]', 'A black painless ulcer indicates cutaneous anthrax, while flu symptoms that worsen rapidly indicate inhalation anthrax. Abdominal pain is a gastrointestinal finding linked to eating infected meat.'),
  ('anthrax', 37, 'A client asks what post-exposure prophylaxis for anthrax involves. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Sixty days of antibiotics plus the vaccine.\""}, {"id": "b", "text": "\"One dose of vaccine with no antibiotics.\""}, {"id": "c", "text": "\"Antitoxin alone given in a single dose.\""}, {"id": "d", "text": "\"Ten days of antibiotics with no vaccine.\""}]'::jsonb, '["a"]', 'Anthrax PEP is 60 days of antibiotics plus vaccine. Antitoxin may be added for inhalation anthrax but is not the PEP regimen.'),
  ('anthrax', 38, 'The nurse evaluates teaching for a client starting post-exposure prophylaxis after an anthrax exposure. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will take doxycycline for 10 days only.\""}, {"id": "b", "text": "\"I''ll take the pills 60 days and get 3 vaccine doses.\""}, {"id": "c", "text": "\"I will get one vaccine dose and no antibiotics.\""}, {"id": "d", "text": "\"I will stay in isolation until I finish my pills.\""}]'::jsonb, '["b"]', 'PEP consists of 60 days of oral ciprofloxacin or doxycycline and 3 doses of anthrax vaccine. Isolation is not required because anthrax is not spread person-to-person.'),
  ('anthrax', 39, 'The nurse is assessing a client with cutaneous anthrax on the arm. In addition to the black ulcer, which finding does the nurse expect around the lesion?', '[{"id": "a", "text": "Severe pain at the site"}, {"id": "b", "text": "A bull''s-eye red ring"}, {"id": "c", "text": "Swelling"}, {"id": "d", "text": "Clear, fluid-filled blisters"}]'::jsonb, '["c"]', 'Cutaneous anthrax causes a black painless ulcer (eschar) with swelling. The lesion is painless, so severe pain is not expected.'),
  ('anthrax', 40, 'A client is admitted with gastrointestinal anthrax. Which assessment findings does the nurse expect?', '[{"id": "a", "text": "A black painless eschar on the hand"}, {"id": "b", "text": "Flu-like symptoms with a widened mediastinum"}, {"id": "c", "text": "Facial drooping and memory loss"}, {"id": "d", "text": "Nausea, vomiting, fever, and severe abdominal pain"}]'::jsonb, '["d"]', 'Gastrointestinal anthrax causes nausea, vomiting, fever, and severe abdominal pain. A widened mediastinum is seen with the inhalation form.'),
  ('anthrax', 41, 'An emergency department nurse is reviewing four clients who work at the same mail-processing center. Which finding raises the greatest concern for anthrax from bioterrorism?', '[{"id": "a", "text": "Flu-like illness that is rapidly worsening"}, {"id": "b", "text": "A small, healing cut on one finger"}, {"id": "c", "text": "Mild seasonal nasal congestion"}, {"id": "d", "text": "Heartburn after a spicy meal"}]'::jsonb, '["a"]', 'Flu-like symptoms that worsen rapidly suggest inhalation anthrax, which is a bioterrorism concern. The other findings do not match any anthrax presentation.'),
  ('anthrax', 42, 'A nursing student asks for which form of anthrax antitoxin may be added to antibiotic therapy. Which response by the nurse is accurate?', '[{"id": "a", "text": "Cutaneous anthrax"}, {"id": "b", "text": "Inhalation anthrax"}, {"id": "c", "text": "Gastrointestinal anthrax"}, {"id": "d", "text": "Post-exposure prophylaxis"}]'::jsonb, '["b"]', 'Antitoxin may be added for inhalation anthrax. Post-exposure prophylaxis consists of 60 days of oral antibiotics plus 3 vaccine doses.'),
  ('anthrax', 43, 'A client with fever, fatigue, and rapidly worsening breathing is suspected of having inhalation anthrax. Which diagnostic study does the nurse prepare the client for?', '[{"id": "a", "text": "A wound swab"}, {"id": "b", "text": "A stool culture"}, {"id": "c", "text": "A chest CT scan"}, {"id": "d", "text": "An abdominal ultrasound"}]'::jsonb, '["c"]', 'Chest x-ray or CT is used for the inhalation form to look for a widened mediastinum. A wound swab is used for the cutaneous form.'),
  ('anthrax', 44, 'The spouse of a client with gastrointestinal anthrax asks how serious this form is compared with the others. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is the deadliest form.\""}, {"id": "b", "text": "\"It is the least deadly form.\""}, {"id": "c", "text": "\"It is mild and harmless.\""}, {"id": "d", "text": "\"It is moderate to severe.\""}]'::jsonb, '["d"]', 'Gastrointestinal anthrax is moderate to severe. Inhalation anthrax is the deadliest form, and cutaneous anthrax is the least deadly.'),
  ('anthrax', 45, 'The charge nurse is assigning a room to a client admitted with inhalation anthrax. Which room assignment is appropriate?', '[{"id": "a", "text": "A standard room using standard precautions"}, {"id": "b", "text": "A negative-pressure airborne isolation room"}, {"id": "c", "text": "A room with droplet precautions posted"}, {"id": "d", "text": "A room with contact precautions posted"}]'::jsonb, '["a"]', 'Anthrax is not spread person-to-person, so no isolation is required and standard precautions are used. A negative-pressure airborne isolation room is unnecessary.'),
  ('anthrax', 46, 'A client is being evaluated for gastrointestinal anthrax. Which question by the nurse is most relevant to the client''s exposure history?', '[{"id": "a", "text": "\"Have you recently traveled by airplane?\""}, {"id": "b", "text": "\"Have you eaten meat from a possibly infected animal?\""}, {"id": "c", "text": "\"Has anyone you live with had a cough?\""}, {"id": "d", "text": "\"Have you had any recent insect bites?\""}]'::jsonb, '["b"]', 'Gastrointestinal anthrax is acquired by eating infected meat, and exposure history is critical for diagnosis. Anthrax is not spread person-to-person, so a household cough is not relevant.'),
  ('anthrax', 47, 'The nurse is caring for a client with a draining cutaneous anthrax lesion. Which personal protective equipment is appropriate for the dressing change?', '[{"id": "a", "text": "An N95 respirator"}, {"id": "b", "text": "A surgical mask only"}, {"id": "c", "text": "Gloves"}, {"id": "d", "text": "A respirator with airborne isolation"}]'::jsonb, '["c"]', 'Standard precautions for wound care include gloves and hand hygiene. Respirators are not needed because anthrax is not contagious person-to-person.'),
  ('anthrax', 48, 'After anthrax spores are deliberately released in an office building, several employees were exposed but have no symptoms. Which intervention does the nurse anticipate for these employees?', '[{"id": "a", "text": "Observation only until symptoms develop"}, {"id": "b", "text": "Isolation in negative-pressure rooms"}, {"id": "c", "text": "A single dose of antitoxin"}, {"id": "d", "text": "Sixty days of antibiotics plus vaccine"}]'::jsonb, '["d"]', 'Post-exposure prophylaxis for anthrax is 60 days of antibiotics plus vaccine. Isolation is not needed because anthrax is not spread person-to-person.'),
  ('anthrax', 49, 'A client asks the nurse whether a vaccine against anthrax exists. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, it is available for high-risk groups such as the military.\""}, {"id": "b", "text": "\"No, there is no vaccine, only antibiotics.\""}, {"id": "c", "text": "\"Yes, it is given routinely to all infants.\""}, {"id": "d", "text": "\"No, the vaccine was replaced by antitoxin.\""}]'::jsonb, '["a"]', 'An anthrax vaccine is available for high-risk groups such as military personnel and laboratory workers. It is also part of post-exposure prophylaxis.'),
  ('anthrax', 50, 'A client with fever and body aches that are worsening quickly has a chest x-ray that shows a widened mediastinum. The nurse interprets this finding as most consistent with which condition?', '[{"id": "a", "text": "Cutaneous anthrax"}, {"id": "b", "text": "Inhalation anthrax"}, {"id": "c", "text": "Gastrointestinal anthrax"}, {"id": "d", "text": "Post-exposure prophylaxis reaction"}]'::jsonb, '["b"]', 'A widened mediastinum on chest x-ray or CT is the finding of inhalation anthrax. Cutaneous anthrax is diagnosed with a wound swab of the eschar.'),
  ('mumps', 1, 'A nurse is assessing an unvaccinated 8-year-old child with suspected mumps. Which finding is considered the hallmark of this illness?', '[{"id": "a", "text": "Painful swelling of one or both parotid glands"}, {"id": "b", "text": "An itchy vesicular rash spreading over the trunk"}, {"id": "c", "text": "Painless swelling of the knees and ankles"}, {"id": "d", "text": "Red, watery eyes with a runny nose"}]'::jsonb, '["a"]', 'Parotitis, painful swelling of one or both parotid glands, is the hallmark of mumps. The other findings are not described as mumps manifestations.'),
  ('mumps', 2, 'A school-age child with mumps reports pain. Which description of the pain should the nurse expect?', '[{"id": "a", "text": "Chest pain that worsens with deep breaths"}, {"id": "b", "text": "Jaw and ear pain that worsens with chewing"}, {"id": "c", "text": "Lower back pain that worsens with walking"}, {"id": "d", "text": "Hand pain that worsens with gripping"}]'::jsonb, '["b"]', 'Mumps causes jaw and ear pain, especially with chewing, because the parotid glands are inflamed. Chest, back, and hand pain are not described findings.'),
  ('mumps', 3, 'A nurse is planning meals for a 6-year-old child hospitalized with mumps. Which food choice is most appropriate?', '[{"id": "a", "text": "Raw carrot sticks"}, {"id": "b", "text": "A chewy bagel"}, {"id": "c", "text": "Mashed potatoes"}, {"id": "d", "text": "Hard pretzels"}]'::jsonb, '["c"]', 'A soft diet that avoids chewing is recommended because chewing worsens jaw and ear pain. Raw carrots, bagels, and pretzels all require significant chewing.'),
  ('mumps', 4, 'A child with mumps is admitted to the pediatric unit. Which type of transmission-based precautions should the nurse implement?', '[{"id": "a", "text": "Airborne precautions in a negative-pressure room"}, {"id": "b", "text": "Contact precautions only"}, {"id": "c", "text": "Standard precautions only"}, {"id": "d", "text": "Droplet precautions"}]'::jsonb, '["d"]', 'Mumps is spread by droplet transmission and requires droplet precautions. Airborne precautions are not what is indicated for mumps.'),
  ('mumps', 5, 'A nurse is about to assess the parotid glands of a client on droplet precautions for mumps. Which statement about masks is correct?', '[{"id": "a", "text": "A surgical mask is worn when within 3 to 6 feet of the client"}, {"id": "b", "text": "No mask is needed if the nurse stays within 3 feet"}, {"id": "c", "text": "A mask is needed only when more than 6 feet away"}, {"id": "d", "text": "A mask is needed only if the client is actively vomiting"}]'::jsonb, '["a"]', 'Droplet precautions for mumps call for a surgical mask within 3 to 6 feet of the client. Going without a mask at close range is unsafe because mumps spreads by respiratory droplets.'),
  ('mumps', 6, 'The parent of a child with mumps asks when the child can return to school. Which response by the nurse is correct?', '[{"id": "a", "text": "\"When the swelling is completely gone.\""}, {"id": "b", "text": "\"Five days after the parotid swelling began.\""}, {"id": "c", "text": "\"Twenty-four hours after the fever breaks.\""}, {"id": "d", "text": "\"Fourteen days after the exposure occurred.\""}]'::jsonb, '["b"]', 'Clients with mumps are isolated for 5 days after the onset of parotid swelling. Fever resolution is not the criterion for ending isolation.'),
  ('mumps', 7, 'A nurse is teaching a community group about the contagious period of mumps. Which statement should the nurse include?', '[{"id": "a", "text": "\"It is contagious only while the fever lasts.\""}, {"id": "b", "text": "\"It is contagious only after the swelling resolves.\""}, {"id": "c", "text": "\"It is contagious from 2 days before to 5 days after swelling begins.\""}, {"id": "d", "text": "\"It is contagious from 2 weeks before swelling until 2 weeks after.\""}]'::jsonb, '["c"]', 'Mumps is contagious from 2 days before to 5 days after parotid swelling. The contagious period does not depend on fever, and it does not extend for weeks.'),
  ('mumps', 8, 'A parent learns that a child in their son''s class has mumps. The parent asks how long it would take for symptoms to appear if the son was infected. Which response is accurate?', '[{"id": "a", "text": "\"Usually within 1 to 2 days.\""}, {"id": "b", "text": "\"Usually within 5 to 7 days.\""}, {"id": "c", "text": "\"Usually about 6 weeks.\""}, {"id": "d", "text": "\"Usually 16 to 18 days.\""}]'::jsonb, '["d"]', 'The incubation period for mumps is 16 to 18 days. Shorter windows of 1 to 7 days do not match this incubation period.'),
  ('mumps', 9, 'A 17-year-old male client with mumps reports new pain and swelling of the testes. The nurse recognizes this finding as which complication?', '[{"id": "a", "text": "Orchitis"}, {"id": "b", "text": "Pancreatitis"}, {"id": "c", "text": "Oophoritis"}, {"id": "d", "text": "Parotitis"}]'::jsonb, '["a"]', 'Orchitis is the most serious complication in post-pubertal males with mumps and is managed with scrotal support. Oophoritis is the corresponding complication in females.'),
  ('mumps', 10, 'The parents of a 16-year-old male with mumps orchitis ask about long-term concerns. The nurse explains that this complication can lead to which outcome?', '[{"id": "a", "text": "Oophoritis"}, {"id": "b", "text": "Infertility"}, {"id": "c", "text": "Pancreatitis"}, {"id": "d", "text": "Dysphagia"}]'::jsonb, '["b"]', 'Orchitis in post-pubertal males can cause infertility. Oophoritis is a separate complication that occurs in females.'),
  ('mumps', 11, 'A post-pubertal male client with mumps develops orchitis. Which comfort measure should the nurse include in the plan of care?', '[{"id": "a", "text": "Encourage chewing gum to relax the jaw"}, {"id": "b", "text": "Restrict oral fluids to limit swelling"}, {"id": "c", "text": "Provide scrotal support"}, {"id": "d", "text": "Encourage vigorous daily exercise"}]'::jsonb, '["c"]', 'Scrotal support is part of supportive treatment for orchitis. Chewing should be avoided, and rest and fluids are encouraged rather than restricted.'),
  ('mumps', 12, 'A nurse in a college health clinic sees four clients with mumps. Which client is at greatest risk for the most serious male complication of mumps?', '[{"id": "a", "text": "A 4-year-old boy"}, {"id": "b", "text": "A 6-year-old girl"}, {"id": "c", "text": "A 30-year-old woman"}, {"id": "d", "text": "A 19-year-old man"}]'::jsonb, '["d"]', 'Orchitis is most serious in post-pubertal males. A 4-year-old boy is not yet post-pubertal.'),
  ('mumps', 13, 'A 20-year-old female client is diagnosed with mumps. Which complication specific to females should the nurse be aware of?', '[{"id": "a", "text": "Oophoritis"}, {"id": "b", "text": "Orchitis"}, {"id": "c", "text": "Parotitis"}, {"id": "d", "text": "Cataracts"}]'::jsonb, '["a"]', 'Oophoritis is the complication of mumps listed for females. Orchitis is the corresponding complication in males.'),
  ('mumps', 14, 'A nurse is teaching the parent of a child recovering from mumps. Which finding should the parent be told to report because it may indicate a permanent complication?', '[{"id": "a", "text": "Mild jaw tenderness when chewing"}, {"id": "b", "text": "Trouble hearing in one or both ears"}, {"id": "c", "text": "Tiredness and general malaise"}, {"id": "d", "text": "Less interest in crunchy foods"}]'::jsonb, '["b"]', 'Sensorineural hearing loss is a permanent complication of mumps. Jaw tenderness with chewing and malaise are expected symptoms of the illness.'),
  ('mumps', 15, 'A nurse is reviewing complications of mumps with a nursing student. Which statement by the student is accurate?', '[{"id": "a", "text": "\"Hearing loss from mumps is always temporary.\""}, {"id": "b", "text": "\"Orchitis is most serious in young boys.\""}, {"id": "c", "text": "\"Mumps can cause pancreatitis.\""}, {"id": "d", "text": "\"Encephalitis is the most frequent complication.\""}]'::jsonb, '["c"]', 'Pancreatitis is a listed complication of mumps. Hearing loss from mumps is permanent, orchitis is most serious in post-pubertal males, and encephalitis is rare.'),
  ('mumps', 16, 'A provider makes an initial diagnosis of mumps in an unvaccinated child without waiting for laboratory results. On which findings is this clinical diagnosis based?', '[{"id": "a", "text": "A rash that started on the trunk"}, {"id": "b", "text": "Joint pain in the hands and knees"}, {"id": "c", "text": "Lesions in several stages of healing"}, {"id": "d", "text": "Parotid swelling and an exposure history"}]'::jsonb, '["d"]', 'Mumps is diagnosed clinically by parotid swelling plus exposure history. Rash and joint pain are not the basis of the clinical diagnosis.'),
  ('mumps', 17, 'A provider orders a viral culture for a child with suspected mumps. Which specimen should the nurse expect to collect?', '[{"id": "a", "text": "Saliva"}, {"id": "b", "text": "Stool"}, {"id": "c", "text": "Vesicle fluid"}, {"id": "d", "text": "Sputum for bacteria"}]'::jsonb, '["a"]', 'Mumps can be diagnosed by viral culture from saliva. Stool and vesicle fluid are not the specimens used for the mumps viral culture.'),
  ('mumps', 18, 'A child with parotid swelling has a positive serum IgM antibody result for mumps. How should the nurse interpret this result?', '[{"id": "a", "text": "The child has immunity from past vaccination"}, {"id": "b", "text": "The child has an acute mumps infection"}, {"id": "c", "text": "The child does not have a current infection"}, {"id": "d", "text": "The child needs passive immunization now"}]'::jsonb, '["b"]', 'Serum IgM antibody indicates acute mumps infection. Passive immunization is not available for mumps.'),
  ('mumps', 19, 'A child has been clinically diagnosed with mumps. Which test should the nurse anticipate being used for confirmation?', '[{"id": "a", "text": "Repeated palpation of the parotid glands"}, {"id": "b", "text": "A detailed exposure history"}, {"id": "c", "text": "Polymerase chain reaction (PCR)"}, {"id": "d", "text": "Trending the fever over 3 days"}]'::jsonb, '["c"]', 'PCR is used to confirm the diagnosis. Parotid swelling and exposure history support the clinical diagnosis but do not confirm it.'),
  ('mumps', 20, 'The parent of a child with mumps asks which medicine will cure the infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"An antiviral pill will cure it within 2 days.\""}, {"id": "b", "text": "\"An antibiotic will shorten the illness.\""}, {"id": "c", "text": "\"An antibody injection will stop the infection.\""}, {"id": "d", "text": "\"Treatment is supportive, such as rest and fluids.\""}]'::jsonb, '["d"]', 'Treatment of mumps is supportive only, including rest, fluids, and pain and fever relief. Passive immunization with antibodies is not available.'),
  ('mumps', 21, 'A child with mumps has a fever and painful parotid swelling. Which medication should the nurse anticipate for these symptoms?', '[{"id": "a", "text": "Acetaminophen or ibuprofen"}, {"id": "b", "text": "An oral antibiotic"}, {"id": "c", "text": "An immune globulin injection"}, {"id": "d", "text": "An extra dose of MMR vaccine"}]'::jsonb, '["a"]', 'Acetaminophen or ibuprofen is used for pain and fever in mumps. Treatment is supportive, and no passive immunization is available.'),
  ('mumps', 22, 'A nurse is caring for a child with swollen, tender parotid glands from mumps. Which comfort measure is appropriate?', '[{"id": "a", "text": "Offer chewing gum to loosen the jaw"}, {"id": "b", "text": "Apply ice packs or warm compresses to the parotid area"}, {"id": "c", "text": "Apply scrotal support for gland pain"}, {"id": "d", "text": "Limit fluids until the swelling subsides"}]'::jsonb, '["b"]', 'Ice packs or warm compresses on the parotid area are supportive measures for mumps. Chewing should be avoided, and fluids are encouraged.'),
  ('mumps', 23, 'A nurse provides home-care teaching to the parent of a 7-year-old child with mumps. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep my child home for 5 days after the swelling began.\""}, {"id": "b", "text": "\"I''ll offer soft foods like yogurt and soup.\""}, {"id": "c", "text": "\"I''ll give gum to chew so the jaw stays loose.\""}, {"id": "d", "text": "\"I''ll put an ice pack on the swollen area.\""}]'::jsonb, '["c"]', 'A soft diet that avoids chewing is recommended, so chewing gum is inappropriate. Isolation for 5 days after swelling, soft foods, and ice packs are correct.'),
  ('mumps', 24, 'A nurse is teaching the parent of a child with mumps about general care at home. Which instruction is appropriate?', '[{"id": "a", "text": "\"Limit fluids to reduce the gland swelling.\""}, {"id": "b", "text": "\"Your child may return to sports right away.\""}, {"id": "c", "text": "\"Give the leftover antibiotics from last year.\""}, {"id": "d", "text": "\"Make sure your child rests and drinks plenty of fluids.\""}]'::jsonb, '["d"]', 'Supportive treatment for mumps includes rest and fluids. Restricting fluids contradicts this supportive care.'),
  ('mumps', 25, 'A nurse is teaching a parent about the MMR vaccine at a 12-month well-child visit. Which statement by the parent indicates understanding?', '[{"id": "a", "text": "\"MMR contains a live but weakened virus.\""}, {"id": "b", "text": "\"MMR contains only a killed virus.\""}, {"id": "c", "text": "\"MMR is given as a single lifetime dose.\""}, {"id": "d", "text": "\"MMR is an antibody shot given after exposure.\""}]'::jsonb, '["a"]', 'The MMR vaccine is a live attenuated virus vaccine given in 2 doses. It is not a killed vaccine or a passive antibody product.'),
  ('mumps', 26, 'The parent of a 1-year-old child asks when the child should receive the MMR vaccine. Which schedule should the nurse describe?', '[{"id": "a", "text": "One dose at birth and one at 6 months"}, {"id": "b", "text": "One dose at 12–15 months and one at 4–6 years"}, {"id": "c", "text": "One dose at 2 months and one at 12 months"}, {"id": "d", "text": "One dose at 10 years and one at 18 years"}]'::jsonb, '["b"]', 'MMR dose 1 is given at 12 to 15 months and dose 2 at 4 to 6 years. The other schedules do not match these ages.'),
  ('mumps', 27, 'Before giving the first MMR dose to a 15-month-old child, the nurse reviews the health record. Which finding requires the nurse to hold the vaccine?', '[{"id": "a", "text": "The child is 15 months old"}, {"id": "b", "text": "The child has never received MMR"}, {"id": "c", "text": "The child is immunocompromised from current therapy"}, {"id": "d", "text": "The child attends a group day care"}]'::jsonb, '["c"]', 'The MMR vaccine is live and is contraindicated in immunocompromised clients. Being 15 months old with no prior dose is consistent with the routine schedule.'),
  ('mumps', 28, 'An unvaccinated 5-year-old child was exposed to mumps at a family gathering. The parent asks whether the child can get an antibody injection to prevent illness. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, an antibody shot within 6 days will prevent it.\""}, {"id": "b", "text": "\"Yes, but only if given within 72 hours.\""}, {"id": "c", "text": "\"Yes, it is given once the swelling starts.\""}, {"id": "d", "text": "\"No, passive immunization is not available for mumps.\""}]'::jsonb, '["d"]', 'No passive immunization is available for mumps. The MMR vaccine is the preventive measure for mumps.'),
  ('mumps', 29, 'A school nurse is reviewing a mumps outbreak. Which group is most commonly affected by mumps?', '[{"id": "a", "text": "Unvaccinated children and young adults"}, {"id": "b", "text": "Older adults who received two MMR doses"}, {"id": "c", "text": "School-age children who are fully vaccinated"}, {"id": "d", "text": "Adults with prior documented mumps infection"}]'::jsonb, '["a"]', 'Mumps is most common in unvaccinated children and young adults. Fully vaccinated individuals are not the group most commonly affected.'),
  ('mumps', 30, 'The parent of a child with mumps asks how the illness is spread. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Through contact with infected blood.\""}, {"id": "b", "text": "\"Through respiratory droplets and saliva.\""}, {"id": "c", "text": "\"Through bites from infected insects.\""}, {"id": "d", "text": "\"Through contaminated swimming water.\""}]'::jsonb, '["b"]', 'Mumps spreads by droplet transmission of respiratory secretions and by direct contact with saliva. Blood, insects, and water are not described routes.'),
  ('mumps', 31, 'A child with mumps is being cared for at home with two siblings. Which instruction should the nurse give to reduce spread within the household?', '[{"id": "a", "text": "\"Cups can be shared once the fever is gone.\""}, {"id": "b", "text": "\"Siblings may share utensils during meals.\""}, {"id": "c", "text": "\"Do not let the siblings share cups or utensils.\""}, {"id": "d", "text": "\"Only contact with blood needs to be avoided.\""}]'::jsonb, '["c"]', 'Mumps spreads by direct contact with saliva, so cups and utensils should not be shared. Sharing items while the child is still contagious allows contact with saliva.'),
  ('mumps', 32, 'A nursing student asks what type of organism causes mumps. Which response by the nurse is correct?', '[{"id": "a", "text": "\"A bacterium that grows in the parotid gland.\""}, {"id": "b", "text": "\"A fungus that spreads through saliva.\""}, {"id": "c", "text": "\"A parasite carried by household pets.\""}, {"id": "d", "text": "\"A paramyxovirus, the same family as measles.\""}]'::jsonb, '["d"]', 'Mumps is caused by a paramyxovirus, the same family as measles. It is a viral, not bacterial, fungal, or parasitic, illness.'),
  ('mumps', 33, 'A nurse is assessing a child with early mumps. In addition to parotid swelling, which group of findings should the nurse expect?', '[{"id": "a", "text": "Fever, headache, malaise, and difficulty swallowing"}, {"id": "b", "text": "Itchy vesicles in several stages on the trunk"}, {"id": "c", "text": "Painless swelling of both hands and feet"}, {"id": "d", "text": "A bright red rash limited to the cheeks"}]'::jsonb, '["a"]', 'Mumps symptoms include fever, headache, malaise, and difficulty swallowing in addition to parotitis. A rash or hand and foot swelling is not described.'),
  ('mumps', 34, 'A nurse on a unit is caring for four clients with mumps. Which client should the nurse assess first?', '[{"id": "a", "text": "A 6-year-old with jaw pain when chewing"}, {"id": "b", "text": "A 17-year-old male with new testicular pain and swelling"}, {"id": "c", "text": "An 8-year-old with mild fever and malaise"}, {"id": "d", "text": "A 5-year-old asking for an ice pack for the cheek"}]'::jsonb, '["b"]', 'Orchitis is the main complication in post-pubertal males and can cause infertility, so new testicular pain needs prompt assessment. Jaw pain, mild fever, and malaise are expected symptoms.'),
  ('mumps', 35, 'A charge nurse is assigning a room to a child admitted with mumps. Which room assignment is most appropriate?', '[{"id": "a", "text": "A shared room with another febrile child"}, {"id": "b", "text": "An open bay bed next to the playroom"}, {"id": "c", "text": "A private room with droplet precautions"}, {"id": "d", "text": "A shared room with a child awaiting surgery"}]'::jsonb, '["c"]', 'A private room is preferred for mumps along with droplet precautions. Sharing a room exposes other children to droplet spread.'),
  ('mumps', 36, 'A nurse observes care being provided to a child with mumps on droplet precautions. Which action requires correction?', '[{"id": "a", "text": "A nurse puts on a surgical mask before examining the child"}, {"id": "b", "text": "A nurse keeps the child in a private room"}, {"id": "c", "text": "A nurse plans precautions for 5 days after swelling began"}, {"id": "d", "text": "A UAP bathes the child at the bedside without a mask"}]'::jsonb, '["d"]', 'A surgical mask is required within 3 to 6 feet of a client on droplet precautions, so bathing the child unmasked is unsafe. The other actions are correct.'),
  ('mumps', 37, 'A child''s parotid swelling began 3 days ago. The parent wants the child to return to school tomorrow. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Not yet; precautions continue until 5 days after the swelling started.\""}, {"id": "b", "text": "\"Yes; the child stopped being contagious once the swelling appeared.\""}, {"id": "c", "text": "\"Yes; the child can return once 3 days have passed.\""}, {"id": "d", "text": "\"Not yet; the child must stay home for 3 more weeks.\""}]'::jsonb, '["a"]', 'Droplet precautions continue for 5 days after swelling starts, so day 4 is too early. Contagiousness extends up to 5 days after swelling, not just until swelling appears.'),
  ('mumps', 38, 'A child''s parotid swelling began this morning. Two days ago, the child shared toys and snacks with a cousin. The parent asks whether the cousin was exposed. Which response is accurate?', '[{"id": "a", "text": "\"No, mumps spreads only after the swelling begins.\""}, {"id": "b", "text": "\"Yes, mumps is contagious 2 days before swelling begins.\""}, {"id": "c", "text": "\"No, mumps spreads only through blood contact.\""}, {"id": "d", "text": "\"Yes, but only if the cousin had a high fever then.\""}]'::jsonb, '["b"]', 'Mumps is contagious beginning 2 days before parotid swelling. It is not limited to the period after swelling appears.'),
  ('mumps', 39, 'An unvaccinated child was exposed to mumps 10 days ago and has no symptoms. The parent states, "We are past the danger point." Which response by the nurse is best?', '[{"id": "a", "text": "\"Correct; symptoms would have appeared within 5 days.\""}, {"id": "b", "text": "\"Correct; if no fever by now, illness will not occur.\""}, {"id": "c", "text": "\"Symptoms usually appear 16 to 18 days after exposure.\""}, {"id": "d", "text": "\"Symptoms usually appear 6 to 8 weeks after exposure.\""}]'::jsonb, '["c"]', 'The incubation period of mumps is 16 to 18 days, so a child 10 days after exposure may still become ill. A 5-day window is much shorter than the incubation period.'),
  ('mumps', 40, 'A child who had mumps has been diagnosed with sensorineural hearing loss. The parent asks whether hearing will return. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Hearing returns once the parotid swelling resolves.\""}, {"id": "b", "text": "\"Hearing returns after the 5-day isolation period.\""}, {"id": "c", "text": "\"Hearing returns once the fever is controlled.\""}, {"id": "d", "text": "\"Hearing loss from mumps can be permanent.\""}]'::jsonb, '["d"]', 'Sensorineural hearing loss is a permanent complication of mumps. It does not resolve with the swelling, isolation period, or fever.'),
  ('mumps', 41, 'A nursing student asks how often encephalitis occurs as a complication of mumps. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is a rare complication.\""}, {"id": "b", "text": "\"It is the most common complication.\""}, {"id": "c", "text": "\"It occurs only in females.\""}, {"id": "d", "text": "\"It occurs in every adult case.\""}]'::jsonb, '["a"]', 'Encephalitis is listed as a rare complication of mumps. Orchitis, not encephalitis, is the main complication in post-pubertal males.'),
  ('mumps', 42, 'A client who is 12 weeks pregnant tells the nurse she never received the MMR vaccine and wants it today to avoid catching mumps. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"You can receive it today since you are past 10 weeks.\""}, {"id": "b", "text": "\"MMR is a live vaccine, so it is not given in pregnancy.\""}, {"id": "c", "text": "\"You should get two doses today for full protection.\""}, {"id": "d", "text": "\"An antibody shot can be given instead today.\""}]'::jsonb, '["b"]', 'MMR is a live vaccine and should be avoided in pregnancy. Passive immunization is not available for mumps, so an antibody shot is not an alternative.'),
  ('mumps', 43, 'A nurse teaches the parent of a 13-month-old child about the MMR vaccine. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"My child will get the first dose now.\""}, {"id": "b", "text": "\"My child will get a second dose between 4 and 6 years.\""}, {"id": "c", "text": "\"My child only needs this one MMR shot for life.\""}, {"id": "d", "text": "\"This vaccine helps protect my child from mumps.\""}]'::jsonb, '["c"]', 'MMR is given as 2 doses: the first at 12 to 15 months and the second at 4 to 6 years. A single lifetime dose is incorrect.'),
  ('mumps', 44, 'A parent says, "My child''s swelling is only on the left side, so it can''t be mumps." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Correct; mumps always swells both sides equally.\""}, {"id": "b", "text": "\"Correct; mumps swelling occurs only in the neck.\""}, {"id": "c", "text": "\"Correct; one-sided swelling rules out mumps.\""}, {"id": "d", "text": "\"Mumps can swell one or both parotid glands.\""}]'::jsonb, '["d"]', 'Parotitis in mumps involves painful swelling of one or both parotid glands. One-sided swelling does not rule out mumps.'),
  ('mumps', 45, 'The parent of a child with mumps asks what is causing the swelling in front of the ear. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The virus is inflaming the parotid salivary glands.\""}, {"id": "b", "text": "\"The virus is causing a bacterial skin abscess.\""}, {"id": "c", "text": "\"The virus is enlarging the thyroid gland.\""}, {"id": "d", "text": "\"The virus is causing fluid to collect in the jaw bone.\""}]'::jsonb, '["a"]', 'Mumps affects the parotid (salivary) glands, causing parotitis. It is not described as affecting the thyroid or causing a bacterial abscess.'),
  ('mumps', 46, 'A child with mumps received acetaminophen 1 hour ago for fever and parotid pain. Which finding best indicates the medication has been effective?', '[{"id": "a", "text": "The parotid swelling is completely gone"}, {"id": "b", "text": "The child reports less jaw pain and feels cooler"}, {"id": "c", "text": "The child is now able to chew hard foods"}, {"id": "d", "text": "The serum IgM antibody test is now negative"}]'::jsonb, '["b"]', 'Acetaminophen is given for pain and fever, so decreased pain and fever show effectiveness. It is a supportive measure and is not expected to eliminate the swelling.'),
  ('mumps', 47, 'A nurse is obtaining a history from the parent of a child with new parotid swelling and fever. Which question is most relevant to the clinical diagnosis of mumps?', '[{"id": "a", "text": "\"Has your child eaten any new foods lately?\""}, {"id": "b", "text": "\"Does anyone in the family have diabetes?\""}, {"id": "c", "text": "\"Has your child been around anyone with mumps?\""}, {"id": "d", "text": "\"Has your child had any recent dental work?\""}]'::jsonb, '["c"]', 'The clinical diagnosis of mumps is based on parotid swelling plus exposure history. The other questions do not address the exposure history.'),
  ('mumps', 48, 'A child with mumps has difficulty swallowing and has been drinking poorly. Which nursing action is most appropriate?', '[{"id": "a", "text": "Hold all fluids until swallowing improves"}, {"id": "b", "text": "Offer crunchy snacks to stimulate the appetite"}, {"id": "c", "text": "Encourage chewing gum to ease swallowing"}, {"id": "d", "text": "Offer fluids and soft foods frequently"}]'::jsonb, '["d"]', 'Dysphagia is a symptom of mumps, and supportive care includes fluids and a soft diet that avoids chewing. Holding fluids contradicts supportive care.'),
  ('mumps', 49, 'A nurse is reviewing neurologic complications of mumps with a group of nursing students. Which complications should the nurse include?', '[{"id": "a", "text": "Viral (aseptic) meningitis and encephalitis"}, {"id": "b", "text": "Cataracts and glaucoma"}, {"id": "c", "text": "Subacute sclerosing panencephalitis and croup"}, {"id": "d", "text": "Corneal ulcers and blindness"}]'::jsonb, '["a"]', 'Viral or aseptic meningitis and rare encephalitis are listed neurologic complications of mumps. The other conditions are not listed as mumps complications.'),
  ('mumps', 50, 'A nurse is evaluating a nursing student''s understanding of mumps. Which statement by the student is correct?', '[{"id": "a", "text": "\"Mumps requires an N95 and a negative-pressure room.\""}, {"id": "b", "text": "\"Mumps spreads by droplets and is prevented by MMR.\""}, {"id": "c", "text": "\"Mumps is routinely treated with antiviral medication.\""}, {"id": "d", "text": "\"Mumps can be prevented by an antibody shot after exposure.\""}]'::jsonb, '["b"]', 'Mumps is spread by droplet transmission and is preventable with the MMR vaccine. Treatment is supportive only, and no passive immunization is available.'),
  ('rubella', 1, 'A nurse is assessing a 5-year-old child with suspected rubella. Where should the nurse expect to find enlarged lymph nodes?', '[{"id": "a", "text": "Behind the ears and at the back of the neck"}, {"id": "b", "text": "In the groin on both sides"}, {"id": "c", "text": "In the axillae on both sides"}, {"id": "d", "text": "Above the elbows on both arms"}]'::jsonb, '["a"]', 'Rubella causes postauricular and suboccipital lymphadenopathy, meaning nodes behind the ears and neck. Groin and axillary nodes are not part of the classic triad.'),
  ('rubella', 2, 'A nurse is assessing the rash of a child with rubella. Which rash pattern should the nurse expect?', '[{"id": "a", "text": "Vesicles that begin on the trunk and spread outward"}, {"id": "b", "text": "A maculopapular rash that begins on the face and spreads downward"}, {"id": "c", "text": "Lesions in all stages of healing at the same time"}, {"id": "d", "text": "A rash that begins on the soles and spreads upward"}]'::jsonb, '["b"]', 'The rubella rash is maculopapular, begins on the face, spreads downward, and lasts 3 days. A rash that starts on the feet reverses this direction.'),
  ('rubella', 3, 'The parent of a child with rubella asks how long the rash will last. Which response by the nurse is correct?', '[{"id": "a", "text": "\"About 3 weeks.\""}, {"id": "b", "text": "\"About 10 days.\""}, {"id": "c", "text": "\"About 3 days.\""}, {"id": "d", "text": "\"About 6 weeks.\""}]'::jsonb, '["c"]', 'Rubella is called 3-day measles because the rash lasts about 3 days. Longer durations do not match this description.'),
  ('rubella', 4, 'A nurse is assessing a 6-year-old child with rubella. Which type of fever should the nurse expect?', '[{"id": "a", "text": "A very high fever lasting for weeks"}, {"id": "b", "text": "No fever at any point in the illness"}, {"id": "c", "text": "A fever that returns every 3 days"}, {"id": "d", "text": "A low-grade fever"}]'::jsonb, '["d"]', 'A low-grade fever is part of the classic rubella triad along with the rash and postauricular and suboccipital lymphadenopathy. A very high, prolonged fever does not fit.'),
  ('rubella', 5, 'A 28-year-old woman diagnosed with rubella reports aching in several joints. How should the nurse interpret this finding?', '[{"id": "a", "text": "Joint pain is an associated finding, especially in adult women"}, {"id": "b", "text": "Joint pain indicates congenital rubella syndrome"}, {"id": "c", "text": "Joint pain means a second infection is present"}, {"id": "d", "text": "Joint pain is unrelated because rubella affects only skin"}]'::jsonb, '["a"]', 'Arthralgia is an associated rubella finding, especially in adult women. Congenital rubella syndrome affects the fetus, not the infected adult.'),
  ('rubella', 6, 'A child with rubella is admitted to the hospital. Which type of transmission-based precautions should the nurse implement?', '[{"id": "a", "text": "Contact precautions only"}, {"id": "b", "text": "Droplet precautions"}, {"id": "c", "text": "Standard precautions only"}, {"id": "d", "text": "Precautions only for blood exposure"}]'::jsonb, '["b"]', 'Rubella is transmitted by droplets from respiratory secretions and requires droplet precautions. Contact or standard precautions alone do not address droplet spread.'),
  ('rubella', 7, 'A hospitalized child developed a rubella rash yesterday. For how long should the nurse plan to maintain isolation?', '[{"id": "a", "text": "Until the fever has resolved"}, {"id": "b", "text": "For 3 days after the rash appeared"}, {"id": "c", "text": "For 7 days after the rash appeared"}, {"id": "d", "text": "For 21 days after the rash appeared"}]'::jsonb, '["c"]', 'Clients with rubella are isolated for 7 days after rash onset. Ending isolation when the 3-day rash fades is too early.'),
  ('rubella', 8, 'A nurse is teaching a community group about rubella. Which statement about the contagious period is accurate?', '[{"id": "a", "text": "\"It is contagious only while the rash is visible.\""}, {"id": "b", "text": "\"It is contagious only after the rash fades.\""}, {"id": "c", "text": "\"It is contagious only on the day the rash appears.\""}, {"id": "d", "text": "\"It is contagious from 7 days before to 7 days after the rash.\""}]'::jsonb, '["d"]', 'Rubella is contagious from 7 days before to 7 days after the rash. Spread is not limited to the time the rash is visible.'),
  ('rubella', 9, 'A parent reports that their child was exposed to rubella at a day-care center. The parent asks when symptoms would appear if the child was infected. Which response is accurate?', '[{"id": "a", "text": "\"Within 14 to 21 days of the exposure.\""}, {"id": "b", "text": "\"Within 1 to 3 days of the exposure.\""}, {"id": "c", "text": "\"Within 4 to 6 days of the exposure.\""}, {"id": "d", "text": "\"Within 2 to 3 months of the exposure.\""}]'::jsonb, '["a"]', 'The incubation period for rubella is 14 to 21 days. Symptoms within a few days would be far shorter than this incubation period.'),
  ('rubella', 10, 'A charge nurse is making assignments on a pediatric unit. Which nurse should NOT be assigned to care for a child with rubella?', '[{"id": "a", "text": "A nurse who recently returned from vacation"}, {"id": "b", "text": "A nurse who is 10 weeks pregnant"}, {"id": "c", "text": "A nurse who is a new graduate"}, {"id": "d", "text": "A nurse who also cares for a child with asthma"}]'::jsonb, '["b"]', 'Persons with rubella should be kept away from pregnant women because of the teratogenic effects, which are most severe early in pregnancy. The other nurses have no stated reason to avoid the assignment.'),
  ('rubella', 11, 'A child with rubella must be admitted to a hospital that also has a busy obstetric unit. Which room placement is most appropriate?', '[{"id": "a", "text": "A room next to the prenatal testing area"}, {"id": "b", "text": "A shared room on the antepartum unit"}, {"id": "c", "text": "A private room away from pregnant clients"}, {"id": "d", "text": "A bed in the labor and delivery triage area"}]'::jsonb, '["c"]', 'Rubella-infected persons should be kept away from pregnant patients and placed on droplet precautions. Placement near prenatal or antepartum areas exposes pregnant clients.'),
  ('rubella', 12, 'A pregnant client asks when during pregnancy rubella poses the greatest risk to the fetus. Which response by the nurse is correct?', '[{"id": "a", "text": "\"During the final 2 weeks before delivery.\""}, {"id": "b", "text": "\"Only during labor and birth.\""}, {"id": "c", "text": "\"Between 30 and 36 weeks of gestation.\""}, {"id": "d", "text": "\"Before 12 weeks of gestation.\""}]'::jsonb, '["d"]', 'Fetal damage is most severe with first-trimester infection, and risk is highest before 12 weeks gestation. Late pregnancy is not the period of highest risk.'),
  ('rubella', 13, 'A nurse is caring for an infant with congenital rubella syndrome (CRS). Which manifestation of CRS is the most common?', '[{"id": "a", "text": "Sensorineural deafness"}, {"id": "b", "text": "Congenital heart defects"}, {"id": "c", "text": "Cataracts"}, {"id": "d", "text": "Microcephaly"}]'::jsonb, '["a"]', 'Sensorineural deafness is the most common CRS manifestation. Cataracts are the classic eye finding but not the most common manifestation overall.'),
  ('rubella', 14, 'A nurse is examining a newborn whose mother had rubella in the first trimester. Which eye finding is classically associated with congenital rubella syndrome?', '[{"id": "a", "text": "Conjunctivitis"}, {"id": "b", "text": "Cataracts"}, {"id": "c", "text": "A stye on the eyelid"}, {"id": "d", "text": "Eyelid swelling"}]'::jsonb, '["b"]', 'Cataracts are the classic eye finding in congenital rubella syndrome. Conjunctivitis is a symptom of acute rubella in the infected person, not the classic CRS eye finding.'),
  ('rubella', 15, 'A nurse teaches the parents of a newborn with congenital rubella syndrome about the infant''s heart. Which statement by the parents indicates understanding?', '[{"id": "a", "text": "\"Heart problems do not occur with congenital rubella.\""}, {"id": "b", "text": "\"Rubella affects only our baby''s eyes and ears.\""}, {"id": "c", "text": "\"Patent ductus arteriosus is a heart defect seen with CRS.\""}, {"id": "d", "text": "\"Heart defects occur only with third-trimester infection.\""}]'::jsonb, '["c"]', 'Congenital heart defects in CRS include patent ductus arteriosus and pulmonary artery stenosis. Fetal damage is most severe with first-trimester, not third-trimester, infection.'),
  ('rubella', 16, 'A nursing student asks which three findings make up the classic triad of congenital rubella syndrome. Which response by the nurse is correct?', '[{"id": "a", "text": "Low fever, rash, and swollen neck nodes"}, {"id": "b", "text": "Arthralgia, conjunctivitis, and URI symptoms"}, {"id": "c", "text": "Glaucoma, microcephaly, and arthralgia"}, {"id": "d", "text": "Cataracts, deafness, and heart defects"}]'::jsonb, '["d"]', 'The CRS triad is cataracts, deafness, and congenital heart defects. Low fever, rash, and lymphadenopathy form the triad of acute rubella, not CRS.'),
  ('rubella', 17, 'A client who is 9 weeks pregnant calls the clinic reporting a low-grade fever, a rash on her face, and swollen glands behind her ears. Which action should the nurse take first?', '[{"id": "a", "text": "Report the suspected rubella to the provider immediately"}, {"id": "b", "text": "Schedule her for a routine visit next month"}, {"id": "c", "text": "Tell her to take a dose of MMR vaccine today"}, {"id": "d", "text": "Reassure her that rubella is a mild illness"}]'::jsonb, '["a"]', 'Any pregnant woman suspected of rubella should be reported immediately because fetal damage is most severe in the first trimester. MMR is contraindicated during pregnancy.'),
  ('rubella', 18, 'A nurse is assessing a newborn whose mother had rubella at 8 weeks of gestation. Which finding is consistent with congenital rubella syndrome?', '[{"id": "a", "text": "A larger-than-expected head size"}, {"id": "b", "text": "Microcephaly"}, {"id": "c", "text": "Swelling of the parotid glands"}, {"id": "d", "text": "Itchy vesicles in several stages"}]'::jsonb, '["b"]', 'Microcephaly and intellectual disability are manifestations of CRS. A larger-than-expected head reverses this finding.'),
  ('rubella', 19, 'A nurse is teaching parents about eye problems that can occur with congenital rubella syndrome. In addition to cataracts, which eye findings should the nurse include?', '[{"id": "a", "text": "Red, watery eyes from a cold"}, {"id": "b", "text": "Temporary eyelid swelling only"}, {"id": "c", "text": "Glaucoma and retinopathy"}, {"id": "d", "text": "Mild conjunctivitis only"}]'::jsonb, '["c"]', 'CRS findings include glaucoma and retinopathy as well as cataracts. Conjunctivitis is a symptom of acute rubella rather than a listed CRS eye finding.'),
  ('rubella', 20, 'A pregnant client with a recent rash has a positive rubella IgM antibody result. How should the nurse interpret this result?', '[{"id": "a", "text": "She is immune from a childhood vaccine"}, {"id": "b", "text": "She has never been exposed to rubella"}, {"id": "c", "text": "She needs MMR vaccine during this pregnancy"}, {"id": "d", "text": "She has a recent or current rubella infection"}]'::jsonb, '["d"]', 'Rubella IgM antibody indicates recent or current infection. Immunity from vaccine or past infection is indicated by the IgG titer.'),
  ('rubella', 21, 'At her first prenatal visit, a client has a positive rubella IgG titer. How should the nurse interpret this result?', '[{"id": "a", "text": "She is immune from vaccination or past infection"}, {"id": "b", "text": "She has an active rubella infection now"}, {"id": "c", "text": "She must be vaccinated during this pregnancy"}, {"id": "d", "text": "She must be isolated for 7 days"}]'::jsonb, '["a"]', 'The rubella IgG titer reflects immunity from vaccine or past infection. Current infection is indicated by IgM, not IgG.'),
  ('rubella', 22, 'A nurse is reviewing routine prenatal screening. When should a client''s rubella titer be checked?', '[{"id": "a", "text": "Only if the client develops a rash"}, {"id": "b", "text": "At the first prenatal visit"}, {"id": "c", "text": "At the 6-week postpartum visit"}, {"id": "d", "text": "Only during the third trimester"}]'::jsonb, '["b"]', 'Prenatal screening includes checking the rubella titer at the first prenatal visit. Waiting for a rash or until late pregnancy misses the screening window.'),
  ('rubella', 23, 'A client at her first prenatal visit is found to be non-immune to rubella. She asks when she can be vaccinated. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Today, before the pregnancy progresses.\""}, {"id": "b", "text": "\"During the second trimester, when it is safest.\""}, {"id": "c", "text": "\"After you deliver, during the postpartum period.\""}, {"id": "d", "text": "\"During labor, so the baby is protected.\""}]'::jsonb, '["c"]', 'Non-immune clients are vaccinated postpartum because the MMR vaccine is contraindicated in pregnancy. Vaccinating at any point during pregnancy is unsafe.'),
  ('rubella', 24, 'A postpartum client who was rubella non-immune receives the MMR vaccine before discharge. Which instruction should the nurse include?', '[{"id": "a", "text": "\"You may become pregnant again right away.\""}, {"id": "b", "text": "\"Avoid pregnancy for 7 days after the vaccine.\""}, {"id": "c", "text": "\"Avoid pregnancy until a second dose next year.\""}, {"id": "d", "text": "\"Avoid becoming pregnant for 28 days after the vaccine.\""}]'::jsonb, '["d"]', 'After MMR vaccination, pregnancy should be avoided for 28 days. A 7-day period is too short.'),
  ('rubella', 25, 'A nurse manager is reviewing care in a prenatal clinic. Which action by a staff nurse requires correction?', '[{"id": "a", "text": "Prepares MMR for a non-immune client at 20 weeks of gestation"}, {"id": "b", "text": "Checks the rubella titer at a client''s first prenatal visit"}, {"id": "c", "text": "Plans postpartum MMR for a client who is non-immune"}, {"id": "d", "text": "Teaches a client to avoid pregnancy for 28 days after MMR"}]'::jsonb, '["a"]', 'MMR must not be given during pregnancy; non-immune clients are vaccinated postpartum. The other actions follow recommended rubella screening and vaccination practices.'),
  ('rubella', 26, 'The parent of a child with rubella asks whether an antiviral medicine can be prescribed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, an antiviral will shorten the rash.\""}, {"id": "b", "text": "\"No, treatment is supportive and no antivirals are used.\""}, {"id": "c", "text": "\"Yes, but only after the rash has faded.\""}, {"id": "d", "text": "\"No, but antibiotics will be prescribed instead.\""}]'::jsonb, '["b"]', 'Rubella treatment is supportive only, with no antivirals. Supportive care includes acetaminophen, rest, and fluids.'),
  ('rubella', 27, 'A child with rubella has a fever and mild discomfort. Which medication should the nurse anticipate being recommended?', '[{"id": "a", "text": "An antiviral medication"}, {"id": "b", "text": "An MMR vaccine dose"}, {"id": "c", "text": "Acetaminophen"}, {"id": "d", "text": "An antibiotic"}]'::jsonb, '["c"]', 'Acetaminophen is used for fever and pain in rubella. Treatment is supportive only, without antivirals.'),
  ('rubella', 28, 'A nursing student asks what causes rubella. Which response by the nurse is correct?', '[{"id": "a", "text": "\"A bacterium spread through blood.\""}, {"id": "b", "text": "\"A fungus found in soil.\""}, {"id": "c", "text": "\"A parasite from undercooked food.\""}, {"id": "d", "text": "\"The rubella virus, a togavirus.\""}]'::jsonb, '["d"]', 'Rubella is caused by the rubella virus of the Togavirus family. It is a viral, not bacterial, fungal, or parasitic, illness.'),
  ('rubella', 29, 'The parent of a healthy 5-year-old child who received one MMR dose at 13 months asks whether another dose is needed. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes, the second dose is due between 4 and 6 years.\""}, {"id": "b", "text": "\"No, a single dose protects for life.\""}, {"id": "c", "text": "\"Yes, but not until the child is 18 years old.\""}, {"id": "d", "text": "\"No, the second dose is only for adults.\""}]'::jsonb, '["a"]', 'MMR dose 1 is given at 12 to 15 months and dose 2 at 4 to 6 years. A single dose does not complete the schedule.'),
  ('rubella', 30, 'A nurse is preparing MMR vaccinations in a clinic. Which client should NOT receive the vaccine?', '[{"id": "a", "text": "A non-immune client who delivered 2 days ago"}, {"id": "b", "text": "A client who is immunocompromised"}, {"id": "c", "text": "A healthy 12-month-old child"}, {"id": "d", "text": "A healthy 5-year-old child due for a dose"}]'::jsonb, '["b"]', 'MMR is contraindicated in immunocompromised clients. Non-immune postpartum clients are vaccinated, and healthy children follow the routine schedule.'),
  ('rubella', 31, 'A nurse is assessing four children with rashes. Which set of findings is most consistent with rubella?', '[{"id": "a", "text": "High fever, itchy vesicles, and crusted lesions"}, {"id": "b", "text": "Parotid swelling, jaw pain, and fever"}, {"id": "c", "text": "A 3-day rash, postauricular nodes, and low fever"}, {"id": "d", "text": "A rash lasting 3 weeks with no lymph nodes"}]'::jsonb, '["c"]', 'A 3-day rash, postauricular lymph nodes, and low fever indicate rubella. A rash lasting weeks without lymphadenopathy does not fit this pattern.'),
  ('rubella', 32, 'The parent of a toddler asks why the child needs a vaccine for rubella if the illness is mild. Which response by the nurse is best?', '[{"id": "a", "text": "\"Rubella often causes permanent joint damage in toddlers.\""}, {"id": "b", "text": "\"Rubella always causes very high fevers in children.\""}, {"id": "c", "text": "\"Rubella commonly causes deafness in the infected child.\""}, {"id": "d", "text": "\"Rubella can cause severe birth defects if a pregnant woman is infected.\""}]'::jsonb, '["d"]', 'Rubella is a mild viral illness but has devastating teratogenic effects in pregnancy. Deafness is a feature of congenital rubella syndrome in the fetus, not the infected child.'),
  ('rubella', 33, 'A client who is 8 weeks pregnant was exposed to rubella at work. She asks why the provider is so concerned about the timing. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Fetal damage is most severe when infection occurs in the first trimester.\""}, {"id": "b", "text": "\"Fetal damage occurs only if infection happens near delivery.\""}, {"id": "c", "text": "\"Infection early in pregnancy affects only the mother.\""}, {"id": "d", "text": "\"The timing matters only if you have already had the vaccine.\""}]'::jsonb, '["a"]', 'If rubella is contracted in the first trimester, fetal damage is most severe. Infection early in pregnancy is not limited to maternal effects.'),
  ('rubella', 34, 'In addition to the classic triad, which findings should the nurse expect in a child with rubella?', '[{"id": "a", "text": "Intense itching and crusted skin lesions"}, {"id": "b", "text": "Conjunctivitis and mild upper respiratory symptoms"}, {"id": "c", "text": "Painful swelling of the parotid glands"}, {"id": "d", "text": "High fever lasting for several weeks"}]'::jsonb, '["b"]', 'Rubella may also cause arthralgia, conjunctivitis, and mild URI symptoms. Rubella fever is low-grade, not high and prolonged.'),
  ('rubella', 35, 'A prenatal clinic nurse is returning four phone calls. Which call should the nurse return first?', '[{"id": "a", "text": "A client at 30 weeks asking about the glucose test"}, {"id": "b", "text": "A client at 22 weeks asking about prenatal vitamins"}, {"id": "c", "text": "A client at 9 weeks with a facial rash and nodes behind her ears"}, {"id": "d", "text": "A client at 36 weeks asking about car seat installation"}]'::jsonb, '["c"]', 'A rash with postauricular nodes suggests rubella, and any pregnant woman suspected of rubella should be reported immediately, especially in the first trimester. The other calls are routine.'),
  ('rubella', 36, 'A charge nurse observes staff caring for a child with rubella. Which action by an unlicensed assistive personnel (UAP) requires correction?', '[{"id": "a", "text": "Keeps the child on droplet precautions"}, {"id": "b", "text": "Keeps the child in a private room"}, {"id": "c", "text": "Reports the child''s temperature to the nurse"}, {"id": "d", "text": "Walks the child through the prenatal clinic waiting room"}]'::jsonb, '["d"]', 'Persons with rubella must be kept away from pregnant women, so walking through a prenatal waiting room is unsafe. Droplet precautions and a private room are appropriate.'),
  ('rubella', 37, 'A child hospitalized with rubella had a rash onset 4 days ago, and the rash has now faded. A staff nurse suggests discontinuing droplet precautions today. Which response by the charge nurse is correct?', '[{"id": "a", "text": "\"Not yet; precautions continue for 7 days after the rash began.\""}, {"id": "b", "text": "\"Yes; the child is no longer contagious once the rash fades.\""}, {"id": "c", "text": "\"Yes; precautions may stop once the fever is gone.\""}, {"id": "d", "text": "\"Not yet; precautions continue for 21 more days.\""}]'::jsonb, '["a"]', 'Droplet precautions continue for 7 days after rash onset, so day 5 is too early. The child remains contagious up to 7 days after the rash, even after it fades.'),
  ('rubella', 38, 'A public health nurse is tracing contacts of a child whose rubella rash began on Monday. Which contacts should the nurse include as possible exposures?', '[{"id": "a", "text": "Only people seen after the rash began"}, {"id": "b", "text": "People seen from 7 days before the rash onward"}, {"id": "c", "text": "Only people seen on the day the rash began"}, {"id": "d", "text": "Only people seen during the past 24 hours"}]'::jsonb, '["b"]', 'Rubella is contagious from 7 days before to 7 days after the rash, so contacts in the week before the rash are exposures. Limiting tracing to after the rash misses the pre-rash contagious period.'),
  ('rubella', 39, 'A nurse in an urgent care clinic sees four clients with confirmed rubella. Which client is most likely to report joint pain?', '[{"id": "a", "text": "A 2-year-old boy"}, {"id": "b", "text": "A 7-year-old girl"}, {"id": "c", "text": "A 30-year-old woman"}, {"id": "d", "text": "A 10-year-old boy"}]'::jsonb, '["c"]', 'Arthralgia occurs in rubella especially in adult women. The young children are not the group in which arthralgia is especially noted.'),
  ('rubella', 40, 'An infant is suspected of having congenital rubella syndrome. Based on the most common manifestation of CRS, which screening is a priority?', '[{"id": "a", "text": "Screening for joint pain"}, {"id": "b", "text": "Screening for parotid swelling"}, {"id": "c", "text": "Screening for skin vesicles"}, {"id": "d", "text": "Screening of hearing"}]'::jsonb, '["d"]', 'Sensorineural deafness is the most common CRS manifestation, making hearing screening a priority. Joint pain is a feature of acute rubella in adult women, not CRS.'),
  ('rubella', 41, 'A nurse is evaluating a nursing student''s understanding of congenital rubella syndrome. Which statement by the student is accurate?', '[{"id": "a", "text": "\"Cataracts are the classic eye finding.\""}, {"id": "b", "text": "\"Deafness is a rare manifestation.\""}, {"id": "c", "text": "\"Risk is highest in the third trimester.\""}, {"id": "d", "text": "\"Heart defects are not part of CRS.\""}]'::jsonb, '["a"]', 'Cataracts are the classic eye finding of CRS. Deafness is the most common manifestation, risk is highest before 12 weeks, and heart defects are part of the CRS triad.'),
  ('rubella', 42, 'The parents of an infant with congenital rubella syndrome ask whether the condition can affect brain development. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"CRS affects only the eyes and ears.\""}, {"id": "b", "text": "\"CRS can include microcephaly and intellectual disability.\""}, {"id": "c", "text": "\"CRS affects only the heart.\""}, {"id": "d", "text": "\"CRS brain effects occur only with third-trimester infection.\""}]'::jsonb, '["b"]', 'CRS can include microcephaly and intellectual disability, along with eye, ear, and heart defects. Fetal damage is most severe with first-trimester infection, not third-trimester infection.'),
  ('rubella', 43, 'A nurse is preparing a postpartum client for discharge. Her prenatal record shows she is not immune to rubella. Which action should the nurse take?', '[{"id": "a", "text": "Plan to vaccinate her early in her next pregnancy"}, {"id": "b", "text": "Tell her immunity matters only while pregnant"}, {"id": "c", "text": "Ensure the MMR vaccine is given before discharge as prescribed"}, {"id": "d", "text": "Recheck her titer at the first visit of her next pregnancy"}]'::jsonb, '["c"]', 'Clients with a negative rubella titer are vaccinated postpartum. Vaccinating during a future pregnancy is contraindicated.'),
  ('rubella', 44, 'A pregnant client was exposed to rubella. Which laboratory test would indicate a current infection rather than prior immunity?', '[{"id": "a", "text": "Rubella IgG titer"}, {"id": "b", "text": "Rubella vaccine record"}, {"id": "c", "text": "Prenatal immunity screen"}, {"id": "d", "text": "Rubella IgM antibody"}]'::jsonb, '["d"]', 'Rubella IgM antibody indicates recent or current infection, while the IgG titer reflects immunity from vaccine or past infection.'),
  ('rubella', 45, 'A nurse teaches a postpartum client who just received the MMR vaccine. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I can stop using birth control in 2 weeks.\""}, {"id": "b", "text": "\"I need to avoid pregnancy for 28 days.\""}, {"id": "c", "text": "\"This vaccine will help protect future pregnancies.\""}, {"id": "d", "text": "\"I received it because my titer showed I wasn''t immune.\""}]'::jsonb, '["a"]', 'Pregnancy should be avoided for 28 days after MMR vaccination, so stopping contraception after 2 weeks is unsafe. Postpartum vaccination is given to clients who are non-immune.'),
  ('rubella', 46, 'A nurse is planning home care for a 4-year-old child with uncomplicated rubella. Which plan is most appropriate?', '[{"id": "a", "text": "Give an antiviral medication twice daily"}, {"id": "b", "text": "Provide rest, fluids, and acetaminophen"}, {"id": "c", "text": "Give an MMR dose to stop the infection"}, {"id": "d", "text": "Give an antibiotic to prevent CRS"}]'::jsonb, '["b"]', 'Rubella treatment is supportive only, including acetaminophen, rest, and fluids, with no antivirals.'),
  ('rubella', 47, 'A nurse is documenting the rash of a child with confirmed rubella. Which documentation is consistent with this diagnosis?', '[{"id": "a", "text": "Vesicular rash that started on the trunk"}, {"id": "b", "text": "Rash that started on the feet and moved upward"}, {"id": "c", "text": "Maculopapular rash that started on the face and spread downward"}, {"id": "d", "text": "Rash that has persisted for the past 3 weeks"}]'::jsonb, '["c"]', 'The rubella rash is maculopapular, begins on the face, spreads downward, and lasts about 3 days. A rash persisting for weeks or starting on the feet is inconsistent.'),
  ('rubella', 48, 'The parent of a child with rubella asks how the illness spreads to others. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Through contact with infected blood.\""}, {"id": "b", "text": "\"Through bites from mosquitoes.\""}, {"id": "c", "text": "\"Through contaminated drinking water.\""}, {"id": "d", "text": "\"Through droplets from respiratory secretions.\""}]'::jsonb, '["d"]', 'Rubella is transmitted by droplets from respiratory secretions, which is why droplet precautions are used. Blood, mosquitoes, and water are not described routes.'),
  ('rubella', 49, 'A child with rubella is being discharged home. The parent mentions that a pregnant aunt plans to visit this week. Which instruction by the nurse is most important?', '[{"id": "a", "text": "\"Keep your child away from the pregnant aunt during the contagious period.\""}, {"id": "b", "text": "\"The visit is safe once your child''s fever is gone.\""}, {"id": "c", "text": "\"The visit is safe if your child wears a bandage over the rash.\""}, {"id": "d", "text": "\"The aunt should receive the MMR vaccine before she visits.\""}]'::jsonb, '["a"]', 'Rubella-infected persons should be kept away from pregnant patients because of teratogenic effects. MMR is contraindicated during pregnancy, so vaccinating the aunt is not appropriate.'),
  ('rubella', 50, 'A newborn is diagnosed with cataracts, sensorineural deafness, and patent ductus arteriosus. Which maternal history is most consistent with these findings?', '[{"id": "a", "text": "MMR vaccination after a previous delivery"}, {"id": "b", "text": "Rubella infection during the first trimester"}, {"id": "c", "text": "A positive rubella IgG titer at the first prenatal visit"}, {"id": "d", "text": "Avoiding pregnancy for 28 days after a past MMR dose"}]'::jsonb, '["b"]', 'Cataracts, deafness, and heart defects form the CRS triad, which follows first-trimester rubella exposure. A positive IgG titer indicates immunity, not infection.'),
  ('measles', 1, 'A nurse is assessing a child with suspected measles for Koplik spots. Where should the nurse look?', '[{"id": "a", "text": "On the buccal mucosa inside the cheeks"}, {"id": "b", "text": "On the palms of the hands"}, {"id": "c", "text": "Along the hairline of the forehead"}, {"id": "d", "text": "On the soles of the feet"}]'::jsonb, '["a"]', 'Koplik spots are small white or bluish-white spots on the buccal mucosa inside the cheeks. The rash, not Koplik spots, begins at the hairline.'),
  ('measles', 2, 'A nurse is teaching a group of nursing students about measles. Which assessment finding should the nurse identify as pathognomonic for measles?', '[{"id": "a", "text": "Painful swelling of the parotid glands"}, {"id": "b", "text": "White spots on the buccal mucosa"}, {"id": "c", "text": "Lesions in all stages of healing"}, {"id": "d", "text": "A rash that lasts exactly 3 days"}]'::jsonb, '["b"]', 'Koplik spots, white spots on the buccal mucosa, are pathognomonic for measles. The measles rash lasts 5 to 7 days rather than 3 days.'),
  ('measles', 3, 'A nurse is assessing an unvaccinated 3-year-old child in the prodromal phase of measles. Which group of findings should the nurse expect?', '[{"id": "a", "text": "Parotid swelling, jaw pain, and dysphagia"}, {"id": "b", "text": "Itchy vesicles, pustules, and crusts"}, {"id": "c", "text": "Cough, coryza, and conjunctivitis"}, {"id": "d", "text": "Joint pain, low fever, and neck nodes"}]'::jsonb, '["c"]', 'The measles prodrome is the 3 Cs: cough, coryza, and conjunctivitis, along with high fever. The other clusters are not described as the measles prodrome.'),
  ('measles', 4, 'The parent of a child with early measles reports that the child has had a constant runny nose. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Conjunctivitis"}, {"id": "b", "text": "Cough"}, {"id": "c", "text": "Croup"}, {"id": "d", "text": "Coryza"}]'::jsonb, '["d"]', 'Coryza refers to a runny nose and is one of the 3 Cs of the measles prodrome. Conjunctivitis refers to red, watery eyes.'),
  ('measles', 5, 'A nurse finds Koplik spots in a child with fever and cough but notes no skin rash yet. When should the nurse expect the rash to appear?', '[{"id": "a", "text": "In about 2 days"}, {"id": "b", "text": "In about 2 weeks"}, {"id": "c", "text": "Only after the spots have healed for a month"}, {"id": "d", "text": "The rash never follows Koplik spots"}]'::jsonb, '["a"]', 'Koplik spots appear about 2 days before the rash. A delay of weeks does not match this timing.'),
  ('measles', 6, 'A nurse is assessing the skin of a child with measles. Which description of the rash should the nurse expect?', '[{"id": "a", "text": "Clear vesicles in several stages of healing"}, {"id": "b", "text": "Confluent, brick-red maculopapular rash"}, {"id": "c", "text": "Pale, flat rash limited to the palms"}, {"id": "d", "text": "Small, isolated blisters around the mouth"}]'::jsonb, '["b"]', 'The measles rash is an erythematous, confluent, brick-red maculopapular rash. Vesicles in several stages do not describe this rash.'),
  ('measles', 7, 'A nurse is teaching the parent of a child with measles about the expected rash. Which description of its spread is correct?', '[{"id": "a", "text": "It starts on the feet and moves upward to the face"}, {"id": "b", "text": "It starts on the trunk and moves outward to the hands"}, {"id": "c", "text": "It starts at the hairline and face and spreads downward"}, {"id": "d", "text": "It appears on the whole body all at once"}]'::jsonb, '["c"]', 'The measles rash starts at the hairline and face and spreads downward to the trunk and extremities. Starting on the feet reverses this direction.'),
  ('measles', 8, 'The parent of a child with measles asks how long the rash will last and how it will go away. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It lasts about 3 days and fades from the feet up.\""}, {"id": "b", "text": "\"It lasts about 3 weeks and fades all at once.\""}, {"id": "c", "text": "\"It lasts about 1 day and fades from the trunk outward.\""}, {"id": "d", "text": "\"It lasts 5 to 7 days and fades from head to toe.\""}]'::jsonb, '["d"]', 'The measles rash lasts 5 to 7 days and fades in the same head-to-toe pattern in which it appeared. A 3-day rash fading from the feet up does not match.'),
  ('measles', 9, 'A child with measles is admitted to the pediatric unit. Which type of transmission-based precautions should the nurse implement?', '[{"id": "a", "text": "Airborne precautions"}, {"id": "b", "text": "Droplet precautions only"}, {"id": "c", "text": "Contact precautions only"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["a"]', 'Measles requires airborne precautions with an N95 respirator and a negative-pressure room. Droplet precautions with a surgical mask are not adequate.'),
  ('measles', 10, 'A charge nurse observes staff entering the room of a child with measles. Which action requires correction?', '[{"id": "a", "text": "A nurse puts on an N95 respirator before entering"}, {"id": "b", "text": "A nurse wears a surgical mask to give medications"}, {"id": "c", "text": "A nurse confirms the room has negative pressure"}, {"id": "d", "text": "A nurse closes the door after entering the room"}]'::jsonb, '["b"]', 'An N95 respirator is required for measles; a surgical mask is not adequate. The N95, negative-pressure room, and closed door are all correct.'),
  ('measles', 11, 'An unlicensed assistive personnel (UAP) is caring for a child with measles in a negative-pressure room. Which action by the UAP requires correction?', '[{"id": "a", "text": "Wears an N95 respirator while in the room"}, {"id": "b", "text": "Reports a rising temperature to the nurse"}, {"id": "c", "text": "Props the room door open to watch the child"}, {"id": "d", "text": "Removes the meal tray promptly after lunch"}]'::jsonb, '["c"]', 'The door of the negative-pressure room must remain closed for a client with measles. Wearing an N95 is correct.'),
  ('measles', 12, 'A charge nurse is assigning staff to care for a child admitted with measles. Which nurse is the most appropriate choice?', '[{"id": "a", "text": "A nurse whose immunity status is unknown"}, {"id": "b", "text": "A nurse who has never had measles or MMR"}, {"id": "c", "text": "A nurse who plans to wear a surgical mask"}, {"id": "d", "text": "A nurse with documented measles immunity"}]'::jsonb, '["d"]', 'Only immune healthcare workers should care for a client with measles. A surgical mask is not adequate protection.'),
  ('measles', 13, 'A hospitalized child with measles developed a rash today. The child is not immunocompromised. How long should the nurse plan to maintain isolation?', '[{"id": "a", "text": "For 4 days after the rash began"}, {"id": "b", "text": "Until the Koplik spots first appear"}, {"id": "c", "text": "For 21 days after the rash began"}, {"id": "d", "text": "Only until the fever resolves"}]'::jsonb, '["a"]', 'Clients with measles are isolated for 4 days after rash onset. Immunocompromised clients are isolated for the entire illness.'),
  ('measles', 14, 'A child receiving chemotherapy who is immunocompromised is hospitalized with measles. How long should the nurse expect isolation to continue?', '[{"id": "a", "text": "For 4 days after the rash began"}, {"id": "b", "text": "For the entire duration of the illness"}, {"id": "c", "text": "Until the Koplik spots fade"}, {"id": "d", "text": "Until the cough has stopped"}]'::jsonb, '["b"]', 'Immunocompromised clients with measles remain isolated for the entire illness duration. The 4-day rule applies to clients who are not immunocompromised.'),
  ('measles', 15, 'A nurse is teaching a community group about measles. Which statement about the contagious period is correct?', '[{"id": "a", "text": "\"It is contagious only after the rash fades.\""}, {"id": "b", "text": "\"It is contagious only while Koplik spots are present.\""}, {"id": "c", "text": "\"It is contagious from 4 days before to 4 days after rash onset.\""}, {"id": "d", "text": "\"It is contagious from 2 weeks before to 2 weeks after the rash.\""}]'::jsonb, '["c"]', 'Measles is contagious from 4 days before to 4 days after rash onset. A 2-week window on either side does not match.'),
  ('measles', 16, 'A family entered a clinic exam room 1 hour after a child with measles had left. A family member later developed measles. The family asks how this happened. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Measles can spread only by direct touch.\""}, {"id": "b", "text": "\"Measles can spread only through shared food.\""}, {"id": "c", "text": "\"Measles is spread only by large droplets that fall quickly.\""}, {"id": "d", "text": "\"The measles virus can linger in the air for up to 2 hours.\""}]'::jsonb, '["d"]', 'Measles is airborne by droplet nuclei that can linger in the air for 2 hours. It is not limited to touch, food, or large droplets.'),
  ('measles', 17, 'A parent reports that their unvaccinated child was exposed to measles at a park. The parent asks when symptoms might appear. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Usually 7 to 14 days after exposure.\""}, {"id": "b", "text": "\"Usually within 24 hours of exposure.\""}, {"id": "c", "text": "\"Usually 4 to 6 weeks after exposure.\""}, {"id": "d", "text": "\"Usually 3 to 6 months after exposure.\""}]'::jsonb, '["a"]', 'The incubation period for measles is 7 to 14 days. Symptoms within 24 hours would be far shorter than the incubation period.'),
  ('measles', 18, 'A nurse is caring for a child with measles. Which complication should the nurse recognize as the most common?', '[{"id": "a", "text": "Subacute sclerosing panencephalitis"}, {"id": "b", "text": "Otitis media"}, {"id": "c", "text": "Blindness"}, {"id": "d", "text": "Encephalitis"}]'::jsonb, '["b"]', 'Otitis media is the most common complication of measles. SSPE is a fatal complication that occurs years later and is not the most common.'),
  ('measles', 19, 'A nurse is teaching staff about the dangers of measles. Which complication is the leading cause of death from measles?', '[{"id": "a", "text": "Otitis media"}, {"id": "b", "text": "Croup"}, {"id": "c", "text": "Pneumonia"}, {"id": "d", "text": "Corneal ulcers"}]'::jsonb, '["c"]', 'Pneumonia is the number one cause of measles death, especially in malnourished children. Otitis media is the most common complication but not the leading cause of death.'),
  ('measles', 20, 'A nurse is caring for four children with measles. Which child should the nurse assess first?', '[{"id": "a", "text": "A child whose rash is fading from the face"}, {"id": "b", "text": "A child with red, watery eyes"}, {"id": "c", "text": "A child with a runny nose and a cough"}, {"id": "d", "text": "A malnourished child with increasing difficulty breathing"}]'::jsonb, '["d"]', 'Pneumonia is the most common cause of death from measles, especially in malnourished children, so breathing difficulty is the priority. A fading rash and the 3 Cs are expected findings.'),
  ('measles', 21, 'The parent of a child recovering from measles asks whether any complication could appear many years later. Which complication should the nurse describe?', '[{"id": "a", "text": "Subacute sclerosing panencephalitis (SSPE)"}, {"id": "b", "text": "Otitis media"}, {"id": "c", "text": "Croup (laryngotracheobronchitis)"}, {"id": "d", "text": "Conjunctivitis"}]'::jsonb, '["a"]', 'SSPE is a fatal measles complication that occurs years later. Otitis media and croup are complications of the acute illness.'),
  ('measles', 22, 'A nurse working in a region with widespread malnutrition is caring for children with measles. Vitamin A deficiency in these children places them at risk for which complication?', '[{"id": "a", "text": "Otitis media"}, {"id": "b", "text": "Blindness from corneal ulcers"}, {"id": "c", "text": "Croup"}, {"id": "d", "text": "Post-infectious encephalitis"}]'::jsonb, '["b"]', 'Blindness in measles is linked to vitamin A deficiency leading to corneal ulcers. Otitis media is the most common complication but is not described as caused by vitamin A deficiency.'),
  ('measles', 23, 'A child with measles develops a respiratory complication involving the larynx, trachea, and bronchi. Which complication has the child developed?', '[{"id": "a", "text": "Otitis media"}, {"id": "b", "text": "Conjunctivitis"}, {"id": "c", "text": "Croup"}, {"id": "d", "text": "Coryza"}]'::jsonb, '["c"]', 'Croup is laryngotracheobronchitis, a listed complication of measles. Coryza and conjunctivitis are prodromal findings rather than complications.'),
  ('measles', 24, 'A child is diagnosed with measles. In addition to antipyretics and fluids, which treatment should the nurse anticipate?', '[{"id": "a", "text": "An antiviral medication"}, {"id": "b", "text": "Routine antibiotics"}, {"id": "c", "text": "A dose of aspirin"}, {"id": "d", "text": "Vitamin A supplementation"}]'::jsonb, '["d"]', 'Vitamin A supplementation is part of measles treatment. There is no specific antiviral, and antibiotics are used only for secondary bacterial infection.'),
  ('measles', 25, 'The parent of a child with measles asks why vitamin A has been prescribed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It reduces the severity and complications of measles.\""}, {"id": "b", "text": "\"It kills the measles virus directly.\""}, {"id": "c", "text": "\"It replaces the need for isolation.\""}, {"id": "d", "text": "\"It prevents the rash from appearing.\""}]'::jsonb, '["a"]', 'Vitamin A supplementation reduces the severity and complications of measles. It is not an antiviral, and isolation is still required.'),
  ('measles', 26, 'The parent of a child with measles asks whether there is a medication that will kill the virus. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes, an antiviral is started once the rash appears.\""}, {"id": "b", "text": "\"No, there is no specific antiviral, so care is supportive.\""}, {"id": "c", "text": "\"Yes, antibiotics are given to every child with measles.\""}, {"id": "d", "text": "\"Yes, vitamin A acts as an antiviral for measles.\""}]'::jsonb, '["b"]', 'There is no specific antiviral for measles; treatment is supportive with vitamin A supplementation. Antibiotics are used only if a secondary bacterial infection develops.'),
  ('measles', 27, 'A nurse teaches the parent of a child with measles about treatment. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will give fluids and let my child rest.\""}, {"id": "b", "text": "\"My child will receive vitamin A.\""}, {"id": "c", "text": "\"My child needs antibiotics to kill the measles virus.\""}, {"id": "d", "text": "\"I can give an antipyretic for the fever.\""}]'::jsonb, '["c"]', 'Antibiotics are used only if a secondary bacterial infection develops; there is no specific antiviral for measles. Fluids, rest, antipyretics, and vitamin A are appropriate.'),
  ('measles', 28, 'An unvaccinated 3-year-old child was exposed to measles yesterday. Which post-exposure intervention should the nurse anticipate?', '[{"id": "a", "text": "No intervention, since exposure has already occurred"}, {"id": "b", "text": "Waiting until a rash appears, then vaccinating"}, {"id": "c", "text": "Starting an antiviral medication immediately"}, {"id": "d", "text": "Giving the MMR vaccine within the 72-hour window"}]'::jsonb, '["d"]', 'Post-exposure prophylaxis includes MMR within 72 hours of exposure. There is no specific antiviral for measles.'),
  ('measles', 29, 'An unvaccinated adult was exposed to measles 4 days ago and has no symptoms. Which post-exposure option remains appropriate?', '[{"id": "a", "text": "IGIV, because it can be given within 6 days"}, {"id": "b", "text": "MMR, because it can be given within 72 hours"}, {"id": "c", "text": "No prophylaxis, because 72 hours have passed"}, {"id": "d", "text": "An antiviral, because symptoms have not begun"}]'::jsonb, '["a"]', 'IGIV can be given within 6 days of exposure, so it is still an option on day 4. The 72-hour window for MMR has already passed.'),
  ('measles', 30, 'The parent of a toddler asks how well the MMR vaccine protects against measles. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is about 50% effective after one dose.\""}, {"id": "b", "text": "\"It is more than 95% effective after two doses.\""}, {"id": "c", "text": "\"It protects only for about 1 year.\""}, {"id": "d", "text": "\"It protects only against mumps and rubella.\""}]'::jsonb, '["b"]', 'The MMR vaccine is a live attenuated vaccine that is more than 95% effective after 2 doses. It protects against measles as well as mumps and rubella.'),
  ('measles', 31, 'A nurse is reviewing the measles immunization schedule with the parent of an infant. Which schedule should the nurse describe?', '[{"id": "a", "text": "One dose at birth and one at 2 months"}, {"id": "b", "text": "One dose at 6 months and one at 9 months"}, {"id": "c", "text": "One dose at 12–15 months and one at 4–6 years"}, {"id": "d", "text": "One dose at 11 years and one at 16 years"}]'::jsonb, '["c"]', 'MMR dose 1 is given at 12 to 15 months and dose 2 at 4 to 6 years. The other schedules do not match these ages.'),
  ('measles', 32, 'A pregnant client who never received the MMR vaccine hears about a measles outbreak and asks to receive the vaccine at today''s prenatal visit. Which response by the nurse is correct?', '[{"id": "a", "text": "\"You can receive it today since you are healthy.\""}, {"id": "b", "text": "\"You can receive it today if you have no fever.\""}, {"id": "c", "text": "\"You should receive two doses today.\""}, {"id": "d", "text": "\"MMR is a live vaccine and is not given in pregnancy.\""}]'::jsonb, '["d"]', 'The MMR vaccine is live attenuated and is contraindicated in pregnancy. Being healthy or afebrile does not change this contraindication.'),
  ('measles', 33, 'A nurse reviews MMR vaccine orders for several clients. Which order should the nurse question?', '[{"id": "a", "text": "MMR for a client who is severely immunocompromised"}, {"id": "b", "text": "MMR for a healthy 12-month-old child"}, {"id": "c", "text": "MMR for a healthy 5-year-old due for dose 2"}, {"id": "d", "text": "MMR for an unvaccinated adult exposed 1 day ago"}]'::jsonb, '["a"]', 'MMR is a live vaccine contraindicated in severely immunocompromised clients. MMR within 72 hours of exposure is an accepted post-exposure option.'),
  ('measles', 34, 'A nursing student asks which virus causes measles. Which response by the nurse is correct?', '[{"id": "a", "text": "\"A herpes virus that stays dormant in nerves.\""}, {"id": "b", "text": "\"A morbillivirus in the paramyxovirus family.\""}, {"id": "c", "text": "\"A bacterium that is spread by droplets.\""}, {"id": "d", "text": "\"A fungus that spreads through the air.\""}]'::jsonb, '["b"]', 'Measles is caused by morbillivirus of the paramyxovirus family. It is a virus, not a bacterium or fungus.'),
  ('measles', 35, 'A new nurse asks why a client with measles needs airborne rather than droplet precautions. Which explanation is most accurate?', '[{"id": "a", "text": "\"The virus spreads only through contact with skin lesions.\""}, {"id": "b", "text": "\"The virus is carried only in large droplets that fall quickly.\""}, {"id": "c", "text": "\"The virus travels in tiny droplet nuclei that stay in the air.\""}, {"id": "d", "text": "\"The virus spreads only through contaminated blood.\""}]'::jsonb, '["c"]', 'Measles is airborne through droplet nuclei smaller than 5 µm that can linger in the air for 2 hours. Large droplets that fall quickly describe droplet, not airborne, spread.'),
  ('measles', 36, 'An unvaccinated 3-year-old child has a high fever, cough, runny nose, and red, watery eyes. The nurse sees small bluish-white spots inside the cheeks. Which condition should the nurse suspect?', '[{"id": "a", "text": "Rubella"}, {"id": "b", "text": "Mumps"}, {"id": "c", "text": "Chickenpox"}, {"id": "d", "text": "Rubeola (measles)"}]'::jsonb, '["d"]', 'White spots on the buccal mucosa are Koplik spots, which are pathognomonic for rubeola (measles), and the 3 Cs with high fever form its prodrome.'),
  ('measles', 37, 'A child with high fever, cough, coryza, conjunctivitis, and a new brick-red rash at the hairline arrives at a busy emergency department. Which action should the nurse take first?', '[{"id": "a", "text": "Place the child in a negative-pressure room with the door closed"}, {"id": "b", "text": "Seat the child in the waiting room with a surgical mask"}, {"id": "c", "text": "Complete a full history in the open triage area"}, {"id": "d", "text": "Give the child vitamin A before any isolation"}]'::jsonb, '["a"]', 'These findings suggest measles, which requires airborne precautions in a negative-pressure room with the door closed to protect others first. A surgical mask is not adequate.'),
  ('measles', 38, 'A healthy child''s measles rash began 2 days ago. The parent asks if the child can return to preschool tomorrow. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes; the child stops being contagious once the rash appears.\""}, {"id": "b", "text": "\"Not yet; isolation continues for 4 days after the rash began.\""}, {"id": "c", "text": "\"Yes; the child can return once the fever is gone.\""}, {"id": "d", "text": "\"Not yet; the child must stay home for 3 more weeks.\""}]'::jsonb, '["b"]', 'Measles requires isolation for 4 days after rash onset, so day 3 is too early. The child remains contagious for 4 days after the rash begins.'),
  ('measles', 39, 'A child''s measles rash appeared this morning. Three days ago, the child attended a crowded birthday party. The parent asks whether the other guests might have been exposed. Which response is accurate?', '[{"id": "a", "text": "\"No, measles spreads only after the rash appears.\""}, {"id": "b", "text": "\"No, measles spreads only when Koplik spots are gone.\""}, {"id": "c", "text": "\"Yes, measles is contagious 4 days before the rash.\""}, {"id": "d", "text": "\"Yes, but only guests who touched the child''s skin.\""}]'::jsonb, '["c"]', 'Measles is contagious from 4 days before to 4 days after the rash, so contact 3 days before the rash is an exposure. Spread is airborne, not limited to skin contact.'),
  ('measles', 40, 'A public health nurse is monitoring unvaccinated contacts after a measles exposure at a school. During which period after exposure should the nurse expect symptoms to develop if a contact was infected?', '[{"id": "a", "text": "Within 48 hours after exposure"}, {"id": "b", "text": "Only on the same day as the exposure"}, {"id": "c", "text": "About 6 to 8 weeks after exposure"}, {"id": "d", "text": "About 7 to 14 days after exposure"}]'::jsonb, '["d"]', 'The incubation period for measles is 7 to 14 days, so contacts are monitored for symptoms during that window. A 48-hour window is far shorter than the incubation period.'),
  ('measles', 41, 'A nurse is volunteering with a health program in a developing country during a measles outbreak. According to WHO recommendations, which children with measles should receive vitamin A?', '[{"id": "a", "text": "All children with measles"}, {"id": "b", "text": "Only children who become blind"}, {"id": "c", "text": "Only children who are hospitalized"}, {"id": "d", "text": "Only children who received MMR"}]'::jsonb, '["a"]', 'The WHO recommends vitamin A for all children with measles because it reduces severity and complications. It is not limited to children with blindness or those hospitalized.'),
  ('measles', 42, 'On day 6 of a measles rash, a nurse notes that the rash has faded on the face but remains on the legs. How should the nurse interpret this finding?', '[{"id": "a", "text": "It suggests a second infection has started"}, {"id": "b", "text": "It is expected because the rash fades head to toe"}, {"id": "c", "text": "It indicates the rash is spreading upward again"}, {"id": "d", "text": "It means the child now needs antibiotics"}]'::jsonb, '["b"]', 'The measles rash lasts 5 to 7 days and fades in the same head-to-toe pattern in which it appeared. Antibiotics are used only for secondary bacterial infection.'),
  ('measles', 43, 'A nurse is reviewing neurologic complications of measles with a group of nursing students. Which complications should the nurse include?', '[{"id": "a", "text": "Orchitis and oophoritis"}, {"id": "b", "text": "Cataracts and glaucoma"}, {"id": "c", "text": "Post-infectious encephalitis and SSPE"}, {"id": "d", "text": "Parotitis and hearing loss"}]'::jsonb, '["c"]', 'Measles complications include post-infectious encephalitis and SSPE, a fatal condition that appears years later. The other pairs are not listed measles complications.'),
  ('measles', 44, 'A nurse is evaluating a nursing student''s understanding of measles isolation. Which statement by the student requires correction?', '[{"id": "a", "text": "\"The room must be under negative pressure.\""}, {"id": "b", "text": "\"Only immune staff should provide care.\""}, {"id": "c", "text": "\"The door to the room must stay closed.\""}, {"id": "d", "text": "\"A surgical mask is adequate when entering the room.\""}]'::jsonb, '["d"]', 'A surgical mask is not adequate for measles; an N95 respirator is required. Negative pressure, a closed door, and immune staff are correct.'),
  ('measles', 45, 'In addition to cough, coryza, and conjunctivitis, which finding should the nurse expect during the measles prodrome?', '[{"id": "a", "text": "High fever"}, {"id": "b", "text": "No fever at all"}, {"id": "c", "text": "Low body temperature"}, {"id": "d", "text": "Itchy crusted lesions"}]'::jsonb, '["a"]', 'The measles prodrome includes the 3 Cs along with a high fever. The absence of fever does not fit the prodrome.'),
  ('measles', 46, 'A nurse is caring for four children with measles. Which child is at greatest risk of dying from measles pneumonia?', '[{"id": "a", "text": "A well-nourished 8-year-old with mild cough"}, {"id": "b", "text": "A malnourished 2-year-old child"}, {"id": "c", "text": "A well-nourished 10-year-old with fading rash"}, {"id": "d", "text": "A well-nourished 6-year-old with coryza"}]'::jsonb, '["b"]', 'Pneumonia is the number one cause of measles death, especially in malnourished children. Well-nourished children with typical findings are at lower risk.'),
  ('measles', 47, 'A nurse is explaining to new staff why strict infection control is needed for clients with measles. Which statement is most accurate?', '[{"id": "a", "text": "\"Measles spreads only between family members.\""}, {"id": "b", "text": "\"Measles rarely spreads from one person to another.\""}, {"id": "c", "text": "\"Measles is one of the most transmissible viruses known.\""}, {"id": "d", "text": "\"Measles spreads only after the rash has faded.\""}]'::jsonb, '["c"]', 'Measles is extremely contagious and one of the most transmissible viruses known. It is contagious from 4 days before to 4 days after rash onset, not only after the rash fades.'),
  ('measles', 48, 'A charge nurse reviews staff assignments for a unit with a client who has measles. Which assignment requires correction?', '[{"id": "a", "text": "An immune nurse assigned to the client with measles"}, {"id": "b", "text": "An immune nurse wearing an N95 to give medications"}, {"id": "c", "text": "An immune UAP assigned to deliver meals to the room"}, {"id": "d", "text": "A nurse without documented immunity assigned to the client"}]'::jsonb, '["d"]', 'Only immune healthcare workers should care for a client with measles. Immune staff wearing N95 respirators may provide care.'),
  ('measles', 49, 'A nurse is planning supportive care for a child with uncomplicated measles. Which interventions should the nurse include?', '[{"id": "a", "text": "Antipyretics, fluids, and rest"}, {"id": "b", "text": "Antiviral medication and bed rest"}, {"id": "c", "text": "Routine antibiotics and fluids"}, {"id": "d", "text": "Aspirin and fluid restriction"}]'::jsonb, '["a"]', 'Supportive care for measles includes antipyretics, fluids, and rest. There is no specific antiviral, and antibiotics are used only for secondary bacterial infection.'),
  ('measles', 50, 'A nurse is documenting the rash of a child with confirmed measles. Which documentation is consistent with this diagnosis?', '[{"id": "a", "text": "Vesicles in several stages, starting on the trunk"}, {"id": "b", "text": "Confluent maculopapular rash spreading from head toward toes"}, {"id": "c", "text": "Pale rash limited to the hands and feet"}, {"id": "d", "text": "Rash that started on the legs and spread upward"}]'::jsonb, '["b"]', 'The measles rash is maculopapular and confluent and spreads from head to toe. A rash that starts on the legs and spreads upward reverses this pattern.'),
  ('hepatitis', 1, 'A client develops hepatitis after eating raw shellfish at a restaurant. Which type of hepatitis does the nurse suspect?', '[{"id": "a", "text": "Hepatitis B"}, {"id": "b", "text": "Hepatitis C"}, {"id": "c", "text": "Hepatitis A"}, {"id": "d", "text": "Hepatitis D"}]'::jsonb, '["c"]', 'Hepatitis A is spread by the fecal-oral route through contaminated food or water, including shellfish. Hepatitis B, C, and D are spread through blood or body fluids.'),
  ('hepatitis', 2, 'Several employees at a restaurant are diagnosed with hepatitis A. Along with vaccination, which measure best prevents further spread?', '[{"id": "a", "text": "Avoiding shared needles"}, {"id": "b", "text": "Screening donated blood"}, {"id": "c", "text": "Avoiding NSAIDs and aspirin"}, {"id": "d", "text": "Thorough hand hygiene"}]'::jsonb, '["d"]', 'Hepatitis A is fecal-oral and is best prevented by hand hygiene plus vaccine. Needle and blood precautions address blood-borne types such as B and C.'),
  ('hepatitis', 3, 'A nurse volunteers at a clinic in a developing country. Which type of viral hepatitis is spread by the fecal-oral route and described as common in developing countries?', '[{"id": "a", "text": "Hepatitis B"}, {"id": "b", "text": "Hepatitis E"}, {"id": "c", "text": "Hepatitis C"}, {"id": "d", "text": "Hepatitis D"}]'::jsonb, '["b"]', 'Hepatitis E is fecal-oral and common in developing countries. Hepatitis B, C, and D are transmitted through blood and body fluids.'),
  ('hepatitis', 4, 'The partner of a client with hepatitis C asks to receive a vaccine against hepatitis C. Which response by the nurse is accurate?', '[{"id": "a", "text": "There is no vaccine for hepatitis C."}, {"id": "b", "text": "The hepatitis B vaccine also prevents hepatitis C."}, {"id": "c", "text": "The hepatitis A vaccine also prevents hepatitis C."}, {"id": "d", "text": "The hepatitis C vaccine is given only at birth."}]'::jsonb, '["a"]', 'There is no vaccine for hepatitis C. The hepatitis B vaccine prevents hepatitis D, not hepatitis C.'),
  ('hepatitis', 5, 'A client newly diagnosed with hepatitis C asks whether the infection usually clears on its own. Which response by the nurse is accurate?', '[{"id": "a", "text": "Hepatitis C is always acute and self-limited."}, {"id": "b", "text": "Hepatitis C clears with rest and fluids alone."}, {"id": "c", "text": "Hepatitis C is prevented by the hepatitis B vaccine."}, {"id": "d", "text": "Hepatitis C becomes chronic in most cases."}]'::jsonb, '["d"]', 'Hepatitis C becomes chronic in most cases. Hepatitis A and E, not C, are acute only and managed with supportive care.'),
  ('hepatitis', 6, 'A client with hepatitis C is starting sofosbuvir/ledipasvir (Harvoni) and asks about the expected outcome. Which response by the nurse is accurate?', '[{"id": "a", "text": "These antivirals cure more than 95% of clients."}, {"id": "b", "text": "Hepatitis C cannot be treated with medication."}, {"id": "c", "text": "This drug slows hepatitis C but cannot cure it."}, {"id": "d", "text": "This drug works only for hepatitis B infection."}]'::jsonb, '["a"]', 'Direct-acting antivirals such as sofosbuvir/ledipasvir (Harvoni) have a cure rate above 95% for hepatitis C. Chronic hepatitis B is treated with tenofovir or entecavir.'),
  ('hepatitis', 7, 'A client with chronic hepatitis B asks about medication treatment. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Sofosbuvir/ledipasvir"}, {"id": "b", "text": "Entecavir"}, {"id": "c", "text": "Hepatitis A vaccine"}, {"id": "d", "text": "No medication; rest only"}]'::jsonb, '["b"]', 'Chronic hepatitis B is treated with the antivirals tenofovir or entecavir. Sofosbuvir/ledipasvir is a direct-acting antiviral for hepatitis C.'),
  ('hepatitis', 8, 'A client''s laboratory results show a positive HBsAg. How does the nurse interpret this finding?', '[{"id": "a", "text": "Immunity from vaccination"}, {"id": "b", "text": "Hepatitis C exposure"}, {"id": "c", "text": "Active hepatitis B infection"}, {"id": "d", "text": "Bile duct involvement"}]'::jsonb, '["c"]', 'HBsAg (surface antigen) indicates active HBV infection. Immunity from vaccination or recovery is shown by anti-HBs.'),
  ('hepatitis', 9, 'A health care worker''s laboratory results show a positive anti-HBs and a negative HBsAg. How does the nurse interpret these results?', '[{"id": "a", "text": "The worker is immune to hepatitis B."}, {"id": "b", "text": "The worker has active hepatitis B."}, {"id": "c", "text": "The worker needs hepatitis C RNA testing."}, {"id": "d", "text": "The worker has hepatitis D superinfection."}]'::jsonb, '["a"]', 'Anti-HBs indicates immunity from vaccine or recovery. A positive HBsAg, which this worker does not have, would indicate active infection.'),
  ('hepatitis', 10, 'The nurse reviews hepatitis B laboratory markers with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "A positive HBsAg means the client is infected."}, {"id": "b", "text": "Anti-HBs can result from vaccination."}, {"id": "c", "text": "Anti-HBs can result from recovery from infection."}, {"id": "d", "text": "A positive anti-HBs means active hepatitis B."}]'::jsonb, '["d"]', 'Anti-HBs indicates immunity from vaccine or recovery, not active infection. Active HBV infection is indicated by HBsAg.'),
  ('hepatitis', 11, 'A client''s screening test is positive for anti-HCV. Which test does the nurse anticipate next to confirm infection?', '[{"id": "a", "text": "Anti-HBs titer"}, {"id": "b", "text": "HBsAg"}, {"id": "c", "text": "Hepatitis C RNA viral load"}, {"id": "d", "text": "Alkaline phosphatase"}]'::jsonb, '["c"]', 'Anti-HCV indicates hepatitis C exposure and is confirmed with an RNA viral load. HBsAg and anti-HBs are hepatitis B markers.'),
  ('hepatitis', 12, 'A client is diagnosed with hepatitis D. Which statement by the nurse about hepatitis D is accurate?', '[{"id": "a", "text": "It occurs only in the presence of hepatitis B."}, {"id": "b", "text": "It is spread by the fecal-oral route."}, {"id": "c", "text": "It requires its own separate vaccine."}, {"id": "d", "text": "It occurs only in pregnant women."}]'::jsonb, '["a"]', 'Hepatitis D occurs only in the presence of HBV, so the hepatitis B vaccine also prevents it. Hepatitis D is blood-borne, not fecal-oral.'),
  ('hepatitis', 13, 'A parent asks which vaccine will also protect a child against hepatitis D. Which response by the nurse is accurate?', '[{"id": "a", "text": "Hepatitis A vaccine"}, {"id": "b", "text": "Hepatitis B vaccine"}, {"id": "c", "text": "Hepatitis E vaccine"}, {"id": "d", "text": "No vaccine can prevent it"}]'::jsonb, '["b"]', 'Hepatitis D only occurs with HBV, so the hepatitis B vaccine prevents hepatitis D as well. The hepatitis A vaccine does not protect against HDV.'),
  ('hepatitis', 14, 'A client asks the nurse how hepatitis D is transmitted. Which response by the nurse is accurate?', '[{"id": "a", "text": "Through contaminated food and water"}, {"id": "b", "text": "Through raw or undercooked shellfish"}, {"id": "c", "text": "Through blood, as a co- or super-infection with HBV"}, {"id": "d", "text": "Through the fecal-oral route, like hepatitis A"}]'::jsonb, '["c"]', 'Hepatitis D is transmitted through blood as a co-infection or super-infection with HBV. Contaminated food, water, and shellfish are fecal-oral sources of hepatitis A.'),
  ('hepatitis', 15, 'During a hepatitis E outbreak, the nurse identifies clients who were exposed. Which client is at greatest risk for death from this infection?', '[{"id": "a", "text": "A pregnant woman"}, {"id": "b", "text": "A school-age child"}, {"id": "c", "text": "A healthy adult man"}, {"id": "d", "text": "An adolescent athlete"}]'::jsonb, '["a"]', 'Hepatitis E carries high mortality in pregnant women. The other clients do not belong to the group identified as high risk.'),
  ('hepatitis', 16, 'A client diagnosed with hepatitis E asks how the infection was acquired. Which route of transmission does the nurse identify?', '[{"id": "a", "text": "Blood transfusion"}, {"id": "b", "text": "Fecal-oral"}, {"id": "c", "text": "Sharing needles"}, {"id": "d", "text": "Co-infection with HBV"}]'::jsonb, '["b"]', 'Hepatitis A and E are transmitted by the fecal-oral route. Blood, needles, and HBV co-infection relate to hepatitis B, C, and D.'),
  ('hepatitis', 17, 'A pregnant client plans to travel to a developing country. The nurse reinforces hand hygiene and safe food and water. Which explanation supports this teaching?', '[{"id": "a", "text": "Hepatitis C spreads through food and has a vaccine."}, {"id": "b", "text": "Hepatitis B spreads fecal-oral and is mild in pregnancy."}, {"id": "c", "text": "Hepatitis E is fecal-oral and has high mortality in pregnancy."}, {"id": "d", "text": "Hepatitis D spreads fecal-oral without any prior infection."}]'::jsonb, '["c"]', 'Hepatitis E is fecal-oral, common in developing countries, and has high mortality in pregnant women. Hepatitis B, C, and D are blood-borne, and hepatitis C has no vaccine.'),
  ('hepatitis', 18, 'Which group of hepatitis viruses is transmitted through blood and body fluids?', '[{"id": "a", "text": "A, B, and E"}, {"id": "b", "text": "A, C, and E"}, {"id": "c", "text": "B, C, and D"}, {"id": "d", "text": "A, D, and E"}]'::jsonb, '["c"]', 'Hepatitis B, C, and D are spread by blood and body fluids. Hepatitis A and E are spread by the fecal-oral route.'),
  ('hepatitis', 19, 'The nurse is teaching a community group about hepatitis prevention. Which two types of hepatitis are transmitted by the fecal-oral route?', '[{"id": "a", "text": "A and E"}, {"id": "b", "text": "B and C"}, {"id": "c", "text": "C and D"}, {"id": "d", "text": "B and D"}]'::jsonb, '["a"]', 'Hepatitis A and E are fecal-oral. Hepatitis B, C, and D are blood-borne.'),
  ('hepatitis', 20, 'A nurse sustains a needle stick from a client whose hepatitis status is unknown. Which types of hepatitis are of concern from this exposure?', '[{"id": "a", "text": "A and E"}, {"id": "b", "text": "E only"}, {"id": "c", "text": "A only"}, {"id": "d", "text": "B and C"}]'::jsonb, '["d"]', 'Hepatitis B is spread by blood and body fluids, and hepatitis C by blood-to-blood contact such as needle sticks. Hepatitis A and E are fecal-oral.'),
  ('hepatitis', 21, 'A client is in the prodromal phase of acute hepatitis. Which finding does the nurse expect?', '[{"id": "a", "text": "Yellow sclera"}, {"id": "b", "text": "Clay-colored stools"}, {"id": "c", "text": "Dark cola-colored urine"}, {"id": "d", "text": "RUQ pain and liver tenderness"}]'::jsonb, '["d"]', 'RUQ pain and liver tenderness occur in the prodromal phase. Jaundice, dark urine, and clay-colored stools are icteric-phase findings.'),
  ('hepatitis', 22, 'A client exposed to hepatitis A reports fatigue, nausea, headache, joint aches, and a low-grade fever. The skin and sclera are not yellow. Which phase of hepatitis does the nurse identify?', '[{"id": "a", "text": "Prodromal phase"}, {"id": "b", "text": "Icteric phase"}, {"id": "c", "text": "Recovery phase"}, {"id": "d", "text": "Immune phase"}]'::jsonb, '["a"]', 'Fatigue, nausea, low-grade fever, headache, arthralgias, and malaise characterize the prodromal phase. The icteric phase is marked by jaundice, which this client does not have.'),
  ('hepatitis', 23, 'A client with hepatitis has yellow sclera, dark urine, and pale stools. Which phase of hepatitis does the nurse identify?', '[{"id": "a", "text": "Prodromal phase, before jaundice"}, {"id": "b", "text": "Icteric phase"}, {"id": "c", "text": "Recovery phase"}, {"id": "d", "text": "Immune phase with positive anti-HBs"}]'::jsonb, '["b"]', 'Jaundice, dark urine, and clay-colored or pale stools occur in the icteric (jaundice) phase. In the recovery phase, jaundice resolves.'),
  ('hepatitis', 24, 'Which set of findings represents the classic triad of viral hepatitis?', '[{"id": "a", "text": "Fatigue, nausea, and low-grade fever"}, {"id": "b", "text": "Pruritus, hepatomegaly, and headache"}, {"id": "c", "text": "Jaundice, dark urine, and clay-colored stools"}, {"id": "d", "text": "RUQ pain, arthralgias, and malaise"}]'::jsonb, '["c"]', 'Jaundice, dark urine, and clay stools form the classic triad. Fatigue, nausea, low-grade fever, RUQ pain, and arthralgias are prodromal findings.'),
  ('hepatitis', 25, 'A client with hepatitis reports that the urine looks like cola. How does the nurse interpret this finding?', '[{"id": "a", "text": "Bilirubin in the urine"}, {"id": "b", "text": "An expected recovery-phase finding"}, {"id": "c", "text": "A sign of immunity to hepatitis"}, {"id": "d", "text": "Normal clotting factor production"}]'::jsonb, '["a"]', 'Dark cola-colored urine reflects bilirubinuria during the icteric phase. In the recovery phase, jaundice resolves rather than worsens.'),
  ('hepatitis', 26, 'A client is in the icteric phase of hepatitis. Which client statement reflects an expected finding of this phase?', '[{"id": "a", "text": "My stools are darker than usual."}, {"id": "b", "text": "My skin itches all the time."}, {"id": "c", "text": "My urine is paler than usual."}, {"id": "d", "text": "My energy has fully returned."}]'::jsonb, '["b"]', 'Pruritus (itching) occurs in the icteric phase. Stools become clay-colored and urine becomes dark, and energy returns only in the recovery phase.'),
  ('hepatitis', 27, 'A client with hepatitis E is admitted with vomiting and fatigue. Which plan of care does the nurse anticipate?', '[{"id": "a", "text": "Rest, nutrition, and hydration"}, {"id": "b", "text": "Tenofovir antiviral therapy"}, {"id": "c", "text": "Sofosbuvir/ledipasvir therapy"}, {"id": "d", "text": "Entecavir antiviral therapy"}]'::jsonb, '["a"]', 'Hepatitis A and E are treated with supportive care: rest, nutrition, hydration, and avoiding alcohol and hepatotoxic drugs. Tenofovir and entecavir treat chronic hepatitis B.'),
  ('hepatitis', 28, 'A client recovering from hepatitis A asks how long it will take to feel normal again. Which response by the nurse is accurate?', '[{"id": "a", "text": "About 24 hours"}, {"id": "b", "text": "About 3 days"}, {"id": "c", "text": "Several weeks to months"}, {"id": "d", "text": "It will never fully resolve"}]'::jsonb, '["c"]', 'The recovery phase can take several weeks to months. Hepatitis A is acute only, so it does resolve.'),
  ('hepatitis', 29, 'Which finding indicates to the nurse that a client with hepatitis is entering the recovery phase?', '[{"id": "a", "text": "The urine becomes darker."}, {"id": "b", "text": "The itching increases."}, {"id": "c", "text": "The ALT and AST rise."}, {"id": "d", "text": "Jaundice resolves and energy returns."}]'::jsonb, '["d"]', 'In the recovery phase, jaundice resolves, energy returns, and liver enzymes normalize. Dark urine and itching are icteric-phase findings.'),
  ('hepatitis', 30, 'A client with hepatitis has markedly elevated ALT and AST levels. How does the nurse interpret this finding?', '[{"id": "a", "text": "Liver cell damage"}, {"id": "b", "text": "Bile duct involvement"}, {"id": "c", "text": "Immunity to hepatitis B"}, {"id": "d", "text": "Hepatitis C exposure"}]'::jsonb, '["a"]', 'Elevated ALT and AST indicate liver cell damage. An elevated alkaline phosphatase indicates bile duct involvement.'),
  ('hepatitis', 31, 'A client with hepatitis has an elevated alkaline phosphatase level. How does the nurse interpret this finding?', '[{"id": "a", "text": "Impaired clotting factor synthesis"}, {"id": "b", "text": "Bile duct involvement"}, {"id": "c", "text": "Active hepatitis B infection"}, {"id": "d", "text": "Immunity from vaccination"}]'::jsonb, '["b"]', 'An elevated alkaline phosphatase indicates bile duct involvement. Impaired clotting factor synthesis is reflected by an elevated PT/INR.'),
  ('hepatitis', 32, 'A client with hepatitis has an elevated PT/INR. How does the nurse interpret this result?', '[{"id": "a", "text": "Bile duct involvement"}, {"id": "b", "text": "Immunity to hepatitis B"}, {"id": "c", "text": "Impaired clotting factor synthesis"}, {"id": "d", "text": "Recovery from hepatitis A"}]'::jsonb, '["c"]', 'An elevated PT/INR reflects impaired clotting factor synthesis from liver dysfunction. Bile duct involvement is reflected by alkaline phosphatase.'),
  ('hepatitis', 33, 'A client with hepatitis has an elevated INR. Which nursing action is the priority?', '[{"id": "a", "text": "Give aspirin for joint pain."}, {"id": "b", "text": "Assess for signs of bleeding."}, {"id": "c", "text": "Offer ibuprofen for headache."}, {"id": "d", "text": "Stop monitoring the INR."}]'::jsonb, '["b"]', 'An elevated PT/INR creates a bleeding risk, so the nurse monitors for bleeding. Aspirin and NSAIDs such as ibuprofen are avoided in hepatitis.'),
  ('hepatitis', 34, 'A client with hepatitis asks why the PT/INR is checked so often. Which response by the nurse is accurate?', '[{"id": "a", "text": "The liver makes clotting factors."}, {"id": "b", "text": "It confirms the type of hepatitis."}, {"id": "c", "text": "It measures immunity to hepatitis B."}, {"id": "d", "text": "It shows bile duct involvement."}]'::jsonb, '["a"]', 'PT/INR is monitored because the liver makes clotting factors. Immunity to hepatitis B is shown by anti-HBs, and bile duct involvement by alkaline phosphatase.'),
  ('hepatitis', 35, 'The nurse is caring for four clients with hepatitis. Which client should the nurse assess first?', '[{"id": "a", "text": "A client in the prodromal phase with fatigue and nausea"}, {"id": "b", "text": "A client in the icteric phase who reports itching"}, {"id": "c", "text": "A client with dark urine and yellow sclera"}, {"id": "d", "text": "A client with an elevated INR and new bleeding gums"}]'::jsonb, '["d"]', 'An elevated PT/INR signals bleeding risk, so new bleeding requires assessment first. Fatigue, nausea, itching, dark urine, and jaundice are expected phase findings.'),
  ('hepatitis', 36, 'The nurse teaches a client with hepatitis about home care. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will avoid drinking alcohol."}, {"id": "b", "text": "I will rest when I feel tired."}, {"id": "c", "text": "I will take ibuprofen for my headaches."}, {"id": "d", "text": "I will drink plenty of fluids."}]'::jsonb, '["c"]', 'Clients with hepatitis should avoid aspirin, NSAIDs such as ibuprofen, and alcohol. Rest and hydration are part of supportive care.'),
  ('hepatitis', 37, 'Which hepatitis type and medication pairing is correct?', '[{"id": "a", "text": "Chronic hepatitis B — tenofovir"}, {"id": "b", "text": "Hepatitis C — entecavir"}, {"id": "c", "text": "Hepatitis A — sofosbuvir"}, {"id": "d", "text": "Hepatitis E — ledipasvir"}]'::jsonb, '["a"]', 'Chronic hepatitis B is treated with tenofovir or entecavir. Sofosbuvir and ledipasvir treat hepatitis C, while hepatitis A and E receive supportive care.'),
  ('hepatitis', 38, 'Which statement by a client with hepatitis A indicates understanding of home care?', '[{"id": "a", "text": "I will need lifelong antiviral medication."}, {"id": "b", "text": "I will avoid alcohol while my liver heals."}, {"id": "c", "text": "I will take aspirin for my joint aches."}, {"id": "d", "text": "I will start sofosbuvir to clear the virus."}]'::jsonb, '["b"]', 'Hepatitis A is treated supportively with rest, nutrition, hydration, and avoidance of alcohol and hepatotoxic drugs. Aspirin is avoided, and sofosbuvir is for hepatitis C.'),
  ('hepatitis', 39, 'The nurse is caring for a healthy newborn. Which hepatitis vaccine series is recommended for all newborns?', '[{"id": "a", "text": "Hepatitis A vaccine"}, {"id": "b", "text": "Hepatitis C vaccine"}, {"id": "c", "text": "Hepatitis E vaccine"}, {"id": "d", "text": "Hepatitis B vaccine"}]'::jsonb, '["d"]', 'The hepatitis B vaccine series is given to all newborns. There is no hepatitis C vaccine.'),
  ('hepatitis', 40, 'A client is diagnosed with hepatitis B. Which history is most consistent with how this infection is transmitted?', '[{"id": "a", "text": "Eating raw shellfish"}, {"id": "b", "text": "Exposure to infected blood or body fluids"}, {"id": "c", "text": "Drinking contaminated water"}, {"id": "d", "text": "Poor hand hygiene by a food handler"}]'::jsonb, '["b"]', 'Hepatitis B is transmitted through blood and body fluids. Shellfish, contaminated water, and poor hand hygiene are fecal-oral sources of hepatitis A.'),
  ('hepatitis', 41, 'Which client does the nurse identify as having the greatest risk for hepatitis C?', '[{"id": "a", "text": "A client who injects drugs and shares needles"}, {"id": "b", "text": "A client who ate raw shellfish last month"}, {"id": "c", "text": "A client who drank untreated well water"}, {"id": "d", "text": "A client who ate at a restaurant with an outbreak"}]'::jsonb, '["a"]', 'Hepatitis C is blood-to-blood, with IV drug use and needle sticks as key risks. Shellfish, contaminated water, and restaurant outbreaks relate to fecal-oral hepatitis A.'),
  ('hepatitis', 42, 'A client planning international travel asks how to prevent hepatitis A. Which response by the nurse is best?', '[{"id": "a", "text": "Avoid sharing needles; there is no vaccine."}, {"id": "b", "text": "Get the hepatitis B vaccine, which also prevents A."}, {"id": "c", "text": "Take entecavir before and during travel."}, {"id": "d", "text": "Get the hepatitis A vaccine and practice hand hygiene."}]'::jsonb, '["d"]', 'Hepatitis A is best prevented by hand hygiene plus vaccine. The hepatitis B vaccine prevents hepatitis D, not A.'),
  ('hepatitis', 43, 'Which sequence correctly lists the clinical phases of acute viral hepatitis?', '[{"id": "a", "text": "Icteric, prodromal, recovery"}, {"id": "b", "text": "Prodromal, recovery, icteric"}, {"id": "c", "text": "Recovery, icteric, prodromal"}, {"id": "d", "text": "Prodromal, icteric, recovery"}]'::jsonb, '["d"]', 'Prodromal symptoms such as fatigue and nausea come first, followed by the icteric (jaundice) phase. In the recovery phase, jaundice resolves and energy returns.'),
  ('hepatitis', 44, 'A client with hepatitis has an elevated total bilirubin. Which assessment finding does the nurse expect?', '[{"id": "a", "text": "Yellow skin and sclera"}, {"id": "b", "text": "Pale, clear urine"}, {"id": "c", "text": "Dark brown, formed stools"}, {"id": "d", "text": "Normal skin color"}]'::jsonb, '["a"]', 'An elevated total bilirubin causes jaundice, dark urine, and clay stools. Pale urine and dark stools are the opposite of expected findings.'),
  ('hepatitis', 45, 'A client reports clay-colored stools and dark urine. Which laboratory tests does the nurse anticipate?', '[{"id": "a", "text": "Anti-HBs titer only"}, {"id": "b", "text": "Bilirubin and liver enzymes"}, {"id": "c", "text": "HCV RNA viral load only"}, {"id": "d", "text": "Hepatitis E vaccine titer"}]'::jsonb, '["b"]', 'Clay-colored stools and dark urine suggest the icteric phase of hepatitis, so bilirubin and liver enzymes are checked. Anti-HBs reflects immunity, not current liver function.'),
  ('hepatitis', 46, 'Which laboratory result does the nurse review to evaluate liver cell damage in a client with hepatitis?', '[{"id": "a", "text": "Alkaline phosphatase"}, {"id": "b", "text": "Anti-HBs"}, {"id": "c", "text": "ALT and AST"}, {"id": "d", "text": "PT/INR"}]'::jsonb, '["c"]', 'Elevated ALT and AST reflect liver cell damage. Alkaline phosphatase reflects bile duct involvement and PT/INR reflects clotting factor synthesis.'),
  ('hepatitis', 47, 'A client with hepatitis C is receiving direct-acting antivirals. Which instruction should the nurse include?', '[{"id": "a", "text": "Receive the hepatitis C vaccine series."}, {"id": "b", "text": "Expect no cure from antiviral therapy."}, {"id": "c", "text": "Take ibuprofen as needed for headaches."}, {"id": "d", "text": "Avoid alcohol, aspirin, and NSAIDs."}]'::jsonb, '["d"]', 'Clients with hepatitis should avoid aspirin, NSAIDs, and alcohol. There is no hepatitis C vaccine, and DAAs have a cure rate above 95%.'),
  ('hepatitis', 48, 'A client is prescribed sofosbuvir/ledipasvir (Harvoni). The nurse recognizes this medication is used to treat which type of hepatitis?', '[{"id": "a", "text": "Hepatitis A"}, {"id": "b", "text": "Hepatitis B"}, {"id": "c", "text": "Hepatitis C"}, {"id": "d", "text": "Hepatitis E"}]'::jsonb, '["c"]', 'Hepatitis C is treated with direct-acting antivirals such as sofosbuvir. Chronic hepatitis B is treated with tenofovir or entecavir, and hepatitis A and E receive supportive care.'),
  ('hepatitis', 49, 'A nursing student is comparing hepatitis viruses. Which type has no vaccine and becomes chronic in most cases?', '[{"id": "a", "text": "Hepatitis A"}, {"id": "b", "text": "Hepatitis B"}, {"id": "c", "text": "Hepatitis C"}, {"id": "d", "text": "Hepatitis D"}]'::jsonb, '["c"]', 'Hepatitis C has no vaccine and becomes chronic in most cases. Hepatitis A and B have vaccines, and the hepatitis B vaccine also prevents hepatitis D.'),
  ('hepatitis', 50, 'The nurse teaches the parents of a newborn about hepatitis prevention. Which statement by a parent indicates understanding?', '[{"id": "a", "text": "Our baby will receive the hepatitis C vaccine at birth."}, {"id": "b", "text": "Newborns do not need any hepatitis vaccines."}, {"id": "c", "text": "The hepatitis B vaccine is delayed until school age."}, {"id": "d", "text": "Our baby will start the hepatitis B vaccine series now."}]'::jsonb, '["d"]', 'The hepatitis B vaccine series is given to all newborns. There is no hepatitis C vaccine.'),
  ('meningitis', 1, 'The nurse is assessing a client with suspected meningitis. Which finding is part of the classic triad?', '[{"id": "a", "text": "Nuchal rigidity"}, {"id": "b", "text": "Bulging fontanelle"}, {"id": "c", "text": "Petechial rash"}, {"id": "d", "text": "Seizures"}]'::jsonb, '["a"]', 'The classic triad is severe headache, stiff neck (nuchal rigidity), and fever. Petechial rash and seizures can occur but are not part of the triad, and a bulging fontanelle is an infant finding.'),
  ('meningitis', 2, 'The nurse assesses a client for nuchal rigidity. Which finding indicates that nuchal rigidity is present?', '[{"id": "a", "text": "The hips flex when the neck is bent forward."}, {"id": "b", "text": "Pain occurs when the knee is straightened."}, {"id": "c", "text": "The client cannot flex the chin to the chest."}, {"id": "d", "text": "Bright light causes eye discomfort."}]'::jsonb, '["c"]', 'Nuchal rigidity is a stiff neck in which the client cannot flex the chin to the chest. Hip flexion with neck bending is Brudzinski''s sign, and knee pain on straightening is Kernig''s sign.'),
  ('meningitis', 3, 'The nurse flexes a client''s hip to 90° and then straightens the knee. The client resists and reports pain. How does the nurse document this finding?', '[{"id": "a", "text": "Positive Brudzinski''s sign"}, {"id": "b", "text": "Positive Kernig''s sign"}, {"id": "c", "text": "Paradoxical irritability"}, {"id": "d", "text": "Negative meningeal signs"}]'::jsonb, '["b"]', 'Kernig''s sign is positive when, with the hip flexed to 90°, the client resists or has pain as the knee is straightened. Brudzinski''s sign is tested by flexing the neck.'),
  ('meningitis', 4, 'When the nurse flexes a client''s neck forward, the client''s hips and knees flex involuntarily. Which finding does the nurse document?', '[{"id": "a", "text": "Positive Kernig''s sign"}, {"id": "b", "text": "Nuchal rigidity only"}, {"id": "c", "text": "Negative meningeal signs"}, {"id": "d", "text": "Positive Brudzinski''s sign"}]'::jsonb, '["d"]', 'Brudzinski''s sign is positive when flexing the neck forward causes involuntary hip and knee flexion. Kernig''s sign involves pain when the knee is straightened.'),
  ('meningitis', 5, 'A nursing student describes the signs of meningeal irritation. Which statement by the student requires correction?', '[{"id": "a", "text": "Brudzinski''s sign is pain when the knee is straightened."}, {"id": "b", "text": "Kernig''s sign is tested with the hip flexed to 90°."}, {"id": "c", "text": "Brudzinski''s sign involves flexing the neck forward."}, {"id": "d", "text": "A positive Kernig''s sign suggests meningeal irritation."}]'::jsonb, '["a"]', 'Knee pain on straightening describes Kernig''s sign; Brudzinski''s sign is involuntary knee flexion when the neck is bent. Both are signs of meningeal irritation.'),
  ('meningitis', 6, 'A client has positive Kernig''s and Brudzinski''s signs. The nurse interprets these findings as evidence of which condition?', '[{"id": "a", "text": "Viral rather than bacterial infection"}, {"id": "b", "text": "Listeria as the likely cause"}, {"id": "c", "text": "Meningeal irritation"}, {"id": "d", "text": "Normal CSF pressure"}]'::jsonb, '["c"]', 'Kernig''s and Brudzinski''s signs are signs of meningeal irritation. Bacterial and viral meningitis are distinguished by CSF findings, not by these signs.'),
  ('meningitis', 7, 'An 8-month-old infant with a fever is being evaluated for meningitis. Which finding supports this diagnosis?', '[{"id": "a", "text": "Sunken fontanelle"}, {"id": "b", "text": "Bulging fontanelle"}, {"id": "c", "text": "Low-pitched cry"}, {"id": "d", "text": "Increased appetite"}]'::jsonb, '["b"]', 'Infants with meningitis may have a bulging fontanelle, a high-pitched cry, and poor feeding. A sunken fontanelle, low-pitched cry, and increased appetite are the opposite of these findings.'),
  ('meningitis', 8, 'Which findings in a 4-month-old infant should the nurse report as possible signs of meningitis?', '[{"id": "a", "text": "Flat fontanelle and eager feeding"}, {"id": "b", "text": "Low-pitched cry and calm behavior"}, {"id": "c", "text": "Strong suck and steady weight gain"}, {"id": "d", "text": "High-pitched cry and poor feeding"}]'::jsonb, '["d"]', 'A high-pitched cry, poor feeding, and irritability are signs of meningitis in infants. Eager feeding and calm behavior are not.'),
  ('meningitis', 9, 'A client admitted with suspected meningitis develops a petechial, purpuric rash. Which action should the nurse take?', '[{"id": "a", "text": "Report it immediately as a medical emergency."}, {"id": "b", "text": "Document it as an expected viral finding."}, {"id": "c", "text": "Recheck the rash at the end of the shift."}, {"id": "d", "text": "Apply a cool compress and reassess in 4 hours."}]'::jsonb, '["a"]', 'A meningococcal rash of petechiae or purpura is a medical emergency and must be reported immediately. It is linked to bacterial (meningococcal) infection, not viral meningitis.'),
  ('meningitis', 10, 'The nurse notes a hemorrhagic petechial rash on a client with meningitis. Which organism is most associated with this finding?', '[{"id": "a", "text": "Enterovirus"}, {"id": "b", "text": "Cryptococcus neoformans"}, {"id": "c", "text": "N. meningitidis"}, {"id": "d", "text": "Naegleria fowleri"}]'::jsonb, '["c"]', 'A hemorrhagic petechial or purpuric rash is characteristic of meningococcal (N. meningitidis) infection. Enteroviruses cause viral meningitis, and Cryptococcus causes fungal meningitis.'),
  ('meningitis', 11, 'A client with bacterial meningitis says the room lights hurt the eyes and the noise in the hallway is unbearable. Which intervention is most appropriate?', '[{"id": "a", "text": "Open the blinds to help orient the client."}, {"id": "b", "text": "Provide a darkened, quiet room."}, {"id": "c", "text": "Turn on the television for distraction."}, {"id": "d", "text": "Keep the overhead lights on for checks."}]'::jsonb, '["b"]', 'Photophobia and phonophobia are managed with a darkened, quiet room. Bright light and added noise worsen these symptoms.'),
  ('meningitis', 12, 'Which position is most appropriate for a client with bacterial meningitis?', '[{"id": "a", "text": "Trendelenburg"}, {"id": "b", "text": "Flat with the neck flexed"}, {"id": "c", "text": "Head of bed elevated 30°"}, {"id": "d", "text": "Prone with the neck flexed"}]'::jsonb, '["c"]', 'The head of the bed is kept at 30°. Trendelenburg and neck flexion are avoided when monitoring for increased ICP.'),
  ('meningitis', 13, 'The nurse observes a UAP caring for a client with bacterial meningitis. Which action by the UAP requires correction?', '[{"id": "a", "text": "Dimming the lights in the room"}, {"id": "b", "text": "Keeping the head of the bed at 30°"}, {"id": "c", "text": "Keeping the room quiet"}, {"id": "d", "text": "Placing pillows to flex the neck forward"}]'::jsonb, '["d"]', 'Neck flexion is avoided to help prevent increased ICP. A darkened, quiet room with the head of the bed at 30° is appropriate.'),
  ('meningitis', 14, 'Which intervention should the nurse include in the initial plan of care for a client with bacterial meningitis?', '[{"id": "a", "text": "Implement seizure precautions."}, {"id": "b", "text": "Place in Trendelenburg position."}, {"id": "c", "text": "Keep the room brightly lit."}, {"id": "d", "text": "Delay antibiotics until LP results."}]'::jsonb, '["a"]', 'Seizures can occur with meningitis, so seizure precautions are part of care. Trendelenburg is avoided, the room is kept dark, and antibiotics are never delayed for LP results.'),
  ('meningitis', 15, 'A client with suspected bacterial meningitis is scheduled for a lumbar puncture (LP) in 2 hours. What is the nurse''s priority action?', '[{"id": "a", "text": "Hold antibiotics until the LP results return."}, {"id": "b", "text": "Administer the prescribed IV antibiotics now."}, {"id": "c", "text": "Give oral antibiotics after the LP is done."}, {"id": "d", "text": "Wait for the CSF culture before any treatment."}]'::jsonb, '["b"]', 'IV antibiotics are started immediately and are never delayed while waiting for the LP or its results. Bacterial meningitis is an emergency with high mortality without treatment.'),
  ('meningitis', 16, 'A client with suspected meningitis shows signs of increased intracranial pressure (ICP). Before the lumbar puncture, which action does the nurse anticipate?', '[{"id": "a", "text": "CT scan to rule out increased ICP or a mass"}, {"id": "b", "text": "Trendelenburg positioning to ease the LP"}, {"id": "c", "text": "Immediate LP without any imaging"}, {"id": "d", "text": "Withholding antibiotics until imaging is done"}]'::jsonb, '["a"]', 'A CT scan is done first to rule out increased ICP or a mass before the LP. Antibiotics are not withheld, and Trendelenburg is avoided.'),
  ('meningitis', 17, 'A client with suspected bacterial meningitis and possible increased ICP arrives in the emergency department. Which sequence of care is correct?', '[{"id": "a", "text": "LP, wait for results, then IV antibiotics"}, {"id": "b", "text": "LP, CT scan, then IV antibiotics"}, {"id": "c", "text": "CT scan, LP, results, then IV antibiotics"}, {"id": "d", "text": "IV antibiotics, CT scan, then LP if stable"}]'::jsonb, '["d"]', 'IV antibiotics start immediately, a CT scan is done first when ICP is suspected, and the LP follows if the client is stable. Antibiotics are never delayed for LP results.'),
  ('meningitis', 18, 'Which diagnostic test is the gold standard for confirming meningitis?', '[{"id": "a", "text": "CT scan of the head"}, {"id": "b", "text": "Lumbar puncture with CSF analysis"}, {"id": "c", "text": "Kernig''s sign assessment"}, {"id": "d", "text": "Inspection of a petechial rash"}]'::jsonb, '["b"]', 'The lumbar puncture is the gold standard for CSF analysis. The CT scan is done first only to rule out increased ICP or a mass.'),
  ('meningitis', 19, 'A client''s CSF is cloudy, with markedly elevated neutrophils, a protein of 250 mg/dL, and a glucose of 30 mg/dL. How does the nurse interpret these results?', '[{"id": "a", "text": "Normal CSF findings"}, {"id": "b", "text": "Viral (aseptic) meningitis"}, {"id": "c", "text": "Bacterial meningitis"}, {"id": "d", "text": "Expected findings after recovery"}]'::jsonb, '["c"]', 'Bacterial meningitis produces cloudy CSF with high neutrophils, low glucose, and high protein. Viral meningitis produces clear CSF with lymphocytes and normal glucose.'),
  ('meningitis', 20, 'A client''s CSF is clear, with elevated lymphocytes and a normal glucose level. How does the nurse interpret these findings?', '[{"id": "a", "text": "Viral meningitis"}, {"id": "b", "text": "Bacterial meningitis"}, {"id": "c", "text": "Meningococcal infection"}, {"id": "d", "text": "Listeria infection"}]'::jsonb, '["a"]', 'Clear CSF with lymphocytes and normal glucose indicates viral meningitis. Bacterial meningitis, including meningococcal and Listeria, produces cloudy CSF with neutrophils and low glucose.'),
  ('meningitis', 21, 'The nurse reviews CSF results for a client with suspected meningitis. Which value is most consistent with bacterial meningitis?', '[{"id": "a", "text": "Glucose 60 mg/dL"}, {"id": "b", "text": "Protein 40 mg/dL"}, {"id": "c", "text": "WBC count of 3"}, {"id": "d", "text": "Glucose 28 mg/dL"}]'::jsonb, '["d"]', 'Bacterial meningitis causes a low CSF glucose of less than 40 mg/dL. Glucose 60 mg/dL, protein 40 mg/dL, and a WBC count of 3 are within normal CSF ranges.'),
  ('meningitis', 22, 'A client''s CSF is clear, with elevated lymphocytes and a normal glucose level. Which plan of care does the nurse anticipate?', '[{"id": "a", "text": "Rest, fluids, and analgesics"}, {"id": "b", "text": "IV ceftriaxone plus vancomycin"}, {"id": "c", "text": "Amphotericin B plus flucytosine"}, {"id": "d", "text": "Ampicillin added for Listeria"}]'::jsonb, '["a"]', 'These CSF findings indicate viral meningitis, which is treated supportively with rest, fluids, and analgesics. Ceftriaxone plus vancomycin is empiric therapy for bacterial meningitis.'),
  ('meningitis', 23, 'A nursing student is reviewing CSF findings in bacterial meningitis. Which statement by the student requires correction?', '[{"id": "a", "text": "The CSF is usually cloudy."}, {"id": "b", "text": "The CSF glucose is high."}, {"id": "c", "text": "The CSF has many neutrophils."}, {"id": "d", "text": "The CSF protein is high."}]'::jsonb, '["b"]', 'In bacterial meningitis, CSF glucose is low, not high. Cloudy fluid, high neutrophils, and high protein are expected.'),
  ('meningitis', 24, 'A client diagnosed with viral (aseptic) meningitis asks what to expect. Which response by the nurse is accurate?', '[{"id": "a", "text": "It is nearly always fatal without surgery."}, {"id": "b", "text": "It requires lifelong antifungal therapy."}, {"id": "c", "text": "It is usually self-limiting with supportive care."}, {"id": "d", "text": "It requires IV ceftriaxone and vancomycin."}]'::jsonb, '["c"]', 'Viral (aseptic) meningitis is self-limiting and managed with supportive care. Ceftriaxone and vancomycin are used for bacterial meningitis.'),
  ('meningitis', 25, 'A parent asks which type of virus most commonly causes viral meningitis. Which response by the nurse is accurate?', '[{"id": "a", "text": "Cryptococcus neoformans"}, {"id": "b", "text": "Naegleria fowleri"}, {"id": "c", "text": "S. pneumoniae"}, {"id": "d", "text": "Enteroviruses"}]'::jsonb, '["d"]', 'Enteroviruses are the most common cause of viral (aseptic) meningitis. Cryptococcus is fungal, Naegleria is parasitic, and S. pneumoniae is bacterial.'),
  ('meningitis', 26, 'The nurse receives report on four clients. Which client should the nurse see first?', '[{"id": "a", "text": "A client with viral meningitis receiving oral fluids"}, {"id": "b", "text": "A client with suspected bacterial meningitis awaiting a first antibiotic dose"}, {"id": "c", "text": "A client with viral meningitis requesting an analgesic"}, {"id": "d", "text": "A client recovering from viral meningitis ready for discharge"}]'::jsonb, '["b"]', 'Bacterial meningitis is an emergency requiring antibiotics STAT because of high mortality without treatment. Viral meningitis is self-limiting and managed with supportive care.'),
  ('meningitis', 27, 'The nurse is reviewing causes of meningitis. Which organism causes bacterial meningitis?', '[{"id": "a", "text": "Enteroviruses"}, {"id": "b", "text": "Cryptococcus neoformans"}, {"id": "c", "text": "Naegleria fowleri"}, {"id": "d", "text": "S. pneumoniae"}]'::jsonb, '["d"]', 'Bacterial meningitis is caused by N. meningitidis, S. pneumoniae, Hib, and Listeria. Enteroviruses cause viral meningitis and Cryptococcus causes fungal meningitis.'),
  ('meningitis', 28, 'Which medication regimen does the nurse anticipate for empiric treatment of bacterial meningitis?', '[{"id": "a", "text": "Amphotericin B and flucytosine"}, {"id": "b", "text": "IV ceftriaxone and vancomycin"}, {"id": "c", "text": "Oral rifampin alone"}, {"id": "d", "text": "Rest, fluids, and analgesics"}]'::jsonb, '["b"]', 'IV ceftriaxone plus vancomycin is broad-spectrum empiric therapy for bacterial meningitis. Amphotericin B and flucytosine treat fungal meningitis.'),
  ('meningitis', 29, 'Dexamethasone is prescribed for a client with bacterial meningitis. When should the nurse administer it?', '[{"id": "a", "text": "24 hours after antibiotics are started"}, {"id": "b", "text": "Only after the LP results return"}, {"id": "c", "text": "With or before the first antibiotic dose"}, {"id": "d", "text": "After the antibiotic course is finished"}]'::jsonb, '["c"]', 'Dexamethasone is given with or before antibiotics to reduce inflammation. Giving it later or waiting for LP results is incorrect.'),
  ('meningitis', 30, 'A client asks why a steroid was given along with antibiotics for bacterial meningitis. Which response by the nurse is accurate?', '[{"id": "a", "text": "It reduces inflammation."}, {"id": "b", "text": "It kills the bacteria directly."}, {"id": "c", "text": "It prevents fungal infection."}, {"id": "d", "text": "It protects close contacts."}]'::jsonb, '["a"]', 'Dexamethasone is given with or before antibiotics to reduce inflammation. Close contacts are protected with rifampin or ciprofloxacin, not steroids.'),
  ('meningitis', 31, 'A 78-year-old client with suspected bacterial meningitis is at risk for Listeria. Which change to empiric therapy does the nurse anticipate?', '[{"id": "a", "text": "Add amphotericin B to the regimen."}, {"id": "b", "text": "Replace vancomycin with rifampin."}, {"id": "c", "text": "Replace ceftriaxone with flucytosine."}, {"id": "d", "text": "Add ampicillin to the regimen."}]'::jsonb, '["d"]', 'Ampicillin is added when Listeria is suspected, as in elderly, immunocompromised, or neonatal clients. Amphotericin B and flucytosine treat fungal meningitis.'),
  ('meningitis', 32, 'Which client with suspected bacterial meningitis is most likely to need ampicillin added for possible Listeria?', '[{"id": "a", "text": "A healthy 20-year-old college student"}, {"id": "b", "text": "A healthy 35-year-old teacher"}, {"id": "c", "text": "A 2-week-old neonate"}, {"id": "d", "text": "A healthy 12-year-old athlete"}]'::jsonb, '["c"]', 'Ampicillin is added for suspected Listeria in elderly, immunocompromised, and neonatal clients. The healthy older children and adults are not in these groups.'),
  ('meningitis', 33, 'A client with AIDS develops meningitis. Which type of meningitis is specifically associated with HIV/AIDS?', '[{"id": "a", "text": "Fungal (Cryptococcus neoformans)"}, {"id": "b", "text": "Parasitic (Naegleria fowleri)"}, {"id": "c", "text": "Bacterial (Hib)"}, {"id": "d", "text": "Viral (mumps)"}]'::jsonb, '["a"]', 'Fungal meningitis caused by Cryptococcus neoformans is common in HIV/AIDS patients. Naegleria fowleri is acquired from warm freshwater.'),
  ('meningitis', 34, 'A client is diagnosed with cryptococcal (fungal) meningitis. Which medications does the nurse anticipate?', '[{"id": "a", "text": "Ceftriaxone and vancomycin"}, {"id": "b", "text": "Rifampin or ciprofloxacin"}, {"id": "c", "text": "Ampicillin alone"}, {"id": "d", "text": "Amphotericin B and flucytosine"}]'::jsonb, '["d"]', 'Fungal meningitis is treated with amphotericin B plus flucytosine. Ceftriaxone and vancomycin are empiric therapy for bacterial meningitis.'),
  ('meningitis', 35, 'A client develops meningitis several days after swimming in a warm freshwater lake. Which organism does the nurse suspect?', '[{"id": "a", "text": "Cryptococcus neoformans"}, {"id": "b", "text": "Naegleria fowleri"}, {"id": "c", "text": "Enterovirus"}, {"id": "d", "text": "Hib"}]'::jsonb, '["b"]', 'Naegleria fowleri, the brain-eating amoeba, is acquired from warm freshwater. Cryptococcus neoformans causes fungal meningitis common in HIV/AIDS.'),
  ('meningitis', 36, 'A client is admitted with meningococcal meningitis. Which type of isolation does the nurse implement?', '[{"id": "a", "text": "Standard precautions only"}, {"id": "b", "text": "Contact precautions"}, {"id": "c", "text": "Droplet precautions"}, {"id": "d", "text": "Airborne precautions"}]'::jsonb, '["c"]', 'Droplet precautions are used for bacterial and meningococcal meningitis. Standard precautions alone are not sufficient.'),
  ('meningitis', 37, 'A client with meningococcal meningitis started IV antibiotics this morning. When can droplet precautions be discontinued?', '[{"id": "a", "text": "When the fever resolves"}, {"id": "b", "text": "After 24 hours of antibiotics"}, {"id": "c", "text": "When the LP results return"}, {"id": "d", "text": "After the antibiotic course ends"}]'::jsonb, '["b"]', 'Droplet precautions are maintained for the first 24 hours after antibiotics are started. Fever resolution and LP results do not determine the duration.'),
  ('meningitis', 38, 'A nurse enters the room of a client with meningococcal meningitis who started antibiotics 4 hours ago. Which action by the nurse is correct?', '[{"id": "a", "text": "Wear a mask only if the client is coughing."}, {"id": "b", "text": "Enter without a mask because antibiotics have started."}, {"id": "c", "text": "Wear a mask only when more than 6 feet away."}, {"id": "d", "text": "Wear a surgical mask when within 3–6 feet."}]'::jsonb, '["d"]', 'Droplet precautions require a surgical mask within 3-6 feet during the first 24 hours of antibiotics. Four hours of therapy is not enough to remove precautions.'),
  ('meningitis', 39, 'Which action by a nurse caring for a client with meningococcal meningitis requires correction?', '[{"id": "a", "text": "Removing droplet precautions 6 hours after the first antibiotic dose"}, {"id": "b", "text": "Wearing a surgical mask within 3 feet of the client"}, {"id": "c", "text": "Keeping the client''s room dark and quiet"}, {"id": "d", "text": "Maintaining the head of the bed at 30°"}]'::jsonb, '["a"]', 'Droplet precautions continue for the first 24 hours of antibiotics, so removing them at 6 hours is unsafe. A mask within 3-6 feet, a dark quiet room, and HOB 30° are correct.'),
  ('meningitis', 40, 'The roommate of a college student diagnosed with meningococcal meningitis asks what to do. Which response does the nurse anticipate?', '[{"id": "a", "text": "You need treatment only if you develop symptoms."}, {"id": "b", "text": "You will receive IV ceftriaxone and vancomycin."}, {"id": "c", "text": "You will need prophylactic rifampin or ciprofloxacin."}, {"id": "d", "text": "You will need amphotericin B and flucytosine."}]'::jsonb, '["c"]', 'Close contacts receive prophylactic rifampin or ciprofloxacin. Ceftriaxone and vancomycin are treatment for the infected client, not prophylaxis for contacts.'),
  ('meningitis', 41, 'A close contact of a client with meningococcal meningitis is being taught about prophylaxis. Which statement by the contact indicates understanding?', '[{"id": "a", "text": "I''ll take dexamethasone to prevent infection."}, {"id": "b", "text": "I''ll take ciprofloxacin as a preventive measure."}, {"id": "c", "text": "I don''t need anything unless I get a fever."}, {"id": "d", "text": "I''ll need amphotericin B as a precaution."}]'::jsonb, '["b"]', 'Close contacts receive prophylactic rifampin or ciprofloxacin. Dexamethasone reduces inflammation in the infected client and is not prophylaxis.'),
  ('meningitis', 42, 'The parent of an 11-year-old asks about the meningococcal conjugate vaccine (MenACWY). Which schedule does the nurse describe?', '[{"id": "a", "text": "One dose at birth with no booster needed"}, {"id": "b", "text": "One dose at 11–12 years and a booster at 16"}, {"id": "c", "text": "One dose at 16 years and a booster at 30"}, {"id": "d", "text": "Given only after exposure to a close contact"}]'::jsonb, '["b"]', 'MenACWY is recommended at 11-12 years with a booster at 16. Contacts of an infected client receive rifampin or ciprofloxacin prophylaxis, not a vaccine schedule.'),
  ('meningitis', 43, 'The parent of an infant asks which vaccine prevents meningitis caused by H. influenzae type b. Which vaccine does the nurse identify?', '[{"id": "a", "text": "MenACWY"}, {"id": "b", "text": "PCV13"}, {"id": "c", "text": "Hib vaccine"}, {"id": "d", "text": "PPSV23"}]'::jsonb, '["c"]', 'The Hib vaccine prevents H. influenzae type b meningitis in children. MenACWY is meningococcal, and PCV13 and PPSV23 are pneumococcal vaccines.'),
  ('meningitis', 44, 'Which vaccines help prevent meningitis caused by S. pneumoniae (pneumococcus)?', '[{"id": "a", "text": "MenACWY"}, {"id": "b", "text": "Hib vaccine"}, {"id": "c", "text": "Rifampin prophylaxis"}, {"id": "d", "text": "PCV13 / PPSV23"}]'::jsonb, '["d"]', 'PCV13 and PPSV23 are the pneumococcal vaccines. MenACWY is the meningococcal conjugate vaccine and rifampin is prophylaxis for close contacts.'),
  ('meningitis', 45, 'The nurse is assessing a client with suspected meningitis. Which client statement is most consistent with this diagnosis?', '[{"id": "a", "text": "My headache came on slowly over weeks."}, {"id": "b", "text": "I can easily touch my chin to my chest."}, {"id": "c", "text": "Bright lights make my eyes hurt."}, {"id": "d", "text": "My temperature has been normal all week."}]'::jsonb, '["c"]', 'Photophobia (light sensitivity) occurs with meningitis. The headache is sudden in onset, the neck is stiff, and high fever is part of the classic triad.'),
  ('meningitis', 46, 'A client is being evaluated for meningitis. Which description of headache is most consistent with this diagnosis?', '[{"id": "a", "text": "Mild, gradual, and relieved by rest"}, {"id": "b", "text": "Sudden onset, the worst of my life"}, {"id": "c", "text": "A dull ache present only in the mornings"}, {"id": "d", "text": "Occurs only after reading for hours"}]'::jsonb, '["b"]', 'The headache of meningitis is severe, sudden in onset, and described as the worst of life. A mild, gradual headache does not fit this description.'),
  ('meningitis', 47, 'Which additional findings should the nurse expect in a client with meningitis?', '[{"id": "a", "text": "Ability to flex the chin to the chest"}, {"id": "b", "text": "Tolerance of bright lights and noise"}, {"id": "c", "text": "Low body temperature and calm affect"}, {"id": "d", "text": "Nausea, vomiting, and altered mental status"}]'::jsonb, '["d"]', 'Nausea, vomiting, and altered mental status occur with meningitis. Clients typically have nuchal rigidity, photophobia, phonophobia, and high fever.'),
  ('meningitis', 48, 'Which combination of findings in a 6-month-old infant with fever should prompt the nurse to suspect meningitis?', '[{"id": "a", "text": "Calm behavior and a sunken fontanelle"}, {"id": "b", "text": "Irritability and a bulging fontanelle"}, {"id": "c", "text": "Low-pitched cry and eager feeding"}, {"id": "d", "text": "Alert play and a flat fontanelle"}]'::jsonb, '["b"]', 'Infants with meningitis show irritability, poor feeding, a high-pitched cry, and a bulging fontanelle. Calm behavior and eager feeding are not signs of meningitis.'),
  ('meningitis', 49, 'The family of a client diagnosed with Naegleria fowleri meningitis asks about the prognosis. Which statement by the nurse is accurate?', '[{"id": "a", "text": "It is self-limiting with supportive care."}, {"id": "b", "text": "It is common in clients with HIV/AIDS."}, {"id": "c", "text": "It is nearly 100% fatal."}, {"id": "d", "text": "It is prevented by the Hib vaccine."}]'::jsonb, '["c"]', 'Naegleria fowleri meningitis, acquired from warm freshwater, is nearly 100% fatal. Viral meningitis is self-limiting, and fungal meningitis is common in HIV/AIDS.'),
  ('meningitis', 50, 'A client presents with a sudden, severe headache and nuchal rigidity. Which additional finding completes the classic triad of meningitis?', '[{"id": "a", "text": "Photophobia"}, {"id": "b", "text": "Bulging fontanelle"}, {"id": "c", "text": "Petechial rash"}, {"id": "d", "text": "High fever"}]'::jsonb, '["d"]', 'The classic triad is severe headache, stiff neck, and fever. Photophobia and petechial rash may occur but are not part of the triad.'),
  ('hiv', 1, 'A client with HIV has a CD4 count of 180 cells/µL and has never had an opportunistic infection. Which statement by the nurse is accurate?', '[{"id": "a", "text": "Your CD4 count meets the criteria for a diagnosis of AIDS."}, {"id": "b", "text": "AIDS cannot be diagnosed until an opportunistic infection occurs."}, {"id": "c", "text": "Your CD4 count is within the expected normal range."}, {"id": "d", "text": "AIDS is diagnosed only after the viral load becomes undetectable."}]'::jsonb, '["a"]', 'AIDS is defined by a CD4 count below 200 cells/µL OR an AIDS-defining opportunistic infection, so a count of 180 alone meets the definition. An opportunistic infection is not required when the CD4 count is below 200.'),
  ('hiv', 2, 'A client with HIV whose CD4 count is 350 cells/µL is diagnosed with an AIDS-defining opportunistic infection. How should the nurse interpret the client''s status?', '[{"id": "a", "text": "The client cannot have AIDS until the CD4 count is below 200."}, {"id": "b", "text": "The client meets the definition of AIDS because of the infection."}, {"id": "c", "text": "The client is in the acute primary stage of HIV infection."}, {"id": "d", "text": "The client''s CD4 count reflects normal immune function."}]'::jsonb, '["b"]', 'AIDS is defined by a CD4 count below 200 OR the presence of an AIDS-defining opportunistic infection, so either criterion is enough. A CD4 count of 350 is also below the normal value of greater than 500.'),
  ('hiv', 3, 'A newly diagnosed client asks the nurse how HIV harms the body. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It destroys red blood cells, which leads to severe anemia."}, {"id": "b", "text": "It attacks B cells while leaving T-helper cells intact."}, {"id": "c", "text": "It attacks CD4+ T-helper cells, progressively destroying immunity."}, {"id": "d", "text": "It infects liver cells, which leads to jaundice and hepatitis."}]'::jsonb, '["c"]', 'HIV attacks CD4+ T-helper cells, and the immune system is progressively destroyed. It does not spare T-helper cells; they are its main target.'),
  ('hiv', 4, 'The nurse teaches a community group about HIV transmission. Which statement by a participant indicates a need for further teaching?', '[{"id": "a", "text": "HIV can be spread by sharing needles to inject drugs."}, {"id": "b", "text": "HIV can pass from a mother to her baby by breastfeeding."}, {"id": "c", "text": "HIV can be spread through vaginal, anal, or oral sex."}, {"id": "d", "text": "HIV can be caught from sitting on a public toilet seat."}]'::jsonb, '["d"]', 'HIV is not transmitted by casual contact, saliva, tears, insect bites, or toilet seats. Needle sharing, breastfeeding, and vaginal, anal, or oral sex are all routes of transmission.'),
  ('hiv', 5, 'The parent of a kindergarten student learns that a classmate has HIV and asks whether the child could become infected by sharing a cup with the classmate. Which response by the school nurse is accurate?', '[{"id": "a", "text": "Yes, HIV is easily spread through shared saliva."}, {"id": "b", "text": "No, HIV is not spread through saliva or casual contact."}, {"id": "c", "text": "Yes, HIV spreads when children share toys or utensils."}, {"id": "d", "text": "No, HIV is spread only by insect bites and toilet seats."}]'::jsonb, '["b"]', 'HIV is not transmitted by casual contact or saliva, so sharing a cup does not transmit the virus. Insect bites and toilet seats are also not routes of transmission.'),
  ('hiv', 6, 'Which occupational event places a nurse at risk for acquiring HIV?', '[{"id": "a", "text": "A needle stick with a needle used on a client with HIV"}, {"id": "b", "text": "A mosquito bite received while making a home visit"}, {"id": "c", "text": "Contact with the tears of a client who has HIV"}, {"id": "d", "text": "Hugging a client with HIV who is upset and crying"}]'::jsonb, '["a"]', 'Blood-to-blood exposure, including needle sticks, transmits HIV. Insect bites, tears, and casual contact such as hugging do not.'),
  ('hiv', 7, 'A pregnant client with HIV asks how her infant could become infected. Which response by the nurse is accurate?', '[{"id": "a", "text": "Only through breastfeeding after the baby is born"}, {"id": "b", "text": "Only during labor and the delivery process"}, {"id": "c", "text": "During pregnancy, labor, and breastfeeding"}, {"id": "d", "text": "Only if the baby later receives a blood transfusion"}]'::jsonb, '["c"]', 'Vertical (mother-to-child) transmission can occur during pregnancy, labor, and breastfeeding. Limiting the risk to only one of these periods is inaccurate.'),
  ('hiv', 8, 'A pregnant client with HIV asks why she should continue antiretroviral therapy (ART) during her pregnancy. Which response by the nurse is accurate?', '[{"id": "a", "text": "ART is stopped in pregnancy to protect the fetus."}, {"id": "b", "text": "ART is only needed after the baby is delivered."}, {"id": "c", "text": "ART cures HIV in the mother before the birth."}, {"id": "d", "text": "ART helps prevent passing HIV to the baby."}]'::jsonb, '["d"]', 'ART is given during pregnancy and labor to prevent vertical transmission, so it is not stopped during pregnancy. ART is also lifelong therapy rather than a short course.'),
  ('hiv', 9, 'A client reports fever and a ''mono-like'' illness that began 3 weeks after unprotected sex with a partner who has HIV. The nurse recognizes these findings as consistent with which stage?', '[{"id": "a", "text": "Chronic latency stage"}, {"id": "b", "text": "Acute (primary) HIV infection"}, {"id": "c", "text": "AIDS with an opportunistic infection"}, {"id": "d", "text": "AIDS defined by a low CD4 count"}]'::jsonb, '["b"]', 'Acute (primary) HIV presents as a flu-like, mono-like illness 2-4 weeks after exposure. Chronic latency is asymptomatic, and nothing in the scenario meets the definition of AIDS.'),
  ('hiv', 10, 'A client diagnosed with acute (primary) HIV infection says, ''I just found out, so I probably can''t pass it to anyone yet.'' Which response by the nurse is accurate?', '[{"id": "a", "text": "That''s right; HIV cannot spread until AIDS develops."}, {"id": "b", "text": "That''s right; you are not infectious for about 10 years."}, {"id": "c", "text": "Actually, this early stage is when HIV is most infectious."}, {"id": "d", "text": "Actually, HIV spreads only once your CD4 count is below 200."}]'::jsonb, '["c"]', 'The acute (primary) stage is the most infectious stage of HIV. Transmission does not wait for AIDS or a CD4 count below 200.'),
  ('hiv', 11, 'A client who was diagnosed with HIV 6 years ago and has never had symptoms asks how that is possible. Which response by the nurse is accurate?', '[{"id": "a", "text": "Having no symptoms means the virus has been cleared."}, {"id": "b", "text": "The chronic latency stage can be asymptomatic for 10 or more years."}, {"id": "c", "text": "Being symptom-free means you have already progressed to AIDS."}, {"id": "d", "text": "You likely have HIV-2, which never causes any symptoms."}]'::jsonb, '["b"]', 'During chronic latency the client is asymptomatic while the virus replicates slowly, and this stage can last 10 or more years. The virus has not been cleared; it is still replicating.'),
  ('hiv', 12, 'A client from West Africa is diagnosed with HIV-2 and asks how it differs from HIV-1. Which response by the nurse is accurate?', '[{"id": "a", "text": "HIV-2 is less virulent than HIV-1."}, {"id": "b", "text": "HIV-2 is the most common type worldwide."}, {"id": "c", "text": "HIV-2 is more virulent than HIV-1."}, {"id": "d", "text": "HIV-2 is found mostly in North America."}]'::jsonb, '["a"]', 'HIV-2 is less virulent and found mostly in West Africa. HIV-1, not HIV-2, is the most common type worldwide.'),
  ('hiv', 13, 'A client without symptoms requests HIV testing after learning that a partner from 2 years ago has HIV. Which test does the nurse anticipate will be performed first?', '[{"id": "a", "text": "CD4 count"}, {"id": "b", "text": "Complete blood count"}, {"id": "c", "text": "ELISA"}, {"id": "d", "text": "Tuberculin skin test"}]'::jsonb, '["c"]', 'The ELISA is the first test used to screen for HIV because it is sensitive. The CD4 count is used for disease staging, not initial screening.'),
  ('hiv', 14, 'A client asks the nurse why an ELISA is used as the first HIV test. Which response by the nurse is accurate?', '[{"id": "a", "text": "It is a sensitive test used for screening."}, {"id": "b", "text": "It measures the CD4 count to stage disease."}, {"id": "c", "text": "It is the test that monitors response to ART."}, {"id": "d", "text": "It is the only HIV test done by oral swab."}]'::jsonb, '["a"]', 'The ELISA is a sensitive screening test. Staging is done with the CD4 count, treatment response is monitored with HIV RNA, and OraQuick is the rapid oral swab test.'),
  ('hiv', 15, 'A client seeks care 10 days after a high-risk sexual exposure and asks which HIV test can detect the virus earliest. Which test does the nurse identify?', '[{"id": "a", "text": "ELISA antibody screen"}, {"id": "b", "text": "CD4 count"}, {"id": "c", "text": "HIV RNA (viral load)"}, {"id": "d", "text": "OraQuick oral swab"}]'::jsonb, '["c"]', 'HIV RNA (viral load) provides the earliest detection, about 10 days after exposure. The CD4 count is used for staging, not early detection.'),
  ('hiv', 16, 'A client has been taking antiretroviral therapy (ART) for 6 months. Which test result does the nurse review to evaluate the client''s response to treatment?', '[{"id": "a", "text": "OraQuick oral swab result"}, {"id": "b", "text": "ELISA screening result"}, {"id": "c", "text": "Complete blood count"}, {"id": "d", "text": "HIV RNA viral load"}]'::jsonb, '["d"]', 'HIV RNA (viral load) monitors treatment response. The ELISA and OraQuick are screening tests, and the CBC is monitored for zidovudine bone marrow suppression.'),
  ('hiv', 17, 'A client with HIV has a CD4 count of 650 cells/µL. How should the nurse interpret this result?', '[{"id": "a", "text": "The count meets the criteria for AIDS."}, {"id": "b", "text": "The count is within the normal range."}, {"id": "c", "text": "The count requires TMP-SMX prophylaxis."}, {"id": "d", "text": "The count indicates severe immunosuppression."}]'::jsonb, '["b"]', 'A normal CD4 count is greater than 500, so 650 is within the normal range. AIDS and PCP prophylaxis with TMP-SMX apply when the CD4 count is below 200.'),
  ('hiv', 18, 'A community health nurse is planning HIV screening at a neighborhood health fair. Which test is designed for this type of setting?', '[{"id": "a", "text": "OraQuick rapid oral swab test"}, {"id": "b", "text": "CD4 count by venous blood draw"}, {"id": "c", "text": "HIV RNA viral load testing"}, {"id": "d", "text": "Complete blood count"}]'::jsonb, '["a"]', 'OraQuick is a rapid oral swab test used for community screening. The CD4 count stages disease and the HIV RNA viral load monitors treatment response.'),
  ('hiv', 19, 'The nurse is teaching a client about sexual transmission of HIV. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Anal sex can transmit HIV."}, {"id": "b", "text": "Oral sex carries no risk of HIV."}, {"id": "c", "text": "Vaginal sex can transmit HIV."}, {"id": "d", "text": "Sharing drug needles can transmit HIV."}]'::jsonb, '["b"]', 'Sexual transmission of HIV includes vaginal, anal, and oral contact, so oral sex is not risk-free. Needle sharing is a blood-to-blood route.'),
  ('hiv', 20, 'The nurse is teaching a client who is starting antiretroviral therapy (ART). Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will need to take ART for the rest of my life."}, {"id": "b", "text": "Missing doses can make the virus drug resistant."}, {"id": "c", "text": "I will take every dose, even when I feel well."}, {"id": "d", "text": "I can skip my pills on weekends if I feel fine."}]'::jsonb, '["d"]', 'ART is lifelong and every dose must be taken, because missing doses leads to drug resistance. Skipping doses on weekends is unsafe.'),
  ('hiv', 21, 'A client on antiretroviral therapy (ART) says, ''I missed several doses last week because I was busy, but my last CD4 count was normal.'' Which response by the nurse is most important?', '[{"id": "a", "text": "Missing doses can cause the virus to become drug resistant."}, {"id": "b", "text": "Missed doses do not matter when the CD4 count is normal."}, {"id": "c", "text": "Missed doses only matter during the first month of ART."}, {"id": "d", "text": "ART can be stopped safely once the CD4 count is normal."}]'::jsonb, '["a"]', 'ART is lifelong and doses must never be skipped because missed doses lead to drug resistance. A normal CD4 count does not make missed doses safe.'),
  ('hiv', 22, 'A client who recently started antiretroviral therapy (ART) asks, ''How long will I need to take these medicines?'' Which response by the nurse is accurate?', '[{"id": "a", "text": "For 28 days after your diagnosis"}, {"id": "b", "text": "Until your CD4 count is above 500"}, {"id": "c", "text": "Until your symptoms have gone away"}, {"id": "d", "text": "For the rest of your life"}]'::jsonb, '["d"]', 'ART is lifelong therapy. The 28-day course applies to post-exposure prophylaxis (PEP), not to ART for HIV infection.'),
  ('hiv', 23, 'A client with HIV is prescribed zidovudine (AZT). Which laboratory test should the nurse plan to monitor for this drug''s major adverse effect?', '[{"id": "a", "text": "Blood glucose level"}, {"id": "b", "text": "Complete blood count"}, {"id": "c", "text": "ELISA antibody result"}, {"id": "d", "text": "Tuberculin skin test"}]'::jsonb, '["b"]', 'Zidovudine (AZT) causes bone marrow suppression, so the CBC is monitored. Hyperglycemia is linked to protease inhibitors, not AZT.'),
  ('hiv', 24, 'The nurse reviews the adverse effects of a client''s antiretroviral regimen. Which adverse effect is most closely associated with zidovudine (AZT)?', '[{"id": "a", "text": "Injection site reactions"}, {"id": "b", "text": "Lipodystrophy"}, {"id": "c", "text": "Bone marrow suppression"}, {"id": "d", "text": "Neuropsychiatric effects"}]'::jsonb, '["c"]', 'AZT causes bone marrow suppression, which is why the CBC is monitored. Injection site reactions occur with enfuvirtide, lipodystrophy with protease inhibitors, and neuropsychiatric effects with efavirenz.'),
  ('hiv', 25, 'A client is taking tenofovir, a nucleoside reverse transcriptase inhibitor (NRTI). The nurse monitors for which adverse effect associated with this drug class?', '[{"id": "a", "text": "Lactic acidosis"}, {"id": "b", "text": "Injection site reactions"}, {"id": "c", "text": "Ring-enhancing brain lesions"}, {"id": "d", "text": "Purple skin lesions"}]'::jsonb, '["a"]', 'NRTIs such as tenofovir and zidovudine are associated with lactic acidosis. Injection site reactions occur with the fusion inhibitor enfuvirtide.'),
  ('hiv', 26, 'Which client report should the nurse recognize as a known adverse effect of efavirenz?', '[{"id": "a", "text": "Redness and swelling where the drug is injected"}, {"id": "b", "text": "Changes in body fat distribution"}, {"id": "c", "text": "New mood changes and confusing thoughts"}, {"id": "d", "text": "White plaques on the tongue and cheeks"}]'::jsonb, '["c"]', 'Efavirenz is associated with neuropsychiatric effects such as mood changes. Injection site reactions occur with enfuvirtide and lipodystrophy with protease inhibitors.'),
  ('hiv', 27, 'A client with HIV is starting nevirapine. Which assessments are priorities for this medication?', '[{"id": "a", "text": "Skin rash and liver toxicity"}, {"id": "b", "text": "Blood glucose and lipodystrophy"}, {"id": "c", "text": "Injection sites for local reactions"}, {"id": "d", "text": "CBC for bone marrow suppression"}]'::jsonb, '["a"]', 'NNRTIs such as nevirapine cause rash and liver toxicity. Bone marrow suppression is the key concern with zidovudine, and hyperglycemia and lipodystrophy with protease inhibitors.'),
  ('hiv', 28, 'A client with HIV is prescribed ritonavir and lopinavir. Which laboratory value should the nurse monitor because of this drug class?', '[{"id": "a", "text": "Complete blood count"}, {"id": "b", "text": "ELISA antibody result"}, {"id": "c", "text": "Tuberculin skin test"}, {"id": "d", "text": "Blood glucose level"}]'::jsonb, '["d"]', 'Protease inhibitors such as ritonavir and lopinavir can cause hyperglycemia, so blood glucose is monitored. CBC monitoring is emphasized for zidovudine bone marrow suppression.'),
  ('hiv', 29, 'A client with HIV reports changes in body fat distribution, which the provider identifies as lipodystrophy. Which medication in the client''s regimen is most likely responsible?', '[{"id": "a", "text": "Enfuvirtide"}, {"id": "b", "text": "Dolutegravir"}, {"id": "c", "text": "Zidovudine"}, {"id": "d", "text": "Lopinavir"}]'::jsonb, '["d"]', 'Protease inhibitors such as lopinavir cause lipodystrophy, hyperglycemia, and GI issues. Zidovudine is associated with bone marrow suppression, and dolutegravir is well tolerated.'),
  ('hiv', 30, 'A newly diagnosed client asks why dolutegravir was chosen for initial HIV therapy. Which response by the nurse is accurate?', '[{"id": "a", "text": "Integrase inhibitors are well tolerated and now preferred first-line."}, {"id": "b", "text": "Integrase inhibitors are used only after all other drugs fail."}, {"id": "c", "text": "Integrase inhibitors are given only to prevent vertical transmission."}, {"id": "d", "text": "Integrase inhibitors require weekly CBCs for marrow suppression."}]'::jsonb, '["a"]', 'Integrase inhibitors such as dolutegravir are well tolerated and now preferred first-line. CBC monitoring for bone marrow suppression is associated with zidovudine.'),
  ('hiv', 31, 'A client with HIV is prescribed enfuvirtide. Which teaching addresses this medication''s main adverse effect?', '[{"id": "a", "text": "Check your blood glucose daily."}, {"id": "b", "text": "Inspect injection sites for reactions."}, {"id": "c", "text": "Report vivid mood or behavior changes."}, {"id": "d", "text": "Have your CBC checked for anemia."}]'::jsonb, '["b"]', 'Enfuvirtide, a fusion inhibitor, causes injection site reactions. Hyperglycemia is linked to protease inhibitors and neuropsychiatric effects to efavirenz.'),
  ('hiv', 32, 'A client with HIV has a CD4 count of 150 cells/µL. Which medication does the nurse anticipate for prophylaxis against Pneumocystis pneumonia (PCP)?', '[{"id": "a", "text": "Ganciclovir"}, {"id": "b", "text": "Fluconazole"}, {"id": "c", "text": "Enfuvirtide"}, {"id": "d", "text": "TMP-SMX (Bactrim)"}]'::jsonb, '["d"]', 'TMP-SMX (Bactrim) is given as PCP prophylaxis when the CD4 count is below 200. Ganciclovir treats CMV retinitis and fluconazole treats thrush.'),
  ('hiv', 33, 'The nurse reviews the CD4 counts of four clients with HIV. Which client does the nurse anticipate will be prescribed TMP-SMX (Bactrim) prophylaxis?', '[{"id": "a", "text": "CD4 count of 650 cells/µL"}, {"id": "b", "text": "CD4 count of 520 cells/µL"}, {"id": "c", "text": "CD4 count of 180 cells/µL"}, {"id": "d", "text": "CD4 count of 350 cells/µL"}]'::jsonb, '["c"]', 'PCP prophylaxis with Bactrim (TMP-SMX) is started when the CD4 count is below 200, so only the client with 180 cells/µL meets this threshold.'),
  ('hiv', 34, 'A client with AIDS has white plaques in the mouth. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Fluconazole"}, {"id": "b", "text": "Ganciclovir"}, {"id": "c", "text": "Azithromycin"}, {"id": "d", "text": "TMP-SMX (Bactrim)"}]'::jsonb, '["a"]', 'White plaques in the mouth indicate oral candidiasis (thrush), which is treated with fluconazole. Ganciclovir is used for CMV retinitis.'),
  ('hiv', 35, 'A client with AIDS and a CD4 count of 40 cells/µL reports new changes in vision. The nurse is most concerned about which opportunistic infection because it can lead to blindness?', '[{"id": "a", "text": "Kaposi sarcoma"}, {"id": "b", "text": "CMV retinitis"}, {"id": "c", "text": "Oral candidiasis"}, {"id": "d", "text": "Pneumocystis pneumonia"}]'::jsonb, '["b"]', 'CMV retinitis occurs at CD4 counts below 50 and leads to blindness. Kaposi sarcoma causes purple skin and mucous membrane lesions, not vision loss.'),
  ('hiv', 36, 'A client with AIDS is diagnosed with CMV retinitis. Which medication does the nurse prepare to administer?', '[{"id": "a", "text": "Fluconazole"}, {"id": "b", "text": "Azithromycin"}, {"id": "c", "text": "Ganciclovir"}, {"id": "d", "text": "Enfuvirtide"}]'::jsonb, '["c"]', 'CMV retinitis is treated with ganciclovir. Fluconazole treats oral or esophageal candidiasis.'),
  ('hiv', 37, 'A client with AIDS and a CD4 count of 30 cells/µL has fever, weight loss, and diarrhea. Which opportunistic infection does the nurse suspect?', '[{"id": "a", "text": "Kaposi sarcoma"}, {"id": "b", "text": "Oral candidiasis"}, {"id": "c", "text": "Toxoplasmosis"}, {"id": "d", "text": "MAC (Mycobacterium avium)"}]'::jsonb, '["d"]', 'MAC occurs at CD4 counts below 50 and presents with fever, weight loss, and diarrhea. Toxoplasmosis is recognized by ring-enhancing brain lesions on MRI.'),
  ('hiv', 38, 'A client with AIDS and a CD4 count of 80 cells/µL has an MRI showing ring-enhancing brain lesions. The nurse recognizes this finding as consistent with which condition?', '[{"id": "a", "text": "Toxoplasmosis"}, {"id": "b", "text": "CMV retinitis"}, {"id": "c", "text": "MAC (Mycobacterium avium)"}, {"id": "d", "text": "Pneumocystis pneumonia"}]'::jsonb, '["a"]', 'Toxoplasmosis of the brain occurs at CD4 counts below 100 and shows ring-enhancing brain lesions on MRI. MAC presents with fever, weight loss, and diarrhea.'),
  ('hiv', 39, 'During a skin assessment of a client with AIDS, the nurse notes purple lesions on the skin and oral mucosa. The nurse recognizes this finding as which condition?', '[{"id": "a", "text": "Oral candidiasis"}, {"id": "b", "text": "Kaposi sarcoma"}, {"id": "c", "text": "CMV retinitis"}, {"id": "d", "text": "Toxoplasmosis"}]'::jsonb, '["b"]', 'Kaposi sarcoma causes purple skin and mucous membrane lesions. Oral candidiasis appears as white plaques in the mouth.'),
  ('hiv', 40, 'A client is newly diagnosed with HIV and has a CD4 count of 700 cells/µL. Which screening is appropriate regardless of the client''s CD4 count?', '[{"id": "a", "text": "Testing for tuberculosis"}, {"id": "b", "text": "Starting TMP-SMX prophylaxis"}, {"id": "c", "text": "Starting ganciclovir therapy"}, {"id": "d", "text": "Brain MRI for ring-enhancing lesions"}]'::jsonb, '["a"]', 'TB can occur at any CD4 count, is the most common OI worldwide, and all HIV-positive clients should be tested. TMP-SMX prophylaxis is started only when the CD4 count is below 200.'),
  ('hiv', 41, 'A nursing student asks which virus is associated with Kaposi sarcoma in clients with HIV/AIDS. Which response by the nurse is accurate?', '[{"id": "a", "text": "CMV"}, {"id": "b", "text": "HIV-2"}, {"id": "c", "text": "Mycobacterium avium"}, {"id": "d", "text": "HHV-8"}]'::jsonb, '["d"]', 'Kaposi sarcoma, which causes purple lesions, is linked to HIV/AIDS plus HHV-8. CMV causes retinitis, not Kaposi sarcoma.'),
  ('hiv', 42, 'A client with HIV who has no other infections is admitted to a medical unit. Which precautions does the nurse implement?', '[{"id": "a", "text": "Airborne precautions in a negative-pressure room"}, {"id": "b", "text": "Droplet precautions with a surgical mask"}, {"id": "c", "text": "Contact precautions with a gown and gloves"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["d"]', 'Only standard precautions are needed because HIV is not transmitted by casual contact. No special isolation room is required.'),
  ('hiv', 43, 'The nurse observes a UAP caring for a client with HIV who has no other infections. Which action by the UAP requires correction?', '[{"id": "a", "text": "Putting on gloves before emptying the client''s urinal"}, {"id": "b", "text": "Putting on a gown and mask to deliver a meal tray"}, {"id": "c", "text": "Performing hand hygiene after providing care"}, {"id": "d", "text": "Sitting and talking with the client without a mask"}]'::jsonb, '["b"]', 'Only standard precautions are needed for HIV, so a gown and mask are unnecessary for delivering a meal tray. Gloves for contact with body fluids and hand hygiene are part of standard precautions.'),
  ('hiv', 44, 'A client with AIDS is severely immunocompromised. Which nursing action is most appropriate?', '[{"id": "a", "text": "Use reverse precautions to protect the client from infection."}, {"id": "b", "text": "Use airborne precautions to protect staff from HIV."}, {"id": "c", "text": "Use droplet precautions because HIV spreads in saliva."}, {"id": "d", "text": "Use contact precautions because HIV spreads by touch."}]'::jsonb, '["a"]', 'HIV-positive clients should be protected from infections, with reverse precautions if severely immunocompromised. HIV is not spread by saliva or casual contact.'),
  ('hiv', 45, 'A nurse sustains a needle stick from a client with HIV. Which statement about post-exposure prophylaxis (PEP) is accurate?', '[{"id": "a", "text": "PEP is started only after the nurse tests HIV-positive."}, {"id": "b", "text": "PEP is effective if it is started within 7 days."}, {"id": "c", "text": "PEP should begin within 72 hours of the exposure."}, {"id": "d", "text": "PEP is taken daily for the rest of the nurse''s life."}]'::jsonb, '["c"]', 'PEP must start within 72 hours of exposure and is taken for 28 days. It is not lifelong and is not delayed until a positive test.'),
  ('hiv', 46, 'A client who was sexually assaulted is started on post-exposure prophylaxis (PEP). Which statement by the client indicates understanding of the teaching?', '[{"id": "a", "text": "I will take these pills for 7 days."}, {"id": "b", "text": "I will take these pills for 28 days."}, {"id": "c", "text": "I will stop once my first HIV test is negative."}, {"id": "d", "text": "I will take these pills for the rest of my life."}]'::jsonb, '["b"]', 'PEP is taken for 28 days. Lifelong therapy describes ART for HIV infection, not PEP.'),
  ('hiv', 47, 'Which client should the nurse identify as a candidate for post-exposure prophylaxis (PEP)?', '[{"id": "a", "text": "A client seen 5 days after unprotected sex"}, {"id": "b", "text": "A client who shared a bathroom with a person with HIV"}, {"id": "c", "text": "A client seen 36 hours after a sexual assault"}, {"id": "d", "text": "An HIV-negative client seeking ongoing protection"}]'::jsonb, '["c"]', 'PEP is indicated after exposures such as sexual assault and must start within 72 hours, so 36 hours qualifies while 5 days does not. Ongoing protection for a high-risk HIV-negative client is PrEP.'),
  ('hiv', 48, 'A high-risk client wants to begin pre-exposure prophylaxis (PrEP). What must the nurse confirm before the client starts?', '[{"id": "a", "text": "The client has a negative HIV test."}, {"id": "b", "text": "The client''s CD4 count is below 200."}, {"id": "c", "text": "The exposure occurred within 72 hours."}, {"id": "d", "text": "The client has finished 28 days of PEP."}]'::jsonb, '["a"]', 'The client must be HIV-negative before starting PrEP. The 72-hour window and 28-day course apply to PEP, not PrEP.'),
  ('hiv', 49, 'A client is prescribed Truvada (tenofovir/emtricitabine) as pre-exposure prophylaxis (PrEP). Which statement by the client indicates correct understanding?', '[{"id": "a", "text": "I take it only after a risky exposure."}, {"id": "b", "text": "I take it for 28 days and then stop."}, {"id": "c", "text": "I take it once I test HIV-positive."}, {"id": "d", "text": "I take one dose every day."}]'::jsonb, '["d"]', 'PrEP is Truvada taken daily by high-risk HIV-negative individuals. Taking medication after an exposure for 28 days describes PEP.'),
  ('hiv', 50, 'Which client is the most appropriate candidate for pre-exposure prophylaxis (PrEP) rather than post-exposure prophylaxis (PEP)?', '[{"id": "a", "text": "A nurse who had a needle stick yesterday"}, {"id": "b", "text": "A client who was sexually assaulted last night"}, {"id": "c", "text": "An HIV-negative, high-risk client wanting ongoing protection"}, {"id": "d", "text": "A client who had unprotected sex 2 days ago"}]'::jsonb, '["c"]', 'PrEP is for high-risk individuals who are HIV-negative. Needle sticks, sexual assault, and unprotected sex within 72 hours are indications for PEP.'),
  ('covid', 1, 'A client with suspected COVID-19 is being admitted from the emergency department. Which room placement and precautions should the nurse arrange?', '[{"id": "a", "text": "Airborne and contact precautions in a negative-pressure room"}, {"id": "b", "text": "Droplet precautions in a semi-private room"}, {"id": "c", "text": "Standard precautions in a positive-pressure room"}, {"id": "d", "text": "Contact precautions only in a standard room"}]'::jsonb, '["a"]', 'SARS and COVID-19 require airborne plus contact precautions with an N95 respirator and a negative-pressure room. Droplet or contact precautions alone are insufficient for NCLEX purposes.'),
  ('covid', 2, 'The nurse is preparing to enter the room of a client with COVID-19. Which type of respiratory protection should the nurse wear?', '[{"id": "a", "text": "A surgical mask"}, {"id": "b", "text": "An N95 respirator"}, {"id": "c", "text": "A cloth face mask"}, {"id": "d", "text": "No mask if gloves are worn"}]'::jsonb, '["b"]', 'An N95 respirator, not a surgical mask, is required for clients with SARS or COVID-19. A surgical mask is insufficient.'),
  ('covid', 3, 'The charge nurse observes care being provided to a client with COVID-19 in a negative-pressure room. Which action by a staff nurse requires correction?', '[{"id": "a", "text": "Wearing goggles while giving care"}, {"id": "b", "text": "Putting on an N95 before entering"}, {"id": "c", "text": "Propping the room door open for easier access"}, {"id": "d", "text": "Wearing a gown and gloves in the room"}]'::jsonb, '["c"]', 'The door of a negative-pressure room must remain closed. Goggles, a gown, gloves, and an N95 respirator are all required protective measures.'),
  ('covid', 4, 'The nurse has put on an N95 respirator before entering the room of a client with COVID-19. Which additional protective equipment is required?', '[{"id": "a", "text": "Gloves and shoe covers only"}, {"id": "b", "text": "A gown and hair cover only"}, {"id": "c", "text": "Shoe covers and a hair cover"}, {"id": "d", "text": "Gown, gloves, and goggles or a face shield"}]'::jsonb, '["d"]', 'Isolation for SARS and COVID-19 includes a gown, gloves, and eye protection (goggles or a face shield) in addition to the N95. Gloves or a gown alone is incomplete.'),
  ('covid', 5, 'A client reports fever and cough that began 2 days ago, and COVID-19 is suspected. Which diagnostic test does the nurse anticipate as the most accurate at this early stage?', '[{"id": "a", "text": "RT-PCR test"}, {"id": "b", "text": "Serology antibody test"}, {"id": "c", "text": "Complete blood count"}, {"id": "d", "text": "Arterial blood gas"}]'::jsonb, '["a"]', 'PCR (RT-PCR) is the gold standard and is best in early infection. Serology detects past exposure and is not used for acute diagnosis.'),
  ('covid', 6, 'A client with fever, cough, and myalgia has a negative rapid antigen test for COVID-19. The client says, "Good, so I don''t have COVID." Which response by the nurse is best?', '[{"id": "a", "text": "\"Correct, a negative rapid test rules out COVID-19.\""}, {"id": "b", "text": "\"Rapid tests are less sensitive, so a PCR test may be needed.\""}, {"id": "c", "text": "\"An antibody test is needed to diagnose current infection.\""}, {"id": "d", "text": "\"A chest x-ray is the gold standard to confirm infection.\""}]'::jsonb, '["b"]', 'The rapid antigen test is a quick screen but is less sensitive, while PCR is the gold standard. Serology is used for past exposure, not acute diagnosis.'),
  ('covid', 7, 'A client with a new cough and fever asks for an antibody blood test to find out whether the current illness is COVID-19. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Antibody testing is the gold standard for new illness.\""}, {"id": "b", "text": "\"Antibody testing is best done in the first days of illness.\""}, {"id": "c", "text": "\"Antibody testing shows past exposure, not current infection.\""}, {"id": "d", "text": "\"Antibody testing replaces the need for isolation.\""}]'::jsonb, '["c"]', 'Serology (antibody testing) is used for past exposure, not acute diagnosis. PCR is the gold standard and best in early infection.'),
  ('covid', 8, 'A client hospitalized with COVID-19 pneumonia has a chest CT scan. Which finding does the nurse expect in the report?', '[{"id": "a", "text": "A single lobar consolidation"}, {"id": "b", "text": "A widened mediastinum"}, {"id": "c", "text": "A normal lung appearance"}, {"id": "d", "text": "Bilateral ground-glass opacities"}]'::jsonb, '["d"]', 'Chest x-ray or CT in SARS and COVID-19 shows bilateral infiltrates with ground-glass opacities. A single-sided or normal finding does not match the expected pattern.'),
  ('covid', 9, 'The nurse reviews the complete blood count of a client with COVID-19. Which finding is typical of this infection?', '[{"id": "a", "text": "Lymphopenia"}, {"id": "b", "text": "Lymphocytosis"}, {"id": "c", "text": "Marked leukocytosis"}, {"id": "d", "text": "Polycythemia"}]'::jsonb, '["a"]', 'Leukopenia and lymphopenia are typical CBC findings in SARS and COVID-19. An elevated lymphocyte or white cell count is the opposite of the expected finding.'),
  ('covid', 10, 'The nurse reviews the arterial blood gas of a client early in the course of COVID-19 pneumonia. Which findings does the nurse expect?', '[{"id": "a", "text": "Hyperoxemia with metabolic acidosis"}, {"id": "b", "text": "Hypoxemia with possible respiratory alkalosis"}, {"id": "c", "text": "Normal oxygen with metabolic alkalosis"}, {"id": "d", "text": "Hyperoxemia with respiratory acidosis"}]'::jsonb, '["b"]', 'ABG findings in SARS and COVID-19 include hypoxemia and possible respiratory alkalosis early. Elevated oxygen levels are not expected.'),
  ('covid', 11, 'A client with COVID-19 pneumonia is receiving supplemental oxygen. The pulse oximeter reads 91%. Which action should the nurse take?', '[{"id": "a", "text": "Document the reading as within the target range"}, {"id": "b", "text": "Decrease the oxygen flow rate"}, {"id": "c", "text": "Titrate oxygen to reach an SpO2 of 94% or higher"}, {"id": "d", "text": "Remove the oxygen and recheck in one hour"}]'::jsonb, '["c"]', 'Supportive care includes supplemental oxygen with a target SpO2 of 94% or higher, so a reading of 91% is below target. Decreasing or removing oxygen would worsen hypoxia.'),
  ('covid', 12, 'A client with COVID-19 develops ARDS and remains hypoxemic. Which position does the nurse anticipate using to help improve oxygenation?', '[{"id": "a", "text": "Supine"}, {"id": "b", "text": "Trendelenburg"}, {"id": "c", "text": "Left lateral"}, {"id": "d", "text": "Prone"}]'::jsonb, '["d"]', 'Prone positioning is used for ARDS and helps oxygenation. The other positions are not identified as treatments for ARDS.'),
  ('covid', 13, 'A client with severe COVID-19 is prescribed dexamethasone. The client asks why a steroid is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It reduces inflammation, especially in severe COVID.\""}, {"id": "b", "text": "\"It directly kills the virus in your lungs.\""}, {"id": "c", "text": "\"It works as a vaccine to prevent reinfection.\""}, {"id": "d", "text": "\"It is used to lower your fever only.\""}]'::jsonb, '["a"]', 'Corticosteroids such as dexamethasone reduce inflammation, especially in severe COVID-19. Acetaminophen, not dexamethasone, is the listed treatment for fever.'),
  ('covid', 14, 'A client is hospitalized with moderate-to-severe COVID-19. Which antiviral medication does the nurse anticipate?', '[{"id": "a", "text": "Acetaminophen"}, {"id": "b", "text": "Remdesivir"}, {"id": "c", "text": "Dexamethasone"}, {"id": "d", "text": "Tocilizumab"}]'::jsonb, '["b"]', 'Remdesivir is the antiviral used for moderate-to-severe, hospitalized COVID-19. Dexamethasone is a corticosteroid and tocilizumab is anti-IL-6 therapy, not antivirals.'),
  ('covid', 15, 'An outpatient client is diagnosed with COVID-19 on the first day of symptoms. Which medication does the nurse anticipate for early treatment at home?', '[{"id": "a", "text": "Remdesivir IV"}, {"id": "b", "text": "Tocilizumab"}, {"id": "c", "text": "Paxlovid"}, {"id": "d", "text": "Dexamethasone"}]'::jsonb, '["c"]', 'Paxlovid (nirmatrelvir/ritonavir) is used for early outpatient treatment. Remdesivir is used for moderate-to-severe, hospitalized clients.'),
  ('covid', 16, 'A client with severe COVID-19 is diagnosed with cytokine storm. Which medication does the nurse anticipate the provider will add?', '[{"id": "a", "text": "Paxlovid"}, {"id": "b", "text": "Acetaminophen"}, {"id": "c", "text": "An mRNA vaccine"}, {"id": "d", "text": "Tocilizumab"}]'::jsonb, '["d"]', 'Anti-IL-6 therapy with tocilizumab is used for cytokine storm. Paxlovid is for early outpatient treatment, not cytokine storm.'),
  ('covid', 17, 'A client with COVID-19 has a temperature of 101.8°F (38.8°C). Which medication does the nurse anticipate administering for the fever?', '[{"id": "a", "text": "Acetaminophen"}, {"id": "b", "text": "Tocilizumab"}, {"id": "c", "text": "Remdesivir"}, {"id": "d", "text": "Paxlovid"}]'::jsonb, '["a"]', 'Acetaminophen is the supportive care medication for fever. Tocilizumab is used for cytokine storm, and remdesivir and Paxlovid are antivirals.'),
  ('covid', 18, 'On day 4 of illness, a client with COVID-19 reports fever of 101°F, cough, muscle aches, headache, and fatigue, with no shortness of breath. The nurse recognizes this as which clinical stage?', '[{"id": "a", "text": "Pulmonary phase"}, {"id": "b", "text": "Early/mild stage"}, {"id": "c", "text": "Severe/late stage"}, {"id": "d", "text": "Incubation period"}]'::jsonb, '["b"]', 'The early/mild stage occurs on days 1–7 with fever, cough, myalgia, malaise, and headache. The pulmonary phase (days 7–10) brings shortness of breath and hypoxia.'),
  ('covid', 19, 'On day 8 of illness, a client with COVID-19 develops shortness of breath, low oxygen saturation, and a persistent cough, and is diagnosed with pneumonia. The nurse recognizes this as which clinical stage?', '[{"id": "a", "text": "Early/mild stage"}, {"id": "b", "text": "Incubation period"}, {"id": "c", "text": "Pulmonary phase"}, {"id": "d", "text": "Severe/late stage"}]'::jsonb, '["c"]', 'The pulmonary phase occurs on days 7–10 with shortness of breath, hypoxia, persistent cough, and pneumonia. The severe/late stage (day 10+) involves ARDS and multi-organ dysfunction.'),
  ('covid', 20, 'On day 12 of illness, a client with COVID-19 develops ARDS, respiratory failure, and signs of multi-organ dysfunction. The nurse recognizes this as which clinical stage?', '[{"id": "a", "text": "Early/mild stage"}, {"id": "b", "text": "Pulmonary phase"}, {"id": "c", "text": "Incubation period"}, {"id": "d", "text": "Severe/late stage"}]'::jsonb, '["d"]', 'The severe/late stage occurs at day 10 and beyond, with ARDS, respiratory failure, multi-organ dysfunction, and septic shock. The pulmonary phase (days 7–10) involves hypoxia and pneumonia without multi-organ failure.'),
  ('covid', 21, 'A client was exposed to a coworker with COVID-19 three days ago and asks how long symptoms could take to appear. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"From 2 to 14 days, with an average of about 5 days.\""}, {"id": "b", "text": "\"From 2 to 10 days, with an average of about 1 day.\""}, {"id": "c", "text": "\"Within 24 hours, or you were not infected.\""}, {"id": "d", "text": "\"From 3 to 30 days, with an average of 21 days.\""}]'::jsonb, '["a"]', 'The incubation period for COVID-19 is 2–14 days with an average of 5. The 2–10 day range is the incubation period for SARS.'),
  ('covid', 22, 'A nursing student is comparing SARS with COVID-19. Which incubation period does the nurse identify for SARS?', '[{"id": "a", "text": "1 to 3 days"}, {"id": "b", "text": "2 to 10 days"}, {"id": "c", "text": "2 to 14 days"}, {"id": "d", "text": "3 to 30 days"}]'::jsonb, '["b"]', 'The incubation period for SARS is 2–10 days. The 2–14 day range is the incubation period for COVID-19.'),
  ('covid', 23, 'A client is diagnosed with SARS. Which treatment plan does the nurse anticipate?', '[{"id": "a", "text": "Remdesivir as the specific antiviral"}, {"id": "b", "text": "Paxlovid for early outpatient care"}, {"id": "c", "text": "Supportive care, since no specific antiviral exists"}, {"id": "d", "text": "Vaccination to treat the active infection"}]'::jsonb, '["c"]', 'SARS has no specific antiviral, so treatment is supportive only. COVID-19, not SARS, has antivirals such as remdesivir and Paxlovid.'),
  ('covid', 24, 'A client asks whether a vaccine is available for SARS, as there is for COVID-19. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, the same mRNA vaccines prevent SARS.\""}, {"id": "b", "text": "\"Yes, a SARS vaccine is given every year.\""}, {"id": "c", "text": "\"Yes, but it is only given to children.\""}, {"id": "d", "text": "\"No, there is no vaccine available for SARS.\""}]'::jsonb, '["d"]', 'SARS has no specific antiviral and no vaccine, whereas COVID-19 has multiple vaccines available.'),
  ('covid', 25, 'The nurse is teaching a community group about differences between SARS and COVID-19. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"Asymptomatic spread is common with COVID-19 but rare with SARS.\""}, {"id": "b", "text": "\"Asymptomatic spread is common with SARS but rare with COVID-19.\""}, {"id": "c", "text": "\"Asymptomatic spread does not occur with COVID-19.\""}, {"id": "d", "text": "\"Asymptomatic spread is equally common with both.\""}]'::jsonb, '["a"]', 'Asymptomatic spread is common with COVID-19 but rare with SARS. The reversed statement is incorrect.'),
  ('covid', 26, 'A nursing student asks how the case fatality rate of SARS compares with that of COVID-19. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"COVID-19 is about 10%, while SARS is about 1–3%.\""}, {"id": "b", "text": "\"SARS is about 10%, while COVID-19 is about 1–3%.\""}, {"id": "c", "text": "\"Both have a case fatality rate of about 10%.\""}, {"id": "d", "text": "\"Both have a case fatality rate below 1%.\""}]'::jsonb, '["b"]', 'The case fatality rate is about 10% for SARS and about 1–3% for COVID-19, varying by variant. The first option reverses the two rates.'),
  ('covid', 27, 'The nurse is caring for a client with COVID-19. Which planned procedure makes wearing an N95 respirator especially important because it is aerosol-generating?', '[{"id": "a", "text": "Measuring an oral temperature"}, {"id": "b", "text": "Administering an oral medication"}, {"id": "c", "text": "Suctioning the airway"}, {"id": "d", "text": "Obtaining a blood pressure"}]'::jsonb, '["c"]', 'Aerosol-generating procedures such as intubation, bronchoscopy, and suctioning create airborne transmission risk in healthcare settings, so an N95 is especially important. The other tasks are not listed as aerosol-generating.'),
  ('covid', 28, 'A family member of a client recovering from COVID-19 at home asks whether the virus can spread through shared objects. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"No, the virus is spread only through blood.\""}, {"id": "b", "text": "\"No, surfaces cannot carry the virus.\""}, {"id": "c", "text": "\"No, it spreads only through contaminated food.\""}, {"id": "d", "text": "\"Yes, contaminated surfaces can spread the virus.\""}]'::jsonb, '["d"]', 'SARS and COVID-19 can be transmitted by contact with contaminated surfaces (fomites). This is one reason contact precautions are used along with airborne precautions.'),
  ('covid', 29, 'Several relatives arrive together to visit a hospitalized client with COVID-19 in a negative-pressure room. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Limit the number of visitors to the room"}, {"id": "b", "text": "Allow all relatives in with surgical masks"}, {"id": "c", "text": "Prop the door open so relatives can talk"}, {"id": "d", "text": "Move the client to a shared room for visits"}]'::jsonb, '["a"]', 'Isolation for SARS and COVID-19 includes limiting visitors and minimizing staff entering the room. The door of the negative-pressure room must remain closed, and surgical masks are insufficient.'),
  ('covid', 30, 'The nurse reviews isolation practices with staff caring for clients with COVID-19. Which staff statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I wear an N95 respirator before entering the room.\""}, {"id": "b", "text": "\"A surgical mask is enough when I suction the client.\""}, {"id": "c", "text": "\"I keep the negative-pressure room door closed.\""}, {"id": "d", "text": "\"I wear goggles or a face shield during care.\""}]'::jsonb, '["b"]', 'A surgical mask is insufficient for SARS or COVID-19; an N95 is required, especially for aerosol-generating procedures such as suctioning. The other statements are correct.'),
  ('covid', 31, 'The nurse is following up by phone with a client on day 3 of mild COVID-19 at home. Which client report requires prompt follow-up?', '[{"id": "a", "text": "\"I have a mild headache.\""}, {"id": "b", "text": "\"My muscles are achy.\""}, {"id": "c", "text": "\"I am getting short of breath.\""}, {"id": "d", "text": "\"I have a cough and feel tired.\""}]'::jsonb, '["c"]', 'Shortness of breath and hypoxia mark the pulmonary phase, signaling progression beyond the early/mild stage. Headache, myalgia, cough, and malaise are expected early/mild symptoms.'),
  ('covid', 32, 'A nursing student asks what type of virus causes SARS and COVID-19. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They are double-stranded DNA viruses.\""}, {"id": "b", "text": "\"They are gram-positive bacteria.\""}, {"id": "c", "text": "\"They are single-stranded DNA viruses.\""}, {"id": "d", "text": "\"They are single-stranded RNA coronaviruses.\""}]'::jsonb, '["d"]', 'SARS and COVID-19 are both caused by single-stranded RNA coronaviruses. They are viruses, not bacteria.'),
  ('covid', 33, 'A client asks why COVID-19 so often leads to pneumonia. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The virus mainly attacks the lower respiratory tract.\""}, {"id": "b", "text": "\"The virus mainly attacks the upper airway only.\""}, {"id": "c", "text": "\"The virus mainly attacks the digestive tract.\""}, {"id": "d", "text": "\"The virus mainly attacks the skin and joints.\""}]'::jsonb, '["a"]', 'SARS and COVID-19 primarily attack the lower respiratory tract, leading to pneumonia and ARDS. The upper airway alone is not the primary target.'),
  ('covid', 34, 'A nursing student is reviewing the coronaviruses. Which statement correctly matches the virus with when it emerged?', '[{"id": "a", "text": "SARS-CoV, which emerged in 2019"}, {"id": "b", "text": "SARS-CoV-2, which emerged in 2019"}, {"id": "c", "text": "SARS-CoV-2, which emerged in 2002–2003"}, {"id": "d", "text": "SARS-CoV, which emerged in 2015"}]'::jsonb, '["b"]', 'COVID-19 is caused by SARS-CoV-2, which emerged in 2019, while SARS is caused by SARS-CoV, which emerged in 2002–2003 in China.'),
  ('covid', 35, 'The nurse is teaching about complications of SARS and COVID-19. Which complication is the main complication of both diseases?', '[{"id": "a", "text": "Long COVID"}, {"id": "b", "text": "Cytokine storm"}, {"id": "c", "text": "ARDS"}, {"id": "d", "text": "Chronic arthritis"}]'::jsonb, '["c"]', 'ARDS is the main complication of both SARS and COVID-19 and may require intubation. Cytokine storm and Long COVID are listed as complications of COVID-19 only.'),
  ('covid', 36, 'A nursing student asks how contagious COVID-19 is compared with SARS. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"SARS is highly contagious; COVID-19 is less so.\""}, {"id": "b", "text": "\"Both are equally and only mildly contagious.\""}, {"id": "c", "text": "\"Neither can spread before symptoms begin.\""}, {"id": "d", "text": "\"COVID-19 is highly contagious; SARS is less so.\""}]'::jsonb, '["d"]', 'COVID-19 is highly contagious with an R0 greater than 2, while SARS is less contagious. Asymptomatic spread is common with COVID-19.'),
  ('covid', 37, 'A client with COVID-19 and ARDS has worsening respiratory failure despite high levels of supplemental oxygen and prone positioning. Which intervention does the nurse anticipate next?', '[{"id": "a", "text": "Intubation and mechanical ventilation"}, {"id": "b", "text": "Discharge with oral Paxlovid"}, {"id": "c", "text": "Switching to a surgical mask"}, {"id": "d", "text": "An antibody test for past exposure"}]'::jsonb, '["a"]', 'ARDS is the main complication and may need intubation, and mechanical ventilation is used if needed. Paxlovid is for early outpatient treatment, not respiratory failure.'),
  ('covid', 38, 'A client with COVID-19 has had poor oral intake for several days and shows signs of dehydration. Which supportive intervention does the nurse anticipate?', '[{"id": "a", "text": "Strict fluid restriction"}, {"id": "b", "text": "IV fluids for hydration"}, {"id": "c", "text": "Tocilizumab infusion"}, {"id": "d", "text": "Holding all fluids until afebrile"}]'::jsonb, '["b"]', 'Supportive care for SARS and COVID-19 includes IV fluids for hydration. Tocilizumab is used for cytokine storm, not dehydration.'),
  ('covid', 39, 'A client asks which types of COVID-19 vaccines are available. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"No vaccine exists yet for COVID-19.\""}, {"id": "b", "text": "\"Only an antibiotic is used to prevent it.\""}, {"id": "c", "text": "\"mRNA vaccines such as Pfizer and Moderna.\""}, {"id": "d", "text": "\"The SARS vaccine also prevents COVID-19.\""}]'::jsonb, '["c"]', 'COVID-19 vaccines include mRNA vaccines (Pfizer and Moderna). SARS has no vaccine available.'),
  ('covid', 40, 'The nurse is assessing four clients who were exposed to COVID-19. Which temperature reading indicates the fever seen in the early/mild stage?', '[{"id": "a", "text": "98.6°F (37°C)"}, {"id": "b", "text": "99.5°F (37.5°C)"}, {"id": "c", "text": "100.0°F (37.8°C)"}, {"id": "d", "text": "101.2°F (38.4°C)"}]'::jsonb, '["d"]', 'Fever in the early/mild stage of SARS and COVID-19 is defined as greater than 100.4°F. Only 101.2°F exceeds this value.'),
  ('covid', 41, 'An unlicensed assistive personnel (UAP) asks why a client with COVID-19 and ARDS is being turned onto the abdomen. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Prone positioning helps oxygenation in ARDS.\""}, {"id": "b", "text": "\"Prone positioning lowers the client''s fever.\""}, {"id": "c", "text": "\"Prone positioning prevents virus spread to staff.\""}, {"id": "d", "text": "\"Prone positioning replaces the need for oxygen.\""}]'::jsonb, '["a"]', 'Prone positioning helps oxygenation in ARDS. Fever is treated with acetaminophen, and supplemental oxygen is still part of supportive care.'),
  ('covid', 42, 'The nurse teaches a group of nursing students about SARS and COVID-19 treatment. Which student statement indicates a need for further teaching?', '[{"id": "a", "text": "\"COVID-19 can be treated with remdesivir.\""}, {"id": "b", "text": "\"SARS is treated with remdesivir or Paxlovid.\""}, {"id": "c", "text": "\"SARS treatment is supportive only.\""}, {"id": "d", "text": "\"Dexamethasone is used in severe COVID-19.\""}]'::jsonb, '["b"]', 'SARS has no specific antiviral and is treated with supportive care only; remdesivir and Paxlovid are COVID-19 antivirals. The other statements are correct.'),
  ('covid', 43, 'The complete blood count of a client admitted with COVID-19 shows a low white blood cell count. How should the nurse interpret this finding?', '[{"id": "a", "text": "It rules out COVID-19 as the diagnosis"}, {"id": "b", "text": "It indicates the client has cytokine storm"}, {"id": "c", "text": "It is a typical finding in COVID-19"}, {"id": "d", "text": "It confirms the client is in the late stage"}]'::jsonb, '["c"]', 'Leukopenia and lymphopenia are typical CBC findings in SARS and COVID-19. A low white count does not rule out the infection.'),
  ('covid', 44, 'A client at an urgent care clinic wants the fastest available screening test for COVID-19. Which test does the nurse anticipate?', '[{"id": "a", "text": "RT-PCR test"}, {"id": "b", "text": "Serology antibody test"}, {"id": "c", "text": "Chest CT scan"}, {"id": "d", "text": "Rapid antigen test"}]'::jsonb, '["d"]', 'The rapid antigen test is a quick screen, although it is less sensitive than PCR. Serology is for past exposure and is not used for acute diagnosis.'),
  ('covid', 45, 'The nurse is planning care for several clients with COVID-19 in negative-pressure rooms. Which strategy best reduces staff exposure?', '[{"id": "a", "text": "Cluster care to limit room entries"}, {"id": "b", "text": "Rotate many staff into each room"}, {"id": "c", "text": "Keep doors open to check on clients"}, {"id": "d", "text": "Use surgical masks for short visits"}]'::jsonb, '["a"]', 'Isolation includes limiting visitors and minimizing staff entering the room. Doors must remain closed, and surgical masks are insufficient.'),
  ('covid', 46, 'A client with early COVID-19 symptoms is prescribed Paxlovid at an outpatient visit. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"This medicine is used early in the illness.\""}, {"id": "b", "text": "\"I should wait until I''m hospitalized to start it.\""}, {"id": "c", "text": "\"I can take this medicine while at home.\""}, {"id": "d", "text": "\"Paxlovid contains nirmatrelvir and ritonavir.\""}]'::jsonb, '["b"]', 'Paxlovid (nirmatrelvir/ritonavir) is for early outpatient treatment, so waiting until hospitalization needs correction. Remdesivir is the antiviral used for hospitalized clients.'),
  ('covid', 47, 'The nurse is comparing the complications of SARS and COVID-19. Which complication is listed for COVID-19 but not for SARS?', '[{"id": "a", "text": "ARDS"}, {"id": "b", "text": "Respiratory failure"}, {"id": "c", "text": "Cytokine storm"}, {"id": "d", "text": "Pneumonia"}]'::jsonb, '["c"]', 'The main complication of SARS is ARDS, whereas COVID-19 complications include ARDS, cytokine storm, and Long COVID. ARDS is shared by both diseases.'),
  ('covid', 48, 'A client without current symptoms has a positive COVID-19 antibody test during a routine visit. How should the nurse interpret this result?', '[{"id": "a", "text": "It confirms a new acute infection"}, {"id": "b", "text": "It shows the client is in the pulmonary phase"}, {"id": "c", "text": "It means the client needs remdesivir"}, {"id": "d", "text": "It suggests past exposure to the virus"}]'::jsonb, '["d"]', 'Serology (antibodies) is used for past exposure, not acute diagnosis. Acute infection is best diagnosed with PCR.'),
  ('covid', 49, 'The nurse is reviewing four clients with COVID-19. Which client is the most appropriate candidate for remdesivir?', '[{"id": "a", "text": "A hospitalized client with moderate disease needing oxygen"}, {"id": "b", "text": "An outpatient client on day 1 of mild symptoms"}, {"id": "c", "text": "A client with no symptoms and a positive antibody test"}, {"id": "d", "text": "A client who recovered from COVID-19 last year"}]'::jsonb, '["a"]', 'Remdesivir is an antiviral for moderate-to-severe, hospitalized COVID-19. Early outpatient treatment uses Paxlovid, and a positive antibody test reflects past exposure.'),
  ('covid', 50, 'A family member asks why the door to a client''s COVID-19 isolation room must stay shut. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It keeps the room warm for the client''s comfort.\""}, {"id": "b", "text": "\"The negative-pressure room only works with the door closed.\""}, {"id": "c", "text": "\"It reduces noise so the client can sleep.\""}, {"id": "d", "text": "\"It is required only during meals.\""}]'::jsonb, '["b"]', 'SARS and COVID-19 require an N95 and a negative-pressure room, and the door must remain closed. The closed door is an isolation requirement, not a comfort measure.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _autoinf_seed_map m USING (source_key)
 CROSS JOIN _autoinf_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _autoinf_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Autoimmune-Infectious seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
